      public.real_date_to_rp_date(coalesce(new.reviewed_at, now())),
      false,
      1,
      jsonb_build_object(
        'interest_rate', new.interest_rate,
        'installments', new.installments,
        'does_not_directly_change_gdp', true
      ),
      'loan_application:' || new.id::text
    );
  end if;

  return new;
end;
$$;


