CREATE OR REPLACE FUNCTION "economy_private"."process_operational_prices"("p_run_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  item_row public.price_basket_items%rowtype;
  state_row public.economic_state%rowtype;
  current_period_id uuid;
  target_hourly numeric;
  demand_pressure numeric;
  interest_pressure numeric;
  shock_pressure numeric;
  policy_pressure numeric;
  price_step numeric;
  next_price numeric;
  inserted_count integer := 0;
  rp_at timestamptz := public.rp_now();
begin
  select * into state_row from public.economic_state where id = true;
  current_period_id := economy_private.period_for('month', rp_at);
  target_hourly := (state_row.inflation_target / 100) / 12 / 14;
  demand_pressure := ((state_row.consumer_confidence - 50) / 100) * .0015;
  interest_pressure := ((10 - state_row.current_selic) / 100) * .001;
  policy_pressure := economy_private.active_policy_impact('inflation_points') / 100 / 12 / 14;

  for item_row in
    select * from public.price_basket_items where is_active order by code
  loop
    shock_pressure := economy_private.active_shock_impact('inflation_points', item_row.sector_id)
      / 100 / 12 / 14;
    price_step := economy_private.clamp(
      target_hourly + demand_pressure + interest_pressure + policy_pressure + shock_pressure,
      -.01,
      .015
    );
    next_price := greatest(.01, item_row.current_price * (1 + price_step));

    update public.price_basket_items
    set current_price = round(next_price, 4), updated_at = now()
    where id = item_row.id;

    insert into public.price_observations (
      basket_item_id,
      sector_id,
      source_table,
      source_id,
      price,
      is_simulated,
      observed_at_real,
      observed_at_rp,
      period_id,
      metadata
    )
    values (
      item_row.id,
      item_row.sector_id,
      'economic_engine_runs',
      p_run_id::text || ':' || item_row.code,
      round(next_price, 4),
      true,
      now(),
      rp_at,
      current_period_id,
      jsonb_build_object(
        'price_step', price_step,
        'target_component', target_hourly,
        'demand_component', demand_pressure,
        'interest_component', interest_pressure,
        'shock_component', shock_pressure,
        'policy_component', policy_pressure
      )
    )
    on conflict do nothing;

    inserted_count := inserted_count + 1;
  end loop;

  return jsonb_build_object(
    'observations', inserted_count,
    'period_id', current_period_id
  );
end;
$$;


ALTER FUNCTION "economy_private"."process_operational_prices"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "economy_private"."process_project"("p_project_id" "uuid", "p_installment" numeric DEFAULT NULL::numeric, "p_actor" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare project_row public.government_projects%rowtype;
  installment numeric;
  new_spent numeric;
  new_progress numeric;
  expenditure_id uuid;
begin
  perform pg_advisory_xact_lock(hashtext('govrp:economy:project:'||p_project_id::text));
  select * into project_row from public.government_projects where id=p_project_id for update;
  if not found or project_row.status not in ('funded','in_progress','delayed') then
    raise exception 'Projeto não está em execução.';
  end if;
  installment := least(
    coalesce(p_installment,project_row.approved_budget*.1),
    project_row.approved_budget-project_row.spent_amount
  );
  if installment<=0 then
    return jsonb_build_object('project_id',p_project_id,'status','completed');
  end if;
  new_spent:=project_row.spent_amount+installment;
  new_progress:=least(100,new_spent/project_row.approved_budget*100);
  insert into public.government_expenditures(
    expenditure_type,ministry,project_id,source_table,source_id,sector_id,
    amount,productive_share,occurred_at_rp,metadata
  )
  values (
    'government_project',project_row.ministry,p_project_id,'government_projects',
    p_project_id::text||':'||to_char(new_spent,'FM999999999999990D00'),
    project_row.sector_id,installment,1,public.rp_now(),
    jsonb_build_object('quality_score',project_row.quality_score,'progress',new_progress)
  )
  returning id into expenditure_id;
  update public.government_projects
  set spent_amount=new_spent,progress=new_progress,
      status=case when new_progress>=100 then 'completed' else 'in_progress' end,
      completed_at=case when new_progress>=100 then now() else completed_at end,
      updated_at=now()
  where id=p_project_id;
  return jsonb_build_object('project_id',p_project_id,'installment',installment,
    'spent_amount',new_spent,'progress',new_progress,'expenditure_id',expenditure_id);
end;
$$;


ALTER FUNCTION "economy_private"."process_project"("p_project_id" "uuid", "p_installment" numeric, "p_actor" "uuid") OWNER TO "postgres";


