CREATE OR REPLACE FUNCTION "economy_private"."publish_bulletin"("p_period_id" "uuid", "p_bulletin_type" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $_$
declare
  period_row public.economic_periods%rowtype;
  title_value text;
  summary_value text;
  content_value text;
  bulletin_id uuid;
  gdp_growth numeric;
  inflation numeric;
  unemployment numeric;
  primary_result numeric;
begin
  select * into period_row from public.economic_periods where id=p_period_id;
  select coalesce(real_value,nominal_value) into gdp_growth
    from public.economic_indicators where period_id=p_period_id and indicator_code like 'gdp_growth%';
  select coalesce(real_value,nominal_value) into inflation
    from public.economic_indicators where period_id=p_period_id and indicator_code='inflation_annual';
  if inflation is null then
    inflation := economy_private.latest_indicator('inflation_annual',period_row.ends_at_rp);
  end if;
  select coalesce(real_value,nominal_value) into unemployment
    from public.economic_indicators where period_id=p_period_id and indicator_code='unemployment_rate';
  if unemployment is null then
    unemployment := economy_private.latest_indicator('unemployment_rate',period_row.ends_at_rp);
  end if;
  select fp.primary_result into primary_result
    from public.fiscal_periods fp where fp.period_id=p_period_id;

  title_value := case p_bulletin_type
    when 'monthly' then format('Boletim econômico — %s/%s',period_row.rp_month,period_row.rp_year)
    when 'quarterly' then format('PIB do %sº trimestre de %s',period_row.rp_quarter,period_row.rp_year)
    when 'annual' then format('Balanço econômico anual de %s',period_row.rp_year)
    else format('Boletim econômico de %s',period_row.rp_year)
  end;
  summary_value := format(
    'Inflação anual em %s%%, desemprego em %s%% e crescimento em %s%%.',
    to_char(coalesce(inflation,0),'FM999990.00'),
    to_char(coalesce(unemployment,0),'FM999990.00'),
    to_char(coalesce(gdp_growth,0),'FM999990.00')
  );
  content_value := format(
    'O fechamento oficial foi calculado a partir do livro-razão econômico. %s Resultado primário: R$ %s. Os números preservam a separação entre produção, transferências e operações financeiras.',
    summary_value,
    to_char(coalesce(primary_result,0),'FM999G999G999G990D00')
  );

  insert into public.economic_bulletins (
    period_id,bulletin_type,title,summary,content,highlights,status
  )
  values (
    p_period_id,
    p_bulletin_type,
    title_value,
    summary_value,
    content_value,
    jsonb_build_array(
      jsonb_build_object('label','Crescimento','value',coalesce(gdp_growth,0),'unit','%'),
      jsonb_build_object('label','Inflação','value',coalesce(inflation,0),'unit','%'),
      jsonb_build_object('label','Desemprego','value',coalesce(unemployment,0),'unit','%')
    ),
    'published'
  )
  on conflict (period_id,bulletin_type) do update set
    title=excluded.title,
    summary=excluded.summary,
    content=excluded.content,
    highlights=excluded.highlights,
    status='corrected',
    published_at=now()
  returning id into bulletin_id;

  return bulletin_id;
end;
$_$;


ALTER FUNCTION "economy_private"."publish_bulletin"("p_period_id" "uuid", "p_bulletin_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "economy_private"."record_event"("p_event_type" "text", "p_classification" "text", "p_source_table" "text", "p_source_id" "text", "p_nominal_amount" numeric DEFAULT 0, "p_actor_profile_id" "uuid" DEFAULT NULL::"uuid", "p_business_id" "uuid" DEFAULT NULL::"uuid", "p_government_entity_id" "uuid" DEFAULT NULL::"uuid", "p_sector_id" "uuid" DEFAULT NULL::"uuid", "p_quantity" numeric DEFAULT NULL::numeric, "p_unit_price" numeric DEFAULT NULL::numeric, "p_tax_amount" numeric DEFAULT 0, "p_subsidy_amount" numeric DEFAULT 0, "p_occurred_at_real" timestamp with time zone DEFAULT "now"(), "p_occurred_at_rp" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_is_simulated" boolean DEFAULT false, "p_macro_weight" numeric DEFAULT 1, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_economic_group_key" "text" DEFAULT NULL::"text", "p_reverses_event_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  event_id uuid;
  rp_at timestamptz := coalesce(
    p_occurred_at_rp,
    public.real_date_to_rp_date(coalesce(p_occurred_at_real, now())),
    public.rp_now()
  );
  period_id uuid;
  actual_amount numeric := coalesce(p_nominal_amount, 0);
  economic_value numeric;
  real_value numeric;
  representativity numeric := economy_private.calibration_numeric('player_representativity_factor', 1000);
  annual_gdp numeric := economy_private.calibration_numeric('baseline_annual_gdp', 10000000000);
  event_cap numeric;
  cpi numeric;
  bounded_weight numeric := economy_private.clamp(coalesce(p_macro_weight, 1), 0, 1);
  suspicious boolean := false;
begin
  if nullif(btrim(p_event_type), '') is null
     or nullif(btrim(p_source_table), '') is null
     or nullif(btrim(p_source_id), '') is null then
    raise exception 'Tipo, tabela e identificador de origem são obrigatórios.';
  end if;

  if abs(actual_amount) > 1000000000000000 then
    raise exception 'Valor econômico fora do limite permitido.';
  end if;

  period_id := economy_private.period_for('month', rp_at);
  event_cap := (annual_gdp / 4)
    * economy_private.calibration_numeric('max_event_share_quarter_gdp', .0025);

  if p_is_simulated then
    economic_value := actual_amount;
  else
    economic_value := sign(actual_amount)
      * least(abs(actual_amount) * representativity * bounded_weight, event_cap);
    suspicious := abs(actual_amount) * representativity > event_cap;
  end if;

  select es.cpi_index into cpi
  from public.economic_state es
  where es.id = true;

  real_value := economic_value / greatest(coalesce(cpi, 100) / 100, .000001);

  insert into public.economic_events (
    event_type,
    economic_classification,
    source_table,
    source_id,
    economic_group_key,
    actor_profile_id,
    business_id,
    government_entity_id,
    sector_id,
    nominal_amount,
    economic_amount,
    real_amount,
    quantity,
    unit_price,
    tax_amount,
    subsidy_amount,
    occurred_at_real,
    occurred_at_rp,
    economic_period_id,
    reverses_event_id,
    is_simulated,
    is_suspicious,
    macro_weight,
    metadata,
    engine_version
  )
  values (
    left(p_event_type, 120),
    p_classification,
    left(p_source_table, 120),
    left(p_source_id, 240),
    nullif(left(coalesce(p_economic_group_key, ''), 240), ''),
    p_actor_profile_id,
    p_business_id,
    p_government_entity_id,
    p_sector_id,
    actual_amount,
    economic_value,
    real_value,
    p_quantity,
    p_unit_price,
    greatest(coalesce(p_tax_amount, 0), 0),
    greatest(coalesce(p_subsidy_amount, 0), 0),
    coalesce(p_occurred_at_real, now()),
    rp_at,
    period_id,
    p_reverses_event_id,
    p_is_simulated,
    suspicious,
    bounded_weight,
    coalesce(p_metadata, '{}'::jsonb)
      || jsonb_build_object(
        'representativity_factor', case when p_is_simulated then 1 else representativity end,
        'impact_capped', suspicious
      ),
    '1.0.0'
  )
  on conflict (source_table, source_id, event_type)
  do nothing
  returning id into event_id;

  if event_id is null then
    select e.id into event_id
    from public.economic_events e
    where e.source_table = left(p_source_table, 120)
      and e.source_id = left(p_source_id, 240)
      and e.event_type = left(p_event_type, 120);
  end if;

  return event_id;
end;
$$;


ALTER FUNCTION "economy_private"."record_event"("p_event_type" "text", "p_classification" "text", "p_source_table" "text", "p_source_id" "text", "p_nominal_amount" numeric, "p_actor_profile_id" "uuid", "p_business_id" "uuid", "p_government_entity_id" "uuid", "p_sector_id" "uuid", "p_quantity" numeric, "p_unit_price" numeric, "p_tax_amount" numeric, "p_subsidy_amount" numeric, "p_occurred_at_real" timestamp with time zone, "p_occurred_at_rp" timestamp with time zone, "p_is_simulated" boolean, "p_macro_weight" numeric, "p_metadata" "jsonb", "p_economic_group_key" "text", "p_reverses_event_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "economy_private"."refresh_citizen_labor_statuses"() RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  changed integer := 0;
begin
  insert into public.citizen_economic_statuses (
    profile_id, labor_status, actively_seeking, last_economic_activity_at
  )
  select
    p.id,
    case
      when p.is_imprisoned then 'imprisoned'
      when exists (
        select 1 from public.businesses b
        where b.owner_id = p.id and b.status = 'active'
      ) then 'entrepreneur'
      when exists (
        select 1 from public.business_employees be
        where be.profile_id = p.id and be.fired_at is null
      ) then 'private_employee'
      when lower(p.role) in (
        'presidente','vice-presidente','ministro','senador','deputado',
        'juiz','policial','militar','promotor','defensor público',
        'presidente do banco central'
      ) then 'public_employee'
      else 'outside_labor_force'
    end,
    false,
    coalesce(
      (select max(uas.last_seen_at) from public.user_activity_sessions uas where uas.user_id=p.id),
      p.updated_at
    )
  from public.profiles p
  on conflict (profile_id) do nothing;
  get diagnostics changed = row_count;

  update public.citizen_economic_statuses ces
  set
    labor_status = case
      when p.is_imprisoned then 'imprisoned'
      when exists (
        select 1 from public.businesses b
        where b.owner_id = p.id and b.status = 'active'
      ) then 'entrepreneur'
      when exists (
        select 1 from public.business_employees be
        where be.profile_id = p.id and be.fired_at is null
      ) then 'private_employee'
      when lower(p.role) in (
        'presidente','vice-presidente','ministro','senador','deputado',
        'juiz','policial','militar','promotor','defensor público',
        'presidente do banco central'
      ) then 'public_employee'
      else ces.labor_status
    end,
    actively_seeking = case
      when p.is_imprisoned
        or exists (select 1 from public.businesses b where b.owner_id=p.id and b.status='active')
        or exists (select 1 from public.business_employees be where be.profile_id=p.id and be.fired_at is null)
        then false
      else ces.actively_seeking
    end,
    updated_at = now()
  from public.profiles p
  where p.id = ces.profile_id;

  return changed;
end;
$$;


ALTER FUNCTION "economy_private"."refresh_citizen_labor_statuses"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "economy_private"."refresh_policy_and_shock_statuses"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  policies_effective integer;
  policies_expired integer;
  shocks_active integer;
  shocks_resolved integer;
begin
  update public.economic_policy_decisions
  set status = 'effective'
  where status = 'announced'
    and effective_at_rp <= public.rp_now();
  get diagnostics policies_effective = row_count;

  update public.economic_policy_decisions
  set status = 'expired'
  where status in ('announced', 'effective')
    and expires_at_rp is not null
    and expires_at_rp <= public.rp_now();
  get diagnostics policies_expired = row_count;

  update public.economic_shocks
  set status = 'active'
  where status = 'scheduled'
    and starts_at_rp <= public.rp_now();
  get diagnostics shocks_active = row_count;

  update public.economic_shocks
  set status = 'resolved'
  where status = 'active'
    and ends_at_rp is not null
    and ends_at_rp <= public.rp_now();
  get diagnostics shocks_resolved = row_count;

  return jsonb_build_object(
    'policies_effective', policies_effective,
    'policies_expired', policies_expired,
    'shocks_active', shocks_active,
    'shocks_resolved', shocks_resolved
  );
end;
$$;


ALTER FUNCTION "economy_private"."refresh_policy_and_shock_statuses"() OWNER TO "postgres";

