CREATE OR REPLACE FUNCTION "economy_private"."resolve_product_basket_item"("p_product" "public"."products") RETURNS "uuid"
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select coalesce(
    p_product.price_basket_item_id,
    (
      select pbi.id
      from public.price_basket_items pbi
      where pbi.code = case
        when lower(coalesce(p_product.category,'')) like '%aliment%'
          or lower(coalesce(p_product.name,'')) like '%comida%' then 'food'
        when lower(coalesce(p_product.category,'')) like '%roup%'
          or lower(coalesce(p_product.category,'')) like '%vest%' then 'clothing'
        when lower(coalesce(p_product.category,'')) like '%saúde%'
          or lower(coalesce(p_product.category,'')) like '%saude%' then 'health'
        when lower(coalesce(p_product.category,'')) like '%educ%'
          or lower(coalesce(p_product.category,'')) like '%livro%' then 'education'
        when lower(coalesce(p_product.category,'')) like '%lazer%'
          or lower(coalesce(p_product.category,'')) like '%entreten%' then 'leisure'
        else 'other'
      end
      limit 1
    )
  )
$$;


ALTER FUNCTION "economy_private"."resolve_product_basket_item"("p_product" "public"."products") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "economy_private"."resolve_sector"("p_business_id" "uuid" DEFAULT NULL::"uuid", "p_sector_code" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  sector_id uuid;
  normalized text := lower(coalesce(p_description, ''));
  resolved_code text;
begin
  if p_business_id is not null then
    select coalesce(b.economic_sector_id, bt.economic_sector_id)
      into sector_id
    from public.businesses b
    left join public.business_types bt on bt.id = b.business_type_id
    where b.id = p_business_id;

    if sector_id is not null then
      return sector_id;
    end if;
  end if;

  resolved_code := coalesce(
    nullif(p_sector_code, ''),
    case
      when normalized like '%energia%' or normalized like '%eletric%' then 'energy'
      when normalized like '%água%' or normalized like '%agua%' then 'public_admin'
      when normalized like '%gás%' or normalized like '%gas%' or normalized like '%combust%' then 'oil_mining'
      when normalized like '%internet%' or normalized like '%telefon%' then 'telecom'
      when normalized like '%aluguel%' or normalized like '%moradia%' then 'real_estate'
      when normalized like '%educa%' or normalized like '%curso%' then 'education'
      when normalized like '%saúde%' or normalized like '%saude%' or normalized like '%terapia%' then 'health'
      when normalized like '%transporte%' or normalized like '%frete%' then 'transport'
      when normalized like '%banco%' or normalized like '%invest%' or normalized like '%cartão%' then 'finance'
      when normalized like '%constru%' or normalized like '%obra%' then 'construction'
      when normalized like '%tecnolog%' or normalized like '%software%' then 'technology'
      when normalized like '%consult%' or normalized like '%advoga%' then 'professional'
      when normalized like '%lazer%' or normalized like '%turismo%' then 'tourism'
      else 'commerce'
    end
  );

  select es.id into sector_id
  from public.economic_sectors es
  where es.code = resolved_code
    and es.is_active;

  if sector_id is null then
    select es.id into sector_id
    from public.economic_sectors es
    where es.code = 'other_services';
  end if;

  return sector_id;
end;
$$;


ALTER FUNCTION "economy_private"."resolve_sector"("p_business_id" "uuid", "p_sector_code" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "economy_private"."run_operational_engine"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  run_id uuid;
  rp_at timestamptz:=public.rp_now();
  offset_month integer;
  period_row public.economic_periods%rowtype;
  activity_result jsonb;
  status_result jsonb;
  price_result jsonb;
  closed_months integer:=0;
  closed_quarters integer:=0;
  closed_years integer:=0;
  result jsonb;
begin
  perform pg_advisory_xact_lock(hashtext('govrp:economy:operational'));
  insert into public.economic_engine_runs(run_type,engine_version,status)
  values ('operational','1.0.0','running')
  returning id into run_id;

  for offset_month in 0..3 loop
    perform economy_private.ensure_periods(rp_at-(offset_month||' months')::interval);
  end loop;

  status_result:=economy_private.refresh_policy_and_shock_statuses();
  activity_result:=economy_private.update_activity_mix();
  price_result:=economy_private.process_operational_prices(run_id);

  for period_row in
    select * from public.economic_periods
    where period_type='month' and status in ('open','failed') and ends_at<=now()
    order by ends_at
  loop
    perform economy_private.close_month(period_row.id,true,null);
    closed_months:=closed_months+1;
  end loop;

  for period_row in
    select * from public.economic_periods
    where period_type='quarter' and status in ('open','failed') and ends_at<=now()
    order by ends_at
  loop
    perform economy_private.close_quarter(period_row.id,true,null);
    closed_quarters:=closed_quarters+1;
  end loop;

  for period_row in
    select * from public.economic_periods
    where period_type='year' and status in ('open','failed') and ends_at<=now()
    order by ends_at
  loop
    perform economy_private.close_year(period_row.id,true,null);
    closed_years:=closed_years+1;
  end loop;

  update public.economic_state
  set last_operational_run_at=now(),updated_at=now()
  where id=true;

  result:=jsonb_build_object(
    'run_id',run_id,'rp_at',rp_at,'activity',activity_result,
    'statuses',status_result,'prices',price_result,
    'closed_months',closed_months,
    'closed_quarters',closed_quarters,
    'closed_years',closed_years
  );
  update public.economic_engine_runs
  set status='completed',finished_at=now(),results=result,
      output_hash=encode(extensions.digest(result::text,'sha256'),'hex')
  where id=run_id;
  return result;
exception
  when others then
    if run_id is not null then
      update public.economic_engine_runs
      set status='failed',finished_at=now(),
          errors=jsonb_build_array(jsonb_build_object('sqlstate',sqlstate,'message',sqlerrm))
      where id=run_id;
    end if;
    raise;
end;
$$;


ALTER FUNCTION "economy_private"."run_operational_engine"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "economy_private"."update_activity_mix"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  active_players integer;
  transactions_count integer;
  active_businesses integer;
  employment_actions integer;
  score numeric;
  thresholds jsonb;
  shares jsonb;
  activity_level text;
  simulated numeric;
begin
  select count(distinct uas.user_id) into active_players
  from public.user_activity_sessions uas
  where uas.last_seen_at >= now() - interval '7 days';

  select count(*) into transactions_count
  from public.transactions t
  where t.created_at >= now() - interval '7 days';

  select count(*) into active_businesses
  from public.businesses b
  where b.status = 'active'
    and b.updated_at >= now() - interval '14 days';

  select count(*) into employment_actions
  from public.economic_events e
  where e.event_type in ('employee_hired', 'employee_dismissed')
    and e.occurred_at_real >= now() - interval '7 days';

  score := coalesce(active_players, 0)
    + least(coalesce(transactions_count, 0), 300) * .18
    + coalesce(active_businesses, 0) * 4
    + coalesce(employment_actions, 0) * 2;

  thresholds := economy_private.calibration_json(
    'activity_thresholds',
    '{"very_low":15,"low":40,"medium":90,"high":180}'::jsonb
  );
  shares := economy_private.calibration_json(
    'simulated_share_levels',
    '{"very_low":0.80,"low":0.70,"medium":0.50,"high":0.30,"very_high":0.15}'::jsonb
  );

  activity_level := case
    when score < coalesce((thresholds->>'very_low')::numeric, 15) then 'very_low'
    when score < coalesce((thresholds->>'low')::numeric, 40) then 'low'
    when score < coalesce((thresholds->>'medium')::numeric, 90) then 'medium'
    when score < coalesce((thresholds->>'high')::numeric, 180) then 'high'
    else 'very_high'
  end;

  simulated := coalesce((shares->>activity_level)::numeric, .8);

  update public.economic_state
  set
    player_activity_level = activity_level,
    simulated_share = simulated,
    player_share = 1 - simulated,
    metadata = coalesce(metadata, '{}'::jsonb)
      || jsonb_build_object(
        'activity_score', round(score, 4),
        'active_players', active_players,
        'recent_transactions', transactions_count,
        'active_businesses', active_businesses,
        'employment_actions', employment_actions
      ),
    updated_at = now()
  where id = true;

  return jsonb_build_object(
    'level', activity_level,
    'score', round(score, 4),
    'simulated_share', simulated,
    'player_share', 1 - simulated
  );
end;
$$;


ALTER FUNCTION "economy_private"."update_activity_mix"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "economy_private"."update_confidence"("p_month_period_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  state_row public.economic_state%rowtype;
  inflation numeric;
  unemployment numeric;
  growth numeric;
  smoothing numeric := economy_private.calibration_numeric('confidence_smoothing',.3);
  consumer_target numeric;
  business_target numeric;
  consumer_next numeric;
  business_next numeric;
  consumer_shock numeric;
  business_shock numeric;
begin
  select * into state_row from public.economic_state where id=true;
  select nominal_value into inflation
  from public.economic_indicators where period_id=p_month_period_id and indicator_code='inflation_annual';
  select nominal_value into unemployment
  from public.economic_indicators where period_id=p_month_period_id and indicator_code='unemployment_rate';
  growth := coalesce(economy_private.latest_indicator('gdp_growth_quarterly'),0);
  consumer_shock := economy_private.active_shock_impact('consumer_confidence');
  business_shock := economy_private.active_shock_impact('business_confidence');

  consumer_target := economy_private.clamp(
    55
      + growth*1.8
      - greatest(coalesce(inflation,0)-state_row.inflation_target,0)*2.2
      - greatest(coalesce(unemployment,8.5)-8.5,0)*1.5
      + economy_private.active_policy_impact('consumer_confidence')
      + consumer_shock,
    0,100
  );
  business_target := economy_private.clamp(
    55
      + growth*2.2
      - greatest(state_row.current_selic-10,0)*1.1
      - greatest(coalesce(inflation,0)-state_row.inflation_target,0)*1.4
      + economy_private.active_policy_impact('business_confidence')
      + business_shock,
    0,100
  );
  consumer_next := economy_private.clamp(
    state_row.consumer_confidence*(1-smoothing)+consumer_target*smoothing,
    0,100
  );
  business_next := economy_private.clamp(
    state_row.business_confidence*(1-smoothing)+business_target*smoothing,
    0,100
  );

  update public.economic_state
  set
    consumer_confidence=consumer_next,
    business_confidence=business_next,
    updated_at=now()
  where id=true;

  perform economy_private.upsert_indicator(
    p_month_period_id,'consumer_confidence',
    consumer_next,consumer_next,consumer_next-state_row.consumer_confidence,
    'index','{}'::jsonb
  );
  perform economy_private.upsert_indicator(
    p_month_period_id,'business_confidence',
    business_next,business_next,business_next-state_row.business_confidence,
    'index','{}'::jsonb
  );

  return jsonb_build_object(
    'consumer_confidence',round(consumer_next,4),
    'business_confidence',round(business_next,4)
  );
end;
$$;


ALTER FUNCTION "economy_private"."update_confidence"("p_month_period_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "economy_private"."upsert_indicator"("p_period_id" "uuid", "p_code" "text", "p_nominal" numeric, "p_real" numeric, "p_variation" numeric, "p_unit" "text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_status" "text" DEFAULT 'official'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  indicator_id uuid;
begin
  insert into public.economic_indicators (
    period_id,
    indicator_code,
    nominal_value,
    real_value,
    variation,
    unit,
    status,
    metadata,
    engine_version
  )
  values (
    p_period_id,
    p_code,
    p_nominal,
    p_real,
    p_variation,
    p_unit,
    p_status,
    coalesce(p_metadata, '{}'::jsonb),
    '1.0.0'
  )
  on conflict (period_id, indicator_code) do update set
    nominal_value = excluded.nominal_value,
    real_value = excluded.real_value,
    variation = excluded.variation,
    unit = excluded.unit,
    status = excluded.status,
    metadata = excluded.metadata,
    engine_version = excluded.engine_version
  returning id into indicator_id;

  return indicator_id;
end;
$$;


ALTER FUNCTION "economy_private"."upsert_indicator"("p_period_id" "uuid", "p_code" "text", "p_nominal" numeric, "p_real" numeric, "p_variation" numeric, "p_unit" "text", "p_metadata" "jsonb", "p_status" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."case_evidence" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "investigation_id" "uuid",
    "criminal_case_id" "uuid",
    "parent_evidence_id" "uuid",
    "version" integer DEFAULT 1 NOT NULL,
    "evidence_type" "text" NOT NULL,
    "title" "text" NOT NULL,
    "description" "text",
    "file_url" "text",
    "submitted_by" "uuid" NOT NULL,
    "collected_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "sealed_at" timestamp with time zone,
    "evidence_hash" "text",
    "status" "public"."justice_evidence_status" DEFAULT 'draft'::"public"."justice_evidence_status" NOT NULL,
    "confidentiality_level" "text" DEFAULT 'restricted'::"text" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "case_evidence_check" CHECK ((("investigation_id" IS NOT NULL) OR ("criminal_case_id" IS NOT NULL))),
    CONSTRAINT "case_evidence_confidentiality_level_check" CHECK (("confidentiality_level" = ANY (ARRAY['public'::"text", 'restricted'::"text", 'confidential'::"text", 'secret'::"text"]))),
    CONSTRAINT "case_evidence_version_check" CHECK (("version" > 0))
);


ALTER TABLE "public"."case_evidence" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_case_evidence"("p_investigation_id" "uuid", "p_case_id" "uuid", "p_evidence_type" "text", "p_title" "text", "p_description" "text", "p_file_url" "text" DEFAULT NULL::"text", "p_confidentiality_level" "text" DEFAULT 'restricted'::"text") RETURNS "public"."case_evidence"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.case_evidence%rowtype;
begin
  if (select auth.uid()) is null then raise exception 'AUTHENTICATION_REQUIRED'; end if;
  if p_investigation_id is null and p_case_id is null then raise exception 'EVIDENCE_CONTEXT_REQUIRED'; end if;
  if p_investigation_id is not null
     and not public.justice_can_access_investigation(p_investigation_id) then
    raise exception 'INVESTIGATION_ACCESS_DENIED';
  end if;
  if p_case_id is not null and not public.justice_can_access_case(p_case_id) then
    raise exception 'CASE_ACCESS_DENIED';
  end if;
  if length(trim(coalesce(p_title, ''))) < 5 then raise exception 'EVIDENCE_TITLE_TOO_SHORT'; end if;
  if length(trim(coalesce(p_description, ''))) < 10 and p_file_url is null then
    raise exception 'EVIDENCE_CONTENT_REQUIRED';
  end if;

  insert into public.case_evidence(
    investigation_id, criminal_case_id, evidence_type, title, description,
    file_url, submitted_by, status, confidentiality_level
  )
  values (
    p_investigation_id, p_case_id, trim(p_evidence_type), trim(p_title),
    nullif(trim(p_description), ''), nullif(trim(p_file_url), ''),
    (select auth.uid()), 'collected', p_confidentiality_level
  )
  returning * into v_row;

  insert into public.evidence_custody_events(
    evidence_id, event_type, actor_id, justification
  )
  values (
    v_row.id, 'created', (select auth.uid()), 'Prova adicionada ao procedimento'
  );

  perform public.justice_write_audit(
    'evidence.created', 'case_evidence', v_row.id,
    null, to_jsonb(v_row), 'Prova adicionada ao procedimento'
  );
  return v_row;
end;
$$;


ALTER FUNCTION "public"."add_case_evidence"("p_investigation_id" "uuid", "p_case_id" "uuid", "p_evidence_type" "text", "p_title" "text", "p_description" "text", "p_file_url" "text", "p_confidentiality_level" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."investigation_parties" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "investigation_id" "uuid" NOT NULL,
    "profile_id" "uuid" NOT NULL,
    "party_type" "text" NOT NULL,
    "notes" "text",
    "is_confidential" boolean DEFAULT false NOT NULL,
    "added_by" "uuid" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "investigation_parties_party_type_check" CHECK (("party_type" = ANY (ARRAY['suspect'::"text", 'victim'::"text", 'witness'::"text", 'reporter'::"text", 'officer'::"text", 'expert'::"text"])))
);


ALTER TABLE "public"."investigation_parties" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_investigation_party"("p_investigation_id" "uuid", "p_profile_id" "uuid", "p_party_type" "text", "p_notes" "text" DEFAULT NULL::"text", "p_is_confidential" boolean DEFAULT false) RETURNS "public"."investigation_parties"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.investigation_parties%rowtype;
begin
  if not public.justice_has_role(array['Admin', 'Policial', 'Police', 'Delegado', 'Promotor']) then
    raise exception 'ROLE_NOT_AUTHORIZED';
  end if;
  if not exists (
    select 1 from public.criminal_investigations
    where id = p_investigation_id and status not in ('archived', 'closed')
  ) then raise exception 'INVESTIGATION_NOT_OPEN'; end if;

  insert into public.investigation_parties(
    investigation_id, profile_id, party_type, notes, is_confidential, added_by
  )
  values (
    p_investigation_id, p_profile_id, p_party_type, nullif(trim(p_notes), ''),
    p_is_confidential, (select auth.uid())
  )
  returning * into v_row;

  insert into public.investigation_events(
    investigation_id, event_type, title, description, actor_id, rp_occurred_at,
    metadata
  )
  values (
    p_investigation_id, 'party_added', 'Participante adicionado à investigação',
    p_party_type, (select auth.uid()), public.rp_now(),
    jsonb_build_object('profile_id', p_profile_id, 'party_type', p_party_type)
  );

  perform public.justice_write_audit(
    'investigation.party_added', 'criminal_investigation', p_investigation_id,
    null, to_jsonb(v_row), coalesce(p_notes, 'Participante adicionado')
  );

  if p_party_type in ('suspect', 'victim', 'witness') and not p_is_confidential then
    perform public.justice_notify(
      p_profile_id, 'justice_investigation_party',
      'Você foi incluído em uma investigação como ' || p_party_type || '.',
      '/services/justice?view=citizen',
      jsonb_build_object('investigation_id', p_investigation_id, 'party_type', p_party_type)
    );
  end if;

  return v_row;
end;
$$;


