CREATE OR REPLACE FUNCTION "public"."admin_change_user_password"("p_user_id" "uuid", "p_new_password" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Checar se a requisição tem mínimo padrão de segurança (pode ser expandido conforme política)
    IF length(p_new_password) < 6 THEN
        RETURN '{"success": false, "message": "A senha deve conter ao menos 6 caracteres"}'::jsonb;
    END IF;

    UPDATE auth.users 
    SET encrypted_password = crypt(p_new_password, gen_salt('bf')) 
    WHERE id = p_user_id;
    
    RETURN '{"success": true, "message": "Senha do usuário atualizada com sucesso!"}'::jsonb;
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', 'Erro crasso no sistema de credenciais: ' || SQLERRM);
END;
$$;


