CREATE OR REPLACE FUNCTION "public"."admin_forgive_debt"("p_user_id" "uuid", "p_debt_type" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
    admin_user_id UUID := auth.uid();
BEGIN
    IF (SELECT role FROM public.profiles WHERE id = admin_user_id) <> 'Admin' THEN
        RETURN json_build_object('success', false, 'message', 'Apenas administradores podem executar esta ação.');
    END IF;

    IF p_debt_type = 'loans' THEN
        UPDATE public.loans SET amount = 0, interest_paid = 0, status = 'Pago' WHERE user_id = p_user_id AND status = 'Ativo';
        RETURN json_build_object('success', true, 'message', 'Todos os empréstimos ativos do usuário foram perdoados.');
    ELSIF p_debt_type = 'invoices' THEN
        UPDATE public.invoices SET status = 'Paga' WHERE user_id = p_user_id AND status = 'Pendente';
        RETURN json_build_object('success', true, 'message', 'Todas as faturas pendentes do usuário foram perdoadas.');
    ELSIF p_debt_type = 'gov_loans' THEN
        UPDATE public.government_finances SET loans_balance = 0 WHERE id = 1;
        RETURN json_build_object('success', true, 'message', 'A dívida de empréstimos do governo foi perdoada.');
    ELSE
        RETURN json_build_object('success', false, 'message', 'Tipo de dívida inválido.');
    END IF;

EXCEPTION
    WHEN others THEN
        RETURN json_build_object('success', false, 'message', 'Ocorreu um erro inesperado ao perdoar a dívida.');
END;
$$;


ALTER FUNCTION "public"."admin_forgive_debt"("p_user_id" "uuid", "p_debt_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_forgive_debt"("p_target_type" "text", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_loan_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
    admin_user_id UUID := auth.uid();
BEGIN
    IF (SELECT role FROM public.profiles WHERE id = admin_user_id) <> 'Admin' THEN
        RETURN json_build_object('success', false, 'message', 'Apenas administradores podem executar esta ação.');
    END IF;

    IF p_target_type = 'government' THEN
        UPDATE public.government_finances SET loans_balance = 0 WHERE id = 1;
        RETURN json_build_object('success', true, 'message', 'Dívida de empréstimos do governo perdoada.');
    ELSIF p_target_type = 'user' THEN
        IF p_loan_id IS NULL THEN
            RETURN json_build_object('success', false, 'message', 'ID do empréstimo do usuário é necessário.');
        END IF;
        
        UPDATE public.loans SET status = 'Perdoado', amount = 0 WHERE id = p_loan_id AND user_id = p_user_id;
        
        IF NOT FOUND THEN
            RETURN json_build_object('success', false, 'message', 'Empréstimo não encontrado para o usuário especificado.');
        END IF;

        RETURN json_build_object('success', true, 'message', 'Dívida do usuário perdoada com sucesso.');
    ELSE
        RETURN json_build_object('success', false, 'message', 'Tipo de alvo inválido. Use "government" ou "user".');
    END IF;
EXCEPTION
    WHEN others THEN
        RETURN json_build_object('success', false, 'message', 'Ocorreu um erro inesperado.');
END;
$$;


ALTER FUNCTION "public"."admin_forgive_debt"("p_target_type" "text", "p_user_id" "uuid", "p_loan_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_forgive_debt"("p_target_type" "text", "p_user_id" "uuid" DEFAULT NULL::"uuid", "p_loan_id" "uuid" DEFAULT NULL::"uuid", "p_amount" numeric DEFAULT NULL::numeric) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
    admin_user_id UUID := auth.uid();
    current_debt NUMERIC;
BEGIN
    IF (SELECT role FROM public.profiles WHERE id = admin_user_id) <> 'Admin' THEN
        RETURN json_build_object('success', false, 'message', 'Apenas administradores podem executar esta ação.');
    END IF;

    IF p_target_type = 'government' THEN
        SELECT loans_balance INTO current_debt FROM public.government_finances WHERE id = 1;

        IF p_amount IS NOT NULL THEN
             IF p_amount <= 0 THEN
                RETURN json_build_object('success', false, 'message', 'O valor a abater deve ser positivo.');
            END IF;
             IF p_amount > current_debt THEN
                RETURN json_build_object('success', false, 'message', 'O valor a abater não pode ser maior que a dívida atual.');
            END IF;
            UPDATE public.government_finances SET loans_balance = loans_balance - p_amount WHERE id = 1;
            RETURN json_build_object('success', true, 'message', 'Valor de ' || format_currency_brl(p_amount) || ' abatido da dívida do governo.');
        ELSE
            UPDATE public.government_finances SET loans_balance = 0 WHERE id = 1;
            RETURN json_build_object('success', true, 'message', 'Dívida de empréstimos do governo totalmente perdoada.');
        END IF;

    ELSIF p_target_type = 'user' THEN
        IF p_loan_id IS NULL THEN
            RETURN json_build_object('success', false, 'message', 'ID do empréstimo do usuário é necessário.');
        END IF;
        
        UPDATE public.loans SET status = 'Perdoado', amount = 0 WHERE id = p_loan_id AND user_id = p_user_id;
        
        IF NOT FOUND THEN
            RETURN json_build_object('success', false, 'message', 'Empréstimo não encontrado para o usuário especificado.');
        END IF;

        RETURN json_build_object('success', true, 'message', 'Dívida do usuário perdoada com sucesso.');
    ELSE
        RETURN json_build_object('success', false, 'message', 'Tipo de alvo inválido. Use "government" ou "user".');
    END IF;
EXCEPTION
    WHEN others THEN
        RETURN json_build_object('success', false, 'message', 'Ocorreu um erro inesperado.');
END;
$$;


ALTER FUNCTION "public"."admin_forgive_debt"("p_target_type" "text", "p_user_id" "uuid", "p_loan_id" "uuid", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_get_all_users"() RETURNS TABLE("id" "uuid", "full_name" "text", "username" "text", "email" "text", "role" "text", "titles" "text"[], "x_handle" "text", "has_bank_account" boolean, "balance" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Garante que somente administradores possam chamar
    IF NOT EXISTS (
        SELECT 1 FROM profiles
        WHERE profiles.id = (SELECT auth.uid())
          AND profiles.role = 'Admin'
    ) THEN
        RAISE EXCEPTION 'Acesso negado. Somente administradores podem executar esta função.';
    END IF;

    RETURN QUERY
    SELECT
        p.id,
        p.full_name,
        p.username,
        p.email,
        p.role,
        p.titles,
        p.x_handle,
        (a.id IS NOT NULL) AS has_bank_account,
        a.balance
    FROM profiles p
    LEFT JOIN accounts a ON p.id = a.user_id;
END;
$$;


ALTER FUNCTION "public"."admin_get_all_users"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_modify_balance"("p_user_id" "uuid", "p_amount" numeric, "p_action" "text", "p_reason" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
    admin_user_id UUID := auth.uid();
    target_account RECORD;
    admin_profile RECORD;
BEGIN
    -- Check if the calling user is an admin
    SELECT * INTO admin_profile FROM public.profiles WHERE id = admin_user_id AND role = 'Admin';
    IF admin_profile IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Apenas administradores podem executar esta ação.');
    END IF;

    -- Find the target user's account
    SELECT * INTO target_account FROM public.accounts WHERE user_id = p_user_id;
    IF target_account IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Conta bancária do usuário não encontrada.');
    END IF;

    -- Perform the balance modification
    IF p_action = 'add' THEN
        UPDATE public.accounts SET balance = balance + p_amount WHERE id = target_account.id;
        
        INSERT INTO public.transactions(to_account_id, amount, description, type)
        VALUES (target_account.id, p_amount, 'Crédito administrativo: ' || p_reason, 'admin_credit');

    ELSIF p_action = 'remove' THEN
        IF target_account.balance < p_amount THEN
            RETURN json_build_object('success', false, 'message', 'Saldo do usuário insuficiente para a remoção.');
        END IF;
        UPDATE public.accounts SET balance = balance - p_amount WHERE id = target_account.id;

        INSERT INTO public.transactions(from_account_id, amount, description, type)
        VALUES (target_account.id, p_amount, 'Débito administrativo: ' || p_reason, 'admin_debit');

    ELSE
        RETURN json_build_object('success', false, 'message', 'Ação inválida. Use "add" ou "remove".');
    END IF;

    RETURN json_build_object('success', true, 'message', 'Saldo do usuário modificado com sucesso.');
EXCEPTION
    WHEN others THEN
        RETURN json_build_object('success', false, 'message', 'Ocorreu um erro inesperado.');
END;
$$;


ALTER FUNCTION "public"."admin_modify_balance"("p_user_id" "uuid", "p_amount" numeric, "p_action" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_modify_currency_balance"("p_user_id" "uuid", "p_currency_code" "text", "p_amount" numeric, "p_action" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
    admin_user_id UUID := auth.uid();
    target_account RECORD;
BEGIN
    IF (SELECT role FROM public.profiles WHERE id = admin_user_id) <> 'Admin' THEN
        RETURN json_build_object('success', false, 'message', 'Apenas administradores podem executar esta ação.');
    END IF;

    SELECT * INTO target_account FROM public.accounts WHERE user_id = p_user_id;
    IF target_account IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Conta bancária do usuário não encontrada.');
    END IF;

    IF p_action = 'set' THEN
        UPDATE public.accounts 
        SET currency_balances = jsonb_set(COALESCE(currency_balances, '{}'), ARRAY[p_currency_code], to_jsonb(p_amount))
        WHERE id = target_account.id;
    ELSE
        RETURN json_build_object('success', false, 'message', 'Ação inválida. Use "set".');
    END IF;

    RETURN json_build_object('success', true, 'message', 'Saldo em moeda estrangeira do usuário modificado com sucesso.');
END;
$$;


ALTER FUNCTION "public"."admin_modify_currency_balance"("p_user_id" "uuid", "p_currency_code" "text", "p_amount" numeric, "p_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_modify_investments"("p_user_id" "uuid", "p_amount" numeric, "p_action" "text", "p_reason" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
    admin_user_id UUID := auth.uid();
    total_invested NUMERIC;
BEGIN
    IF (SELECT role FROM public.profiles WHERE id = admin_user_id) <> 'Admin' THEN
        RETURN json_build_object('success', false, 'message', 'Apenas administradores podem executar esta ação.');
    END IF;

    SELECT COALESCE(SUM(amount_invested), 0) INTO total_invested FROM public.user_investments WHERE user_id = p_user_id;

    IF p_action = 'add' THEN
        -- Simply add a new "manual" investment record
        INSERT INTO public.user_investments (user_id, investment_id, amount_invested, is_active)
        -- Using a placeholder UUID for a 'manual adjustment' investment type
        VALUES (p_user_id, '00000000-0000-0000-0000-000000000001', p_amount, true);
    ELSIF p_action = 'remove' THEN
        IF total_invested < p_amount THEN
            RETURN json_build_object('success', false, 'message', 'Saldo de investimento insuficiente para a remoção.');
        END IF;
        -- Create a negative investment to balance it out
        INSERT INTO public.user_investments (user_id, investment_id, amount_invested, is_active)
        VALUES (p_user_id, '00000000-0000-0000-0000-000000000001', -p_amount, true);
    ELSIF p_action = 'set' THEN
         -- Delete all existing investments and create a new one with the target amount
        DELETE FROM public.user_investments WHERE user_id = p_user_id;
        IF p_amount > 0 THEN
            INSERT INTO public.user_investments (user_id, investment_id, amount_invested, is_active)
            VALUES (p_user_id, '00000000-0000-0000-0000-000000000001', p_amount, true);
        END IF;
    ELSE
        RETURN json_build_object('success', false, 'message', 'Ação inválida. Use "add", "remove" ou "set".');
    END IF;

    RETURN json_build_object('success', true, 'message', 'Investimentos do usuário modificados com sucesso.');
END;
$$;


ALTER FUNCTION "public"."admin_modify_investments"("p_user_id" "uuid", "p_amount" numeric, "p_action" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_modify_treasury"("p_amount" numeric, "p_action" "text", "p_reason" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $$
DECLARE
    admin_user_id UUID := auth.uid();
BEGIN
    IF (SELECT role FROM public.profiles WHERE id = admin_user_id) <> 'Admin' THEN
        RETURN json_build_object('success', false, 'message', 'Apenas administradores podem executar esta ação.');
    END IF;

    IF p_action = 'add' THEN
        UPDATE public.government_finances SET treasury_balance = treasury_balance + p_amount WHERE id = 1;
    ELSIF p_action = 'remove' THEN
        IF (SELECT treasury_balance FROM public.government_finances WHERE id = 1) < p_amount THEN
            RETURN json_build_object('success', false, 'message', 'Saldo do cofre insuficiente para a remoção.');
        END IF;
        UPDATE public.government_finances SET treasury_balance = treasury_balance - p_amount WHERE id = 1;
    ELSIF p_action = 'set' THEN
        IF p_amount < 0 THEN
             RETURN json_build_object('success', false, 'message', 'O valor não pode ser negativo.');
        END IF;
        UPDATE public.government_finances SET treasury_balance = p_amount WHERE id = 1;
    ELSE
        RETURN json_build_object('success', false, 'message', 'Ação inválida. Use "add", "remove" ou "set".');
    END IF;

    RETURN json_build_object('success', true, 'message', 'Cofre do Governo modificado com sucesso.');
EXCEPTION
    WHEN others THEN
        RETURN json_build_object('success', false, 'message', 'Ocorreu um erro inesperado.');
END;
$$;


ALTER FUNCTION "public"."admin_modify_treasury"("p_amount" numeric, "p_action" "text", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_pay_invoice"("p_invoice_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    admin_user_id UUID := auth.uid();
    invoice_info RECORD;
BEGIN
    IF (SELECT role FROM public.profiles WHERE id = admin_user_id) <> 'Admin' THEN
        RETURN json_build_object('success', false, 'message', 'Apenas administradores podem executar esta ação.');
    END IF;

    SELECT * INTO invoice_info FROM public.card_invoices WHERE id = p_invoice_id;

    IF invoice_info IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Fatura não encontrada.');
    END IF;

    IF invoice_info.status = 'paid' THEN
        RETURN json_build_object('success', false, 'message', 'Esta fatura já foi paga.');
    END IF;

    -- Update card used limit
    UPDATE public.cards SET used_limit = GREATEST(0, used_limit - invoice_info.amount) WHERE id = invoice_info.card_id;

    -- Update invoice status
    UPDATE public.card_invoices SET status = 'paid', amount = 0, updated_at = now() WHERE id = p_invoice_id;

    RETURN json_build_object('success', true, 'message', 'Fatura quitada com sucesso em nome do usuário.');
EXCEPTION
    WHEN others THEN
        RETURN json_build_object('success', false, 'message', 'Ocorreu um erro inesperado.');
END;
$$;


ALTER FUNCTION "public"."admin_pay_invoice"("p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_pay_user_invoice"("p_invoice_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    admin_user_id UUID := auth.uid();
    invoice_details RECORD;
    gov_balance NUMERIC;
BEGIN
    IF (SELECT role FROM public.profiles WHERE id = admin_user_id) <> 'Admin' THEN
        RETURN json_build_object('success', false, 'message', 'Apenas administradores podem executar esta ação.');
    END IF;

    SELECT amount, status INTO invoice_details FROM public.invoices WHERE id = p_invoice_id;

    IF NOT FOUND THEN
        RETURN json_build_object('success', false, 'message', 'Fatura não encontrada.');
    END IF;

    IF invoice_details.status <> 'Pendente' THEN
        RETURN json_build_object('success', false, 'message', 'Esta fatura não está pendente de pagamento.');
    END IF;

    SELECT treasury_balance INTO gov_balance FROM public.government_finances WHERE id = 1;

    IF gov_balance < invoice_details.amount THEN
        RETURN json_build_object('success', false, 'message', 'Cofre do governo não tem saldo suficiente para pagar esta fatura.');
    END IF;

    -- Update government treasury
    UPDATE public.government_finances SET treasury_balance = treasury_balance - invoice_details.amount WHERE id = 1;

    -- Update invoice status
    UPDATE public.invoices SET status = 'Paga' WHERE id = p_invoice_id;

    RETURN json_build_object('success', true, 'message', 'Fatura paga com sucesso utilizando fundos do governo.');

EXCEPTION
    WHEN others THEN
        RETURN json_build_object('success', false, 'message', 'Ocorreu um erro inesperado ao pagar a fatura.');
END;
$$;


ALTER FUNCTION "public"."admin_pay_user_invoice"("p_invoice_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."admin_set_gov_card_limit"("p_new_limit" numeric) RETURNS json
