CREATE OR REPLACE FUNCTION "public"."admin_update_user"("p_user_id" "uuid", "p_full_name" "text", "p_username" "text", "p_role" "text", "p_titles" "text"[]) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    admin_user_id UUID := auth.uid();
    old_role TEXT;
BEGIN
    -- Check if the calling user is an admin
    IF (SELECT role FROM public.profiles WHERE id = admin_user_id) <> 'Admin' THEN
        RETURN json_build_object('success', false, 'message', 'Apenas administradores podem executar esta ação.');
    END IF;

    -- Get the old role before updating
    SELECT role INTO old_role FROM public.profiles WHERE id = p_user_id;

    -- Update the user's profile
    UPDATE public.profiles
    SET
        full_name = p_full_name,
        username = p_username,
        role = p_role,
        titles = p_titles,
        updated_at = now()
    WHERE id = p_user_id;

    -- Manually call the sync function if the role has changed
    IF old_role IS DISTINCT FROM p_role THEN
        PERFORM public.sync_parliament_membership(p_user_id, p_role, old_role);
    END IF;

    RETURN json_build_object('success', true, 'message', 'Usuário atualizado com sucesso.');
EXCEPTION
    WHEN others THEN
        RETURN json_build_object('success', false, 'message', 'Ocorreu um erro inesperado ao atualizar o usuário: ' || SQLERRM);
END;
$$;


ALTER FUNCTION "public"."admin_update_user"("p_user_id" "uuid", "p_full_name" "text", "p_username" "text", "p_role" "text", "p_titles" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."appeal_fine"("p_fine_id" "uuid", "p_reason" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
BEGIN
    IF NOT EXISTS(SELECT 1 FROM public.police_fines WHERE id = p_fine_id AND user_id = current_user_id AND status = 'Pendente') THEN
        RETURN json_build_object('success', false, 'message', 'Multa não encontrada ou não pode ser contestada.');
    END IF;

    INSERT INTO public.prison_appeals (fine_id, user_id, reason)
    VALUES (p_fine_id, current_user_id, p_reason);
    
    UPDATE public.police_fines SET status = 'Em Recurso' WHERE id = p_fine_id;

    RETURN json_build_object('success', true, 'message', 'Recurso enviado com sucesso.');
END;
$$;


ALTER FUNCTION "public"."appeal_fine"("p_fine_id" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_economic_shock"("p_shock_type" "text", "p_title" "text", "p_description" "text", "p_origin" "text", "p_intensity" numeric, "p_duration_rp_months" numeric, "p_affected_sector_ids" "uuid"[], "p_impacts" "jsonb", "p_expected_consequences" "text"[], "p_justification" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  shock_id uuid;
  rp_start timestamptz := public.rp_now();
  rp_end timestamptz;
begin
  if auth.uid() is null or not public.economic_has_role(array['Admin']) then
    raise exception 'Apenas administradores podem criar choques.' using errcode='42501';
  end if;
  if p_intensity<=0 or p_intensity>1 or p_duration_rp_months<=0 or p_duration_rp_months>24 then
    raise exception 'Intensidade ou duração fora dos limites.';
  end if;
  if length(trim(coalesce(p_justification,'')))<20 then
    raise exception 'Justificativa insuficiente.';
  end if;
  rp_end := rp_start+make_interval(days=>round(p_duration_rp_months*365/12)::integer);
  insert into public.economic_shocks(
    shock_type,title,description,origin,intensity,
    starts_at_real,starts_at_rp,ends_at_real,ends_at_rp,
    affected_sector_ids,impacts,expected_consequences,status,
    created_by,justification
  )
  values (
    p_shock_type,trim(p_title),trim(p_description),p_origin,p_intensity,
    now(),rp_start,public.rp_date_to_real_date(rp_end),rp_end,
    coalesce(p_affected_sector_ids,array[]::uuid[]),coalesce(p_impacts,'{}'::jsonb),
    coalesce(p_expected_consequences,array[]::text[]),'active',
    auth.uid(),trim(p_justification)
  )
  returning id into shock_id;
  perform economy_private.audit('apply_economic_shock','economic_shock',shock_id::text,
    null,to_jsonb((select s from public.economic_shocks s where s.id=shock_id)),
    p_justification,auth.uid());
  return shock_id;
end;
$$;


ALTER FUNCTION "public"."apply_economic_shock"("p_shock_type" "text", "p_title" "text", "p_description" "text", "p_origin" "text", "p_intensity" numeric, "p_duration_rp_months" numeric, "p_affected_sector_ids" "uuid"[], "p_impacts" "jsonb", "p_expected_consequences" "text"[], "p_justification" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_policy_decision"("p_policy_type" "text", "p_new_value" numeric, "p_justification" "text", "p_market_expectation" numeric DEFAULT NULL::numeric, "p_effective_at_rp" timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  actor_id uuid := auth.uid();
  previous_value numeric;
  delta numeric;
  decision_id uuid;
  impacts jsonb;
  rp_effective timestamptz := coalesce(p_effective_at_rp,public.rp_now());
  real_effective timestamptz;
  authority_name text;
  item record;
  start_lag interval;
  peak_lag interval;
  end_lag interval;
begin
  if actor_id is null then
    raise exception 'Autenticação obrigatória.' using errcode='42501';
  end if;
  if length(trim(coalesce(p_justification,'')))<20 then
    raise exception 'A justificativa deve possuir pelo menos 20 caracteres.';
  end if;
  if p_policy_type in ('selic','inflation_target','reserve_requirement','exchange_intervention') then
    if not public.economic_has_role(array[
      'Admin','Presidente','Presidente do Banco Central','Banco Central'
    ]) then
      raise exception 'Cargo sem competência monetária.' using errcode='42501';
    end if;
    authority_name := case
      when public.economic_has_role(array['Presidente do Banco Central','Banco Central'])
        then 'Banco Central'
      else 'Presidência'
    end;
  else
    if not public.economic_has_role(array[
      'Admin','Presidente','Ministro da Fazenda','Ministro da Economia','Ministro'
    ]) then
      raise exception 'Cargo sem competência fiscal.' using errcode='42501';
    end if;
    authority_name := 'Governo';
  end if;

  previous_value := case p_policy_type
    when 'selic' then (select current_selic from public.economic_state where id=true)
    when 'inflation_target' then (select inflation_target from public.economic_state where id=true)
    else coalesce((select new_value from public.economic_policy_decisions
      where policy_type=p_policy_type and status in ('announced','effective')
      order by announced_at_real desc limit 1),0)
  end;
  delta := p_new_value-previous_value;
  if p_new_value is null or p_new_value::text in ('NaN','Infinity','-Infinity') then
    raise exception 'Valor inválido.';
  end if;
  if p_policy_type in ('selic','inflation_target') and (p_new_value<0 or p_new_value>100) then
    raise exception 'Taxa fora do intervalo permitido.';
  end if;
  if p_policy_type='selic' and abs(delta)>5 then
    raise exception 'A Selic só pode variar até 5 pontos por decisão.';
  end if;
  if p_policy_type in ('consumption_tax','corporate_tax','income_tax','payroll_tax')
     and (p_new_value<0 or p_new_value>60 or abs(delta)>10) then
    raise exception 'Alteração tributária fora dos limites.';
  end if;

  real_effective := public.rp_date_to_real_date(rp_effective);
  impacts := economy_private.policy_impacts(p_policy_type,previous_value,p_new_value);

  update public.economic_policy_decisions
  set status='superseded'
  where policy_type=p_policy_type and status in ('announced','effective');

  insert into public.economic_policy_decisions(
    policy_type,authority,authority_profile_id,previous_value,new_value,
    value_unit,justification,announced_at_rp,effective_at_real,effective_at_rp,
    status,expected_impacts,market_expectation,surprise_index
  )
  values (
    p_policy_type,authority_name,actor_id,previous_value,p_new_value,
    case when p_policy_type='minimum_wage' then 'BRL' else 'percent' end,
    trim(p_justification),public.rp_now(),real_effective,rp_effective,
    case when rp_effective<=public.rp_now() then 'effective' else 'announced' end,
    impacts,p_market_expectation,
    case when p_market_expectation is null then 0 else p_new_value-p_market_expectation end
  )
  returning id into decision_id;

  for item in select key as effect_code,(value #>> '{}')::numeric as impact
              from jsonb_each(impacts)
              where jsonb_typeof(value)='number'
                and key not in ('previous_value','new_value','confidence')
  loop
    start_lag := case
      when item.effect_code in ('consumer_confidence','business_confidence','credit_percent') then interval '0'
      else interval '1 month'
    end;
    peak_lag := case
      when item.effect_code='inflation_points' then interval '6 months'
      when item.effect_code in ('output_percent','employment_percent') then interval '4 months'
      else interval '2 months'
    end;
    end_lag := case
      when item.effect_code='inflation_points' then interval '12 months'
      else interval '8 months'
    end;
    insert into public.economic_policy_effects(
      policy_decision_id,effect_code,total_impact,starts_at_rp,peaks_at_rp,ends_at_rp
    )
    values (
      decision_id,item.effect_code,item.impact,
      rp_effective+start_lag,rp_effective+peak_lag,rp_effective+end_lag
    );
  end loop;

  if p_policy_type='selic' and rp_effective<=public.rp_now() then
    update public.economic_state set current_selic=p_new_value,updated_at=now() where id=true;
  elsif p_policy_type='inflation_target' and rp_effective<=public.rp_now() then
    update public.economic_state set inflation_target=p_new_value,updated_at=now() where id=true;
  end if;

  perform economy_private.audit(
    'apply_policy_decision','economic_policy_decision',decision_id::text,
    jsonb_build_object('value',previous_value),
    jsonb_build_object('value',p_new_value,'impacts',impacts),
    p_justification,actor_id
  );
  perform economy_private.create_alert(
    'policy_'||decision_id::text,'info','Nova decisão econômica',
    format('%s alterada de %s para %s.',p_policy_type,previous_value,p_new_value),
    null,'economic_policy_decision',decision_id::text,
    jsonb_build_object('policy_type',p_policy_type)
  );
  return jsonb_build_object('decision_id',decision_id,'previous_value',previous_value,
    'new_value',p_new_value,'expected_impacts',impacts,'effective_at_rp',rp_effective);
end;
$$;


ALTER FUNCTION "public"."apply_policy_decision"("p_policy_type" "text", "p_new_value" numeric, "p_justification" "text", "p_market_expectation" numeric, "p_effective_at_rp" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."appoint_minister"("p_user_id" "uuid", "p_ministry" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    president_id UUID := auth.uid();
BEGIN
    IF (SELECT role FROM public.profiles WHERE id = president_id) NOT IN ('Presidente', 'Admin') THEN
        RETURN json_build_object('success', false, 'message', 'Apenas o presidente ou admin pode nomear ministros.');
    END IF;

    -- Remove o usuário de qualquer cargo de ministro anterior
    DELETE FROM public.ministers WHERE user_id = p_user_id;

    -- Insere o novo cargo
    INSERT INTO public.ministers (user_id, ministry) VALUES (p_user_id, p_ministry);

    -- Atualiza o cargo do usuário na tabela de perfis
    UPDATE public.profiles SET role = 'Ministro' WHERE id = p_user_id;

    RETURN json_build_object('success', true, 'message', 'Ministro nomeado com sucesso.');
EXCEPTION
    WHEN others THEN
        RETURN json_build_object('success', false, 'message', 'Ocorreu um erro ao nomear o ministro.');
END;
$$;


ALTER FUNCTION "public"."appoint_minister"("p_user_id" "uuid", "p_ministry" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_candidacy"("p_candidate_id" "uuid", "p_feedback" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    candidate_info RECORD;
BEGIN
    IF get_user_role(auth.uid()) <> 'Admin' THEN
        RETURN json_build_object('success', false, 'message', 'Apenas administradores podem aprovar candidaturas.');
    END IF;
    
    UPDATE public.candidates
    SET status = 'Approved', admin_feedback = p_feedback
    WHERE id = p_candidate_id AND status = 'Pendente'
    RETURNING * INTO candidate_info;
    
    IF FOUND THEN
        INSERT INTO public.notifications(user_id, type, content, link)
        VALUES(candidate_info.user_id, 'candidacy_approved', 'Sua candidatura para ' || (SELECT name FROM elections WHERE id = candidate_info.election_id) || ' foi APROVADA.', '/services/elections');
        RETURN json_build_object('success', true, 'message', 'Candidatura aprovada com sucesso.');
    ELSE
        RETURN json_build_object('success', false, 'message', 'Candidatura não encontrada ou já processada.');
    END IF;
END;
$$;


ALTER FUNCTION "public"."approve_candidacy"("p_candidate_id" "uuid", "p_feedback" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_credit_card_application"("p_application_id" "uuid", "p_card_limit" numeric DEFAULT NULL::numeric, "p_brand" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  application_record public.credit_card_applications%rowtype;
  account_id_value uuid;
  approved_limit_value numeric(14, 2);
  approved_brand_value text;
  holder_name_value text;
  created_card_id uuid;
  policy_value jsonb;
  policy_default_limit numeric(14, 2);
begin
  if (select auth.uid()) is null or not public.is_national_bank_manager() then
    return jsonb_build_object(
      'success',
      false,
      'message',
      'Apenas o Banco Nacional pode aprovar cartões.'
    );
  end if;

  select *
  into application_record
  from public.credit_card_applications
  where id = p_application_id
  for update;

  if not found then
    return jsonb_build_object(
      'success',
      false,
      'message',
      'Solicitação de cartão não encontrada.'
    );
  end if;

  if application_record.status not in ('Pendente', 'pending') then
    return jsonb_build_object(
      'success',
      false,
      'message',
      'Esta solicitação já foi analisada.'
    );
  end if;

  select account.id
  into account_id_value
  from public.accounts as account
  where account.user_id = application_record.user_id
  order by account.id
  limit 1;

  if account_id_value is null then
    return jsonb_build_object(
      'success',
      false,
      'message',
      'O usuário precisa ter conta bancária para receber cartão.'
    );
  end if;

  select coalesce(
    nullif(btrim(profile.full_name), ''),
    nullif(btrim(profile.username), '')
  )
  into holder_name_value
  from public.profiles as profile
  where profile.id = application_record.user_id;

  holder_name_value := upper(coalesce(holder_name_value, 'CLIENTE GOV.RP'));
  approved_brand_value := public.normalize_card_brand(
    coalesce(nullif(btrim(p_brand), ''), application_record.brand, 'visa')
  );

  policy_value := public.get_bank_policy();
  begin
    policy_default_limit :=
      nullif(policy_value ->> 'credit_card_default_limit', '')::numeric;
  exception
    when invalid_text_representation then
      policy_default_limit := 5000;
  end;

  approved_limit_value := greatest(
    100,
    coalesce(
      nullif(p_card_limit, 0),
      nullif(application_record.requested_limit, 0),
      policy_default_limit,
      5000
    )
  );

  insert into public.cards (
    user_id,
    account_id,
    card_number,
    card_holder_name,
    expiry_date,
    cvv,
    type,
    card_type,
    brand,
    card_limit,
    used_limit,
    closing_day,
    due_day,
    is_active,
    created_at
  )
  values (
    application_record.user_id,
    account_id_value,
    public.generate_card_number(),
    holder_name_value,
    to_char(now() + interval '4 years', 'MM/YY'),
    lpad(floor(random() * 1000)::integer::text, 3, '0'),
    'credit',
    'credit',
    approved_brand_value,
    approved_limit_value,
    0,
    25,
    5,
    true,
    now()
  )
  returning id into created_card_id;

  update public.credit_card_applications
  set
    status = 'Aprovado',
    approved_limit = approved_limit_value,
    approved_brand = approved_brand_value,
    reviewed_by = (select auth.uid()),
    reviewed_at = now(),
    updated_at = now(),
    admin_feedback = coalesce(
      admin_feedback,
      'Cartão aprovado pelo Banco Nacional.'
    )
  where id = application_record.id;

  insert into public.notifications (
    user_id,
    type,
    content,
    link,
    is_read,
    metadata,
    created_at
  )
  values (
    application_record.user_id,
    'bank_credit_review',
    'Seu cartão de crédito foi aprovado pelo Banco Nacional.',
    '/services/bank',
    false,
    jsonb_build_object(
      'application_id',
      application_record.id,
      'card_id',
      created_card_id,
      'approved_limit',
      approved_limit_value,
      'brand',
      approved_brand_value
    ),
    now()
  );

  return jsonb_build_object(
    'success',
    true,
    'message',
    'Cartão aprovado e emitido com sucesso.',
    'card_id',
    created_card_id,
    'card_holder_name',
    holder_name_value
  );
end;
$$;


ALTER FUNCTION "public"."approve_credit_card_application"("p_application_id" "uuid", "p_card_limit" numeric, "p_brand" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_government_project"("p_project_id" "uuid", "p_justification" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare project_row public.government_projects%rowtype;
  treasury numeric;
begin
  if auth.uid() is null or not public.economic_has_role(array['Admin','Presidente']) then
    raise exception 'Aprovação restrita à Presidência ou Administração.' using errcode='42501';
  end if;
  select * into project_row from public.government_projects where id=p_project_id for update;
  if not found or project_row.status not in ('proposed','pending_parliament') then
    raise exception 'Projeto não está disponível para aprovação.';
  end if;
  select treasury_balance into treasury from public.government_finances where id=1 for update;
  if treasury<project_row.approved_budget then
    raise exception 'Tesouro sem recursos para reservar o orçamento.';
  end if;
  update public.government_projects
  set status='funded',reserved_amount=approved_budget,approved_by=auth.uid(),
      approved_at=now(),started_at=now(),updated_at=now()
  where id=p_project_id;
  update public.government_finances
  set treasury_balance=treasury_balance-project_row.approved_budget,updated_at=now()
  where id=1;
  perform economy_private.audit('approve_government_project','government_project',p_project_id::text,
    to_jsonb(project_row),to_jsonb((select p from public.government_projects p where p.id=p_project_id)),
    p_justification,auth.uid());
  return jsonb_build_object('project_id',p_project_id,'status','funded',
    'reserved_amount',project_row.approved_budget);
end;
$$;


ALTER FUNCTION "public"."approve_government_project"("p_project_id" "uuid", "p_justification" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_loan_application"("p_application_id" "uuid", "p_installments" integer DEFAULT 12, "p_feedback" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog', 'public', 'auth'
    AS $_$
declare
  application_record public.loan_applications%rowtype;
  account_record public.accounts%rowtype;
  bank_policy jsonb := '{}'::jsonb;
  installment_count integer := greatest(1, least(120, coalesce(p_installments, 12)));
  monthly_rate numeric := 2.5;
  total_due_value numeric;
begin
  if not public.is_national_bank_manager() then
    return jsonb_build_object('success', false, 'message', 'Apenas o Banco Nacional pode aprovar empréstimos.');
  end if;

  select * into application_record
  from public.loan_applications
  where id = p_application_id
  for update;

  if not found then
    return jsonb_build_object('success', false, 'message', 'Solicitação de empréstimo não encontrada.');
  end if;

  if application_record.status not in ('Pendente', 'pending') then
    return jsonb_build_object('success', false, 'message', 'Esta solicitação já foi analisada.');
  end if;

  select * into account_record
  from public.accounts
  where user_id = application_record.user_id
  order by id
  limit 1
  for update;

  if not found then
    return jsonb_build_object('success', false, 'message', 'O usuário precisa ter conta bancária para receber empréstimo.');
  end if;

  select coalesce(value::jsonb, '{}'::jsonb) into bank_policy
  from public.system_settings
  where key = 'bank_policy';

  if bank_policy ? 'loan_interest_rate'
     and (bank_policy->>'loan_interest_rate') ~ '^-?[0-9]+(\.[0-9]+)?$' then
    monthly_rate := greatest(0, (bank_policy->>'loan_interest_rate')::numeric);
  end if;

  total_due_value := round(
    greatest(0, coalesce(application_record.amount, 0)) * (1 + (monthly_rate / 100) * installment_count),
    2
  );

  update public.accounts
  set balance = coalesce(balance, 0) + greatest(0, coalesce(application_record.amount, 0))
  where id = account_record.id;

  update public.loan_applications
  set
    status = 'Aprovado',
    installments = installment_count,
    interest_rate = monthly_rate,
    total_due = total_due_value,
    feedback = p_feedback,
    admin_feedback = p_feedback,
    reviewed_by = auth.uid(),
    reviewed_at = now()
  where id = p_application_id;

  return jsonb_build_object('success', true, 'message', 'Empréstimo aprovado e creditado em conta.');
end;
$_$;


ALTER FUNCTION "public"."approve_loan_application"("p_application_id" "uuid", "p_installments" integer, "p_feedback" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."approve_plebiscite"("p_plebiscite_id" "uuid", "p_house_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    plebiscite_info RECORD;
BEGIN
    IF NOT (get_user_role(current_user_id) = ANY(ARRAY['Admin', 'Deputado', 'Senador'])) THEN
        RETURN json_build_object('success', false, 'message', 'Você não tem permissão para aprovar plebiscitos.');
    END IF;

    SELECT * INTO plebiscite_info FROM public.plebiscites WHERE id = p_plebiscite_id AND status = 'Pendente';

    IF plebiscite_info IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Plebiscito não encontrado ou já processado.');
    END IF;

    UPDATE public.plebiscites
    SET 
        status = 'Ativo',
        approved_by_house_id = p_house_id,
        start_date = now(),
        end_date = now() + interval '7 days'
    WHERE id = p_plebiscite_id;

    RETURN json_build_object('success', true, 'message', 'Plebiscito aprovado e enviado para votação popular.');
END;
$$;


ALTER FUNCTION "public"."approve_plebiscite"("p_plebiscite_id" "uuid", "p_house_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_parliament_commission_member"("p_commission_id" "uuid", "p_member_id" "uuid", "p_role" "text" DEFAULT 'member'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_commission record;
  v_member record;
  v_has_governance_access boolean;
  v_house_match boolean;
begin
  if v_user_id is null then
    raise exception 'É necessário estar autenticado.';
  end if;

  if p_role not in ('chair', 'vice_chair', 'member', 'reporter', 'secretary') then
    raise exception 'Função da comissão inválida.';
  end if;

  select pc.*
    into v_commission
    from public.parliament_commissions pc
   where pc.id = p_commission_id;

  if not found then
    raise exception 'Comissão não encontrada.';
  end if;

  select exists (
    select 1
      from public.parliament_commission_houses pch
     where pch.commission_id = p_commission_id
       and public.is_parliament_governance_manager(v_user_id, pch.house_id)
  )
    into v_has_governance_access;

  if not v_has_governance_access then
    raise exception 'Somente a mesa diretora pode compor a comissão.';
  end if;

  select *
    into v_member
    from public.parliament_members
   where id = p_member_id;

  if not found then
    raise exception 'Membro parlamentar não encontrado.';
  end if;

  select exists (
    select 1
      from public.parliament_commission_houses
     where commission_id = p_commission_id
       and house_id = v_member.house_id
  )
    into v_house_match;

  if not v_house_match then
    raise exception 'O parlamentar selecionado não pertence a uma Casa abrangida pela comissão.';
  end if;

  if p_role = 'reporter' then
    update public.parliament_commission_members
       set role = 'member'
     where commission_id = p_commission_id
       and role = 'reporter';

    update public.parliament_commissions
       set reporter_member_id = p_member_id
     where id = p_commission_id;
  end if;

  insert into public.parliament_commission_members (
    commission_id,
    member_id,
    role,
    appointed_by
  )
  values (
    p_commission_id,
    p_member_id,
    p_role,
    v_user_id
  )
  on conflict (commission_id, member_id) do update
    set role = excluded.role,
        appointed_by = excluded.appointed_by,
        appointed_at = now();

  return jsonb_build_object(
    'success', true,
    'message', 'Membro atribuído à comissão com sucesso.'
  );
end;
$$;


ALTER FUNCTION "public"."assign_parliament_commission_member"("p_commission_id" "uuid", "p_member_id" "uuid", "p_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."award_political_points"("p_user_id" "uuid", "p_event_type" "text", "p_related_id" "uuid", "p_related_title" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb", "p_points" integer DEFAULT NULL::integer) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_config jsonb := '{}'::jsonb;
  v_points integer := 0;
  v_event_id uuid;
  v_event_label text;
begin
  if p_user_id is null or p_related_id is null or coalesce(trim(p_event_type), '') = '' then
    return jsonb_build_object(
      'success', false,
      'awarded', false,
      'message', 'Parametros invalidos para contabilizar Pontos Politicos.'
    );
  end if;

  select value
    into v_config
  from public.system_settings
  where key = 'political_points_config';

  v_points := coalesce(
    p_points,
    nullif(v_config ->> p_event_type, '')::integer,
    0
  );

  if v_points <= 0 then
    return jsonb_build_object(
      'success', false,
      'awarded', false,
      'message', 'A configuracao de Pontos Politicos para este evento e invalida.'
    );
  end if;

  v_event_label := case p_event_type
    when 'election_win' then 'vencer uma eleicao'
    when 'bill_approved' then 'ter um projeto aprovado'
    when 'plebiscite_approved' then 'ter um plebiscito aprovado'
    else 'um ato politico relevante'
  end;

  insert into public.political_point_events (
    user_id,
    event_type,
    related_id,
    related_title,
    points,
    metadata
  )
  values (
    p_user_id,
    p_event_type,
    p_related_id,
    p_related_title,
    v_points,
    coalesce(p_metadata, '{}'::jsonb)
  )
  on conflict (user_id, event_type, related_id) do nothing
  returning id
    into v_event_id;

  if v_event_id is null then
    return jsonb_build_object(
      'success', true,
      'awarded', false,
      'message', 'Os Pontos Politicos ja foram contabilizados para este evento.'
    );
  end if;

  update public.profiles
  set
    political_points = coalesce(political_points, 0) + v_points,
    updated_at = now()
  where id = p_user_id;

  insert into public.notifications (
    user_id,
    content,
    link,
    is_read,
    created_at,
    type,
    metadata
  )
  values (
    p_user_id,
    format('Voce recebeu %s PP por %s.', v_points, v_event_label),
    '/dashboard/citizen',
    false,
    now(),
    'political_points_awarded',
    jsonb_build_object(
      'event_type', p_event_type,
      'points', v_points,
      'related_id', p_related_id,
      'related_title', p_related_title
    )
  );

  return jsonb_build_object(
    'success', true,
    'awarded', true,
    'points', v_points,
    'message', format('Foram adicionados %s Pontos Politicos ao usuario.', v_points)
  );
end;
$$;


ALTER FUNCTION "public"."award_political_points"("p_user_id" "uuid", "p_event_type" "text", "p_related_id" "uuid", "p_related_title" "text", "p_metadata" "jsonb", "p_points" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."buy_business_listing"("p_listing_type" "text", "p_listing_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_buyer_id uuid := auth.uid();
  v_buyer_account public.accounts%rowtype;
  v_seller_account public.accounts%rowtype;
  v_business public.businesses%rowtype;
  v_enterprise public.state_enterprises%rowtype;
  v_finance public.government_finances%rowtype;
  v_price numeric(14,2);
  v_new_business_id uuid;
  v_business_type_id text;
begin
  if v_buyer_id is null then
    return jsonb_build_object('success', false, 'message', 'Sessao invalida.');
  end if;

  select * into v_buyer_account
  from public.accounts
  where user_id = v_buyer_id
  for update;

  if v_buyer_account.id is null then
    return jsonb_build_object('success', false, 'message', 'Voce precisa ter conta bancaria para comprar empresas.');
  end if;

  if p_listing_type = 'private' then
    select * into v_business
    from public.businesses
    where id = p_listing_id
      and is_for_sale = true
    for update;

    if v_business.id is null then
      return jsonb_build_object('success', false, 'message', 'Empresa privada nao encontrada ou nao esta mais a venda.');
    end if;

    if v_business.owner_id = v_buyer_id then
      return jsonb_build_object('success', false, 'message', 'Voce nao pode comprar a propria empresa.');
    end if;

    v_price := coalesce(v_business.sale_price, 0);
    if v_price <= 0 then
      return jsonb_build_object('success', false, 'message', 'Preco de venda invalido.');
    end if;

    if coalesce(v_buyer_account.balance, 0) < v_price then
      return jsonb_build_object('success', false, 'message', 'Saldo insuficiente para comprar esta empresa.');
    end if;

    select * into v_seller_account
    from public.accounts
    where user_id = v_business.owner_id
    for update;

    if v_seller_account.id is null then
      return jsonb_build_object('success', false, 'message', 'Conta bancaria do vendedor nao encontrada.');
    end if;

    update public.accounts
    set balance = balance - v_price,
        updated_at = now()
    where id = v_buyer_account.id;

    update public.accounts
    set balance = balance + v_price,
        updated_at = now()
    where id = v_seller_account.id;

    update public.businesses
    set previous_owner_id = owner_id,
        owner_id = v_buyer_id,
        is_for_sale = false,
        sale_price = null,
        sale_listed_at = null,
        sold_at = now(),
        status = coalesce(nullif(status, ''), 'active')
    where id = v_business.id;

    insert into public.transactions (from_account_id, to_account_id, amount, type, description, created_at, metadata)
    values (
      v_buyer_account.id,
      v_seller_account.id,
      v_price,
      'business_sale',
      'Compra da empresa: ' || v_business.name,
      now(),
      jsonb_build_object('business_id', v_business.id, 'listing_type', 'private')
    );

    return jsonb_build_object('success', true, 'message', 'Empresa comprada com sucesso.', 'business_id', v_business.id);
  end if;

  if p_listing_type = 'state' then
    select * into v_enterprise
    from public.state_enterprises
    where id = p_listing_id
      and privatization_status = 'for_sale'
      and coalesce(is_privatized, false) = false
    for update;

    if v_enterprise.id is null then
      return jsonb_build_object('success', false, 'message', 'Estatal nao encontrada ou privatizacao indisponivel.');
    end if;

    v_price := coalesce(v_enterprise.privatization_price, 0);
    if v_price <= 0 then
      return jsonb_build_object('success', false, 'message', 'Preco de privatizacao invalido.');
    end if;

    if coalesce(v_buyer_account.balance, 0) < v_price then
      return jsonb_build_object('success', false, 'message', 'Saldo insuficiente para comprar esta estatal.');
    end if;

    select * into v_finance
    from public.government_finances
    order by updated_at desc
    limit 1
    for update;

    if v_finance.id is null then
      return jsonb_build_object('success', false, 'message', 'Financas do governo nao encontradas.');
    end if;

    v_business_type_id := case v_enterprise.sector
      when 'Energia Elétrica' then 'fabrica'
      when 'Água' then 'distribuidora'
      when 'Gás' then 'distribuidora'
      when 'Internet' then 'consultoria'
      when 'Telefonia' then 'consultoria'
      else 'consultoria'
    end;

    update public.accounts
    set balance = balance - v_price,
        updated_at = now()
    where id = v_buyer_account.id;

    update public.government_finances
    set treasury_balance = treasury_balance + v_price,
        updated_at = now()
    where id = v_finance.id;

    insert into public.businesses (
      owner_id,
      business_type_id,
      name,
      description,
      status,
      employees,
      monthly_revenue
    )
    values (
      v_buyer_id,
      v_business_type_id,
      v_enterprise.name,
      coalesce(v_enterprise.description, 'Empresa privatizada a partir de estatal.'),
      'active',
      0,
      0
    )
    returning id into v_new_business_id;

    update public.state_enterprises
    set is_privatized = true,
        is_active = false,
        privatization_status = 'sold',
        privatization_buyer_id = v_buyer_id,
        privatized_at = now(),
        updated_at = now()
    where id = v_enterprise.id;

    insert into public.transactions (from_account_id, to_account_id, amount, type, description, created_at, metadata)
    values (
      v_buyer_account.id,
      null,
      v_price,
      'privatization_purchase',
      'Compra de estatal privatizada: ' || v_enterprise.name,
      now(),
      jsonb_build_object(
        'state_enterprise_id', v_enterprise.id,
        'business_id', v_new_business_id,
        'treasury_credit', true,
        'listing_type', 'state'
      )
    );

    return jsonb_build_object('success', true, 'message', 'Estatal comprada e privatizada com sucesso.', 'business_id', v_new_business_id);
  end if;

  return jsonb_build_object('success', false, 'message', 'Tipo de listagem invalido.');
end;
$$;


ALTER FUNCTION "public"."buy_business_listing"("p_listing_type" "text", "p_listing_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."buy_product"("p_product_id" "uuid", "p_payment_method" "text", "p_card_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    buyer_id UUID := auth.uid();
    product_info RECORD;
    buyer_account RECORD;
    seller_account RECORD;
    buyer_card RECORD;
    new_transaction_id UUID;
    buyer_profile RECORD;
    transaction_description TEXT;
    transaction_type TEXT;
    base_price NUMERIC;
    tax_rate NUMERIC;
    tax_amount NUMERIC;
    total_price NUMERIC;
    seller_info RECORD;
    gov_account_id UUID;
BEGIN
    SELECT p.*, s.full_name as seller_name, s.role as seller_role, s.cpf as seller_cpf
    INTO product_info
    FROM public.products p
    JOIN public.profiles s ON p.seller_id = s.id
    WHERE p.id = p_product_id;

    IF product_info IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Produto não encontrado.');
    END IF;

    IF product_info.seller_id = buyer_id THEN
        RETURN json_build_object('success', false, 'message', 'Você não pode comprar seu próprio produto.');
    END IF;

    IF product_info.product_type = 'one-time' AND (product_info.stock IS NULL OR product_info.stock <= 0) THEN
        RETURN json_build_object('success', false, 'message', 'Produto esgotado.');
    END IF;

    IF product_info.promotion_price IS NOT NULL AND product_info.promotion_expires_at > now() THEN
        base_price := product_info.promotion_price;
    ELSE
        base_price := product_info.price;
    END IF;

    -- Get Tax Rate
    IF product_info.product_type = 'subscription' THEN
        SELECT (value->>'service_tax')::numeric INTO tax_rate FROM public.system_settings WHERE key = 'tax_rates';
    ELSE
        SELECT (value->>'product_tax')::numeric INTO tax_rate FROM public.system_settings WHERE key = 'tax_rates';
    END IF;

    tax_rate := COALESCE(tax_rate, 0);
    tax_amount := base_price * tax_rate;
    total_price := base_price + tax_amount;

    IF product_info.product_type = 'subscription' THEN
        transaction_description := 'Assinatura: ' || product_info.name;
        transaction_type := 'subscription_payment';
    ELSE
        transaction_description := 'Compra: ' || product_info.name;
        transaction_type := 'purchase';
    END IF;

    SELECT * INTO seller_account FROM public.accounts WHERE user_id = product_info.seller_id;
    IF seller_account IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'O vendedor não possui uma conta bancária para receber o pagamento.');
    END IF;

    SELECT id INTO gov_account_id FROM public.accounts WHERE user_id = '00000000-0000-0000-0000-000000000001';
    IF gov_account_id IS NULL THEN
       RETURN json_build_object('success', false, 'message', 'Conta do governo não encontrada.');
    END IF;
    
    SELECT
        p.full_name,
        d.document_number as cnpj,
        d.metadata->>'business_name' as business_name
    INTO seller_info
    FROM public.profiles p
    LEFT JOIN public.documents d ON p.id = d.user_id AND d.type = 'CNPJ'
    WHERE p.id = product_info.seller_id;

    IF p_payment_method = 'balance' THEN
        SELECT * INTO buyer_account FROM public.accounts WHERE user_id = buyer_id;
        IF buyer_account IS NULL THEN
            RETURN json_build_object('success', false, 'message', 'Você precisa de uma conta bancária para comprar com saldo.');
        END IF;
        IF buyer_account.balance < total_price THEN
            RETURN json_build_object('success', false, 'message', 'Saldo insuficiente para realizar a compra (incluindo impostos).');
        END IF;

        UPDATE public.accounts SET balance = balance - total_price WHERE id = buyer_account.id;
        UPDATE public.accounts SET balance = balance + base_price WHERE id = seller_account.id;
        UPDATE public.government_finances SET treasury_balance = treasury_balance + tax_amount WHERE id = 1;
        
        INSERT INTO public.transactions(from_account_id, to_account_id, amount, description, type, metadata)
        VALUES (buyer_account.id, seller_account.id, total_price, transaction_description, transaction_type,
                jsonb_build_object(
                    'platform', 'Negócios Livres',
                    'seller_name', seller_info.full_name,
                    'seller_cpf_cnpj', COALESCE(seller_info.cnpj, product_info.seller_cpf),
                    'base_price', base_price,
                    'tax_amount', tax_amount
                ))
        RETURNING id INTO new_transaction_id;

    ELSIF p_payment_method = 'card' THEN
        IF p_card_id IS NULL THEN
            RETURN json_build_object('success', false, 'message', 'Nenhum cartão de crédito selecionado.');
        END IF;
        
        SELECT * INTO buyer_card FROM public.cards WHERE id = p_card_id AND user_id = buyer_id;
        IF buyer_card IS NULL THEN
            RETURN json_build_object('success', false, 'message', 'Cartão de crédito inválido.');
        END IF;

        IF (buyer_card.card_limit - buyer_card.used_limit) < total_price THEN
            RETURN json_build_object('success', false, 'message', 'Limite do cartão de crédito insuficiente (incluindo impostos).');
        END IF;

        UPDATE public.cards SET used_limit = used_limit + total_price WHERE id = buyer_card.id;
        UPDATE public.accounts SET balance = balance + base_price WHERE id = seller_account.id;
        UPDATE public.government_finances SET treasury_balance = treasury_balance + tax_amount WHERE id = 1;

        INSERT INTO public.transactions(to_account_id, amount, description, type, metadata)
        VALUES (seller_account.id, total_price, transaction_description, transaction_type || '_card',
                jsonb_build_object(
                    'platform', 'Negócios Livres',
                    'card_id', p_card_id,
                    'seller_name', seller_info.full_name,
                    'seller_cpf_cnpj', COALESCE(seller_info.cnpj, product_info.seller_cpf),
                    'base_price', base_price,
                    'tax_amount', tax_amount
                ))
        RETURNING id INTO new_transaction_id;
        
    ELSE
        RETURN json_build_object('success', false, 'message', 'Método de pagamento inválido.');
    END IF;

    IF product_info.product_type = 'subscription' THEN
        INSERT INTO public.user_subscriptions(user_id, product_id, seller_id, status, last_payment_date, next_payment_date)
        VALUES (buyer_id, p_product_id, product_info.seller_id, 'active', now(), now() + (product_info.subscription_interval)::interval);
        UPDATE public.products SET subscribers_count = COALESCE(subscribers_count, 0) + 1 WHERE id = p_product_id;
    ELSE
        INSERT INTO public.user_inventory(user_id, product_id, quantity, acquired_at)
        VALUES (buyer_id, p_product_id, 1, now());
        UPDATE public.products SET stock = stock - 1, sales_count = COALESCE(sales_count, 0) + 1 WHERE id = p_product_id;
    END IF;

    SELECT full_name INTO buyer_profile FROM public.profiles WHERE id = buyer_id;
    INSERT INTO public.notifications(user_id, sender_id, type, content, link)
    VALUES (product_info.seller_id, buyer_id, 'product_sold', buyer_profile.full_name || ' comprou seu produto: ' || product_info.name, '/dashboard?tab=products');

    RETURN json_build_object('success', true, 'message', 'Compra realizada com sucesso!', 'transaction_id', new_transaction_id);
EXCEPTION
    WHEN others THEN
        RETURN json_build_object('success', false, 'message', 'Ocorreu um erro inesperado durante a compra.');
END;
$$;


