CREATE OR REPLACE FUNCTION "public"."calculate_sentence_duration"("p_sentence_years" numeric, "p_modifier" numeric DEFAULT 1) RETURNS integer
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO ''
    AS $$
declare
  v_bracket public.penal_time_brackets%rowtype;
  v_ratio numeric;
  v_seconds numeric;
  v_global_multiplier numeric;
begin
  if p_sentence_years < 0 or p_modifier <= 0 then
    raise exception 'INVALID_SENTENCE_DURATION';
  end if;

  select * into v_bracket
  from public.penal_time_brackets b
  where b.is_active
    and p_sentence_years >= b.minimum_years
    and (b.maximum_years is null or p_sentence_years <= b.maximum_years)
  order by b.sort_order
  limit 1;

  if not found then
    raise exception 'PENAL_TIME_BRACKET_NOT_CONFIGURED';
  end if;

  if v_bracket.maximum_years is null then
    v_seconds := v_bracket.minimum_real_seconds
      + least(1, greatest(0, (p_sentence_years - v_bracket.minimum_years) / 20))
        * (v_bracket.maximum_real_seconds - v_bracket.minimum_real_seconds);
  else
    v_ratio := (p_sentence_years - v_bracket.minimum_years)
      / nullif(v_bracket.maximum_years - v_bracket.minimum_years, 0);
    v_seconds := v_bracket.minimum_real_seconds
      + greatest(0, least(1, v_ratio))
        * (v_bracket.maximum_real_seconds - v_bracket.minimum_real_seconds);
  end if;

  select penal_time_multiplier into v_global_multiplier
  from public.rp_time_settings where id = true;

  return greatest(60, round(v_seconds * p_modifier * v_global_multiplier))::integer;
end;
$$;


ALTER FUNCTION "public"."calculate_sentence_duration"("p_sentence_years" numeric, "p_modifier" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_affiliation_request"("p_request_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.party_affiliation_requests WHERE id = p_request_id AND user_id = current_user_id AND status = 'pending') THEN
        RETURN json_build_object('success', false, 'message', 'Solicitação não encontrada ou não pode ser cancelada.');
    END IF;

    DELETE FROM public.party_affiliation_requests WHERE id = p_request_id;

    RETURN json_build_object('success', true, 'message', 'Solicitação de filiação cancelada.');
END;
$$;


