CREATE OR REPLACE FUNCTION "public"."cancel_credit_card"("p_card_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    card_info RECORD;
BEGIN
    SELECT * INTO card_info FROM public.cards WHERE id = p_card_id AND user_id = current_user_id;

    IF card_info IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Cartão não encontrado ou não pertence a você.');
    END IF;

    IF card_info.used_limit > 0 THEN
        RETURN json_build_object('success', false, 'message', 'Para cancelar, pague a fatura em aberto do seu cartão.');
    END IF;

    DELETE FROM public.cards WHERE id = p_card_id AND user_id = current_user_id;
    RETURN json_build_object('success', true, 'message', 'Cartão cancelado com sucesso.');
END;
$$;


ALTER FUNCTION "public"."cancel_credit_card"("p_card_id" "uuid") OWNER TO "postgres";


