CREATE OR REPLACE FUNCTION "public"."cancel_subscription"("p_subscription_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    subscription_record RECORD;
BEGIN
    SELECT * INTO subscription_record FROM public.user_subscriptions
    WHERE id = p_subscription_id AND user_id = current_user_id;

    IF subscription_record IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Assinatura não encontrada ou não pertence a você.');
    END IF;

    UPDATE public.user_subscriptions
    SET status = 'cancelled', updated_at = now()
    WHERE id = p_subscription_id;

    UPDATE public.products
    SET subscribers_count = GREATEST(0, subscribers_count - 1)
    WHERE id = subscription_record.product_id;

    RETURN json_build_object('success', true, 'message', 'Assinatura cancelada com sucesso.');
END;
$$;


ALTER FUNCTION "public"."cancel_subscription"("p_subscription_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cast_leadership_vote"("p_election_id" "uuid", "p_candidate_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_election record;
  v_candidate record;
  v_member_id uuid;
begin
  if v_user_id is null then
    raise exception 'É necessário estar autenticado.';
  end if;

  select *
    into v_election
    from public.parliament_leadership_elections
   where id = p_election_id;

  if not found then
    raise exception 'Eleição não encontrada.';
  end if;

  if v_election.status <> 'open' then
    raise exception 'A eleição não está aberta para votos.';
  end if;

  v_member_id := public.get_active_parliament_member_id(v_user_id, v_election.house_id);

  if v_member_id is null then
    raise exception 'Somente parlamentares ativos desta Casa podem votar.';
  end if;

  select plc.*
    into v_candidate
    from public.parliament_leadership_candidates plc
    join public.parliament_members pm
      on pm.id = plc.member_id
   where plc.id = p_candidate_id
     and plc.election_id = p_election_id
     and pm.house_id = v_election.house_id;

  if not found then
    raise exception 'Candidato não encontrado para esta eleição.';
  end if;

  insert into public.parliament_leadership_votes (
    election_id,
    voter_member_id,
    candidate_id
  )
  values (
    p_election_id,
    v_member_id,
    p_candidate_id
  );

  return jsonb_build_object(
    'success', true,
    'message', 'Voto registrado com sucesso.'
  );
exception
  when unique_violation then
    raise exception 'Cada parlamentar pode votar apenas uma vez por eleição.';
end;
$$;


ALTER FUNCTION "public"."cast_leadership_vote"("p_election_id" "uuid", "p_candidate_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cast_parliament_vote"("p_voting_id" "uuid", "p_member_id" "uuid", "p_vote" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    is_member BOOLEAN;
    voting_status TEXT;
BEGIN
    SELECT EXISTS (
        SELECT 1 FROM public.parliament_members WHERE id = p_member_id AND user_id = current_user_id
    ) INTO is_member;

    IF NOT is_member AND (SELECT role FROM public.profiles WHERE id = current_user_id) <> 'Admin' THEN
        RETURN json_build_object('success', false, 'message', 'Apenas membros do parlamento podem votar.');
    END IF;

    IF p_vote NOT IN ('Aprovar', 'Rejeitar', 'Abster') THEN
        RETURN json_build_object('success', false, 'message', 'Voto inválido.');
    END IF;

    SELECT status INTO voting_status FROM public.parliament_votings WHERE id = p_voting_id;
    IF voting_status <> 'active' THEN
        RETURN json_build_object('success', false, 'message', 'Esta votação não está ativa.');
    END IF;

    IF EXISTS (SELECT 1 FROM public.parliament_voting_votes WHERE voting_id = p_voting_id AND member_id = p_member_id) THEN
        RETURN json_build_object('success', false, 'message', 'Você já votou nesta sessão.');
    END IF;

    INSERT INTO public.parliament_voting_votes (voting_id, member_id, vote)
    VALUES (p_voting_id, p_member_id, p_vote);

    RETURN json_build_object('success', true, 'message', 'Seu voto foi computado com sucesso!');
END;
$$;


ALTER FUNCTION "public"."cast_parliament_vote"("p_voting_id" "uuid", "p_member_id" "uuid", "p_vote" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cast_plebiscite_vote"("p_plebiscite_id" "uuid", "p_vote" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    user_role TEXT;
    plebiscite_status TEXT;
BEGIN
    SELECT role INTO user_role FROM public.profiles WHERE id = current_user_id;
    IF user_role = 'Usuário' THEN
        RETURN json_build_object('success', false, 'message', 'Apenas cidadãos com cargos podem votar.');
    END IF;

    IF p_vote NOT IN ('Sim', 'Não', 'Abstenção') THEN
        RETURN json_build_object('success', false, 'message', 'Voto inválido.');
    END IF;

    SELECT status INTO plebiscite_status FROM public.plebiscites WHERE id = p_plebiscite_id;
    IF plebiscite_status <> 'Ativo' THEN
        RETURN json_build_object('success', false, 'message', 'Este plebiscito não está ativo para votação.');
    END IF;

    IF EXISTS (SELECT 1 FROM public.plebiscite_votes WHERE plebiscite_id = p_plebiscite_id AND voter_id = current_user_id) THEN
        RETURN json_build_object('success', false, 'message', 'Você já votou neste plebiscito.');
    END IF;

    INSERT INTO public.plebiscite_votes (plebiscite_id, voter_id, vote)
    VALUES (p_plebiscite_id, current_user_id, p_vote);

    IF p_vote = 'Sim' THEN
        UPDATE public.plebiscites SET votes_sim = votes_sim + 1 WHERE id = p_plebiscite_id;
    ELSIF p_vote = 'Não' THEN
        UPDATE public.plebiscites SET votes_nao = votes_nao + 1 WHERE id = p_plebiscite_id;
    ELSE
        UPDATE public.plebiscites SET votes_abstencao = votes_abstencao + 1 WHERE id = p_plebiscite_id;
    END IF;

    RETURN json_build_object('success', true, 'message', 'Seu voto foi computado com sucesso!');
END;
$$;


ALTER FUNCTION "public"."cast_plebiscite_vote"("p_plebiscite_id" "uuid", "p_vote" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cast_vote"("p_election_id" "uuid", "p_candidate_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    active_election elections%ROWTYPE;
BEGIN
    SELECT * INTO active_election FROM public.elections 
    WHERE id = p_election_id AND status = 'Voting' AND now() BETWEEN voting_start_date AND voting_end_date;

    IF active_election IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Eleição não está ativa para votação.');
    END IF;

    IF EXISTS (SELECT 1 FROM public.votes WHERE election_id = p_election_id AND voter_id = current_user_id) THEN
        RETURN json_build_object('success', false, 'message', 'Você já votou nesta eleição.');
    END IF;

    INSERT INTO public.votes(election_id, voter_id, candidate_id)
    VALUES(p_election_id, current_user_id, p_candidate_id);

    RETURN json_build_object('success', true, 'message', 'Voto computado com sucesso!');
END;
$$;


ALTER FUNCTION "public"."cast_vote"("p_election_id" "uuid", "p_candidate_id" "uuid") OWNER TO "postgres";


