CREATE OR REPLACE FUNCTION "public"."check_police_query"("p_query_type" "text", "p_user_id" "uuid", "p_occurrence_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    result_data RECORD;
    result_message TEXT;
BEGIN
    IF p_query_type = 'warrant' THEN
        SELECT crime INTO result_message FROM public.police_wanted_list WHERE profile_id = p_user_id AND status = 'Ativo' LIMIT 1;
        IF result_message IS NOT NULL THEN
            RETURN json_build_object('success', true, 'found', true, 'message', 'Mandado de prisão ativo encontrado por: ' || result_message);
        ELSE
            RETURN json_build_object('success', true, 'found', false, 'message', 'Nenhum mandado de prisão ativo encontrado.');
        END IF;
    ELSIF p_query_type = 'investigation' THEN
        SELECT details INTO result_message FROM public.police_investigations inv JOIN public.profiles p ON inv.subject = p.full_name WHERE p.id = p_user_id AND inv.status = 'Em andamento' LIMIT 1;
        IF result_message IS NOT NULL THEN
            RETURN json_build_object('success', true, 'found', true, 'message', 'Você está sob investigação. Detalhes: ' || result_message);
        ELSE
            RETURN json_build_object('success', true, 'found', false, 'message', 'Você não está sob investigação no momento.');
        END IF;
    ELSIF p_query_type = 'occurrence_status' THEN
        SELECT status INTO result_message FROM public.police_occurrences WHERE id = p_occurrence_id AND user_id = p_user_id LIMIT 1;
        IF result_message IS NOT NULL THEN
            RETURN json_build_object('success', true, 'found', true, 'message', 'O status da ocorrência é: ' || result_message);
        ELSE
            RETURN json_build_object('success', false, 'found', false, 'message', 'Ocorrência não encontrada ou não pertence a você.');
        END IF;
    ELSIF p_query_type = 'clearance_certificate' THEN
        SELECT crime INTO result_message FROM public.criminal_records WHERE user_id = p_user_id AND is_active = true LIMIT 1;
        IF result_message IS NOT NULL THEN
            RETURN json_build_object('success', true, 'found', true, 'message', 'Certidão Negativa: NEGADA. Consta registro criminal ativo por: ' || result_message);
        ELSE
            RETURN json_build_object('success', true, 'found', false, 'message', 'Certidão Negativa: APROVADA. Nada consta.');
        END IF;
    ELSE
        RETURN json_build_object('success', false, 'message', 'Tipo de consulta inválida.');
    END IF;
END;
$$;


ALTER FUNCTION "public"."check_police_query"("p_query_type" "text", "p_user_id" "uuid", "p_occurrence_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_recipient_by_key"("p_transfer_key" "text") RETURNS json
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  recipient_info RECORD;
BEGIN
  SELECT p.full_name, p.id as user_id INTO recipient_info
  FROM public.accounts a 
  JOIN public.profiles p ON a.user_id = p.id
  WHERE a.transfer_key = upper(p_transfer_key);

  IF recipient_info IS NULL THEN
    RETURN json_build_object('found', false, 'message', 'Chave de transferência não encontrada.');
  ELSE
    RETURN json_build_object('found', true, 'name', recipient_info.full_name, 'user_id', recipient_info.user_id);
  END IF;
EXCEPTION
  WHEN others THEN
    RETURN json_build_object('found', false, 'message', 'Erro interno ao verificar destinatário.');
END;
$$;


ALTER FUNCTION "public"."check_recipient_by_key"("p_transfer_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."claim_daily_check_in"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  v_user_id uuid := auth.uid();
  v_account_id uuid;
  v_config jsonb := '{}'::jsonb;
  v_timezone text := 'America/Sao_Paulo';
  v_today date;
  v_today_check_in public.daily_check_ins%rowtype;
  v_latest_check_in public.daily_check_ins%rowtype;
  v_new_check_in public.daily_check_ins%rowtype;
  v_new_streak integer := 1;
  v_base_reward numeric(12, 2) := 150;
  v_streak_bonus numeric(12, 2) := 25;
  v_weekly_bonus numeric(12, 2) := 200;
  v_reputation_reward integer := 3;
  v_streak_bonus_amount numeric(12, 2) := 0;
  v_weekly_bonus_amount numeric(12, 2) := 0;
  v_reward_amount numeric(12, 2) := 0;
  v_notification_content text;
begin
  if v_user_id is null then
    raise exception 'Usuario nao autenticado.';
  end if;

  select value
    into v_config
  from public.system_settings
  where key = 'daily_check_in_config';

  v_timezone := coalesce(nullif(v_config ->> 'timezone', ''), v_timezone);
  v_base_reward := coalesce((v_config ->> 'base_reward')::numeric, v_base_reward);
  v_streak_bonus := coalesce((v_config ->> 'streak_bonus')::numeric, v_streak_bonus);
  v_weekly_bonus := coalesce((v_config ->> 'weekly_bonus')::numeric, v_weekly_bonus);
  v_reputation_reward := coalesce((v_config ->> 'reputation_reward')::integer, v_reputation_reward);
  v_today := timezone(v_timezone, now())::date;

  select id
    into v_account_id
  from public.accounts
  where user_id = v_user_id
  limit 1;

  if v_account_id is null then
    return jsonb_build_object(
      'success', false,
      'requires_bank_account', true,
      'message', 'Abra sua conta no Banco Nacional para receber a recompensa diaria.'
    );
  end if;

  select *
    into v_today_check_in
  from public.daily_check_ins
  where user_id = v_user_id
    and reward_date = v_today
  limit 1;

  if found then
    return jsonb_build_object(
      'success', false,
      'already_claimed', true,
      'current_streak', v_today_check_in.streak_count,
      'message', 'O check-in de hoje ja foi registrado.'
    );
  end if;

  select *
    into v_latest_check_in
  from public.daily_check_ins
  where user_id = v_user_id
  order by reward_date desc
  limit 1;

  if found and v_latest_check_in.reward_date = (v_today - 1) then
    v_new_streak := v_latest_check_in.streak_count + 1;
  else
    v_new_streak := 1;
  end if;

  v_streak_bonus_amount := greatest(v_new_streak - 1, 0) * v_streak_bonus;
  v_weekly_bonus_amount := case
    when mod(v_new_streak, 7) = 0 then v_weekly_bonus
    else 0
  end;
  v_reward_amount := v_base_reward + v_streak_bonus_amount + v_weekly_bonus_amount;

  insert into public.daily_check_ins (
    user_id,
    reward_date,
    streak_count,
    reward_amount,
    reputation_reward,
    metadata
  )
  values (
    v_user_id,
    v_today,
    v_new_streak,
    v_reward_amount,
    v_reputation_reward,
    jsonb_build_object(
      'base_reward', v_base_reward,
      'streak_bonus_amount', v_streak_bonus_amount,
      'weekly_bonus_amount', v_weekly_bonus_amount,
      'timezone', v_timezone
    )
  )
  returning *
    into v_new_check_in;

  update public.accounts
  set
    balance = coalesce(balance, 0) + v_reward_amount,
    updated_at = now()
  where id = v_account_id;

  update public.profiles
  set
    reputation_points = coalesce(reputation_points, 0) + v_reputation_reward,
    updated_at = now()
  where id = v_user_id;

  insert into public.transactions (
    from_account_id,
    to_account_id,
    amount,
    description,
    created_at,
    type,
    metadata
  )
  values (
    null,
    v_account_id,
    v_reward_amount,
    format('Check-in diario - dia %s da sequencia', v_new_streak),
    now(),
    'daily_check_in_reward',
    jsonb_build_object(
      'daily_check_in_id', v_new_check_in.id,
      'streak_count', v_new_streak,
      'reputation_reward', v_reputation_reward
    )
  );

  v_notification_content := format(
    'Check-in diario concluido. Voce recebeu R$ %s e %s pontos de reputacao.',
    trim(to_char(v_reward_amount, 'FM999999990D00')),
    v_reputation_reward
  );

  insert into public.notifications (
    user_id,
    content,
    link,
    is_read,
    created_at,
    type,
    metadata
  )
  values (
    v_user_id,
    v_notification_content,
    '/dashboard/citizen',
    false,
    now(),
    'daily_check_in',
    jsonb_build_object(
      'daily_check_in_id', v_new_check_in.id,
      'reward_amount', v_reward_amount,
      'streak_count', v_new_streak
    )
  );

  return jsonb_build_object(
    'success', true,
    'current_streak', v_new_streak,
    'reward_amount', v_reward_amount,
    'reputation_reward', v_reputation_reward,
    'weekly_bonus_amount', v_weekly_bonus_amount,
    'message', format(
      'Voce recebeu %s e %s pontos de reputacao no dia %s da sua sequencia.',
      to_char(v_reward_amount, '"R$ "FM999999990D00'),
      v_reputation_reward,
      v_new_streak
    )
  );
end;
$_$;


ALTER FUNCTION "public"."claim_daily_check_in"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."classify_transaction_economic_effect"("p_transaction_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  transaction_owner uuid;
begin
  if auth.uid() is null then
    raise exception 'Autenticação obrigatória.' using errcode = '42501';
  end if;

  select a.user_id into transaction_owner
  from public.transactions t
  join public.accounts a on a.id = t.from_account_id
  where t.id = p_transaction_id;

  if transaction_owner is distinct from auth.uid()
     and not public.economic_has_role(array['Admin']) then
    raise exception 'Sem permissão para classificar esta transação.'
      using errcode = '42501';
  end if;

  return economy_private.classify_transaction(p_transaction_id);
end;
$$;


ALTER FUNCTION "public"."classify_transaction_economic_effect"("p_transaction_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cleanup_profile_political_dependencies"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_candidate_ids uuid[];
  v_member_ids uuid[];
begin
  select array_agg(id)
    into v_candidate_ids
  from public.candidates
  where user_id = old.id;

  if coalesce(array_length(v_candidate_ids, 1), 0) > 0 then
    delete from public.votes
    where candidate_id = any(v_candidate_ids);

    delete from public.candidates
    where id = any(v_candidate_ids);
  end if;

  select array_agg(id)
    into v_member_ids
  from public.parliament_members
  where user_id = old.id;

  if coalesce(array_length(v_member_ids, 1), 0) > 0 then
    delete from public.bill_votes
    where member_id = any(v_member_ids);

    delete from public.parliament_voting_votes
    where member_id = any(v_member_ids);

    delete from public.parliament_members
    where id = any(v_member_ids);
  end if;

  delete from public.plebiscite_votes
  where voter_id = old.id;

  delete from public.votes
  where voter_id = old.id;

  delete from public.bill_suggestions
  where author_id = old.id;

  delete from public.plebiscites
  where author_id = old.id;

  delete from public.party_affiliation_requests
  where user_id = old.id;

  delete from public.party_members
  where user_id = old.id;

  delete from public.daily_check_ins
  where user_id = old.id;

  delete from public.political_point_events
  where user_id = old.id;

  return old;
end;
$$;


ALTER FUNCTION "public"."cleanup_profile_political_dependencies"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_cnpj"("p_document_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    doc_info RECORD;
BEGIN
    SELECT * INTO doc_info FROM public.documents WHERE id = p_document_id AND user_id = current_user_id AND type = 'CNPJ';

    IF doc_info IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'CNPJ não encontrado ou não pertence a você.');
    END IF;

    IF NOT doc_info.is_valid THEN
        RETURN json_build_object('success', false, 'message', 'Esta empresa já foi encerrada.');
    END IF;

    -- Invalidate the document
    UPDATE public.documents SET is_valid = false, expires_at = now() WHERE id = p_document_id;

    -- Delete associated products
    DELETE FROM public.products WHERE seller_id = current_user_id;

    -- Update user role if they were PJ
    UPDATE public.profiles SET role = 'Cidadão' WHERE id = current_user_id AND role = 'PJ';

    RETURN json_build_object('success', true, 'message', 'Empresa encerrada com sucesso. Todos os seus produtos foram removidos.');
END;
$$;


ALTER FUNCTION "public"."close_cnpj"("p_document_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_completed_sentences"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_deadline record;
  v_sentence public.sentences%rowtype;
  v_term record;
  v_finalized integer := 0;
  v_released integer := 0;
  v_expired_warrants integer := 0;
begin
  update public.warrants
  set status = 'expired'
  where status = 'issued' and expires_at <= now();
  get diagnostics v_expired_warrants = row_count;

  for v_deadline in
    select * from public.justice_deadlines
    where status = 'open' and real_due_at <= now()
    order by real_due_at
    for update skip locked
  loop
    if v_deadline.deadline_type = 'appeal'
       and not exists (
         select 1 from public.appeals
         where case_id = v_deadline.case_id
           and status in ('filed', 'under_review')
       ) then
      update public.justice_deadlines
      set status = 'expired' where id = v_deadline.id;
      update public.criminal_cases
      set status = 'final' where id = v_deadline.case_id;
      update public.judicial_decisions
      set is_final = true where case_id = v_deadline.case_id and decision_type = 'sentence';

      for v_sentence in
        update public.sentences
        set status = 'final'
        where case_id = v_deadline.case_id and status = 'appealable'
        returning *
      loop
        insert into public.criminal_records(
          user_id, crime, sentence_details, sentence_start_date, sentence_end_date,
          is_active, judge_id, case_id, sentence_id, record_status
        )
        select
          v_sentence.defendant_id,
          string_agg(pc.name, ', ' order by pc.code),
          'Condenação no processo ' || cc.case_number || ' a '
            || v_sentence.final_sentence_units || ' ano(s) RP.',
          now(), now() + make_interval(secs => v_sentence.real_duration_seconds),
          true, v_sentence.judge_id, cc.id, v_sentence.id, 'conviction'
        from public.criminal_cases cc
        join public.case_charges ch on ch.case_id = cc.id
          and ch.defendant_id = v_sentence.defendant_id and ch.status = 'convicted'
        join public.penal_code pc on pc.id = ch.penal_code_id
        where cc.id = v_sentence.case_id
        group by cc.id, cc.case_number
        on conflict do nothing;

        perform public.justice_admit_sentence(v_sentence.id);
        v_finalized := v_finalized + 1;
      end loop;
    end if;
  end loop;

  for v_term in
    select * from public.prison_terms
    where custody_status in ('provisional', 'serving')
      and expected_release_at <= now()
    order by expected_release_at
    for update skip locked
  loop
    update public.prison_terms
    set custody_status = 'released', actual_release_at = now(),
        release_reason = 'Prazo de custódia integralmente cumprido'
    where id = v_term.id;

    if v_term.sentence_id is not null then
      update public.sentences set status = 'served', ends_at = now()
      where id = v_term.sentence_id;
    end if;
    if v_term.arrest_id is not null then
      update public.arrests
      set status = 'released', released_at = now(),
          release_reason = 'Prazo de custódia integralmente cumprido'
      where id = v_term.arrest_id;
    end if;

    insert into public.prison_events(
      prison_term_id, event_type, title, description
    )
    values (
      v_term.id, 'release', 'Soltura automática',
      'Prazo de custódia integralmente cumprido'
    );

    perform public.justice_notify(
      v_term.inmate_id, 'justice_release_order',
      'Seu prazo de custódia terminou e a soltura foi executada automaticamente.',
      '/services/justice?view=citizen',
      jsonb_build_object('prison_term_id', v_term.id)
    );
    perform public.justice_write_audit(
      'prison.auto_released', 'prison_term', v_term.id,
      to_jsonb(v_term), jsonb_build_object('custody_status', 'released'),
      'Prazo de custódia integralmente cumprido'
    );
    v_released := v_released + 1;
  end loop;

  return jsonb_build_object(
    'finalized_sentences', v_finalized,
    'released_prisoners', v_released,
    'expired_warrants', v_expired_warrants
  );
end;
$$;


ALTER FUNCTION "public"."close_completed_sentences"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_due_invoices"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  policy jsonb;
  rate numeric(8, 4);
  affected_count integer;
begin
  policy := public.get_bank_policy();
  rate := coalesce((policy->>'credit_card_revolving_rate')::numeric, 8.9);

  update public.card_invoices
  set interest_rate = rate,
      interest_amount = round((amount * (rate / 100))::numeric, 2),
      amount = round((amount * (1 + rate / 100))::numeric, 2),
      status = 'overdue',
      interest_applied_at = now(),
      updated_at = now()
  where status in ('open', 'closed')
    and due_date < current_date
    and interest_applied_at is null;

  get diagnostics affected_count = row_count;

  return jsonb_build_object(
    'success', true,
    'message', 'Faturas vencidas processadas.',
    'affected_count', affected_count,
    'interest_rate', rate
  );
end;
$$;


ALTER FUNCTION "public"."close_due_invoices"() OWNER TO "postgres";


