CREATE OR REPLACE FUNCTION "public"."close_leadership_election"("p_election_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_election record;
  v_vote_total integer;
  v_active_members integer;
  v_winner_candidate_id uuid;
  v_winner_member_id uuid;
  v_top_votes integer;
  v_top_count integer;
  v_new_term_id uuid;
  v_previous_term record;
  v_previous_user_id uuid;
begin
  if v_user_id is null then
    raise exception 'É necessário estar autenticado.';
  end if;

  select *
    into v_election
    from public.parliament_leadership_elections
   where id = p_election_id;

  if not found then
    raise exception 'Eleição não encontrada.';
  end if;

  if not public.is_parliament_governance_manager(v_user_id, v_election.house_id) then
    raise exception 'Somente a mesa diretora ou a administração podem encerrar esta eleição.';
  end if;

  if v_election.status <> 'open' then
    return jsonb_build_object(
      'success', true,
      'message', 'A eleição já foi encerrada anteriormente.'
    );
  end if;

  select count(*)
    into v_vote_total
    from public.parliament_leadership_votes
   where election_id = p_election_id;

  select count(*)
    into v_active_members
    from public.parliament_members
   where house_id = v_election.house_id
     and term_end_date >= current_date;

  if v_vote_total < coalesce(v_active_members, 0)
     and (v_election.end_at is null or v_election.end_at > now()) then
    raise exception 'A eleição ainda está em andamento.';
  end if;

  if not exists (
    select 1
      from public.parliament_leadership_candidates
     where election_id = p_election_id
  ) then
    update public.parliament_leadership_elections
       set status = 'cancelled',
           concluded_at = now()
     where id = p_election_id;

    return jsonb_build_object(
      'success', true,
      'message', 'Eleição encerrada sem candidaturas registradas.'
    );
  end if;

  with candidate_totals as (
    select plc.id as candidate_id,
           plc.member_id,
           count(plv.id) as total_votes
      from public.parliament_leadership_candidates plc
      left join public.parliament_leadership_votes plv
        on plv.candidate_id = plc.id
     where plc.election_id = p_election_id
     group by plc.id, plc.member_id
  )
  select candidate_id, member_id, total_votes
    into v_winner_candidate_id, v_winner_member_id, v_top_votes
    from candidate_totals
   order by total_votes desc, candidate_id
   limit 1;

  with candidate_totals as (
    select count(plv.id) as total_votes
      from public.parliament_leadership_candidates plc
      left join public.parliament_leadership_votes plv
        on plv.candidate_id = plc.id
     where plc.election_id = p_election_id
     group by plc.id
  )
  select count(*)
    into v_top_count
    from candidate_totals
   where total_votes = coalesce(v_top_votes, 0);

  if v_top_votes is null then
    update public.parliament_leadership_elections
       set status = 'cancelled',
           concluded_at = now()
     where id = p_election_id;

    return jsonb_build_object(
      'success', true,
      'message', 'Eleição encerrada sem votos válidos.'
    );
  end if;

  if v_top_count > 1 then
    update public.parliament_leadership_elections
       set status = 'tied',
           concluded_at = now()
     where id = p_election_id;

    return jsonb_build_object(
      'success', true,
      'message', 'Empate detectado. É necessário abrir nova eleição.'
    );
  end if;

  select plt.*, pm.user_id
    into v_previous_term
    from public.parliament_leadership_terms plt
    join public.parliament_members pm
      on pm.id = plt.member_id
   where plt.house_id = v_election.house_id
     and plt.position = v_election.position
     and plt.status = 'active'
   limit 1;

  if found then
    update public.parliament_leadership_terms
       set status = 'completed',
           concluded_at = now()
     where id = v_previous_term.id;

    v_previous_user_id := v_previous_term.user_id;

    update public.profiles
       set role = public.get_parliament_base_role_label(v_election.house_id),
           updated_at = now()
     where id = v_previous_user_id
       and role = public.get_parliament_leadership_role_label(v_election.house_id, v_election.position);
  end if;

  insert into public.parliament_leadership_terms (
    house_id,
    position,
    member_id,
    elected_by_election_id,
    term_start_date,
    term_end_date,
    status
  )
  values (
    v_election.house_id,
    v_election.position,
    v_winner_member_id,
    p_election_id,
    current_date,
    (current_date + interval '1 month')::date,
    'active'
  )
  returning id into v_new_term_id;

  update public.parliament_leadership_elections
     set status = 'closed',
         winner_member_id = v_winner_member_id,
         concluded_at = now()
   where id = p_election_id;

  update public.profiles
     set role = public.get_parliament_leadership_role_label(v_election.house_id, v_election.position),
         updated_at = now()
   where id = (
     select user_id
       from public.parliament_members
      where id = v_winner_member_id
   );

  return jsonb_build_object(
    'success', true,
    'term_id', v_new_term_id,
    'winner_member_id', v_winner_member_id,
    'message', 'Eleição encerrada e mandato da mesa diretora registrado.'
  );
end;
$$;


ALTER FUNCTION "public"."close_leadership_election"("p_election_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."close_parliament_commission"("p_commission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_commission record;
  v_house_id uuid;
  v_has_governance_access boolean;
begin
  if v_user_id is null then
    raise exception 'É necessário estar autenticado.';
  end if;

  select pc.*, pch.house_id
    into v_commission
    from public.parliament_commissions pc
    join public.parliament_commission_houses pch
      on pch.commission_id = pc.id
   where pc.id = p_commission_id
   limit 1;

  if not found then
    raise exception 'Comissão não encontrada.';
  end if;

  v_house_id := v_commission.house_id;

  select exists (
    select 1
      from public.parliament_commission_houses pch
     where pch.commission_id = p_commission_id
       and public.is_parliament_governance_manager(v_user_id, pch.house_id)
  )
    into v_has_governance_access;

  if not v_has_governance_access then
    raise exception 'Somente a mesa diretora pode encerrar a comissão.';
  end if;

  if v_commission.type in ('cpi', 'cpmi')
     and (v_commission.final_report is null or btrim(v_commission.final_report) = '') then
    raise exception 'Comissões de inquérito exigem Relatório Final antes do encerramento.';
  end if;

  update public.parliament_commissions
     set status = 'completed',
         closed_at = now()
   where id = p_commission_id;

  return jsonb_build_object(
    'success', true,
    'message', 'Comissão encerrada com sucesso.'
  );
end;
$$;


ALTER FUNCTION "public"."close_parliament_commission"("p_commission_id" "uuid") OWNER TO "postgres";


