CREATE TABLE IF NOT EXISTS "public"."prison_activity_runs" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "prison_term_id" "uuid" NOT NULL,
    "activity_id" "uuid" NOT NULL,
    "inmate_id" "uuid" NOT NULL,
    "started_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "completes_at" timestamp with time zone NOT NULL,
    "completed_at" timestamp with time zone,
    "status" "text" DEFAULT 'in_progress'::"text" NOT NULL,
    "result" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    CONSTRAINT "prison_activity_runs_status_check" CHECK (("status" = ANY (ARRAY['in_progress'::"text", 'completed'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."prison_activity_runs" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_prison_activity"("p_run_id" "uuid") RETURNS "public"."prison_activity_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_run public.prison_activity_runs%rowtype;
  v_activity public.prison_activities%rowtype;
  v_term public.prison_terms%rowtype;
  v_credit integer;
  v_max_credit integer;
begin
  select * into v_run from public.prison_activity_runs
  where id = p_run_id and inmate_id = (select auth.uid()) for update;
  if not found then raise exception 'ACTIVITY_RUN_NOT_FOUND'; end if;
  if v_run.status <> 'in_progress' then raise exception 'ACTIVITY_ALREADY_FINISHED'; end if;
  if v_run.completes_at > now() then raise exception 'ACTIVITY_NOT_FINISHED_YET'; end if;

  select * into v_activity from public.prison_activities where id = v_run.activity_id;
  select * into v_term from public.prison_terms where id = v_run.prison_term_id for update;

  v_max_credit := floor(v_term.original_duration_seconds * 0.10)::integer;
  v_credit := least(
    v_activity.sentence_credit_seconds,
    greatest(0, v_max_credit - v_term.sentence_credit_seconds)
  );

  update public.prison_activity_runs
  set status = 'completed', completed_at = now(),
      result = jsonb_build_object(
        'behavior_points', v_activity.behavior_points,
        'sentence_credit_seconds', v_credit
      )
  where id = p_run_id
  returning * into v_run;

  update public.prison_terms
  set behavior_points = behavior_points + v_activity.behavior_points,
      sentence_credit_seconds = sentence_credit_seconds + v_credit,
      expected_release_at = greatest(now(), expected_release_at - make_interval(secs => v_credit))
  where id = v_term.id;

  insert into public.prison_events(
    prison_term_id, event_type, title, description, behavior_points,
    sentence_credit_seconds, registered_by, approved_by
  )
  values (
    v_term.id, v_activity.activity_type, v_activity.name,
    'Atividade concluída pelo detento.', v_activity.behavior_points,
    v_credit, (select auth.uid()), (select auth.uid())
  );

  perform public.justice_write_audit(
    'prison.activity_completed', 'prison_term', v_term.id,
    to_jsonb(v_term),
    jsonb_build_object('activity_run_id', v_run.id, 'sentence_credit_seconds', v_credit),
    'Atividade prisional concluída e benefício calculado automaticamente'
  );
  return v_run;
end;
$$;


ALTER FUNCTION "public"."complete_prison_activity"("p_run_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."complete_residency_onboarding"("p_country_code" "text", "p_country_name" "text", "p_state_code" "text", "p_state_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
	IF auth.uid() IS NULL THEN
		RAISE EXCEPTION 'Usuário não autenticado';
	END IF;

	UPDATE public.profiles
	SET
		country_code = p_country_code,
		country_name = p_country_name,
		state_code = p_state_code,
		state_name = p_state_name,
		onboarding_completed = false,
		updated_at = NOW()
	WHERE id = auth.uid();

	IF NOT FOUND THEN
		RAISE EXCEPTION 'Perfil não encontrado';
	END IF;
END;
$$;


ALTER FUNCTION "public"."complete_residency_onboarding"("p_country_code" "text", "p_country_name" "text", "p_state_code" "text", "p_state_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_bank_account"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    user_profile RECORD;
    account_exists BOOLEAN;
    generated_agency_number TEXT;
    generated_account_number TEXT;
    generated_transfer_key TEXT;
BEGIN
    SELECT EXISTS(SELECT 1 FROM public.accounts WHERE user_id = current_user_id) INTO account_exists;

    IF account_exists THEN
        RETURN json_build_object('success', false, 'message', 'Você já possui uma conta bancária.');
    END IF;

    SELECT cpf INTO user_profile FROM public.profiles WHERE id = current_user_id;
    IF user_profile.cpf IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Você precisa ter um CPF cadastrado no seu perfil para abrir uma conta.');
    END IF;

    generated_agency_number := lpad((floor(random() * 9999))::text, 4, '0');
    generated_account_number := lpad((floor(random() * 9999999))::text, 7, '0') || '-' || (floor(random() * 9))::text;
    generated_transfer_key := public.generate_unique_transfer_key();

    INSERT INTO public.accounts (user_id, agency_number, account_number, balance, cpf, transfer_key)
    VALUES (current_user_id, generated_agency_number, generated_account_number, 1000.00, user_profile.cpf, generated_transfer_key);

    RETURN json_build_object('success', true, 'message', 'Conta bancária criada com sucesso!');
END;
$$;


ALTER FUNCTION "public"."create_bank_account"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_comment_reply"("p_post_id" "uuid", "p_parent_comment_id" "uuid", "p_content" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    parent_author_id UUID;
    replier_username TEXT;
    new_comment_id UUID;
BEGIN
    -- Insert the new reply and get its ID
    INSERT INTO public.comments(post_id, user_id, content, parent_comment_id)
    VALUES(p_post_id, current_user_id, p_content, p_parent_comment_id)
    RETURNING id INTO new_comment_id;

    -- Increment reply count on parent comment
    UPDATE public.comments
    SET replies_count = replies_count + 1
    WHERE id = p_parent_comment_id;

    -- Notify the author of the parent comment
    SELECT user_id INTO parent_author_id FROM public.comments WHERE id = p_parent_comment_id;
    IF current_user_id <> parent_author_id THEN
        SELECT username INTO replier_username FROM public.profiles WHERE id = current_user_id;
        INSERT INTO public.notifications(user_id, content, link)
        VALUES(parent_author_id, replier_username || ' respondeu ao seu comentário.', '/services/x');
    END IF;
END;
$$;


ALTER FUNCTION "public"."create_comment_reply"("p_post_id" "uuid", "p_parent_comment_id" "uuid", "p_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_leadership_election"("p_house_id" "uuid", "p_position" "text", "p_description" "text" DEFAULT NULL::"text", "p_duration_hours" integer DEFAULT 24) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_house_name text;
  v_title text;
  v_election_id uuid;
begin
  if v_user_id is null then
    raise exception 'É necessário estar autenticado.';
  end if;

  if p_position not in ('president', 'vice_president') then
    raise exception 'Posição da eleição inválida.';
  end if;

  if not public.is_parliament_governance_manager(v_user_id, p_house_id) then
    raise exception 'Somente a mesa diretora ou a administração podem abrir a eleição.';
  end if;

  perform public.refresh_parliament_leadership_terms();

  if exists (
    select 1
      from public.parliament_leadership_elections
     where house_id = p_house_id
       and position = p_position
       and status = 'open'
  ) then
    raise exception 'Já existe uma eleição aberta para esta posição.';
  end if;

  select name
    into v_house_name
    from public.parliament_houses
   where id = p_house_id;

  v_title := case
    when p_position = 'president' then 'Eleição para Presidente'
    else 'Eleição para Vice-Presidente'
  end || ' - ' || coalesce(v_house_name, 'Casa Legislativa');

  insert into public.parliament_leadership_elections (
    house_id,
    position,
    title,
    description,
    created_by,
    end_at
  )
  values (
    p_house_id,
    p_position,
    v_title,
    nullif(btrim(coalesce(p_description, '')), ''),
    v_user_id,
    now() + make_interval(hours => greatest(coalesce(p_duration_hours, 24), 1))
  )
  returning id into v_election_id;

  return jsonb_build_object(
    'success', true,
    'election_id', v_election_id,
    'message', 'Eleição interna aberta com sucesso.'
  );
end;
$$;


ALTER FUNCTION "public"."create_leadership_election"("p_house_id" "uuid", "p_position" "text", "p_description" "text", "p_duration_hours" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_minister_dou_entry"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_full_name text;
  v_ministry text;
begin
  select full_name
    into v_full_name
  from public.profiles
  where id = coalesce(new.user_id, old.user_id);

  v_ministry := coalesce(new.ministry, old.ministry, 'Ministério');

  if tg_op = 'INSERT' then
    insert into public.dou_entries (
      title,
      summary,
      content,
      published_at,
      type,
      source_id
    )
    values (
      format('Nomeação ministerial: %s', coalesce(v_full_name, 'Ministro')),
      format('%s foi nomeado para %s.', coalesce(v_full_name, 'O cidadão indicado'), v_ministry),
      format('%s assumiu oficialmente o cargo de %s.', coalesce(v_full_name, 'O cidadão indicado'), v_ministry),
      now(),
      'Nomeação e Exoneração',
      gen_random_uuid()
    );

    return new;
  end if;

  insert into public.dou_entries (
    title,
    summary,
    content,
    published_at,
    type,
    source_id
  )
  values (
    format('Exoneração ministerial: %s', coalesce(v_full_name, 'Ministro')),
    format('%s deixou o cargo de %s.', coalesce(v_full_name, 'O ministro'), v_ministry),
    format('%s foi exonerado do cargo de %s.', coalesce(v_full_name, 'O ministro'), v_ministry),
    now(),
    'Nomeação e Exoneração',
    gen_random_uuid()
  );

  return old;
end;
$$;


ALTER FUNCTION "public"."create_minister_dou_entry"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_parliament_commission"("p_title" "text", "p_summary" "text", "p_purpose" "text", "p_type" "text", "p_house_ids" "uuid"[]) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_scope text;
  v_status text;
  v_house_id uuid;
  v_member_id uuid;
  v_commission_id uuid;
begin
  if v_user_id is null then
    raise exception 'É necessário estar autenticado para criar comissão.';
  end if;

  if p_title is null or btrim(p_title) = '' or p_summary is null or btrim(p_summary) = '' or p_purpose is null or btrim(p_purpose) = '' then
    raise exception 'Título, resumo e objetivo são obrigatórios.';
  end if;

  if p_type not in ('permanent', 'temporary', 'cpi', 'cpmi') then
    raise exception 'Tipo de comissão inválido.';
  end if;

  if coalesce(array_length(p_house_ids, 1), 0) = 0 then
    raise exception 'Ao menos uma casa legislativa deve ser informada.';
  end if;

  if p_type = 'cpmi' then
    if coalesce(array_length(p_house_ids, 1), 0) <> 2 then
      raise exception 'CPMI deve envolver exatamente duas Casas.';
    end if;
    v_scope := 'mixed';
    v_status := 'collecting_support';
  else
    if coalesce(array_length(p_house_ids, 1), 0) <> 1 then
      raise exception 'Esta comissão deve estar vinculada a uma única Casa.';
    end if;
    v_scope := 'house';
    v_status := case
      when p_type = 'permanent' then 'active'
      when p_type = 'temporary' then 'pending_plenary'
      else 'collecting_support'
    end;
  end if;

  if p_type = 'permanent' and not public.is_parliament_governance_manager(v_user_id, p_house_ids[1]) then
    raise exception 'Somente a mesa diretora pode criar comissões permanentes.';
  end if;

  v_house_id := p_house_ids[1];
  v_member_id := public.get_active_parliament_member_id(v_user_id, v_house_id);

  if v_member_id is null and not exists (
    select 1
      from public.profiles
     where id = v_user_id
       and role in ('Admin', 'Presidente')
  ) then
    raise exception 'Somente parlamentares ativos podem iniciar esse fluxo.';
  end if;

  insert into public.parliament_commissions (
    title,
    summary,
    purpose,
    scope,
    type,
    status,
    requested_by,
    officialized_by,
    officialized_at,
    opened_at
  )
  values (
    btrim(p_title),
    btrim(p_summary),
    btrim(p_purpose),
    v_scope,
    p_type,
    v_status,
    v_user_id,
    case when p_type = 'permanent' then v_user_id else null end,
    case when p_type = 'permanent' then now() else null end,
    case when p_type = 'permanent' then now() else null end
  )
  returning id into v_commission_id;

  foreach v_house_id in array p_house_ids
  loop
    insert into public.parliament_commission_houses (commission_id, house_id)
    values (v_commission_id, v_house_id);
  end loop;

  if v_member_id is not null and p_type in ('cpi', 'cpmi') then
    insert into public.parliament_commission_supports (commission_id, member_id)
    values (v_commission_id, v_member_id)
    on conflict do nothing;
  end if;

  if v_member_id is not null and p_type = 'permanent' then
    insert into public.parliament_commission_members (commission_id, member_id, role, appointed_by)
    values (v_commission_id, v_member_id, 'chair', v_user_id)
    on conflict (commission_id, member_id) do update
      set role = excluded.role,
          appointed_by = excluded.appointed_by,
          appointed_at = now();
  end if;

  return jsonb_build_object(
    'success', true,
    'commission_id', v_commission_id,
    'message', case
      when p_type = 'temporary' then 'Comissão temporária cadastrada e pronta para deliberação do plenário.'
      when p_type = 'permanent' then 'Comissão permanente criada com sucesso.'
      else 'Requerimento de comissão registrado. Agora ele pode receber apoios parlamentares.'
    end
  );
end;
$$;


ALTER FUNCTION "public"."create_parliament_commission"("p_title" "text", "p_summary" "text", "p_purpose" "text", "p_type" "text", "p_house_ids" "uuid"[]) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."police_occurrences" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "user_id" "uuid",
    "type" "text" NOT NULL,
    "title" "text" NOT NULL,
    "details" "text" NOT NULL,
    "location" "text",
    "status" "text" DEFAULT 'Pendente'::"text" NOT NULL,
    "is_anonymous" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "protocol_number" "text",
    "occurrence_type" "text",
    "description" "text",
    "occurred_at" timestamp with time zone,
    "reported_by" "uuid",
    "anonymous" boolean,
    "assigned_officer_id" "uuid",
    "assigned_delegate_id" "uuid",
    "priority" "text" DEFAULT 'normal'::"text" NOT NULL,
    "confidentiality_level" "text" DEFAULT 'restricted'::"text" NOT NULL,
    "triage_notes" "text",
    "department" "text",
    CONSTRAINT "police_occurrences_confidentiality_level_check" CHECK (("confidentiality_level" = ANY (ARRAY['public'::"text", 'restricted'::"text", 'confidential'::"text", 'secret'::"text"]))),
    CONSTRAINT "police_occurrences_priority_check" CHECK (("priority" = ANY (ARRAY['low'::"text", 'normal'::"text", 'high'::"text", 'urgent'::"text"])))
);


ALTER TABLE "public"."police_occurrences" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_police_occurrence"("p_title" "text", "p_description" "text", "p_occurrence_type" "text", "p_location" "text" DEFAULT NULL::"text", "p_occurred_at" timestamp with time zone DEFAULT "now"(), "p_anonymous" boolean DEFAULT false, "p_priority" "text" DEFAULT 'normal'::"text") RETURNS "public"."police_occurrences"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_user_id uuid := (select auth.uid());
  v_row public.police_occurrences%rowtype;
begin
  if v_user_id is null then raise exception 'AUTHENTICATION_REQUIRED'; end if;
  if length(trim(coalesce(p_title, ''))) < 5 then raise exception 'TITLE_TOO_SHORT'; end if;
  if length(trim(coalesce(p_description, ''))) < 20 then raise exception 'DESCRIPTION_TOO_SHORT'; end if;
  if p_priority not in ('low', 'normal', 'high', 'urgent') then raise exception 'INVALID_PRIORITY'; end if;

  insert into public.police_occurrences(
    protocol_number, title, description, details, occurrence_type, type,
    location, occurred_at, reported_by, user_id, anonymous, is_anonymous,
    priority, status, confidentiality_level
  )
  values (
    public.justice_next_number('BO'), trim(p_title), trim(p_description), trim(p_description),
    trim(p_occurrence_type), trim(p_occurrence_type), nullif(trim(p_location), ''),
    coalesce(p_occurred_at, now()),
    case when p_anonymous then null else v_user_id end,
    case when p_anonymous then null else v_user_id end,
    p_anonymous, p_anonymous, p_priority, 'Pendente', 'restricted'
  )
  returning * into v_row;

  perform public.justice_write_audit(
    'occurrence.created', 'police_occurrence', v_row.id, null,
    to_jsonb(v_row) - 'user_id' - 'reported_by',
    'Ocorrência registrada pelo cidadão'
  );

  perform public.justice_notify(
    v_user_id, 'justice_occurrence_created',
    'Ocorrência ' || v_row.protocol_number || ' recebida.',
    '/services/justice?view=citizen',
    jsonb_build_object('occurrence_id', v_row.id, 'protocol_number', v_row.protocol_number)
  );

  return v_row;
end;
$$;


ALTER FUNCTION "public"."create_police_occurrence"("p_title" "text", "p_description" "text", "p_occurrence_type" "text", "p_location" "text", "p_occurred_at" timestamp with time zone, "p_anonymous" boolean, "p_priority" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_political_party"("p_name" "text", "p_acronym" "text", "p_ideology" "text", "p_logo_url" "text", "p_statute" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    founder_id UUID := auth.uid();
    new_party_id UUID;
    reg_num TEXT;
BEGIN
    reg_num := 'GOVRP-' || nextval('party_reg_num_seq');

    INSERT INTO political_parties(name, acronym, ideology, logo_url, founder_id, president_id, statute, registration_number)
    VALUES(p_name, p_acronym, p_ideology, p_logo_url, founder_id, founder_id, p_statute, reg_num)
    RETURNING id INTO new_party_id;

    INSERT INTO party_members(party_id, user_id, role)
    VALUES(new_party_id, founder_id, 'Fundador');

    RETURN json_build_object('success', true, 'message', 'Partido criado com sucesso!', 'party_id', new_party_id);
END;
$$;


ALTER FUNCTION "public"."create_political_party"("p_name" "text", "p_acronym" "text", "p_ideology" "text", "p_logo_url" "text", "p_statute" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_political_party"("p_name" "text", "p_acronym" "text", "p_ideology" "text", "p_logo_url" "text", "p_statute" "text", "p_description" "text", "p_orientation" "public"."political_orientation") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
    DECLARE
        current_user_id UUID := auth.uid();
        new_party_id UUID;
        reg_num TEXT;
    BEGIN
        IF EXISTS (SELECT 1 FROM public.party_members WHERE user_id = current_user_id) THEN
            RETURN json_build_object('success', false, 'message', 'Você já é membro de um partido. Por favor, desfilie-se antes de criar um novo.');
        END IF;

        reg_num := 'GOVRP-' || nextval('party_reg_num_seq');

        INSERT INTO public.political_parties(name, acronym, ideology, logo_url, founder_id, owner_id, president_id, statute, registration_number, description, orientation, affiliation_mode, status, is_active)
        VALUES(p_name, p_acronym, p_ideology, p_logo_url, current_user_id, current_user_id, current_user_id, p_statute, reg_num, p_description, p_orientation, 'automatic', 'Em Formação', false)
        RETURNING id INTO new_party_id;

        INSERT INTO public.party_members(party_id, user_id, role)
        VALUES(new_party_id, current_user_id, 'Dono');

        RETURN json_build_object('success', true, 'message', 'Partido criado com sucesso!', 'party_id', new_party_id);
    END;
    $$;


ALTER FUNCTION "public"."create_political_party"("p_name" "text", "p_acronym" "text", "p_ideology" "text", "p_logo_url" "text", "p_statute" "text", "p_description" "text", "p_orientation" "public"."political_orientation") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_reply"("p_parent_post_id" "uuid", "p_content" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    parent_author_id UUID;
    replier_username TEXT;
BEGIN
    SELECT user_id INTO parent_author_id FROM public.posts WHERE id = p_parent_post_id;
    SELECT username INTO replier_username FROM public.profiles WHERE id = current_user_id;

    INSERT INTO public.posts(user_id, content, parent_post_id)
    VALUES(current_user_id, p_content, p_parent_post_id);

    UPDATE public.posts
    SET replies_count = replies_count + 1
    WHERE id = p_parent_post_id;

    IF current_user_id <> parent_author_id THEN
        INSERT INTO public.notifications(user_id, content, link)
        VALUES(parent_author_id, replier_username || ' respondeu ao seu post.', '/services/x');
    END IF;
END;
$$;


ALTER FUNCTION "public"."create_reply"("p_parent_post_id" "uuid", "p_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_repost"("p_post_id" "uuid", "p_quote_content" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  current_user_id UUID := auth.uid();
  post_author_id UUID;
  reposter_x_handle TEXT;
BEGIN
    -- Check if the original post exists
    IF NOT EXISTS (SELECT 1 FROM public.posts WHERE id = p_post_id) THEN
      RAISE EXCEPTION 'Original post does not exist.';
    END IF;

    -- Prevent reposting a repost
    IF EXISTS (SELECT 1 FROM public.posts WHERE id = p_post_id AND original_post_id IS NOT NULL) THEN
        RAISE EXCEPTION 'Cannot repost a repost.';
    END IF;

    -- Check if the user has already reposted this post
    IF EXISTS (SELECT 1 FROM public.posts WHERE original_post_id = p_post_id AND user_id = current_user_id) THEN
        RAISE EXCEPTION 'You have already reposted this post.';
    END IF;
    
    -- Insert the new post, which is the repost
    INSERT INTO public.posts (user_id, content, quote_content, original_post_id)
    VALUES (current_user_id, 'repost', p_quote_content, p_post_id);

    -- Increment the reposts_count on the original post
    UPDATE public.posts
    SET reposts_count = reposts_count + 1
    WHERE id = p_post_id;

    -- Create notification for the original author
    SELECT user_id INTO post_author_id FROM public.posts WHERE id = p_post_id;
    
    IF current_user_id <> post_author_id THEN
        SELECT x_handle INTO reposter_x_handle FROM public.profiles WHERE id = current_user_id;
        INSERT INTO public.notifications (user_id, sender_id, type, content, link)
        VALUES (post_author_id, current_user_id, 'x_repost', '@' || reposter_x_handle || ' repostou seu post.', '/services/x');
    END IF;
END;
$$;


ALTER FUNCTION "public"."create_repost"("p_post_id" "uuid", "p_quote_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."create_x_profile"("p_x_handle" "text", "p_x_username" "text") RETURNS json
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    clean_handle TEXT;
    handle_exists BOOLEAN;
    profile_has_x_account BOOLEAN;
BEGIN
    clean_handle := lower(trim(replace(p_x_handle, '@', '')));

    IF p_x_username IS NULL OR trim(p_x_username) = '' OR clean_handle IS NULL OR clean_handle = '' THEN
        RETURN json_build_object('success', false, 'message', 'Nome de usuário e @handle não podem estar vazios.');
    END IF;
    
    IF length(clean_handle) < 4 THEN
        RETURN json_build_object('success', false, 'message', '@handle deve ter pelo menos 4 caracteres.');
    END IF;

    SELECT (x_handle IS NOT NULL) INTO profile_has_x_account FROM public.profiles WHERE id = current_user_id;
    IF profile_has_x_account THEN
        RETURN json_build_object('success', false, 'message', 'Você já possui um perfil X.');
    END IF;

    SELECT EXISTS(SELECT 1 FROM public.profiles WHERE x_handle = clean_handle) INTO handle_exists;
    IF handle_exists THEN
        RETURN json_build_object('success', false, 'message', 'Este @handle já está em uso. Tente outro.');
    END IF;

    UPDATE public.profiles
    SET x_username = p_x_username, x_handle = clean_handle
    WHERE id = current_user_id;

    RETURN json_build_object('success', true, 'message', 'Perfil X criado com sucesso!');
END;
$$;


ALTER FUNCTION "public"."create_x_profile"("p_x_handle" "text", "p_x_username" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."decide_judicial_request"("p_request_id" "uuid", "p_approved" boolean, "p_decision_reason" "text", "p_warrant_duration_rp_days" numeric DEFAULT 7) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_old public.judicial_requests%rowtype;
  v_request public.judicial_requests%rowtype;
  v_warrant public.warrants%rowtype;
  v_warrant_type text;
  v_seconds bigint;
begin
  if not public.justice_has_role(array['Admin', 'Juiz']) then
    raise exception 'ROLE_NOT_AUTHORIZED';
  end if;
  if length(trim(coalesce(p_decision_reason, ''))) < 20 then
    raise exception 'DECISION_REASON_TOO_SHORT';
  end if;

  select * into v_old from public.judicial_requests
  where id = p_request_id for update;
  if not found then raise exception 'REQUEST_NOT_FOUND'; end if;
  if v_old.status <> 'pending' then raise exception 'REQUEST_ALREADY_DECIDED'; end if;
  if v_old.requested_by = (select auth.uid()) then raise exception 'JUDGE_CONFLICT_OF_INTEREST'; end if;
  if v_old.expires_at is not null and v_old.expires_at <= now() then
    update public.judicial_requests set status = 'expired' where id = p_request_id;
    raise exception 'REQUEST_EXPIRED';
  end if;

  update public.judicial_requests
  set status = case when p_approved then 'approved' else 'denied' end,
      decided_by = (select auth.uid()),
      decision_reason = trim(p_decision_reason),
      decided_at = now()
  where id = p_request_id
  returning * into v_request;

  if p_approved and v_request.request_type in ('arrest_warrant', 'search_warrant') then
    v_warrant_type := case
      when v_request.request_type = 'arrest_warrant' then 'arrest'
      else 'search'
    end;
    v_seconds := public.rp_duration_to_real_seconds(p_warrant_duration_rp_days, 'day');

    insert into public.warrants(
      warrant_number, warrant_type, target_profile_id, case_id, investigation_id,
      request_id, issued_by, expires_at, status
    )
    values (
      public.justice_next_number('MAN'), v_warrant_type, v_request.target_profile_id,
      v_request.case_id, v_request.investigation_id, v_request.id,
      (select auth.uid()), now() + make_interval(secs => v_seconds), 'issued'
    )
    returning * into v_warrant;

    perform public.justice_notify(
      v_request.requested_by, 'justice_warrant_issued',
      'O pedido judicial foi aprovado e o mandado ' || v_warrant.warrant_number || ' foi emitido.',
      '/services/justice?view=authority',
      jsonb_build_object('request_id', v_request.id, 'warrant_id', v_warrant.id)
    );
  else
    perform public.justice_notify(
      v_request.requested_by,
      case when p_approved then 'justice_request_approved' else 'justice_request_denied' end,
      case when p_approved then 'Seu pedido judicial foi aprovado.' else 'Seu pedido judicial foi negado.' end,
      '/services/justice?view=authority',
      jsonb_build_object('request_id', v_request.id)
    );
  end if;

  perform public.justice_write_audit(
    'judicial_request.decided', 'judicial_request', v_request.id,
    to_jsonb(v_old), to_jsonb(v_request), p_decision_reason
  );

  return jsonb_build_object('request', to_jsonb(v_request), 'warrant', to_jsonb(v_warrant));
end;
$$;


ALTER FUNCTION "public"."decide_judicial_request"("p_request_id" "uuid", "p_approved" boolean, "p_decision_reason" "text", "p_warrant_duration_rp_days" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_party"("p_party_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
BEGIN
    -- Check if user is the founder
    IF NOT EXISTS (SELECT 1 FROM public.political_parties WHERE id = p_party_id AND founder_id = current_user_id) THEN
        RETURN json_build_object('success', false, 'message', 'Apenas o fundador pode excluir o partido.');
    END IF;

    DELETE FROM public.political_parties WHERE id = p_party_id;
    -- party_members will be deleted by cascade

    RETURN json_build_object('success', true, 'message', 'Partido excluído com sucesso.');
END;
$$;


ALTER FUNCTION "public"."delete_party"("p_party_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_post"("p_post_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    post_info RECORD;
    is_admin BOOLEAN;
    media_path TEXT;
    bucket_name TEXT;
BEGIN
    SELECT role = 'Admin' INTO is_admin FROM public.profiles WHERE id = current_user_id;
    SELECT user_id, image_url, metadata->>'type' as media_type INTO post_info FROM public.posts WHERE id = p_post_id;

    IF post_info IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Post não encontrado.');
    END IF;

    IF post_info.user_id <> current_user_id AND NOT is_admin THEN
        RETURN json_build_object('success', false, 'message', 'Você não tem permissão para excluir este post.');
    END IF;

    -- Delete associated media from storage
    IF post_info.image_url IS NOT NULL THEN
        IF post_info.media_type = 'video' THEN
            bucket_name := 'post-videos';
        ELSE
            bucket_name := 'post-images';
        END IF;
        
        media_path := substring(post_info.image_url from (bucket_name || '/(.*)'));
        
        IF media_path IS NOT NULL THEN
            PERFORM storage.delete_object(bucket_name, media_path);
        END IF;
    END IF;

    DELETE FROM public.posts WHERE id = p_post_id;
    
    RETURN json_build_object('success', true, 'message', 'Post excluído com sucesso.');
END;
$$;


ALTER FUNCTION "public"."delete_post"("p_post_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_repost"("p_original_post_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    repost_id_to_delete UUID;
BEGIN
    -- Find the user's repost of the original post
    SELECT id INTO repost_id_to_delete
    FROM public.posts
    WHERE original_post_id = p_original_post_id AND user_id = current_user_id;

    -- If a repost exists, delete it
    IF repost_id_to_delete IS NOT NULL THEN
        DELETE FROM public.posts WHERE id = repost_id_to_delete;
        
        -- Decrement the reposts_count on the original post
        UPDATE public.posts
        SET reposts_count = GREATEST(0, reposts_count - 1)
        WHERE id = p_original_post_id;
    ELSE
      RAISE EXCEPTION 'Repost not found.';
    END IF;
END;
$$;


ALTER FUNCTION "public"."delete_repost"("p_original_post_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."delete_story"("p_story_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    story_info RECORD;
    media_path TEXT;
    bucket_name TEXT := 'stories';
BEGIN
    SELECT user_id, media_url, media_type INTO story_info FROM public.stories WHERE id = p_story_id;

    IF story_info IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Story não encontrado.');
    END IF;

    IF story_info.user_id <> current_user_id AND (SELECT role FROM public.profiles WHERE id = current_user_id) <> 'Admin' THEN
        RETURN json_build_object('success', false, 'message', 'Você não tem permissão para excluir este story.');
    END IF;

    IF story_info.media_type <> 'text' AND story_info.media_url IS NOT NULL THEN
        -- Extract the path from the full URL
        media_path := substring(story_info.media_url from (bucket_name || '/(.*)'));
        
        IF media_path IS NOT NULL AND media_path <> '' THEN
            PERFORM storage.delete_object(bucket_name, media_path);
        END IF;
    END IF;

    -- Delete associated post if it exists (for text-based stories)
    DELETE FROM public.posts WHERE story_id = p_story_id;
    -- Finally, delete the story
    DELETE FROM public.stories WHERE id = p_story_id;

    RETURN json_build_object('success', true, 'message', 'Story excluído com sucesso.');
EXCEPTION
    WHEN others THEN
        RETURN json_build_object('success', false, 'message', 'Erro interno: ' || SQLERRM);
END;
$$;


ALTER FUNCTION "public"."delete_story"("p_story_id" "uuid") OWNER TO "postgres";


