CREATE OR REPLACE FUNCTION "public"."disaffiliate_from_party"("p_party_id" "uuid", "p_new_founder_id" "uuid" DEFAULT NULL::"uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    party_info RECORD;
    member_count INT;
BEGIN
    SELECT * INTO party_info FROM public.political_parties WHERE id = p_party_id;

    IF NOT EXISTS (SELECT 1 FROM public.party_members WHERE party_id = p_party_id AND user_id = current_user_id) THEN
        RETURN json_build_object('success', false, 'message', 'Você não é membro deste partido.');
    END IF;

    SELECT count(*) INTO member_count FROM public.party_members WHERE party_id = p_party_id;

    IF party_info.founder_id = current_user_id THEN
        IF member_count <= 1 THEN
            DELETE FROM public.political_parties WHERE id = p_party_id;
            RETURN json_build_object('success', true, 'message', 'Você era o último membro. O partido foi extinto.');
        ELSIF p_new_founder_id IS NULL THEN
            -- Replicar lógica automática de sucessão do antigo single-arg function
            PERFORM 1; -- placeholder
            -- Se quiser o comportamento automático original (presidente/vice/mais antigo), cole aqui o bloco do v1
            RETURN json_build_object('success', false, 'message', 'Você deve transferir a posse para outro membro antes de sair.');
        ELSIF NOT EXISTS (SELECT 1 FROM public.party_members WHERE party_id = p_party_id AND user_id = p_new_founder_id AND user_id <> current_user_id) THEN
             RETURN json_build_object('success', false, 'message', 'O novo fundador indicado não é um membro válido do partido.');
        ELSE
            UPDATE public.political_parties SET founder_id = p_new_founder_id, president_id = CASE WHEN president_id = current_user_id THEN p_new_founder_id ELSE president_id END WHERE id = p_party_id;
            UPDATE public.party_members SET role = 'Fundador' WHERE user_id = p_new_founder_id AND party_id = p_party_id;
            DELETE FROM public.party_members WHERE user_id = current_user_id AND party_id = p_party_id;
            RETURN json_build_object('success', true, 'message', 'Você transferiu a posse e saiu do partido.');
        END IF;
    ELSE
        DELETE FROM public.party_members WHERE user_id = current_user_id AND party_id = p_party_id;
        IF (SELECT count(*) FROM party_members WHERE party_id = p_party_id) = 0 THEN
             DELETE FROM public.political_parties WHERE id = p_party_id;
             RETURN json_build_object('success', true, 'message', 'Você era o último membro. O partido foi extinto.');
        END IF;
        RETURN json_build_object('success', true, 'message', 'Você se desfiliou do partido.');
    END IF;
END;
$$;


ALTER FUNCTION "public"."disaffiliate_from_party"("p_party_id" "uuid", "p_new_founder_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."disaffiliate_from_party__v1_bak"("p_party_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    party_info RECORD;
    member_count INT;
    new_founder_id UUID;
BEGIN
    SELECT * INTO party_info FROM public.political_parties WHERE id = p_party_id;
    
    IF NOT EXISTS (SELECT 1 FROM public.party_members WHERE party_id = p_party_id AND user_id = current_user_id) THEN
        RETURN json_build_object('success', false, 'message', 'Você não é membro deste partido.');
    END IF;

    SELECT count(*) INTO member_count FROM public.party_members WHERE party_id = p_party_id;

    IF party_info.founder_id = current_user_id THEN
        IF member_count <= 1 THEN
            DELETE FROM public.political_parties WHERE id = p_party_id;
            RETURN json_build_object('success', true, 'message', 'Você era o último membro. O partido foi extinto.');
        END IF;

        -- Automatic succession logic
        IF party_info.president_id IS NOT NULL AND party_info.president_id <> current_user_id THEN
            new_founder_id := party_info.president_id;
        ELSIF party_info.vice_president_id IS NOT NULL AND party_info.vice_president_id <> current_user_id THEN
            new_founder_id := party_info.vice_president_id;
            -- Promote VP to President as well
            UPDATE public.political_parties SET president_id = new_founder_id WHERE id = p_party_id;
            UPDATE public.party_members SET role = 'Presidente' WHERE user_id = new_founder_id AND party_id = p_party_id;
        ELSE
            -- Find the oldest member as a last resort
            SELECT user_id INTO new_founder_id 
            FROM public.party_members 
            WHERE party_id = p_party_id AND user_id <> current_user_id 
            ORDER BY joined_at ASC 
            LIMIT 1;

            IF new_founder_id IS NULL THEN
              RETURN json_build_object('success', false, 'message', 'Não há um sucessor elegível. O partido não pode ser deixado sem um líder.');
            END IF;
        END IF;

        -- Transfer ownership and then leave
        UPDATE public.political_parties SET founder_id = new_founder_id WHERE id = p_party_id;
        UPDATE public.party_members SET role = 'Fundador' WHERE user_id = new_founder_id AND party_id = p_party_id;
        DELETE FROM public.party_members WHERE user_id = current_user_id AND party_id = p_party_id;
        RETURN json_build_object('success', true, 'message', 'Você transferiu a posse e saiu do partido.');

    ELSE
        -- Normal member leaving
        DELETE FROM public.party_members WHERE user_id = current_user_id AND party_id = p_party_id;
        IF (SELECT count(*) FROM party_members WHERE party_id = p_party_id) = 0 THEN
             DELETE FROM public.political_parties WHERE id = p_party_id;
             RETURN json_build_object('success', true, 'message', 'Você era o último membro. O partido foi extinto.');
        END IF;
        RETURN json_build_object('success', true, 'message', 'Você se desfiliou do partido.');
    END IF;
END;
$$;


ALTER FUNCTION "public"."disaffiliate_from_party__v1_bak"("p_party_id" "uuid") OWNER TO "postgres";


