CREATE OR REPLACE FUNCTION "public"."dismiss_minister"("p_user_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    president_id UUID := auth.uid();
BEGIN
    IF (SELECT role FROM public.profiles WHERE id = president_id) NOT IN ('Presidente', 'Admin') THEN
        RETURN json_build_object('success', false, 'message', 'Apenas o presidente ou admin pode exonerar ministros.');
    END IF;

    DELETE FROM public.ministers WHERE user_id = p_user_id;
    UPDATE public.profiles SET role = 'Cidadão' WHERE id = p_user_id;

    RETURN json_build_object('success', true, 'message', 'Ministro exonerado com sucesso.');
EXCEPTION
    WHEN others THEN
        RETURN json_build_object('success', false, 'message', 'Ocorreu um erro ao exonerar o ministro.');
END;
$$;


ALTER FUNCTION "public"."dismiss_minister"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."economic_has_role"("p_roles" "text"[]) RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select exists (
    select 1
    from public.profiles p
    where p.id = (select auth.uid())
      and (
        lower(p.role) = any (
          select lower(unnest(p_roles))
        )
        or exists (
          select 1
          from unnest(coalesce(p.titles, array[]::text[])) title
          where lower(title) = any (
            select lower(unnest(p_roles))
          )
        )
        or (
          (
            lower(p.role) = 'presidente do banco nacional'
            or exists (
              select 1
              from unnest(coalesce(p.titles, array[]::text[])) title
              where lower(title) = 'presidente do banco nacional'
            )
          )
          and exists (
            select 1
            from unnest(p_roles) requested_role
            where lower(requested_role) in ('banco central', 'presidente do banco central')
          )
        )
      )
  );
$$;


ALTER FUNCTION "public"."economic_has_role"("p_roles" "text"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."election_supersedes_manual_role"("p_role" "text", "p_role_assigned_at" timestamp with time zone) RETURNS boolean
    LANGUAGE "sql" STABLE
    AS $$
  select coalesce(
    exists (
      select 1
      from public.system_settings settings
      cross join lateral jsonb_array_elements(coalesce(settings.value::jsonb->'settlements', '[]'::jsonb)) settlement
      where settings.key = 'election_office_sync'
        and p_role is not null
        and p_role_assigned_at is not null
        and nullif(settlement->>'term_start_at', '') is not null
        and (
          (settlement->>'office_role' = 'Presidente' and p_role in ('Presidente', 'Vice-Presidente'))
          or settlement->>'office_role' = p_role
        )
        and (settlement->>'term_start_at')::timestamptz > p_role_assigned_at
    ),
    false
  );
$$;


ALTER FUNCTION "public"."election_supersedes_manual_role"("p_role" "text", "p_role_assigned_at" timestamp with time zone) OWNER TO "postgres";


