    LANGUAGE "plpgsql"
    SET "search_path" TO 'public'
    AS $$
begin
  if new.term_start_date is null then
    new.term_start_date = current_date;
  end if;

  new.term_end_date = (new.term_start_date + interval '1 month')::date;
  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_parliament_member_monthly_term"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."enforce_required_vice_candidate"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  requires_vice boolean;
begin
  select
    coalesce(et.requires_vice_candidate, false)
    or lower(coalesce(et.name, '')) = 'presidente'
    or lower(coalesce(e.name, '')) like '%presidencial%'
    into requires_vice
  from public.elections e
  join public.election_types et on et.id = e.election_type_id
  where e.id = new.election_id;

  if coalesce(requires_vice, false) and new.vice_candidate_id is null then
    raise exception 'Candidaturas presidenciais exigem vice aceito antes do envio.';
  end if;

  if coalesce(requires_vice, false) and new.vice_candidate_id = new.user_id then
    raise exception 'O candidato nao pode ser o proprio vice.';
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."enforce_required_vice_candidate"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_party_core_leadership"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if new.owner_id is null and new.president_id is null then
    new.owner_id := coalesce(public.get_oldest_party_member(new.id, '{}'::uuid[]), new.founder_id);
    new.president_id := coalesce(
      public.get_oldest_party_member(new.id, array_remove(array[new.owner_id], null)),
      new.owner_id
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."ensure_party_core_leadership"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ensure_profile_exists"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  -- O trigger já deve ter criado o perfil. Esta função existe para compatibilidade
  -- e pode ser chamada após o signUp para garantir que o perfil esteja presente.
  INSERT INTO public.profiles (id, username, full_name, email, role, onboarding_completed, created_at, updated_at)
  SELECT
    au.id,
    COALESCE(NULLIF(au.raw_user_meta_data->>'username',''), 'u_' || substring(au.id::text from 1 for 8)),
    au.raw_user_meta_data->>'full_name',
    au.email,
    'Cidadão',
    false,
    NOW(),
    NOW()
  FROM auth.users au
  LEFT JOIN public.profiles p ON p.id = au.id
  WHERE au.id = auth.uid()
    AND p.id IS NULL;
END;
$$;


ALTER FUNCTION "public"."ensure_profile_exists"() OWNER TO "postgres";


