CREATE OR REPLACE FUNCTION "public"."execute_arrest_warrant"("p_warrant_id" "uuid", "p_location" "text", "p_description" "text") RETURNS "public"."arrests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_warrant public.warrants%rowtype;
  v_arrest public.arrests%rowtype;
  v_facility public.prison_facilities%rowtype;
  v_term_seconds bigint;
begin
  if not public.justice_has_role(array['Admin', 'Policial', 'Police', 'Delegado']) then
    raise exception 'ROLE_NOT_AUTHORIZED';
  end if;
  select * into v_warrant from public.warrants where id = p_warrant_id for update;
  if not found then raise exception 'WARRANT_NOT_FOUND'; end if;
  if v_warrant.status <> 'issued' then raise exception 'WARRANT_NOT_ACTIVE'; end if;
  if v_warrant.expires_at <= now() then
    update public.warrants set status = 'expired' where id = p_warrant_id;
    raise exception 'WARRANT_EXPIRED';
  end if;

  insert into public.arrests(
    arrest_number, arrest_type, suspect_id, officer_id, warrant_id,
    investigation_id, case_id, alleged_crime, description, location,
    expires_at
  )
  values (
    public.justice_next_number('PRI'), 'warrant', v_warrant.target_profile_id,
    (select auth.uid()), v_warrant.id, v_warrant.investigation_id, v_warrant.case_id,
    'Prisão autorizada por mandado ' || v_warrant.warrant_number,
    trim(p_description), trim(p_location), v_warrant.expires_at
  )
  returning * into v_arrest;

  update public.warrants
  set status = 'executed', executed_by = (select auth.uid()), executed_at = now()
  where id = p_warrant_id;

  select * into v_facility from public.prison_facilities
  where is_active order by case security_level
    when 'high' then 1 when 'maximum' then 2 else 3 end
  limit 1;
  if not found then raise exception 'NO_PRISON_FACILITY'; end if;

  v_term_seconds := greatest(600, extract(epoch from (v_warrant.expires_at - now()))::bigint);
  insert into public.prison_terms(
    arrest_id, inmate_id, facility_id, expected_release_at,
    custody_status, security_level, original_duration_seconds
  )
  values (
    v_arrest.id, v_arrest.suspect_id, v_facility.id, v_warrant.expires_at,
    'provisional', v_facility.security_level, v_term_seconds
  );

  perform public.justice_notify(
    v_arrest.suspect_id, 'justice_arrest_executed',
    'Você foi preso em cumprimento ao mandado ' || v_warrant.warrant_number || '.',
    '/services/prison',
    jsonb_build_object('arrest_id', v_arrest.id, 'warrant_id', v_warrant.id)
  );
  perform public.justice_write_audit(
    'warrant.executed', 'warrant', v_warrant.id,
    to_jsonb(v_warrant), jsonb_build_object('status', 'executed', 'arrest_id', v_arrest.id),
    p_description
  );
  return v_arrest;
end;
$$;


ALTER FUNCTION "public"."execute_arrest_warrant"("p_warrant_id" "uuid", "p_location" "text", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."execute_exchange"("p_from_currency" "text", "p_to_currency" "text", "p_from_amount" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  account_record public.accounts%rowtype;
  currency_balances_value jsonb := '{}'::jsonb;
  from_currency text := upper(trim(coalesce(p_from_currency, '')));
  to_currency text := upper(trim(coalesce(p_to_currency, '')));
  from_amount numeric := coalesce(p_from_amount, 0);
  rate_from numeric;
  rate_to numeric;
  from_balance numeric;
  to_balance numeric;
  bank_policy jsonb := '{}'::jsonb;
  fee_free boolean := true;
  fee_type text := 'percentage';
  fee_rate numeric := 0;
  fee_fixed_brl numeric := 0;
  fee_amount numeric := 0;
  net_amount numeric := 0;
  converted_amount numeric := 0;
begin
  if auth.uid() is null then
    return jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  end if;

  if from_currency = '' or to_currency = '' or from_currency = to_currency then
    return jsonb_build_object('success', false, 'message', 'Selecione moedas diferentes para realizar o câmbio.');
  end if;

  if from_amount <= 0 then
    return jsonb_build_object('success', false, 'message', 'Informe um valor positivo para converter.');
  end if;

  rate_from := case from_currency
    when 'BRL' then 1
    when 'USD' then 0.19
    when 'EUR' then 0.17
    when 'GBP' then 0.15
    when 'JPY' then 29.00
    when 'CNY' then 1.36
    else null
  end;

  rate_to := case to_currency
    when 'BRL' then 1
    when 'USD' then 0.19
    when 'EUR' then 0.17
    when 'GBP' then 0.15
    when 'JPY' then 29.00
    when 'CNY' then 1.36
    else null
  end;

  if rate_from is null or rate_to is null then
    return jsonb_build_object('success', false, 'message', 'Moeda não suportada.');
  end if;

  select * into account_record
  from public.accounts
  where user_id = auth.uid()
  order by id
  limit 1
  for update;

  if not found then
    return jsonb_build_object('success', false, 'message', 'Conta bancária não encontrada.');
  end if;

  currency_balances_value := coalesce(account_record.currency_balances, '{}'::jsonb);
  from_balance := case
    when from_currency = 'BRL' then coalesce(account_record.balance, 0)
    else coalesce(nullif(currency_balances_value->>from_currency, '')::numeric, 0)
  end;

  if from_balance < from_amount then
    return jsonb_build_object('success', false, 'message', 'Saldo insuficiente para realizar o câmbio.');
  end if;

  select coalesce(value::jsonb, '{}'::jsonb) into bank_policy
  from public.system_settings
  where key = 'bank_policy';

  fee_free := coalesce((bank_policy->>'exchange_fee_free')::boolean, true);
  fee_type := coalesce(nullif(bank_policy->>'exchange_fee_type', ''), 'percentage');

  if bank_policy ? 'exchange_fee_rate'
     and (bank_policy->>'exchange_fee_rate') ~ '^-?[0-9]+(\.[0-9]+)?$' then
    fee_rate := least(100, greatest(0, (bank_policy->>'exchange_fee_rate')::numeric));
  end if;

  if bank_policy ? 'exchange_fee_fixed_amount'
     and (bank_policy->>'exchange_fee_fixed_amount') ~ '^-?[0-9]+(\.[0-9]+)?$' then
    fee_fixed_brl := greatest(0, (bank_policy->>'exchange_fee_fixed_amount')::numeric);
  end if;

  if fee_free then
    fee_amount := 0;
  elsif fee_type = 'fixed' then
    fee_amount := case
      when from_currency = 'BRL' then fee_fixed_brl
      else fee_fixed_brl * rate_from
    end;
  else
    fee_amount := from_amount * fee_rate / 100;
  end if;

  fee_amount := least(from_amount, round(greatest(0, fee_amount), 4));
  net_amount := from_amount - fee_amount;
  converted_amount := round((net_amount / rate_from) * rate_to, 4);

  if from_currency = 'BRL' then
    account_record.balance := coalesce(account_record.balance, 0) - from_amount;
  else
    currency_balances_value := jsonb_set(
      currency_balances_value,
      array[from_currency],
      to_jsonb(round(from_balance - from_amount, 4)),
      true
    );
  end if;

  if to_currency = 'BRL' then
    account_record.balance := coalesce(account_record.balance, 0) + converted_amount;
  else
    to_balance := coalesce(nullif(currency_balances_value->>to_currency, '')::numeric, 0);
    currency_balances_value := jsonb_set(
      currency_balances_value,
      array[to_currency],
      to_jsonb(round(to_balance + converted_amount, 4)),
      true
    );
  end if;

  update public.accounts
  set
    balance = round(account_record.balance, 2),
    currency_balances = currency_balances_value
  where id = account_record.id;

  return jsonb_build_object(
    'success', true,
    'message', 'Câmbio realizado com sucesso.',
    'from_currency', from_currency,
    'to_currency', to_currency,
    'from_amount', from_amount,
    'fee_amount', fee_amount,
    'net_amount', net_amount,
    'converted_amount', converted_amount
  );
end;
$_$;


ALTER FUNCTION "public"."execute_exchange"("p_from_currency" "text", "p_to_currency" "text", "p_from_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."execute_transfer"("p_sender_id" "uuid", "p_recipient_id" "uuid", "p_amount" numeric, "p_description" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
    sender_account RECORD;
    recipient_account RECORD;
    new_transaction_id UUID;
    sender_profile RECORD;
    tax_settings JSONB;
    tax_type TEXT;
    tax_value NUMERIC;
    tax_amount NUMERIC := 0;
    total_deduction NUMERIC;
BEGIN
    IF p_sender_id = p_recipient_id THEN
        RETURN json_build_object('success', false, 'message', 'Não é possível transferir para si mesmo.');
    END IF;

    SELECT * INTO sender_account FROM public.accounts WHERE user_id = p_sender_id;
    SELECT * INTO recipient_account FROM public.accounts WHERE user_id = p_recipient_id;

    IF sender_account IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Sua conta de origem não foi encontrada.');
    END IF;
    IF recipient_account IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'A conta do destinatário não foi encontrada.');
    END IF;
    IF p_amount < 0.01 THEN
        RETURN json_build_object('success', false, 'message', 'O valor mínimo para transferência é de R$ 0,01.');
    END IF;

    -- Calculate transaction tax
    SELECT value INTO tax_settings FROM public.system_settings WHERE key = 'transaction_tax';
    IF tax_settings IS NOT NULL AND (tax_settings->>'value')::numeric > 0 THEN
        tax_type := tax_settings->>'type';
        tax_value := (tax_settings->>'value')::numeric;

        IF tax_type = 'percentage' THEN
            tax_amount := p_amount * tax_value;
        ELSIF tax_type = 'fixed' THEN
            tax_amount := tax_value;
        END IF;
    END IF;

    total_deduction := p_amount + tax_amount;

    IF sender_account.balance < total_deduction THEN
        RETURN json_build_object('success', false, 'message', 'Saldo insuficiente para realizar a transferência (incluindo impostos).');
    END IF;

    -- Execute transactions
    UPDATE public.accounts SET balance = balance - total_deduction, updated_at = now() WHERE id = sender_account.id;
    UPDATE public.accounts SET balance = balance + p_amount, updated_at = now() WHERE id = recipient_account.id;
    
    IF tax_amount > 0 THEN
        UPDATE public.government_finances SET treasury_balance = treasury_balance + tax_amount WHERE id = 1;
    END IF;

    INSERT INTO public.transactions(from_account_id, to_account_id, amount, description, type, metadata)
    VALUES (sender_account.id, recipient_account.id, p_amount, COALESCE(p_description, 'Transferência'), 'transfer', 
            jsonb_build_object('tax_amount', tax_amount, 'tax_details', tax_settings))
    RETURNING id INTO new_transaction_id;
    
    SELECT full_name INTO sender_profile FROM public.profiles p WHERE p.id = p_sender_id;
    
    INSERT INTO public.notifications(user_id, sender_id, type, content, link)
    VALUES (p_recipient_id, p_sender_id, 'transfer_received', 'Você recebeu uma transferência de ' || to_char(p_amount, 'FM999G999G990D00') || ' de ' || sender_profile.full_name, '/services/bank');
    
    RETURN json_build_object('success', true, 'message', 'Transferência realizada com sucesso!', 'transaction_id', new_transaction_id);
EXCEPTION
    WHEN others THEN
        RETURN json_build_object('success', false, 'message', 'Ocorreu um erro inesperado durante a transação.');
END;
$_$;


ALTER FUNCTION "public"."execute_transfer"("p_sender_id" "uuid", "p_recipient_id" "uuid", "p_amount" numeric, "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."expel_party_member"("p_party_id" "uuid", "p_member_id_to_expel" "uuid", "p_reason" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
    DECLARE
        expeller_id UUID := auth.uid();
        expeller_role party_role;
        member_to_expel_role party_role;
        party_info RECORD;
        member_name TEXT;
    BEGIN
        SELECT * INTO party_info FROM public.political_parties WHERE id = p_party_id;
        
        -- Get roles
        SELECT role INTO expeller_role FROM public.party_members WHERE user_id = expeller_id AND party_id = p_party_id;
        SELECT role INTO member_to_expel_role FROM public.party_members WHERE user_id = p_member_id_to_expel AND party_id = p_party_id;
        
        -- Check if member to expel exists
        IF member_to_expel_role IS NULL THEN
            RETURN json_build_object('success', false, 'message', 'Membro não encontrado no partido.');
        END IF;

        -- Check permissions
        IF expeller_role IS NULL OR expeller_role NOT IN ('Dono', 'Presidente') THEN
            RETURN json_build_object('success', false, 'message', 'Você não tem permissão para expulsar membros.');
        END IF;
        
        -- Hierarchy check
        IF (expeller_role = 'Presidente' AND member_to_expel_role = 'Dono') THEN
             RETURN json_build_object('success', false, 'message', 'O Presidente não pode expulsar o Dono do partido.');
        END IF;
        
        -- Get member name for notifications
        SELECT full_name INTO member_name FROM public.profiles WHERE id = p_member_id_to_expel;

        -- Expel member
        DELETE FROM public.party_members WHERE user_id = p_member_id_to_expel AND party_id = p_party_id;
        
        -- Notify expelled member
        INSERT INTO public.notifications (user_id, sender_id, type, content, link)
        VALUES (p_member_id_to_expel, expeller_id, 'party_expelled', 'Você foi expulso do partido ' || party_info.name || '. Motivo: ' || p_reason, '/services/political-parties');

        -- Notify remaining members
        INSERT INTO public.notifications (user_id, type, content, link)
        SELECT pm.user_id, 'party_member_left', member_name || ' foi expulso do partido ' || party_info.name || '.', '/services/political-parties/' || p_party_id
        FROM public.party_members pm WHERE pm.party_id = p_party_id;

        RETURN json_build_object('success', true, 'message', 'Membro expulso com sucesso.');
    END;
    $$;


ALTER FUNCTION "public"."expel_party_member"("p_party_id" "uuid", "p_member_id_to_expel" "uuid", "p_reason" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."extract_hashtags"("content" "text") RETURNS "text"[]
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
BEGIN
  RETURN (SELECT array_agg(DISTINCT lower(tags[1])) FROM regexp_matches(content, '#([a-zA-Z0-9_]+)', 'g') AS tags);
END;
$$;


