);


ALTER TABLE "public"."criminal_cases" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."file_criminal_charges"("p_investigation_id" "uuid", "p_defendant_id" "uuid", "p_title" "text", "p_facts" "text", "p_charges" "jsonb") RETURNS "public"."criminal_cases"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_case public.criminal_cases%rowtype;
  v_charge jsonb;
  v_penal public.penal_code%rowtype;
begin
  if not public.justice_has_role(array['Admin', 'Promotor']) then
    raise exception 'ROLE_NOT_AUTHORIZED';
  end if;
  if length(trim(coalesce(p_facts, ''))) < 40 then raise exception 'FACTS_TOO_SHORT'; end if;
  if jsonb_typeof(p_charges) <> 'array' or jsonb_array_length(p_charges) = 0 then
    raise exception 'AT_LEAST_ONE_CHARGE_REQUIRED';
  end if;
  if not exists (
    select 1 from public.criminal_investigations
    where id = p_investigation_id and status = 'sent_to_prosecutor'
  ) then raise exception 'INVESTIGATION_NOT_READY_FOR_CHARGES'; end if;
  if not exists (
    select 1 from public.investigation_parties
    where investigation_id = p_investigation_id
      and profile_id = p_defendant_id and party_type = 'suspect'
  ) then raise exception 'DEFENDANT_NOT_INVESTIGATION_SUSPECT'; end if;

  insert into public.criminal_cases(
    case_number, investigation_id, prosecutor_id, status, title, summary, filed_at
  )
  values (
    public.justice_next_number('GOV'), p_investigation_id, (select auth.uid()),
    'charge_filed', trim(p_title), trim(p_facts), now()
  )
  returning * into v_case;

  insert into public.case_parties(case_id, profile_id, party_type, representation_status)
  values
    (v_case.id, p_defendant_id, 'defendant', 'pending'),
    (v_case.id, (select auth.uid()), 'prosecutor', 'active');

  for v_charge in select * from jsonb_array_elements(p_charges)
  loop
    select * into v_penal from public.penal_code
    where id = (v_charge->>'penal_code_id')::uuid and is_active;
    if not found then raise exception 'INVALID_PENAL_CODE'; end if;

    insert into public.case_charges(
      case_id, defendant_id, penal_code_id, charge_description,
      aggravating_factors, mitigating_factors, requested_sentence, attempted
    )
    values (
      v_case.id, p_defendant_id, v_penal.id,
      coalesce(nullif(trim(v_charge->>'description'), ''), v_penal.name),
      coalesce(v_charge->'aggravating_factors', '[]'::jsonb),
      coalesce(v_charge->'mitigating_factors', '[]'::jsonb),
      nullif(v_charge->>'requested_sentence', '')::numeric,
      coalesce((v_charge->>'attempted')::boolean, false)
    );
  end loop;

  perform public.justice_assign_case_judge(v_case.id);
  select * into v_case from public.criminal_cases where id = v_case.id;

  perform public.justice_notify(
    p_defendant_id, 'justice_charges_filed',
    'Foi apresentada denúncia no processo ' || v_case.case_number || '.',
    '/services/justice?view=citizen',
    jsonb_build_object('case_id', v_case.id, 'case_number', v_case.case_number)
  );

  perform public.justice_write_audit(
    'case.charges_filed', 'criminal_case', v_case.id,
    null, to_jsonb(v_case), p_facts
  );

  return v_case;
end;
$$;


ALTER FUNCTION "public"."file_criminal_charges"("p_investigation_id" "uuid", "p_defendant_id" "uuid", "p_title" "text", "p_facts" "text", "p_charges" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."finalize_temporary_commission_voting"("p_commission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_commission record;
  v_voting record;
  v_seat_count integer;
  v_vote_count integer;
  v_approve_count integer;
  v_reject_count integer;
  v_decisive_count integer;
  v_passed boolean;
begin
  select pc.*, pch.house_id
    into v_commission
    from public.parliament_commissions pc
    join public.parliament_commission_houses pch
      on pch.commission_id = pc.id
   where pc.id = p_commission_id
   limit 1;

  if not found then
    raise exception 'Comissão não encontrada.';
  end if;

  if v_commission.type <> 'temporary' then
    raise exception 'Apenas comissões temporárias podem finalizar este fluxo.';
  end if;

  if v_commission.voting_id is null then
    raise exception 'Não há votação vinculada a esta comissão.';
  end if;

  select *
    into v_voting
    from public.parliament_votings
   where id = v_commission.voting_id;

  if not found then
    raise exception 'Votação vinculada não encontrada.';
  end if;

  select count(*)
    into v_seat_count
    from public.parliament_members
   where house_id = v_commission.house_id
     and term_end_date >= current_date;

  select
    count(*),
    count(*) filter (where vote = 'Aprovar'),
    count(*) filter (where vote = 'Rejeitar')
    into v_vote_count, v_approve_count, v_reject_count
    from public.parliament_voting_votes
   where voting_id = v_voting.id;

  if v_voting.status <> 'active' then
    return jsonb_build_object(
      'success', true,
      'approved', v_commission.status = 'approved_pending_officialization',
      'message', 'A votação desta comissão já foi encerrada.'
    );
  end if;

  if v_vote_count < coalesce(v_seat_count, 0)
     and (v_voting.end_date is null or v_voting.end_date > now()) then
    return jsonb_build_object(
      'success', false,
      'message', 'A votação ainda está em andamento.'
    );
  end if;

  v_decisive_count := coalesce(v_approve_count, 0) + coalesce(v_reject_count, 0);
  v_passed := v_decisive_count > 0 and coalesce(v_approve_count, 0) > coalesce(v_reject_count, 0);

  update public.parliament_votings
     set status = 'closed'
   where id = v_voting.id;

  update public.parliament_commissions
     set status = case
       when v_passed then 'approved_pending_officialization'
       else 'rejected'
     end,
         closed_at = case when v_passed then closed_at else now() end
   where id = p_commission_id;

  return jsonb_build_object(
    'success', true,
    'approved', v_passed,
    'message', case
      when v_passed then 'Plenário aprovou a comissão temporária. Ela aguarda oficialização da Presidência da Casa.'
      else 'Comissão temporária rejeitada pelo plenário.'
    end
  );
end;
$$;


ALTER FUNCTION "public"."finalize_temporary_commission_voting"("p_commission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_recipient"("p_method" "text", "p_value1" "text", "p_value2" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    recipient_info RECORD;
    current_user_id UUID := auth.uid();
BEGIN
    IF p_method = 'key' THEN
        SELECT p.id as user_id, p.full_name, a.transfer_key, a.cpf, a.agency_number, a.account_number
        INTO recipient_info
        FROM public.accounts a
        JOIN public.profiles p ON a.user_id = p.id
        WHERE a.transfer_key = upper(p_value1);
    ELSIF p_method = 'cpf' THEN
        SELECT p.id as user_id, p.full_name, a.transfer_key, a.cpf, a.agency_number, a.account_number
        INTO recipient_info
        FROM public.accounts a
        JOIN public.profiles p ON a.user_id = p.id
        WHERE a.cpf = p_value1;
    ELSIF p_method = 'account' THEN
        SELECT p.id as user_id, p.full_name, a.transfer_key, a.cpf, a.agency_number, a.account_number
        INTO recipient_info
        FROM public.accounts a
        JOIN public.profiles p ON a.user_id = p.id
        WHERE a.agency_number = p_value1 AND a.account_number = p_value2;
    ELSE
        RETURN json_build_object('found', false, 'message', 'Método de busca inválido.');
    END IF;

    IF recipient_info IS NULL THEN
        RETURN json_build_object('found', false, 'message', 'Destinatário não encontrado.');
    ELSIF recipient_info.user_id = current_user_id THEN
        RETURN json_build_object('found', false, 'message', 'Você não pode transferir para si mesmo.');
    ELSE
        RETURN json_build_object('found', true, 'user_id', recipient_info.user_id, 'full_name', recipient_info.full_name, 'transfer_key', recipient_info.transfer_key, 'cpf', recipient_info.cpf, 'agency_number', recipient_info.agency_number, 'account_number', recipient_info.account_number);
    END IF;
EXCEPTION
    WHEN others THEN
        RETURN json_build_object('found', false, 'message', 'Erro ao buscar destinatário.');
END;
$$;


ALTER FUNCTION "public"."find_recipient"("p_method" "text", "p_value1" "text", "p_value2" "text") OWNER TO "postgres";


