CREATE OR REPLACE FUNCTION "public"."founder_leave_party"("p_party_id" "uuid", "p_new_founder_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    party_info RECORD;
    member_count INT;
BEGIN
    -- Check if user is the founder
    SELECT * INTO party_info FROM public.political_parties WHERE id = p_party_id AND founder_id = current_user_id;
    IF party_info IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Você não é o fundador deste partido.');
    END IF;

    -- Get member count
    SELECT count(*) INTO member_count FROM public.party_members WHERE party_id = p_party_id;

    -- If founder is the last member, delete the party
    IF member_count <= 1 THEN
        DELETE FROM public.political_parties WHERE id = p_party_id;
        RETURN json_build_object('success', true, 'message', 'Você era o último membro. O partido foi extinto.');
    END IF;

    -- If there are other members, a new founder must be designated
    IF p_new_founder_id IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Você deve transferir a posse para outro membro antes de sair.');
    END IF;

    -- Transfer ownership and leave
    UPDATE public.political_parties SET founder_id = p_new_founder_id WHERE id = p_party_id;
    UPDATE public.party_members SET role = 'Fundador' WHERE user_id = p_new_founder_id AND party_id = p_party_id;
    DELETE FROM public.party_members WHERE user_id = current_user_id AND party_id = p_party_id;

    RETURN json_build_object('success', true, 'message', 'Você transferiu a posse e saiu do partido.');
END;
$$;


ALTER FUNCTION "public"."founder_leave_party"("p_party_id" "uuid", "p_new_founder_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_bill_for_fine"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    new_bill_code TEXT;
BEGIN
    -- Generate a unique bill code
    new_bill_code := 'FINE-' || substr(md5(random()::text || clock_timestamp()::text), 1, 10);

    -- Insert into bills_of_exchange
    INSERT INTO public.bills_of_exchange(issuer_id, payer_id, bill_code, amount, due_date, status, description)
    VALUES (
        '00000000-0000-0000-0000-000000000001', -- Government account as issuer
        NEW.user_id,
        new_bill_code,
        NEW.amount,
        NEW.due_date,
        'pending',
        'Multa Policial: ' || NEW.reason
    );

    -- Update the fine with the bill code
    NEW.bill_code := new_bill_code;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."generate_bill_for_fine"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_card_number"() RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
declare
  generated_number text;
begin
  loop
    generated_number := (
      floor(random() * 9000000000000000 + 1000000000000000)::bigint
    )::text;

    exit when not exists (
      select 1 from public.cards where card_number = generated_number
    );
  end loop;

  return generated_number;
end;
$$;


