CREATE OR REPLACE FUNCTION "public"."generate_transaction_receipt"("p_transaction_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    receipt_data RECORD;
    current_user_id UUID := auth.uid();
    is_involved BOOLEAN;
    is_admin_user BOOLEAN;
    seller_cnpj_details JSONB;
    recipient_user_id UUID;
    total_amount NUMERIC;
BEGIN
    SELECT EXISTS (SELECT 1 FROM public.profiles WHERE id = current_user_id AND role = 'Admin') INTO is_admin_user;

    SELECT EXISTS (
        SELECT 1
        FROM public.transactions t
        LEFT JOIN public.accounts a_from ON t.from_account_id = a_from.id
        LEFT JOIN public.accounts a_to ON t.to_account_id = a_to.id
        WHERE t.id = p_transaction_id AND (a_from.user_id = current_user_id OR a_to.user_id = current_user_id)
    ) INTO is_involved;

    IF NOT is_involved AND NOT is_admin_user THEN
        RETURN jsonb_build_object('success', false, 'message', 'Você não tem permissão para ver este comprovante.');
    END IF;

    SELECT
        t.id,
        t.amount, -- This is the base amount
        t.description,
        t.type,
        t.created_at,
        t.metadata,
        COALESCE((t.metadata->>'tax_amount')::numeric, 0) as tax_amount, -- get tax from metadata
        sender_p.full_name as sender_name,
        sender_p.role as sender_role,
        sender_acc.transfer_key as sender_key,
        sender_acc.cpf as sender_cpf,
        sender_acc.agency_number as sender_agency,
        sender_acc.account_number as sender_account,
        recipient_p.full_name as recipient_name,
        recipient_p.role as recipient_role,
        recipient_acc.transfer_key as recipient_key,
        recipient_acc.cpf as recipient_cpf,
        recipient_acc.agency_number as recipient_agency,
        recipient_acc.account_number as recipient_account,
        recipient_acc.user_id as recipient_user_id
    INTO receipt_data
    FROM public.transactions t
    LEFT JOIN public.accounts sender_acc ON t.from_account_id = sender_acc.id
    LEFT JOIN public.profiles sender_p ON sender_acc.user_id = sender_p.id
    LEFT JOIN public.accounts recipient_acc ON t.to_account_id = recipient_acc.id
    LEFT JOIN public.profiles recipient_p ON recipient_acc.user_id = recipient_p.id
    WHERE t.id = p_transaction_id;

    IF receipt_data IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Comprovante não encontrado.');
    END IF;
    
    total_amount := receipt_data.amount + receipt_data.tax_amount;

    IF receipt_data.recipient_role = 'PJ' THEN
        SELECT jsonb_build_object(
            'cnpj', d.document_number,
            'business_name', d.metadata->>'business_name',
            'trade_name', d.metadata->>'trade_name'
        )
        INTO seller_cnpj_details
        FROM public.documents d
        WHERE d.user_id = receipt_data.recipient_user_id
        AND d.type = 'CNPJ'
        LIMIT 1;

        receipt_data.metadata := jsonb_set(COALESCE(receipt_data.metadata, '{}'::jsonb), '{seller_cnpj_details}', seller_cnpj_details);
    END IF;
    
    RETURN jsonb_build_object('success', true, 'total_amount', total_amount) || jsonb_strip_nulls(to_jsonb(receipt_data));
END;
$$;


ALTER FUNCTION "public"."generate_transaction_receipt"("p_transaction_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_transfer_key_for_user"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    user_account RECORD;
    new_key TEXT;
BEGIN
    SELECT * INTO user_account FROM public.accounts WHERE user_id = current_user_id;

    IF user_account IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Você não possui uma conta bancária.');
    END IF;

    IF user_account.transfer_key IS NOT NULL THEN
        RETURN json_build_object('success', false, 'message', 'Você já possui uma chave de transferência.');
    END IF;

    new_key := public.generate_unique_transfer_key();

    UPDATE public.accounts SET transfer_key = new_key WHERE user_id = current_user_id;

    RETURN json_build_object('success', true, 'message', 'Sua chave de transferência foi gerada com sucesso!', 'transfer_key', new_key);
END;
$$;


ALTER FUNCTION "public"."generate_transfer_key_for_user"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_unique_document_number"("doc_type" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    new_number text;
    is_unique boolean := false;
BEGIN
    WHILE NOT is_unique LOOP
        IF doc_type = 'CNH' THEN
            new_number := lpad(floor(random() * 100000000000)::text, 11, '0');
        ELSIF doc_type = 'Passport' THEN
            new_number := 'PA' || lpad(floor(random() * 10000000)::text, 7, '0');
        ELSIF doc_type = 'CNPJ' THEN
            new_number := lpad(floor(random() * 10000000000000)::text, 14, '0');
            new_number := substring(new_number, 1, 2) || '.' || substring(new_number, 3, 3) || '.' || substring(new_number, 6, 3) || '/' || substring(new_number, 9, 4) || '-' || substring(new_number, 13, 2);
        ELSIF doc_type = 'CTD' THEN
            new_number := lpad(floor(random() * 10000000)::text, 7, '0') || ' ' || lpad(floor(random() * 1000)::text, 3, '0') || ' ' || lpad(floor(random() * 100)::text, 2, '0');
        ELSIF doc_type = 'Título de Eleitor' THEN
             new_number := lpad(floor(random() * 100000000000)::text, 12, '0');
        ELSIF doc_type = 'Certificado de Reservista' THEN
             new_number := lpad(floor(random() * 100000000000)::text, 12, '0');
        ELSIF doc_type = 'Certidão de Casamento' THEN
             new_number := lpad(floor(random() * 1000000000000000)::text, 16, '0');
        ELSIF doc_type = 'Registro Profissional' THEN
             new_number := 'RP' || lpad(floor(random() * 1000000000)::text, 10, '0');
        ELSE
            RAISE EXCEPTION 'Tipo de documento inválido: %', doc_type;
        END IF;

        SELECT NOT EXISTS (
            SELECT 1 FROM public.documents WHERE document_number = new_number AND type = doc_type
        ) INTO is_unique;
    END LOOP;
    RETURN new_number;
END;
$$;


ALTER FUNCTION "public"."generate_unique_document_number"("doc_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."generate_unique_transfer_key"() RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    new_key TEXT;
    key_exists BOOLEAN;
BEGIN
    LOOP
        new_key := (
            SELECT string_agg(c, '')
            FROM (
                SELECT c
                FROM unnest(string_to_array('ABCDEFGHIJKLMNPQRSTUVWXYZ123456789', NULL)) AS c
                ORDER BY random()
                LIMIT 5
            ) AS s
        );
        
        SELECT EXISTS(SELECT 1 FROM public.accounts WHERE transfer_key = new_key) INTO key_exists;
        
        IF NOT key_exists THEN
            RETURN new_key;
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."generate_unique_transfer_key"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_account_transactions"("p_account_id" "uuid") RETURNS TABLE("id" "uuid", "created_at" timestamp with time zone, "type" "text", "amount" double precision, "description" "text", "metadata" "jsonb", "direction" "text", "other_party_name" "text")
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    RETURN QUERY
    SELECT
        t.id,
        t.created_at,
        t.type,
        t.amount,
        t.description,
        t.metadata,
        -- Define a direção (enviado ou recebido)
        CASE WHEN t.from_account_id = p_account_id THEN 'sent'::text ELSE 'received'::text END as direction,
        -- A lógica crucial: escolhe o nome do destinatário se for 'sent', ou o nome do remetente se for 'received'
        CASE
            WHEN t.from_account_id = p_account_id THEN p_receiver.full_name
            ELSE p_sender.full_name
        END as other_party_name
    FROM
        public.transactions t
    -- Junta as tabelas para encontrar os detalhes do REMETENTE
    LEFT JOIN public.accounts a_sender ON t.from_account_id = a_sender.id
    LEFT JOIN public.profiles p_sender ON a_sender.user_id = p_sender.id
    -- Junta as tabelas para encontrar os detalhes do DESTINATÁRIO
    LEFT JOIN public.accounts a_receiver ON t.to_account_id = a_receiver.id
    LEFT JOIN public.profiles p_receiver ON a_receiver.user_id = p_receiver.id
    WHERE
        t.from_account_id = p_account_id OR t.to_account_id = p_account_id
    ORDER BY
        t.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."get_account_transactions"("p_account_id" "uuid") OWNER TO "postgres";


