CREATE OR REPLACE FUNCTION "public"."get_admin_dashboard_stats"() RETURNS TABLE("total_users" bigint, "total_posts" bigint, "total_transactions" bigint, "total_accounts" bigint, "total_comments" bigint, "total_cards" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Verifica se o usuário autenticado tem o papel “Admin”
    IF (SELECT role FROM public.profiles WHERE id = (SELECT auth.uid())) <> 'Admin' THEN
        RAISE EXCEPTION 'Acesso negado: apenas administradores podem consultar estas estatísticas';
    END IF;

    RETURN QUERY
    SELECT
        (SELECT COUNT(*) FROM public.profiles)          AS total_users,
        (SELECT COUNT(*) FROM public.posts)             AS total_posts,
        (SELECT COUNT(*) FROM public.transactions)      AS total_transactions,
        (SELECT COUNT(*) FROM public.accounts)          AS total_accounts,
        (SELECT COUNT(*) FROM public.comments)          AS total_comments,
        (SELECT COUNT(*) FROM public.cards)             AS total_cards;
END;
$$;


ALTER FUNCTION "public"."get_admin_dashboard_stats"() OWNER TO "postgres";


