CREATE OR REPLACE FUNCTION "public"."get_citizen_economic_dashboard"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare result jsonb;
begin
  if auth.uid() is null then raise exception 'Autenticação obrigatória.' using errcode='42501'; end if;
  select jsonb_build_object(
    'status',to_jsonb(s),
    'latest_snapshot',to_jsonb(cs),
    'history',coalesce((select jsonb_agg(to_jsonb(h) order by h.ends_at_rp)
      from (
        select p.ends_at_rp,c.nominal_income,c.disposable_income,c.real_income,
          c.consumption,c.savings,c.debt,c.basket_cost,c.purchasing_power_index,
          c.consumer_confidence,c.poverty_status
        from public.citizen_economic_snapshots c
        join public.economic_periods p on p.id=c.period_id
        where c.profile_id=auth.uid()
        order by p.ends_at_rp desc limit 12
      ) h),'[]'::jsonb),
    'opportunities',jsonb_build_object(
      'open_vacancies',economy_private.latest_indicator('open_vacancies'),
      'average_wage',economy_private.latest_indicator('average_wage'),
      'inflation_annual',economy_private.latest_indicator('inflation_annual'),
      'current_selic',(select current_selic from public.economic_state where id=true)
    )
  ) into result
  from public.citizen_economic_statuses s
  left join lateral (
    select c.* from public.citizen_economic_snapshots c
    join public.economic_periods p on p.id=c.period_id
    where c.profile_id=auth.uid()
    order by p.ends_at_rp desc limit 1
  ) cs on true
  where s.profile_id=auth.uid();
  return coalesce(result,jsonb_build_object('status',null,'latest_snapshot',null,'history','[]'::jsonb));
end;
$$;


ALTER FUNCTION "public"."get_citizen_economic_dashboard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_daily_check_in_status"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_config jsonb := '{}'::jsonb;
  v_timezone text := 'America/Sao_Paulo';
  v_today date;
  v_has_bank_account boolean := false;
  v_latest_check_in public.daily_check_ins%rowtype;
  v_has_checked_in_today boolean := false;
  v_current_streak integer := 0;
  v_next_streak integer := 1;
  v_preview_streak integer := 1;
  v_base_reward numeric(12, 2) := 150;
  v_streak_bonus numeric(12, 2) := 25;
  v_weekly_bonus numeric(12, 2) := 200;
  v_reputation_reward integer := 3;
  v_streak_bonus_amount numeric(12, 2) := 0;
  v_weekly_bonus_amount numeric(12, 2) := 0;
  v_reward_preview_amount numeric(12, 2) := 0;
begin
  if v_user_id is null then
    raise exception 'Usuario nao autenticado.';
  end if;

  select value
    into v_config
  from public.system_settings
  where key = 'daily_check_in_config';

  v_timezone := coalesce(nullif(v_config ->> 'timezone', ''), v_timezone);
  v_base_reward := coalesce((v_config ->> 'base_reward')::numeric, v_base_reward);
  v_streak_bonus := coalesce((v_config ->> 'streak_bonus')::numeric, v_streak_bonus);
  v_weekly_bonus := coalesce((v_config ->> 'weekly_bonus')::numeric, v_weekly_bonus);
  v_reputation_reward := coalesce((v_config ->> 'reputation_reward')::integer, v_reputation_reward);
  v_today := timezone(v_timezone, now())::date;

  select exists(
    select 1
    from public.accounts
    where user_id = v_user_id
  )
    into v_has_bank_account;

  select *
    into v_latest_check_in
  from public.daily_check_ins
  where user_id = v_user_id
  order by reward_date desc
  limit 1;

  if found then
    if v_latest_check_in.reward_date = v_today then
      v_has_checked_in_today := true;
      v_current_streak := v_latest_check_in.streak_count;
      v_next_streak := v_latest_check_in.streak_count;
    elsif v_latest_check_in.reward_date = (v_today - 1) then
      v_current_streak := v_latest_check_in.streak_count;
      v_next_streak := v_latest_check_in.streak_count + 1;
    end if;
  end if;

  v_preview_streak := case
    when v_has_checked_in_today then greatest(v_current_streak + 1, 1)
    else greatest(v_next_streak, 1)
  end;

  v_streak_bonus_amount := greatest(v_preview_streak - 1, 0) * v_streak_bonus;
  v_weekly_bonus_amount := case
    when mod(v_preview_streak, 7) = 0 then v_weekly_bonus
    else 0
  end;
  v_reward_preview_amount := v_base_reward + v_streak_bonus_amount + v_weekly_bonus_amount;

  return jsonb_build_object(
    'has_bank_account', v_has_bank_account,
    'has_checked_in_today', v_has_checked_in_today,
    'can_claim_today', v_has_bank_account and not v_has_checked_in_today,
    'current_streak', v_current_streak,
    'next_streak', v_preview_streak,
    'last_reward_date', v_latest_check_in.reward_date,
    'last_checked_in_at', v_latest_check_in.checked_in_at,
    'reward_preview_amount', v_reward_preview_amount,
    'streak_bonus_amount', v_streak_bonus_amount,
    'weekly_bonus_amount', v_weekly_bonus_amount,
    'reputation_reward', v_reputation_reward,
    'next_claim_date', case
      when v_has_checked_in_today then v_today + 1
      else v_today
    end,
    'timezone', v_timezone
  );
end;
$$;


ALTER FUNCTION "public"."get_daily_check_in_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_dashboard_growth_stats"() RETURNS TABLE("new_users_last_24h" bigint, "new_posts_last_24h" bigint, "new_transactions_last_24h" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- Verifica o papel do usuário chamador
    IF (SELECT role FROM public.profiles WHERE id = (SELECT auth.uid())) <> 'Admin' THEN
        RAISE EXCEPTION 'Acesso negado: apenas administradores podem consultar estas estatísticas';
    END IF;

    RETURN QUERY
    SELECT
        (SELECT COUNT(*) FROM public.profiles
         WHERE created_at >= now() - interval '24 hours')          AS new_users_last_24h,
        (SELECT COUNT(*) FROM public.posts
         WHERE created_at >= now() - interval '24 hours')          AS new_posts_last_24h,
        (SELECT COUNT(*) FROM public.transactions
         WHERE created_at >= now() - interval '24 hours')          AS new_transactions_last_24h;
END;
$$;


ALTER FUNCTION "public"."get_dashboard_growth_stats"() OWNER TO "postgres";


