CREATE OR REPLACE FUNCTION "public"."get_election_results"("p_election_id" "uuid") RETURNS TABLE("candidate_id" "uuid", "political_name" "text", "campaign_photo_url" "text", "party_name" "text", "party_logo_url" "text", "vote_count" bigint)
    LANGUAGE "sql"
    AS $$
    SELECT 
        c.id as candidate_id,
        c.political_name,
        c.campaign_photo_url,
        pp.name as party_name,
        pp.logo_url as party_logo_url,
        count(v.id) as vote_count
    FROM public.candidates c
    LEFT JOIN public.votes v ON c.id = v.candidate_id
    LEFT JOIN public.political_parties pp ON c.party_id = pp.id
    WHERE c.election_id = p_election_id AND c.status = 'Approved'
    GROUP BY c.id, pp.name, pp.logo_url
    ORDER BY vote_count DESC;
$$;


