CREATE OR REPLACE FUNCTION "public"."get_initial_election_status"("p_candidacy_start_date" timestamp with time zone, "p_candidacy_end_date" timestamp with time zone, "p_voting_start_date" timestamp with time zone, "p_voting_end_date" timestamp with time zone) RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    current_time_brt timestamp with time zone := now() AT TIME ZONE 'America/Sao_Paulo';
BEGIN
    IF current_time_brt < p_candidacy_start_date THEN
        RETURN 'Scheduled';
    ELSIF current_time_brt BETWEEN p_candidacy_start_date AND p_candidacy_end_date THEN
        RETURN 'Candidacy';
    ELSIF current_time_brt > p_candidacy_end_date AND current_time_brt < p_voting_start_date THEN
        RETURN 'Scheduled';
    ELSIF current_time_brt BETWEEN p_voting_start_date AND p_voting_end_date THEN
        RETURN 'Voting';
    ELSIF current_time_brt > p_voting_end_date THEN
        RETURN 'Finished';
    ELSE
        -- This case covers gaps between candidacy and voting, or other edge cases.
        RETURN 'Scheduled';
    END IF;
END;
$$;


ALTER FUNCTION "public"."get_initial_election_status"("p_candidacy_start_date" timestamp with time zone, "p_candidacy_end_date" timestamp with time zone, "p_voting_start_date" timestamp with time zone, "p_voting_end_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_inmates"() RETURNS TABLE("id" "uuid", "crime" "text", "sentence_start_date" timestamp with time zone, "sentence_end_date" timestamp with time zone, "is_active" boolean, "profile" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    -- First, update the status of any prisoner whose sentence has ended.
    UPDATE public.profiles p
    SET 
        is_imprisoned = false,
        release_date = NULL,
        criminal_status = 'Cidadão de Bem'
    WHERE 
        p.is_imprisoned = true 
        AND p.release_date IS NOT NULL 
        AND p.release_date <= now();

    UPDATE public.criminal_records cr
    SET is_active = false
    FROM public.profiles p
    WHERE 
        cr.user_id = p.id
        AND cr.is_active = true
        AND p.is_imprisoned = false;

    -- Then, return the current list of inmates.
    RETURN QUERY
    SELECT 
        cr.id,
        cr.crime,
        cr.sentence_start_date,
        cr.sentence_end_date,
        cr.is_active,
        jsonb_build_object(
            'id', p.id,
            'full_name', p.full_name,
            'avatar_url', p.avatar_url
        ) as profile
    FROM public.criminal_records cr
    JOIN public.profiles p ON cr.user_id = p.id
    WHERE cr.is_active = true;
END;
$$;


ALTER FUNCTION "public"."get_inmates"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_invoice_items"("p_invoice_id" "uuid") RETURNS TABLE("id" "uuid", "transaction_id" "uuid", "description" "text", "amount" numeric, "created_at" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
begin
  if v_user_id is null then
    raise exception 'Usuario nao autenticado.';
  end if;

  return query
  select
    cii.id as id,
    cii.transaction_id,
    cii.description,
    cii.amount,
    cii.created_at
  from public.card_invoice_items cii
  inner join public.card_invoices ci
    on ci.id = cii.invoice_id
  where cii.invoice_id = p_invoice_id
    and ci.user_id = v_user_id
  order by cii.created_at desc, cii.id desc;
end;
$$;


