CREATE OR REPLACE FUNCTION "public"."get_oldest_party_member"("p_party_id" "uuid", "p_excluded_user_ids" "uuid"[] DEFAULT '{}'::"uuid"[]) RETURNS "uuid"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
declare
  order_expression text := 'member.id::text';
  selected_user_id uuid;
begin
  if exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'party_members'
      and column_name = 'created_at'
  ) then
    order_expression := 'member.created_at';
  elsif exists (
    select 1
    from information_schema.columns
    where table_schema = 'public'
      and table_name = 'party_members'
      and column_name = 'joined_at'
  ) then
    order_expression := 'member.joined_at';
  end if;

  execute format(
    'select member.user_id
       from public.party_members member
      where member.party_id = $1
        and member.user_id is not null
        and not (member.user_id = any($2))
      order by %s asc nulls last, member.id::text asc
      limit 1',
    order_expression
  )
  into selected_user_id
  using p_party_id, coalesce(p_excluded_user_ids, '{}'::uuid[]);

  return selected_user_id;
end;
$_$;


ALTER FUNCTION "public"."get_oldest_party_member"("p_party_id" "uuid", "p_excluded_user_ids" "uuid"[]) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_parliament_access_data"("p_user_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    user_profile RECORD;
    member_record RECORD;
    house_record RECORD;
    is_admin BOOLEAN;
    default_house_id uuid;
BEGIN
    -- Obter o perfil do usuário para verificar o cargo
    SELECT role, id INTO user_profile FROM public.profiles WHERE id = p_user_id;

    IF user_profile IS NULL THEN
        RETURN jsonb_build_object('has_access', false, 'reason', 'Perfil não encontrado.');
    END IF;

    is_admin := (user_profile.role = 'Admin');

    -- Tentar encontrar uma associação na tabela de membros do parlamento
    SELECT pm.*, ph.id as house_id, ph.name as house_name, ph.description as house_description 
    INTO member_record 
    FROM public.parliament_members pm
    JOIN public.parliament_houses ph ON pm.house_id = ph.id
    WHERE pm.user_id = p_user_id;

    -- Se não for admin E não for membro do parlamento, negar acesso
    IF NOT is_admin AND member_record IS NULL THEN
        RETURN jsonb_build_object('has_access', false, 'reason', 'Não é membro do parlamento.');
    END IF;

    IF member_record IS NOT NULL THEN
        house_record := member_record;
    ELSE
        -- Não é membro; como é admin, atribuir uma house padrão
        -- Escolhe a primeira house disponível como padrão (ajuste conforme necessário)
        SELECT id AS house_id, name AS house_name, description AS house_description
        INTO house_record
        FROM public.parliament_houses
        ORDER BY id
        LIMIT 1;

        -- Se não existir house no sistema, retornar erro controlado
        IF house_record IS NULL THEN
            RETURN jsonb_build_object('has_access', false, 'reason', 'Nenhuma casa configurada para servir como padrão.');
        END IF;
    END IF;

    -- Se chegou até aqui, o acesso é permitido. Retornar os dados consolidados.
    RETURN jsonb_build_object(
        'has_access', true,
        'is_admin', is_admin,
        'member', to_jsonb(member_record),
        'house', jsonb_build_object(
            'id', house_record.house_id,
            'name', house_record.house_name,
            'description', house_record.house_description
        )
    );

EXCEPTION
    WHEN others THEN
        RETURN jsonb_build_object('has_access', false, 'reason', 'Erro inesperado no servidor: ' || SQLERRM);
END;
$$;


ALTER FUNCTION "public"."get_parliament_access_data"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_parliament_base_role_label"("p_house_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_house_name text;
begin
  select name
    into v_house_name
    from public.parliament_houses
   where id = p_house_id;

  if v_house_name ilike '%senado%' then
    return 'Senador';
  end if;

  return 'Deputado';
end;
$$;


ALTER FUNCTION "public"."get_parliament_base_role_label"("p_house_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_parliament_house_member_threshold"("p_house_id" "uuid") RETURNS integer
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  select greatest(
    1,
    ceil(
      greatest(
        count(*) filter (where pm.term_end_date >= current_date),
        1
      )::numeric / 3
    )::integer
  )
    from public.parliament_members pm
   where pm.house_id = p_house_id;
$$;


