CREATE OR REPLACE FUNCTION "public"."get_parliament_leadership_role_label"("p_house_id" "uuid", "p_position" "text") RETURNS "text"
    LANGUAGE "plpgsql" STABLE
    SET "search_path" TO 'public'
    AS $$
declare
  v_house_name text;
begin
  select name
    into v_house_name
    from public.parliament_houses
   where id = p_house_id;

  if p_position not in ('president', 'vice_president') then
    raise exception 'Posição de mesa diretora inválida.';
  end if;

  if v_house_name ilike '%senado%' then
    return case
      when p_position = 'president' then 'Presidente do Senado'
      else 'Vice-Presidente do Senado Federal'
    end;
  end if;

  return case
    when p_position = 'president' then 'Presidente da Câmara dos Deputados'
    else 'Vice-Presidente da Câmara dos Deputados'
  end;
end;
$$;


