CREATE OR REPLACE FUNCTION "public"."get_posts_with_interactions"("p_user_id" "uuid") RETURNS TABLE("id" "uuid", "user_id" "uuid", "content" "text", "created_at" timestamp with time zone, "parent_post_id" "uuid", "likes_count" integer, "comments_count" integer, "views_count" integer, "reposts_count" integer, "image_url" "text", "author" json, "is_liked_by_user" boolean, "is_reposted_by_user" boolean, "original_post" json, "quote_content" "text", "metadata" "jsonb", "updated_at" timestamp with time zone)
    LANGUAGE "sql"
    AS $$
SELECT
    p.id,
    p.user_id,
    p.content,
    p.created_at,
    p.parent_post_id,
    p.likes_count,
    p.comments_count,
    p.views_count,
    p.reposts_count,
    p.image_url,
    json_build_object(
        'id', u.id,
        'username', u.username,
        'full_name', u.full_name,
        'avatar_url', u.avatar_url,
        'x_avatar_url', u.x_avatar_url,
        'x_username', u.x_username,
        'x_handle', u.x_handle,
        'role', u.role,
        'titles', u.titles
    ) as author,
    EXISTS(SELECT 1 FROM public.likes l WHERE l.post_id = p.id AND l.user_id = p_user_id) as is_liked_by_user,
    EXISTS(SELECT 1 FROM public.posts rp WHERE rp.original_post_id = p.id AND rp.user_id = p_user_id) as is_reposted_by_user,
    (
      SELECT json_build_object(
        'id', op.id,
        'content', op.content,
        'created_at', op.created_at,
        'image_url', op.image_url,
        'author', json_build_object(
          'id', op_author.id,
          'x_username', op_author.x_username,
          'x_handle', op_author.x_handle,
          'x_avatar_url', op_author.x_avatar_url
        )
      )
      FROM public.posts op
      JOIN public.profiles op_author ON op.user_id = op_author.id
      WHERE op.id = p.original_post_id
    ) as original_post,
    p.quote_content,
    p.metadata,
    p.updated_at
FROM
    public.posts p
JOIN
    public.profiles u ON p.user_id = u.id
WHERE 
    p.parent_post_id IS NULL -- This fetches both original posts and reposts, but not comments
ORDER BY
    p.created_at DESC;
$$;


ALTER FUNCTION "public"."get_posts_with_interactions"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_presidential_economic_dashboard"() RETURNS "jsonb"
    LANGUAGE "plpgsql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null or not public.economic_has_role(array[
    'Admin','Presidente','Vice-Presidente','Ministro','Ministro da Fazenda','Ministro da Economia'
  ]) then
    raise exception 'Painel restrito ao Governo.' using errcode='42501';
  end if;
  return jsonb_build_object(
    'public',public.get_public_economic_dashboard(),
    'fiscal',to_jsonb((select f from public.fiscal_periods f
      join public.economic_periods p on p.id=f.period_id order by p.ends_at_rp desc limit 1)),
    'treasury',to_jsonb((select g from public.government_finances g where g.id=1)),
    'projects',coalesce((select jsonb_agg(to_jsonb(p) order by p.created_at desc)
      from public.government_projects p),'[]'::jsonb),
    'policies',coalesce((select jsonb_agg(to_jsonb(p) order by p.announced_at_real desc)
      from (select * from public.economic_policy_decisions order by announced_at_real desc limit 20) p),'[]'::jsonb),
    'forecasts',coalesce((select jsonb_agg(to_jsonb(f) order by f.created_at desc)
      from (select * from public.economic_forecasts order by created_at desc limit 12) f),'[]'::jsonb)
  );
end;
$$;


ALTER FUNCTION "public"."get_presidential_economic_dashboard"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_products_with_final_price"() RETURNS TABLE("id" "uuid", "seller_id" "uuid", "name" "text", "description" "text", "price" numeric, "image_url" "text", "created_at" timestamp with time zone, "product_type" "text", "subscription_interval" "text", "subscription_price" numeric, "metadata" "jsonb", "category" "text", "stock" integer, "promotion_price" numeric, "promotion_expires_at" timestamp with time zone, "sales_count" integer, "subscribers_count" integer, "tax_rate" numeric, "final_price" numeric, "seller" json)
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_tax_rates jsonb;
BEGIN
    SELECT value INTO v_tax_rates FROM public.system_settings WHERE key = 'tax_rates';
    IF v_tax_rates IS NULL THEN
        v_tax_rates := '{"product_tax": 0, "service_tax": 0}';
    END IF;

    RETURN QUERY
    SELECT
        p.id,
        p.seller_id,
        p.name,
        p.description,
        p.price,
        p.image_url,
        p.created_at,
        p.product_type,
        p.subscription_interval,
        p.subscription_price,
        p.metadata,
        p.category,
        p.stock,
        p.promotion_price,
        p.promotion_expires_at,
        p.sales_count,
        p.subscribers_count,
        (
            CASE
                WHEN p.product_type = 'subscription' THEN COALESCE((v_tax_rates->>'service_tax')::numeric, 0)
                ELSE COALESCE((v_tax_rates->>'product_tax')::numeric, 0)
            END
        ) AS tax_rate,
        (
            (
                CASE
                    WHEN p.promotion_price IS NOT NULL AND p.promotion_expires_at > now() THEN p.promotion_price
                    ELSE p.price
                END
            ) * (1 + COALESCE(
                CASE
                    WHEN p.product_type = 'subscription' THEN (v_tax_rates->>'service_tax')::numeric
                    ELSE (v_tax_rates->>'product_tax')::numeric
                END, 0)
            )
        ) AS final_price,
        json_build_object(
            'id', s.id,
            'full_name', s.full_name,
            'x_handle', s.x_handle,
            'role', s.role,
            'documents', (SELECT json_agg(d) FROM public.documents d WHERE d.user_id = s.id AND d.type = 'CNPJ')
        ) as seller
    FROM public.products p
    JOIN public.profiles s ON p.seller_id = s.id;
END;
$$;


ALTER FUNCTION "public"."get_products_with_final_price"() OWNER TO "postgres";


