CREATE OR REPLACE FUNCTION "public"."get_user_posts_with_interactions"("p_viewer_id" "uuid", "p_target_user_id" "uuid") RETURNS TABLE("id" "uuid", "user_id" "uuid", "content" "text", "created_at" timestamp with time zone, "parent_post_id" "uuid", "likes_count" integer, "comments_count" integer, "views_count" integer, "reposts_count" integer, "image_url" "text", "author" json, "is_liked_by_user" boolean, "is_reposted_by_user" boolean, "original_post" json, "quote_content" "text", "metadata" "jsonb", "updated_at" timestamp with time zone)
    LANGUAGE "sql"
    AS $$
SELECT
    p.id,
    p.user_id,
    p.content,
    p.created_at,
    p.parent_post_id,
    p.likes_count,
    p.comments_count,
    p.views_count,
    p.reposts_count,
    p.image_url,
    json_build_object(
        'id', u.id,
        'username', u.username,
        'full_name', u.full_name,
        'avatar_url', u.avatar_url,
        'x_avatar_url', u.x_avatar_url,
        'x_username', u.x_username,
        'x_handle', u.x_handle,
        'role', u.role,
        'titles', u.titles
    ) as author,
    EXISTS(SELECT 1 FROM public.likes l WHERE l.post_id = p.id AND l.user_id = p_viewer_id) as is_liked_by_user,
    EXISTS(SELECT 1 FROM public.posts rp WHERE rp.original_post_id = p.id AND rp.user_id = p_viewer_id) as is_reposted_by_user,
    (
      SELECT json_build_object(
        'id', op.id,
        'content', op.content,
        'created_at', op.created_at,
        'image_url', op.image_url,
        'author', json_build_object(
          'id', op_author.id,
          'x_username', op_author.x_username,
          'x_handle', op_author.x_handle,
          'x_avatar_url', op_author.x_avatar_url,
          'role', op_author.role,
          'titles', op_author.titles
        )
      )
      FROM public.posts op
      JOIN public.profiles op_author ON op.user_id = op_author.id
      WHERE op.id = p.original_post_id
    ) as original_post,
    p.quote_content,
    p.metadata,
    p.updated_at
FROM
    public.posts p
JOIN
    public.profiles u ON p.user_id = u.id
WHERE 
    p.parent_post_id IS NULL AND 
    (
        (p.user_id = p_target_user_id AND p.original_post_id IS NULL) OR 
        (p.original_post_id IS NOT NULL AND p.user_id = p_target_user_id)
    )
ORDER BY
    p.created_at DESC;
$$;


ALTER FUNCTION "public"."get_user_posts_with_interactions"("p_viewer_id" "uuid", "p_target_user_id" "uuid") OWNER TO "postgres";


