CREATE OR REPLACE FUNCTION "public"."get_user_transactions"("p_user_id" "uuid") RETURNS TABLE("id" "uuid", "amount" numeric, "description" "text", "created_at" timestamp with time zone, "type" "text", "direction" "text", "other_party_name" "text", "metadata" "jsonb")
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    user_account_id UUID;
BEGIN
    SELECT a.id INTO user_account_id FROM public.accounts a WHERE a.user_id = p_user_id;

    RETURN QUERY
    SELECT
        t.id,
        t.amount,
        t.description,
        t.created_at,
        t.type,
        CASE
            WHEN t.from_account_id = user_account_id THEN 'sent'
            WHEN t.to_account_id = user_account_id THEN 'received'
            WHEN t.metadata->>'card_id' IN (SELECT c.id::text FROM public.cards c WHERE c.user_id = p_user_id) THEN 'sent'
            ELSE 'other'
        END as direction,
        CASE
            WHEN t.type = 'transfer' THEN
              CASE
                WHEN t.from_account_id = user_account_id THEN (SELECT p.full_name FROM public.profiles p JOIN public.accounts a ON p.id = a.user_id WHERE a.id = t.to_account_id)
                ELSE (SELECT p.full_name FROM public.profiles p JOIN public.accounts a ON p.id = a.user_id WHERE a.id = t.from_account_id)
              END
            WHEN t.type LIKE '%purchase%' OR t.type LIKE '%subscription%' THEN
                (SELECT p.full_name FROM public.profiles p JOIN public.accounts a ON p.id = a.user_id WHERE a.id = t.to_account_id)
            WHEN t.type = 'admin_credit' THEN 'Administração'
            WHEN t.type = 'admin_debit' THEN 'Administração'
            ELSE NULL
        END as other_party_name,
        t.metadata
    FROM public.transactions t
    WHERE (user_account_id IS NOT NULL AND (t.from_account_id = user_account_id OR t.to_account_id = user_account_id))
       OR (t.metadata->>'card_id' IN (SELECT c.id::text FROM public.cards c WHERE c.user_id = p_user_id))
    ORDER BY t.created_at DESC
    LIMIT 50;
END;
$$;


ALTER FUNCTION "public"."get_user_transactions"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_user_transactions_for_admin"("p_user_id" "uuid") RETURNS TABLE("id" "uuid", "amount" numeric, "description" "text", "created_at" timestamp with time zone, "type" "text", "direction" "text", "other_party_name" "text", "metadata" "jsonb")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    user_account_id UUID;
    caller_role TEXT;
BEGIN
    SELECT role INTO caller_role FROM public.profiles WHERE public.profiles.id = auth.uid();

    IF caller_role NOT IN ('Admin', 'Agente Secreto') THEN
        RAISE EXCEPTION 'Acesso não autorizado.';
    END IF;

    SELECT a.id INTO user_account_id FROM public.accounts a WHERE a.user_id = p_user_id;

    RETURN QUERY
    SELECT
        t.id,
        t.amount,
        t.description,
        t.created_at,
        t.type,
        CASE
            WHEN t.from_account_id = user_account_id THEN 'sent'
            WHEN t.to_account_id = user_account_id THEN 'received'
            WHEN t.metadata->>'card_id' IN (SELECT c.id::text FROM public.cards c WHERE c.user_id = p_user_id) THEN 'sent'
            ELSE 'other'
        END as direction,
        CASE
            WHEN t.type = 'transfer' THEN
              CASE
                WHEN t.from_account_id = user_account_id THEN (SELECT p.full_name FROM public.profiles p JOIN public.accounts a ON p.id = a.user_id WHERE a.id = t.to_account_id)
                ELSE (SELECT p.full_name FROM public.profiles p JOIN public.accounts a ON p.id = a.user_id WHERE a.id = t.from_account_id)
              END
            WHEN t.type LIKE '%purchase%' OR t.type LIKE '%subscription%' THEN
                (SELECT p.full_name FROM public.profiles p JOIN public.accounts a ON p.id = a.user_id WHERE a.id = t.to_account_id)
            WHEN t.type = 'admin_credit' THEN 'Administração'
            WHEN t.type = 'admin_debit' THEN 'Administração'
            ELSE NULL
        END as other_party_name,
        t.metadata
    FROM public.transactions t
    WHERE (user_account_id IS NOT NULL AND (t.from_account_id = user_account_id OR t.to_account_id = user_account_id))
       OR (t.metadata->>'card_id' IN (SELECT c.id::text FROM public.cards c WHERE c.user_id = p_user_id))
    ORDER BY t.created_at DESC
    LIMIT 100;
END;
$$;


ALTER FUNCTION "public"."get_user_transactions_for_admin"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_users_with_pending_invoices"() RETURNS TABLE("id" "uuid", "full_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF (SELECT role FROM public.profiles WHERE public.profiles.id = auth.uid()) <> 'Admin' THEN
    RAISE EXCEPTION 'Permission denied. Not an admin.';
  END IF;

  RETURN QUERY
  SELECT DISTINCT p.id, p.full_name
  FROM public.profiles p
  JOIN public.card_invoices ci ON p.id = ci.user_id
  WHERE ci.status = 'pending' AND ci.amount > 0;
END;
$$;


ALTER FUNCTION "public"."get_users_with_pending_invoices"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."gift_inventory_item"("p_inventory_id" "uuid", "p_recipient_cpf" "text", "p_quantity" integer) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    sender_id UUID := auth.uid();
    recipient_id UUID;
    sender_item RECORD;
    recipient_inventory_item RECORD;
BEGIN
    -- Validate inputs
    IF p_quantity <= 0 THEN
        RETURN json_build_object('success', false, 'message', 'A quantidade deve ser maior que zero.');
    END IF;

    -- Find recipient
    SELECT id INTO recipient_id FROM public.profiles WHERE cpf = p_recipient_cpf;
    IF recipient_id IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Destinatário não encontrado com o CPF informado.');
    END IF;

    IF sender_id = recipient_id THEN
        RETURN json_build_object('success', false, 'message', 'Você não pode presentear a si mesmo.');
    END IF;

    -- Find sender's item
    SELECT * INTO sender_item FROM public.user_inventory WHERE id = p_inventory_id AND user_id = sender_id;
    IF sender_item IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Item não encontrado no seu inventário.');
    END IF;

    IF sender_item.quantity < p_quantity THEN
        RETURN json_build_object('success', false, 'message', 'Quantidade insuficiente para presentear.');
    END IF;

    -- Decrement or delete sender's item
    IF sender_item.quantity > p_quantity THEN
        UPDATE public.user_inventory SET quantity = quantity - p_quantity WHERE id = p_inventory_id;
    ELSE
        DELETE FROM public.user_inventory WHERE id = p_inventory_id;
    END IF;

    -- Find if recipient already has this product
    SELECT * INTO recipient_inventory_item FROM public.user_inventory WHERE user_id = recipient_id AND product_id = sender_item.product_id;

    -- Increment or insert for recipient
    IF recipient_inventory_item IS NOT NULL THEN
        UPDATE public.user_inventory SET quantity = quantity + p_quantity WHERE id = recipient_inventory_item.id;
    ELSE
        INSERT INTO public.user_inventory (user_id, product_id, quantity, acquired_at)
        VALUES (recipient_id, sender_item.product_id, p_quantity, now());
    END IF;

    -- Create notification for recipient
    INSERT INTO public.notifications (user_id, sender_id, type, content, link)
    VALUES (recipient_id, sender_id, 'item_gifted', 'Você recebeu ' || p_quantity || 'x ' || (SELECT name FROM products WHERE id = sender_item.product_id) || ' de presente!', '/services/inventory');

    RETURN json_build_object('success', true, 'message', 'Item presenteado com sucesso!');
END;
$$;


ALTER FUNCTION "public"."gift_inventory_item"("p_inventory_id" "uuid", "p_recipient_cpf" "text", "p_quantity" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."government_take_loan"("p_amount" numeric, "p_installments" integer DEFAULT 12) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  finance record;
  policy jsonb;
  rate numeric(8, 4);
  final_total numeric(14, 2);
  available_amount numeric(14, 2);
begin
  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'message', 'Valor de emprestimo invalido.');
  end if;

  select * into finance
  from public.government_finances
  order by updated_at asc
  limit 1
  for update;

  if not found then
    return jsonb_build_object('success', false, 'message', 'Financas do governo nao encontradas.');
  end if;

  available_amount := coalesce(finance.loan_limit, 0) - coalesce(finance.loans_balance, 0);

  if p_amount > available_amount then
    return jsonb_build_object('success', false, 'message', 'Valor excede a margem disponivel para emprestimos.');
  end if;

  policy := public.get_bank_policy();
  rate := coalesce((policy->>'government_debt_interest_rate')::numeric, 1.75);
  final_total := round((p_amount * (1 + rate / 100))::numeric, 2);

  update public.government_finances
  set treasury_balance = coalesce(treasury_balance, 0) + p_amount,
      loans_balance = coalesce(loans_balance, 0) + final_total,
      updated_at = now()
  where id = finance.id;

  return jsonb_build_object(
    'success', true,
    'message', 'Emprestimo governamental contratado com juros do Banco Nacional.',
    'amount', p_amount,
    'interest_rate', rate,
    'installments', greatest(1, coalesce(p_installments, 12)),
    'total_due', final_total
  );
end;
$$;


ALTER FUNCTION "public"."government_take_loan"("p_amount" numeric, "p_installments" integer) OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."prison_terms" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "sentence_id" "uuid",
    "arrest_id" "uuid",
    "inmate_id" "uuid" NOT NULL,
    "facility_id" "uuid" NOT NULL,
    "cell_id" "uuid",
    "admitted_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expected_release_at" timestamp with time zone NOT NULL,
    "actual_release_at" timestamp with time zone,
    "custody_status" "public"."justice_custody_status" NOT NULL,
    "security_level" "text" NOT NULL,
    "original_duration_seconds" integer NOT NULL,
    "sentence_credit_seconds" integer DEFAULT 0 NOT NULL,
    "remaining_units" numeric(8,2),
    "behavior_points" integer DEFAULT 0 NOT NULL,
    "release_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "prison_terms_check" CHECK (("num_nonnulls"("sentence_id", "arrest_id") = 1)),
    CONSTRAINT "prison_terms_original_duration_seconds_check" CHECK (("original_duration_seconds" > 0)),
    CONSTRAINT "prison_terms_security_level_check" CHECK (("security_level" = ANY (ARRAY['low'::"text", 'medium'::"text", 'high'::"text", 'maximum'::"text"]))),
    CONSTRAINT "prison_terms_sentence_credit_seconds_check" CHECK (("sentence_credit_seconds" >= 0))
);


ALTER TABLE "public"."prison_terms" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."grant_sentence_credit"("p_prison_term_id" "uuid", "p_credit_seconds" integer, "p_justification" "text") RETURNS "public"."prison_terms"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_old public.prison_terms%rowtype;
  v_new public.prison_terms%rowtype;
  v_max_credit integer;
begin
  if not public.justice_has_role(array['Admin', 'Juiz']) then raise exception 'ROLE_NOT_AUTHORIZED'; end if;
  if p_credit_seconds <= 0 then raise exception 'INVALID_SENTENCE_CREDIT'; end if;
  if length(trim(coalesce(p_justification, ''))) < 30 then raise exception 'JUSTIFICATION_TOO_SHORT'; end if;

  select * into v_old from public.prison_terms where id = p_prison_term_id for update;
  if not found then raise exception 'PRISON_TERM_NOT_FOUND'; end if;
  if v_old.custody_status <> 'serving' then raise exception 'SENTENCE_NOT_SERVING'; end if;
  v_max_credit := floor(v_old.original_duration_seconds * 0.25)::integer;
  if v_old.sentence_credit_seconds + p_credit_seconds > v_max_credit then
    raise exception 'SENTENCE_CREDIT_LIMIT_EXCEEDED';
  end if;

  update public.prison_terms
  set sentence_credit_seconds = sentence_credit_seconds + p_credit_seconds,
      expected_release_at = greatest(now(), expected_release_at - make_interval(secs => p_credit_seconds))
  where id = p_prison_term_id
  returning * into v_new;

  insert into public.prison_events(
    prison_term_id, event_type, title, description, sentence_credit_seconds,
    registered_by, approved_by
  )
  values (
    p_prison_term_id, 'sentence_credit', 'Redução judicial de pena',
    trim(p_justification), p_credit_seconds, (select auth.uid()), (select auth.uid())
  );
  perform public.justice_write_audit(
    'sentence.credit_granted', 'prison_term', p_prison_term_id,
    to_jsonb(v_old), to_jsonb(v_new), p_justification
  );
  return v_new;
end;
$$;


ALTER FUNCTION "public"."grant_sentence_credit"("p_prison_term_id" "uuid", "p_credit_seconds" integer, "p_justification" "text") OWNER TO "postgres";


