CREATE OR REPLACE FUNCTION "public"."handle_election_political_points_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_winner record;
begin
  if new.status = 'Finished'
     and old.status is distinct from new.status then
    for v_winner in
      with ranked_results as (
        select
          c.user_id,
          c.id as candidate_id,
          count(v.id) as vote_count,
          dense_rank() over (order by count(v.id) desc) as result_rank
        from public.candidates c
        left join public.votes v
          on v.candidate_id = c.id
        where c.election_id = new.id
          and c.user_id is not null
        group by c.user_id, c.id
      )
      select user_id, candidate_id, vote_count
      from ranked_results
      where result_rank = 1
        and vote_count > 0
    loop
      perform public.award_political_points(
        v_winner.user_id,
        'election_win',
        new.id,
        new.name,
        jsonb_build_object(
          'source_table', 'elections',
          'election_id', new.id,
          'candidate_id', v_winner.candidate_id,
          'vote_count', v_winner.vote_count,
          'name', new.name
        )
      );
    end loop;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."handle_election_political_points_trigger"() OWNER TO "postgres";


