CREATE OR REPLACE FUNCTION "public"."handle_new_user"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_username text;
  v_full_name text;
  v_phone text;
  v_country_code text;
  v_date_of_birth text;
  v_rg text;
  v_cpf text;
BEGIN
  -- Extrai metadados do usuário recém-criado
  v_username := NEW.raw_user_meta_data->>'username';
  v_full_name := NEW.raw_user_meta_data->>'full_name';
  v_phone := NEW.raw_user_meta_data->>'phone';
  v_country_code := NEW.raw_user_meta_data->>'country_code';
  v_date_of_birth := NEW.raw_user_meta_data->>'date_of_birth';
  v_rg := NEW.raw_user_meta_data->>'rg';
  v_cpf := NEW.raw_user_meta_data->>'cpf';

  -- Validação mínima para evitar constraint violation
  IF v_username IS NULL OR char_length(v_username) < 3 OR char_length(v_username) > 20 THEN
    v_username := 'u_' || substring(NEW.id::text from 1 for 8);
  END IF;

  -- Insere ou atualiza o perfil com os dados do cadastro
  INSERT INTO public.profiles (
    id,
    username,
    full_name,
    email,
    phone,
    country_code,
    date_of_birth,
    rg,
    cpf,
    role,
    onboarding_completed,
    created_at,
    updated_at
  )
  VALUES (
    NEW.id,
    v_username,
    v_full_name,
    NEW.email,
    v_phone,
    v_country_code,
    CASE WHEN v_date_of_birth IS NOT NULL THEN v_date_of_birth::date ELSE NULL END,
    v_rg,
    v_cpf,
    'Cidadão',
    false,
    NOW(),
    NOW()
  )
  ON CONFLICT (id) DO UPDATE
  SET
    username = EXCLUDED.username,
    full_name = COALESCE(EXCLUDED.full_name, profiles.full_name),
    email = EXCLUDED.email,
    phone = COALESCE(EXCLUDED.phone, profiles.phone),
    country_code = COALESCE(EXCLUDED.country_code, profiles.country_code),
    date_of_birth = COALESCE(EXCLUDED.date_of_birth, profiles.date_of_birth),
    rg = COALESCE(EXCLUDED.rg, profiles.rg),
    cpf = COALESCE(EXCLUDED.cpf, profiles.cpf),
    updated_at = NOW();

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."handle_new_user"() OWNER TO "postgres";


