CREATE OR REPLACE FUNCTION "public"."handle_suggestion_acceptance"("p_suggestion_id" "uuid", "p_house_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    suggestion_rec RECORD;
    new_voting_id UUID;
    caller_role TEXT;
BEGIN
    -- Security check: ensure the caller has the authority.
    SELECT role INTO caller_role FROM public.profiles WHERE id = auth.uid();
    IF caller_role NOT IN ('Admin', 'Presidente da Câmara', 'Presidente do Senado') THEN
        RETURN json_build_object('success', false, 'message', 'Acesso negado.');
    END IF;

    -- Get suggestion details
    SELECT * INTO suggestion_rec FROM public.bill_suggestions WHERE id = p_suggestion_id;

    IF suggestion_rec IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Sugestão não encontrada.');
    END IF;

    IF suggestion_rec.status <> 'Pendente' THEN
        RETURN json_build_object('success', false, 'message', 'Esta sugestão não está mais pendente.');
    END IF;

    -- Create a new entry in parliament_votings
    INSERT INTO public.parliament_votings (house_id, title, description, type, related_id, status, end_date)
    VALUES (
        p_house_id,
        suggestion_rec.title,
        suggestion_rec.suggestion,
        'suggestion',
        p_suggestion_id,
        'active',
        now() + interval '7 days'
    ) RETURNING id INTO new_voting_id;

    -- Update suggestion status to indicate it has moved to voting
    UPDATE public.bill_suggestions SET status = 'em_votacao' WHERE id = p_suggestion_id;

    RETURN json_build_object('success', true, 'message', 'Votação para a sugestão iniciada com sucesso.', 'voting_id', new_voting_id);
END;
$$;


ALTER FUNCTION "public"."handle_suggestion_acceptance"("p_suggestion_id" "uuid", "p_house_id" "uuid") OWNER TO "postgres";


