CREATE OR REPLACE FUNCTION "public"."invest"("p_investment_id" "uuid", "p_amount" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_account record;
  v_option record;
  v_existing record;
  v_accrued numeric := 0;
  v_days numeric := 0;
begin
  if v_user_id is null then
    return jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  end if;

  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'message', 'Informe um valor positivo para investir.');
  end if;

  select *
  into v_option
  from public.investment_options
  where id = p_investment_id and coalesce(is_active, true) = true;

  if not found then
    return jsonb_build_object('success', false, 'message', 'Opção de investimento não encontrada.');
  end if;

  if p_amount < coalesce(v_option.minimum_amount, 0) then
    return jsonb_build_object('success', false, 'message', 'Valor abaixo da aplicação mínima.');
  end if;

  select *
  into v_account
  from public.accounts
  where user_id = v_user_id
  for update;

  if not found or coalesce(v_account.balance, 0) < p_amount then
    return jsonb_build_object('success', false, 'message', 'Saldo insuficiente para investir.');
  end if;

  update public.accounts
  set balance = round(coalesce(balance, 0) - p_amount, 2), updated_at = now()
  where id = v_account.id;

  select *
  into v_existing
  from public.user_investments
  where user_id = v_user_id and investment_option_id = p_investment_id
  for update;

  if found then
    v_days := greatest(0, extract(epoch from (now() - coalesce(v_existing.updated_at, v_existing.created_at, now()))) / 86400);
    v_accrued := round(coalesce(v_existing.amount_invested, 0) * coalesce(v_option.annual_return_rate, 0) * (v_days / 365), 2);

    update public.user_investments
    set
      amount_invested = round(coalesce(amount_invested, 0) + v_accrued + p_amount, 2),
      updated_at = now()
    where id = v_existing.id;
  else
    insert into public.user_investments (
      user_id,
      investment_option_id,
      amount_invested,
      created_at,
      updated_at
    )
    values (
      v_user_id,
      p_investment_id,
      round(p_amount, 2),
      now(),
      now()
    );
  end if;

  insert into public.transactions (from_account_id, to_account_id, amount, type, description, created_at, metadata)
  values (
    v_account.id,
    null,
    round(p_amount, 2),
    'investment_application',
    'Aplicação em investimento: ' || v_option.name,
    now(),
    jsonb_build_object('investment_option_id', p_investment_id, 'accrued_before_application', v_accrued)
  );

  return jsonb_build_object('success', true, 'message', 'Investimento aplicado com sucesso.');
end;
$$;


