CREATE OR REPLACE FUNCTION "public"."is_national_bank_manager"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select public.is_national_bank_manager((select auth.uid()));
$$;


ALTER FUNCTION "public"."is_national_bank_manager"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_national_bank_manager"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
  select p_user_id is not null
    and (
      exists (
        select 1
        from public.profiles as profile
        where profile.id = p_user_id
          and profile.role in (
            'Admin',
            'Presidente',
            'Presidente do Banco Nacional'
          )
      )
      or exists (
        select 1
        from public.system_settings as setting
        where setting.key = 'executive_governance'
          and setting.value
            -> 'specialAppointments'
            -> 'national_bank_president'
            ->> 'user_id' = p_user_id::text
      )
    );
$$;


ALTER FUNCTION "public"."is_national_bank_manager"("p_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."is_parliament_governance_manager"("p_user_id" "uuid", "p_house_id" "uuid") RETURNS boolean
    LANGUAGE "sql" STABLE
    SET "search_path" TO 'public'
    AS $$
  with profile_role as (
    select role
      from public.profiles
     where id = p_user_id
  )
  select exists (
    select 1
      from profile_role
     where role in ('Admin', 'Presidente')
  )
  or exists (
    select 1
      from public.parliament_leadership_terms plt
      join public.parliament_members pm
        on pm.id = plt.member_id
     where pm.user_id = p_user_id
       and pm.house_id = p_house_id
       and pm.term_end_date >= current_date
       and plt.house_id = p_house_id
       and plt.status = 'active'
  );
$$;


