    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "case_id" "uuid" NOT NULL,
    "request_id" "uuid",
    "decision_type" "text" NOT NULL,
    "judge_id" "uuid" NOT NULL,
    "summary" "text" NOT NULL,
    "legal_reasoning" "text" NOT NULL,
    "result" "text" NOT NULL,
    "issued_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "is_final" boolean DEFAULT false NOT NULL
);


ALTER TABLE "public"."judicial_decisions" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."issue_acquittal"("p_case_id" "uuid", "p_defendant_id" "uuid", "p_legal_reasoning" "text") RETURNS "public"."judicial_decisions"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_case public.criminal_cases%rowtype;
  v_decision public.judicial_decisions%rowtype;
begin
  if not public.justice_has_role(array['Admin', 'Juiz']) then raise exception 'ROLE_NOT_AUTHORIZED'; end if;
  if length(trim(coalesce(p_legal_reasoning, ''))) < 80 then raise exception 'LEGAL_REASONING_TOO_SHORT'; end if;
  select * into v_case from public.criminal_cases where id = p_case_id for update;
  if not found then raise exception 'CASE_NOT_FOUND'; end if;
  if v_case.judge_id is distinct from (select auth.uid())
     and not public.justice_has_role(array['Admin']) then
    raise exception 'ONLY_ASSIGNED_JUDGE_CAN_DECIDE';
  end if;

  insert into public.judicial_decisions(
    case_id, decision_type, judge_id, summary, legal_reasoning, result, is_final
  )
  values (
    p_case_id, 'sentence', (select auth.uid()), 'Sentença absolutória',
    trim(p_legal_reasoning), 'acquittal', false
  )
  returning * into v_decision;

  update public.case_charges set status = 'acquitted'
  where case_id = p_case_id and defendant_id = p_defendant_id;
  update public.criminal_cases
  set status = 'acquitted', final_decision = 'Absolvição ainda sujeita a recurso'
  where id = p_case_id;

  perform public.justice_notify(
    p_defendant_id, 'justice_acquittal',
    'Você foi absolvido no processo ' || v_case.case_number || '.',
    '/services/justice?view=citizen',
    jsonb_build_object('case_id', p_case_id)
  );
  perform public.justice_write_audit(
    'case.acquitted', 'criminal_case', p_case_id,
    to_jsonb(v_case), jsonb_build_object('status', 'acquitted'), p_legal_reasoning
  );
  return v_decision;
end;
$$;


ALTER FUNCTION "public"."issue_acquittal"("p_case_id" "uuid", "p_defendant_id" "uuid", "p_legal_reasoning" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."sentences" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "case_id" "uuid" NOT NULL,
    "decision_id" "uuid" NOT NULL,
    "defendant_id" "uuid" NOT NULL,
    "judge_id" "uuid" NOT NULL,
    "sentence_type" "text" NOT NULL,
    "base_sentence_units" numeric(8,2) NOT NULL,
    "final_sentence_units" numeric(8,2) NOT NULL,
    "real_duration_seconds" integer NOT NULL,
    "fine_amount" numeric(14,2) DEFAULT 0 NOT NULL,
    "prison_regime" "text" NOT NULL,
    "starts_at" timestamp with time zone,
    "ends_at" timestamp with time zone,
    "status" "text" DEFAULT 'appealable'::"text" NOT NULL,
    "provisional_time_credit_seconds" integer DEFAULT 0 NOT NULL,
    "issued_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "sentences_base_sentence_units_check" CHECK (("base_sentence_units" >= (0)::numeric)),
    CONSTRAINT "sentences_final_sentence_units_check" CHECK (("final_sentence_units" >= (0)::numeric)),
    CONSTRAINT "sentences_fine_amount_check" CHECK (("fine_amount" >= (0)::numeric)),
    CONSTRAINT "sentences_prison_regime_check" CHECK (("prison_regime" = ANY (ARRAY['open'::"text", 'semi_open'::"text", 'closed'::"text", 'maximum_security'::"text"]))),
    CONSTRAINT "sentences_provisional_time_credit_seconds_check" CHECK (("provisional_time_credit_seconds" >= 0)),
    CONSTRAINT "sentences_real_duration_seconds_check" CHECK (("real_duration_seconds" > 0)),
    CONSTRAINT "sentences_sentence_type_check" CHECK (("sentence_type" = ANY (ARRAY['custodial'::"text", 'fine'::"text", 'community_service'::"text", 'mixed'::"text"]))),
    CONSTRAINT "sentences_status_check" CHECK (("status" = ANY (ARRAY['appealable'::"text", 'appealed'::"text", 'final'::"text", 'serving'::"text", 'served'::"text", 'cancelled'::"text"])))
);


ALTER TABLE "public"."sentences" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."issue_criminal_sentence"("p_case_id" "uuid", "p_defendant_id" "uuid", "p_result" "text", "p_legal_reasoning" "text", "p_final_sentence_units" numeric, "p_fine_amount" numeric DEFAULT 0, "p_prison_regime" "text" DEFAULT 'closed'::"text", "p_special_justification" "text" DEFAULT NULL::"text") RETURNS "public"."sentences"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_case public.criminal_cases%rowtype;
  v_decision public.judicial_decisions%rowtype;
  v_sentence public.sentences%rowtype;
  v_min numeric;
  v_max numeric;
  v_base numeric;
  v_seconds integer;
  v_outside_limits boolean;
begin
  if not public.justice_has_role(array['Admin', 'Juiz']) then raise exception 'ROLE_NOT_AUTHORIZED'; end if;
  if p_result not in ('conviction', 'partial_conviction') then raise exception 'INVALID_SENTENCE_RESULT'; end if;
  if length(trim(coalesce(p_legal_reasoning, ''))) < 80 then raise exception 'LEGAL_REASONING_TOO_SHORT'; end if;

  select * into v_case from public.criminal_cases where id = p_case_id for update;
  if not found then raise exception 'CASE_NOT_FOUND'; end if;
  if v_case.judge_id is distinct from (select auth.uid())
     and not public.justice_has_role(array['Admin']) then
    raise exception 'ONLY_ASSIGNED_JUDGE_CAN_SENTENCE';
  end if;
  if exists (
    select 1 from public.case_parties cp
    where cp.case_id = p_case_id and cp.profile_id = (select auth.uid())
      and cp.party_type <> 'judge'
  ) then raise exception 'JUDGE_CONFLICT_OF_INTEREST'; end if;

  select
    sum(pc.minimum_sentence_units),
    sum(pc.maximum_sentence_units),
    sum((pc.minimum_sentence_units + pc.maximum_sentence_units) / 2)
  into v_min, v_max, v_base
  from public.case_charges cc
  join public.penal_code pc on pc.id = cc.penal_code_id
  where cc.case_id = p_case_id and cc.defendant_id = p_defendant_id
    and cc.status in ('filed', 'admitted');

  if v_min is null then raise exception 'NO_ADMITTED_CHARGES'; end if;
  v_outside_limits := p_final_sentence_units < v_min or p_final_sentence_units > v_max;
  if v_outside_limits and length(trim(coalesce(p_special_justification, ''))) < 40 then
    raise exception 'OUTSIDE_LIMITS_REQUIRES_SPECIAL_JUSTIFICATION';
  end if;

  v_seconds := public.calculate_sentence_duration(p_final_sentence_units, 1);

  insert into public.judicial_decisions(
    case_id, decision_type, judge_id, summary, legal_reasoning, result, is_final
  )
  values (
    p_case_id, 'sentence', (select auth.uid()),
    'Sentença condenatória', trim(p_legal_reasoning), p_result, false
  )
  returning * into v_decision;

  insert into public.sentences(
    case_id, decision_id, defendant_id, judge_id, sentence_type,
    base_sentence_units, final_sentence_units, real_duration_seconds,
    fine_amount, prison_regime
  )
  values (
    p_case_id, v_decision.id, p_defendant_id, (select auth.uid()),
    case when p_fine_amount > 0 then 'mixed' else 'custodial' end,
    v_base, p_final_sentence_units, v_seconds,
    greatest(0, p_fine_amount), p_prison_regime
  )
  returning * into v_sentence;

  update public.case_charges
  set status = 'convicted'
  where case_id = p_case_id and defendant_id = p_defendant_id
    and status in ('filed', 'admitted');

  update public.criminal_cases
  set status = 'convicted', final_decision = 'Condenação ainda sujeita a recurso'
  where id = p_case_id;

  insert into public.justice_deadlines(
    case_id, deadline_type, responsible_profile_id, rp_due_at, real_due_at
  )
  values (
    p_case_id, 'appeal',
    p_defendant_id,
    public.rp_now() + interval '5 days',
    now() + make_interval(secs => public.rp_duration_to_real_seconds(5, 'day'))
  );

  perform public.justice_notify(
    p_defendant_id, 'justice_sentence_issued',
    'Sentença emitida no processo ' || v_case.case_number || '. O prazo de recurso está aberto.',
    '/services/justice?view=citizen',
    jsonb_build_object('case_id', p_case_id, 'sentence_id', v_sentence.id)
  );

  perform public.justice_write_audit(
    'sentence.issued', 'sentence', v_sentence.id,
    null, to_jsonb(v_sentence),
    coalesce(p_special_justification, p_legal_reasoning)
  );

  return v_sentence;
end;
$$;


ALTER FUNCTION "public"."issue_criminal_sentence"("p_case_id" "uuid", "p_defendant_id" "uuid", "p_result" "text", "p_legal_reasoning" "text", "p_final_sentence_units" numeric, "p_fine_amount" numeric, "p_prison_regime" "text", "p_special_justification" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."issue_document"("p_request_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    request record;
    new_doc_number text;
    doc_fee numeric := 0.00; -- Taxa pode ser ajustada aqui ou em uma tabela de configurações
    user_account record;
BEGIN
    -- Apenas admins podem executar
    IF NOT is_admin() THEN
        RETURN json_build_object('success', false, 'message', 'Acesso não autorizado.');
    END IF;

    SELECT * INTO request FROM public.document_requests WHERE id = p_request_id;

    IF request IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Solicitação não encontrada.');
    END IF;

    IF request.status <> 'Pendente' THEN
        RETURN json_build_object('success', false, 'message', 'Esta solicitação já foi processada.');
    END IF;

    -- Verificar se o usuário tem saldo para a taxa
    SELECT * INTO user_account FROM public.accounts WHERE user_id = request.user_id;
    IF user_account IS NULL THEN
        UPDATE public.document_requests SET status = 'Recusado' WHERE id = p_request_id;
        RETURN json_build_object('success', false, 'message', 'Usuário não possui conta bancária para pagar a taxa.');
    END IF;

    IF user_account.balance < doc_fee THEN
        UPDATE public.document_requests SET status = 'Recusado' WHERE id = p_request_id;
        RETURN json_build_object('success', false, 'message', 'Saldo insuficiente para pagar a taxa de emissão.');
    END IF;

    -- Gerar número único
    new_doc_number := public.generate_unique_document_number(request.document_type);

    -- Inserir novo documento
    INSERT INTO public.documents (user_id, type, document_number, issued_at, expires_at, is_valid)
    VALUES (
        request.user_id,
        request.document_type,
        new_doc_number,
        now(),
        CASE
            WHEN request.document_type = 'CNH' THEN now() + interval '5 years'
            WHEN request.document_type = 'Passport' THEN now() + interval '10 years'
            ELSE NULL
        END,
        true
    );

    -- Debitar taxa
    IF doc_fee > 0 THEN
        UPDATE public.accounts SET balance = balance - doc_fee WHERE id = user_account.id;
        INSERT INTO public.transactions (from_account_id, amount, description, type)
        VALUES (user_account.id, doc_fee, 'Taxa de emissão de ' || request.document_type, 'service_fee');
    END IF;

    -- Atualizar status da solicitação
    UPDATE public.document_requests SET status = 'Aprovado' WHERE id = p_request_id;

    -- Notificar usuário
    INSERT INTO public.notifications (user_id, type, content, link)
    VALUES (request.user_id, 'document_issued', 'Seu documento ' || request.document_type || ' foi emitido com sucesso!', '/services/dic');

    RETURN json_build_object('success', true, 'message', 'Documento emitido com sucesso.');
END;
$$;


ALTER FUNCTION "public"."issue_document"("p_request_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."issue_document_request"("p_document_type" "text", "p_metadata" "jsonb" DEFAULT NULL::"jsonb") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    doc_fee numeric;
    user_account record;
    new_doc_number text;
BEGIN
    -- Check for document-specific fees, default to 0.
    SELECT COALESCE((SELECT value::numeric FROM public.app_config WHERE key = 'doc_fee_' || lower(p_document_type)), 0.00) INTO doc_fee;

    -- Prevent issuing duplicate documents, except for CNPJ which can have multiple.
    IF EXISTS (SELECT 1 FROM public.documents WHERE user_id = current_user_id AND type = p_document_type AND p_document_type <> 'CNPJ') THEN
      RETURN json_build_object('success', false, 'message', 'Você já possui este documento.');
    END IF;
    
    -- Check if user has a bank account to pay fees.
    SELECT * INTO user_account FROM public.accounts WHERE user_id = current_user_id;
    IF user_account IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Você precisa de uma conta bancária para solicitar documentos.');
    END IF;

    -- Check for sufficient balance.
    IF user_account.balance < doc_fee THEN
        RETURN json_build_object('success', false, 'message', 'Saldo insuficiente para pagar a taxa de emissão.');
    END IF;

    -- Generate a unique number for the new document.
    new_doc_number := public.generate_unique_document_number(p_document_type);

    -- Insert the new document record.
    INSERT INTO public.documents (user_id, type, document_number, issued_at, expires_at, is_valid, metadata)
    VALUES (
        current_user_id,
        p_document_type,
        new_doc_number,
        now(),
        CASE
            WHEN p_document_type = 'CNH' THEN now() + interval '5 years'
            WHEN p_document_type = 'Passport' THEN now() + interval '10 years'
            ELSE NULL
        END,
        true,
        p_metadata -- Store additional data like business names for CNPJ
    );

    -- Deduct fee if applicable and record the transaction.
    IF doc_fee > 0 THEN
        UPDATE public.accounts SET balance = balance - doc_fee WHERE id = user_account.id;
        INSERT INTO public.transactions (from_account_id, amount, description, type)
        VALUES (user_account.id, doc_fee, 'Taxa de emissão de ' || p_document_type, 'service_fee');
    END IF;

    -- Notify the user.
    INSERT INTO public.notifications (user_id, type, content, link)
    VALUES (current_user_id, 'document_issued', 'Seu documento ' || p_document_type || ' foi emitido com sucesso!', '/dashboard');

    RETURN json_build_object('success', true, 'message', 'Documento emitido com sucesso!');
END;
$$;


ALTER FUNCTION "public"."issue_document_request"("p_document_type" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."issue_fine"("p_user_id" "uuid", "p_reason" "text", "p_amount" numeric, "p_due_date" timestamp with time zone) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    issuer_role TEXT;
    officer_or_judge_id UUID;
    v_fine_code TEXT;
BEGIN
    SELECT role INTO issuer_role FROM public.profiles WHERE id = current_user_id;

    IF (issuer_role = 'Policial' OR issuer_role = 'Admin' OR issuer_role = 'Juiz') THEN
        officer_or_judge_id := current_user_id;
    ELSE
        RETURN json_build_object('success', false, 'message', 'Acesso não autorizado para emitir multas.');
    END IF;

    IF p_amount <= 0 THEN
        RETURN json_build_object('success', false, 'message', 'O valor da multa deve ser positivo.');
    END IF;

    v_fine_code := 'FINE-' || upper(substr(md5(random()::text || clock_timestamp()::text), 1, 8));

    INSERT INTO public.police_fines(user_id, officer_id, reason, amount, status, due_date, fine_code)
    VALUES (p_user_id, officer_or_judge_id, p_reason, p_amount, 'Pendente', p_due_date, v_fine_code);

    RETURN json_build_object('success', true, 'message', 'Multa emitida com sucesso!', 'fine_code', v_fine_code);
EXCEPTION
    WHEN others THEN
        RETURN json_build_object('success', false, 'message', 'Ocorreu um erro inesperado ao emitir a multa: ' || SQLERRM);
END;
$$;


ALTER FUNCTION "public"."issue_fine"("p_user_id" "uuid", "p_reason" "text", "p_amount" numeric, "p_due_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."issue_onboarding_document"("p_document_type" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
	v_user_id uuid := auth.uid();
	v_document_number text;
	v_document public.documents%ROWTYPE;
	v_is_complete boolean;
BEGIN
	IF v_user_id IS NULL THEN
		RAISE EXCEPTION 'Usuário não autenticado';
	END IF;

	IF p_document_type NOT IN ('CTD', 'Título de Eleitor') THEN
		RAISE EXCEPTION 'Tipo de documento inválido';
	END IF;

	IF NOT EXISTS (
		SELECT 1
		FROM public.profiles
		WHERE id = v_user_id
			AND state_code IS NOT NULL
	) THEN
		RAISE EXCEPTION 'Confirme sua residência antes de emitir os documentos';
	END IF;

	SELECT *
	INTO v_document
	FROM public.documents
	WHERE user_id = v_user_id
		AND type = p_document_type
		AND is_valid = true
	ORDER BY issued_at DESC
	LIMIT 1;

	IF NOT FOUND THEN
		LOOP
			IF p_document_type = 'Título de Eleitor' THEN
				v_document_number := LPAD(floor(random() * 1000000000000)::text, 12, '0');
			ELSE
				v_document_number := LPAD(floor(random() * 10000000)::text, 7, '0')
					|| ' ' || LPAD(floor(random() * 1000)::text, 3, '0');
			END IF;

			EXIT WHEN NOT EXISTS (
				SELECT 1
				FROM public.documents
				WHERE document_number = v_document_number
			);
		END LOOP;

		INSERT INTO public.documents (
			user_id,
			type,
			document_number,
			issued_at,
			is_valid,
			qr_code_data,
			full_name
		)
		SELECT
			p.id,
			p_document_type,
			v_document_number,
			NOW(),
			true,
			'GOVRP:' || p_document_type || ':' || p.id || ':' || v_document_number,
			p.full_name
		FROM public.profiles p
		WHERE p.id = v_user_id
		RETURNING * INTO v_document;
	END IF;

	UPDATE public.profiles
	SET
		titulo_eleitor = CASE
			WHEN p_document_type = 'Título de Eleitor' THEN v_document.document_number
			ELSE titulo_eleitor
		END,
		carteira_trabalho = CASE
			WHEN p_document_type = 'CTD' THEN v_document.document_number
			ELSE carteira_trabalho
		END,
		updated_at = NOW()
	WHERE id = v_user_id;

	SELECT COUNT(*) = 2
	INTO v_is_complete
	FROM public.documents
	WHERE user_id = v_user_id
		AND is_valid = true
		AND type IN ('CTD', 'Título de Eleitor');

	UPDATE public.profiles
	SET onboarding_completed = v_is_complete, updated_at = NOW()
	WHERE id = v_user_id;

	RETURN jsonb_build_object(
		'document', to_jsonb(v_document),
		'onboarding_completed', v_is_complete
	);
END;
$$;


ALTER FUNCTION "public"."issue_onboarding_document"("p_document_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."join_party"("p_party_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
BEGIN
    IF EXISTS (SELECT 1 FROM party_members WHERE user_id = current_user_id) THEN
        RETURN json_build_object('success', false, 'message', 'Você já é membro de um partido.');
    END IF;

    INSERT INTO party_members(party_id, user_id, role)
    VALUES(p_party_id, current_user_id, 'Membro');
    
    RETURN json_build_object('success', true, 'message', 'Filiação realizada com sucesso!');
END;
$$;


