CREATE OR REPLACE FUNCTION "public"."justice_write_audit"("p_action" "text", "p_entity_type" "text", "p_entity_id" "uuid", "p_previous_state" "jsonb", "p_new_state" "jsonb", "p_justification" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
