CREATE OR REPLACE FUNCTION "public"."leave_party"("p_party_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    party_founder_id UUID;
BEGIN
    SELECT founder_id INTO party_founder_id FROM political_parties WHERE id = p_party_id;
    IF party_founder_id = current_user_id THEN
        RETURN json_build_object('success', false, 'message', 'O fundador não pode abandonar o partido.');
    END IF;

    DELETE FROM party_members WHERE party_id = p_party_id AND user_id = current_user_id;

    RETURN json_build_object('success', true, 'message', 'Você saiu do partido.');
END;
$$;


ALTER FUNCTION "public"."leave_party"("p_party_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."manage_party_affiliation"("p_party_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    current_affiliation RECORD;
BEGIN
    -- Check if user is already affiliated
    SELECT * INTO current_affiliation FROM public.party_members WHERE user_id = current_user_id;

    -- If trying to join the same party, do nothing
    IF current_affiliation IS NOT NULL AND current_affiliation.party_id = p_party_id THEN
        RETURN json_build_object('success', false, 'message', 'Você já é membro deste partido.');
    END IF;

    -- If affiliated with another party, leave it first
    IF current_affiliation IS NOT NULL THEN
        DELETE FROM public.party_members WHERE user_id = current_user_id;
    END IF;

    -- Join the new party
    INSERT INTO public.party_members(party_id, user_id, role)
    VALUES(p_party_id, current_user_id, 'Membro');
    
    RETURN json_build_object('success', true, 'message', 'Filiação realizada com sucesso!');
END;
$$;


ALTER FUNCTION "public"."manage_party_affiliation"("p_party_id" "uuid") OWNER TO "postgres";


