CREATE OR REPLACE FUNCTION "public"."normalize_official_gazette_source_id"("p_seed" "text") RETURNS "uuid"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select (
    substr(md5(coalesce(p_seed, '')), 1, 8) || '-' ||
    substr(md5(coalesce(p_seed, '')), 9, 4) || '-' ||
    '4' || substr(md5(coalesce(p_seed, '')), 14, 3) || '-' ||
    'a' || substr(md5(coalesce(p_seed, '')), 18, 3) || '-' ||
    substr(md5(coalesce(p_seed, '')), 21, 12)
  )::uuid;
$$;


ALTER FUNCTION "public"."normalize_official_gazette_source_id"("p_seed" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_election_results"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    finished_election RECORD;
    winner RECORD;
    total_votes BIGINT;
    winner_votes BIGINT;
    winner_percentage NUMERIC;
    candidate_rec RECORD;
    election_type_name TEXT;
BEGIN
    FOR finished_election IN 
        SELECT id, name, election_type_id FROM public.elections 
        WHERE status = 'Voting' AND voting_end_date <= now()
    LOOP
        UPDATE public.elections SET status = 'Finished' WHERE id = finished_election.id;

        SELECT SUM(v.vote_count) INTO total_votes
        FROM (
            SELECT COUNT(*) as vote_count FROM public.votes WHERE election_id = finished_election.id
        ) v;
        
        total_votes := COALESCE(total_votes, 0);

        SELECT 
            c.user_id, 
            c.political_name,
            v.vote_count
        INTO winner
        FROM public.candidates c
        JOIN (
            SELECT candidate_id, COUNT(*) as vote_count
            FROM public.votes
            WHERE election_id = finished_election.id
            GROUP BY candidate_id
            ORDER BY vote_count DESC
            LIMIT 1
        ) as v ON c.id = v.candidate_id
        WHERE c.election_id = finished_election.id;
        
        winner_votes := COALESCE(winner.vote_count, 0);

        IF total_votes > 0 THEN
            winner_percentage := (winner_votes::NUMERIC / total_votes::NUMERIC) * 100;
        ELSE
            winner_percentage := 0;
        END IF;

        SELECT name INTO election_type_name FROM public.election_types WHERE id = finished_election.election_type_id;

        IF winner IS NOT NULL THEN
            UPDATE public.profiles SET role = election_type_name WHERE id = winner.user_id AND election_type_name IS NOT NULL;
            
            IF election_type_name = 'Presidente' THEN
                INSERT INTO public.notifications (user_id, type, content, link)
                SELECT p.id, 'election_winner_announced', 
                winner.political_name || ' venceu a eleição presidencial com ' || winner_votes || ' votos (' || round(winner_percentage, 2) || '%).', 
                '/services/elections'
                FROM public.profiles p;
            END IF;
        END IF;

        FOR candidate_rec IN 
            SELECT user_id, political_name FROM public.candidates WHERE election_id = finished_election.id AND status = 'Approved'
        LOOP
            IF winner IS NOT NULL AND candidate_rec.user_id = winner.user_id THEN
                INSERT INTO public.notifications(user_id, type, content, link)
                VALUES (candidate_rec.user_id, 'election_won', 'Parabéns! Você venceu a eleição para ' || finished_election.name || '!', '/services/elections');
            ELSE
                INSERT INTO public.notifications(user_id, type, content, link)
                VALUES (candidate_rec.user_id, 'election_lost', 'A apuração da eleição para ' || finished_election.name || ' foi concluída. Infelizmente, você não foi eleito desta vez.', '/services/elections');
            END IF;
        END LOOP;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."notify_election_results"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."notify_on_new_bill_suggestion"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    author_name TEXT;
    party_name TEXT;
    member_record RECORD;
BEGIN
    SELECT full_name INTO author_name FROM public.profiles WHERE id = NEW.author_id;

    IF NEW.target_type = 'parliamentarian' THEN
        INSERT INTO public.notifications(user_id, sender_id, type, content, link)
        VALUES (
            NEW.target_id, 
            NEW.author_id, 
            'bill_suggestion_received', 
            author_name || ' sugeriu um novo projeto: "' || NEW.title || '"',
            '/services/parliament/panel'
        );
    ELSIF NEW.target_type = 'party' THEN
        SELECT name INTO party_name FROM public.political_parties WHERE id = NEW.target_id;
        
        FOR member_record IN 
            SELECT user_id FROM public.party_members WHERE party_id = NEW.target_id 
        LOOP
            INSERT INTO public.notifications(user_id, sender_id, type, content, link)
            VALUES (
                member_record.user_id, 
                NEW.author_id, 
                'bill_suggestion_received_party', 
                author_name || ' sugeriu um novo projeto para o partido ' || party_name || ': "' || NEW.title || '"',
                '/services/political-parties/' || NEW.target_id
            );
        END LOOP;
    ELSIF NEW.target_type = 'house' THEN
         FOR member_record IN 
            SELECT p_mem.user_id 
            FROM public.parliament_members p_mem
            WHERE p_mem.house_id = NEW.target_id
        LOOP
            INSERT INTO public.notifications(user_id, sender_id, type, content, link)
            VALUES (
                member_record.user_id, 
                NEW.author_id, 
                'bill_suggestion_received', 
                author_name || ' enviou uma sugestão para a casa legislativa: "' || NEW.title || '"',
                '/services/parliament/panel'
            );
        END LOOP;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."notify_on_new_bill_suggestion"() OWNER TO "postgres";


