CREATE OR REPLACE FUNCTION "public"."officialize_parliament_commission"("p_commission_id" "uuid", "p_reporter_member_id" "uuid" DEFAULT NULL::"uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_commission record;
  v_house_id uuid;
begin
  if v_user_id is null then
    raise exception 'É necessário estar autenticado.';
  end if;

  select pc.*, pch.house_id
    into v_commission
    from public.parliament_commissions pc
    join public.parliament_commission_houses pch
      on pch.commission_id = pc.id
   where pc.id = p_commission_id
   limit 1;

  if not found then
    raise exception 'Comissão não encontrada.';
  end if;

  v_house_id := v_commission.house_id;

  if not public.is_parliament_governance_manager(v_user_id, v_house_id) then
    raise exception 'Somente a presidência da Casa pode oficializar esta comissão.';
  end if;

  if v_commission.type <> 'temporary' then
    raise exception 'A oficialização manual é reservada às comissões temporárias.';
  end if;

  if v_commission.status <> 'approved_pending_officialization' then
    raise exception 'A comissão ainda não está apta para oficialização.';
  end if;

  update public.parliament_commissions
     set status = 'active',
         officialized_by = v_user_id,
         officialized_at = now(),
         opened_at = coalesce(opened_at, now()),
         reporter_member_id = coalesce(p_reporter_member_id, reporter_member_id)
   where id = p_commission_id;

  if p_reporter_member_id is not null then
    perform public.assign_parliament_commission_member(
      p_commission_id,
      p_reporter_member_id,
      case when v_commission.type in ('cpi', 'cpmi') then 'reporter' else 'member' end
    );
  end if;

  return jsonb_build_object(
    'success', true,
    'message', 'Comissão oficializada com sucesso.'
  );
end;
$$;


ALTER FUNCTION "public"."officialize_parliament_commission"("p_commission_id" "uuid", "p_reporter_member_id" "uuid") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."criminal_investigations" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "occurrence_id" "uuid" NOT NULL,
    "investigation_number" "text" NOT NULL,
    "lead_officer_id" "uuid",
    "delegate_id" "uuid",
    "summary" "text" NOT NULL,
    "status" "text" DEFAULT 'open'::"text" NOT NULL,
    "opened_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "closed_at" timestamp with time zone,
    "conclusion" "text",
    "recommended_action" "text",
    "created_by" "uuid" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "criminal_investigations_status_check" CHECK (("status" = ANY (ARRAY['open'::"text", 'in_progress'::"text", 'delegate_review'::"text", 'complement_requested'::"text", 'sent_to_prosecutor'::"text", 'archived'::"text", 'closed'::"text"])))
);


ALTER TABLE "public"."criminal_investigations" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."open_criminal_investigation"("p_occurrence_id" "uuid", "p_summary" "text", "p_lead_officer_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."criminal_investigations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.criminal_investigations%rowtype;
  v_occurrence public.police_occurrences%rowtype;
  v_lead uuid := coalesce(p_lead_officer_id, (select auth.uid()));
begin
  if not public.justice_has_role(array['Admin', 'Policial', 'Police', 'Delegado']) then
    raise exception 'ROLE_NOT_AUTHORIZED';
  end if;
  if p_lead_officer_id is distinct from (select auth.uid())
     and not public.justice_has_role(array['Admin', 'Delegado']) then
    raise exception 'ONLY_DELEGATE_CAN_ASSIGN_ANOTHER_OFFICER';
  end if;
  if length(trim(coalesce(p_summary, ''))) < 20 then raise exception 'SUMMARY_TOO_SHORT'; end if;

  select * into v_occurrence from public.police_occurrences
  where id = p_occurrence_id for update;
  if not found then raise exception 'OCCURRENCE_NOT_FOUND'; end if;

  if exists (
    select 1 from public.criminal_investigations
    where occurrence_id = p_occurrence_id and status <> 'archived'
  ) then raise exception 'INVESTIGATION_ALREADY_EXISTS'; end if;

  insert into public.criminal_investigations(
    occurrence_id, investigation_number, lead_officer_id, delegate_id,
    summary, status, created_by
  )
  values (
    p_occurrence_id, public.justice_next_number('INQ'), v_lead,
    case when public.justice_has_role(array['Delegado']) then (select auth.uid()) else null end,
    trim(p_summary), 'in_progress', (select auth.uid())
  )
  returning * into v_row;

  update public.police_occurrences
  set status = 'Em investigação',
      assigned_officer_id = v_lead
  where id = p_occurrence_id;

  insert into public.investigation_events(
    investigation_id, event_type, title, description, actor_id, rp_occurred_at
  )
  values (
    v_row.id, 'investigation_opened', 'Investigação aberta',
    trim(p_summary), (select auth.uid()), public.rp_now()
  );

  perform public.justice_write_audit(
    'investigation.opened', 'criminal_investigation', v_row.id,
    null, to_jsonb(v_row), trim(p_summary)
  );

  return v_row;
end;
$$;


ALTER FUNCTION "public"."open_criminal_investigation"("p_occurrence_id" "uuid", "p_summary" "text", "p_lead_officer_id" "uuid") OWNER TO "postgres";


