CREATE OR REPLACE FUNCTION "public"."open_temporary_commission_voting"("p_commission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_commission record;
  v_house_id uuid;
  v_voting_id uuid;
begin
  if v_user_id is null then
    raise exception 'É necessário estar autenticado.';
  end if;

  select pc.*
    into v_commission
    from public.parliament_commissions pc
   where pc.id = p_commission_id;

  if not found then
    raise exception 'Comissão não encontrada.';
  end if;

  if v_commission.type <> 'temporary' then
    raise exception 'Apenas comissões temporárias usam votação plenária.';
  end if;

  if v_commission.status <> 'pending_plenary' then
    raise exception 'A comissão já não está aguardando votação plenária.';
  end if;

  select house_id
    into v_house_id
    from public.parliament_commission_houses
   where commission_id = p_commission_id
   limit 1;

  if v_house_id is null then
    raise exception 'Casa legislativa da comissão não encontrada.';
  end if;

  if not public.is_parliament_governance_manager(v_user_id, v_house_id) then
    raise exception 'Somente a mesa diretora pode abrir a votação desta comissão.';
  end if;

  if v_commission.voting_id is not null then
    if exists (
      select 1
        from public.parliament_votings
       where id = v_commission.voting_id
         and status = 'active'
    ) then
      raise exception 'Já existe uma votação ativa para esta comissão.';
    end if;
  end if;

  insert into public.parliament_votings (
    house_id,
    title,
    description,
    type,
    related_id,
    status,
    end_date
  )
  values (
    v_house_id,
    '[Comissão Temporária] ' || v_commission.title,
    v_commission.summary,
    'commission',
    p_commission_id,
    'active',
    now() + interval '24 hours'
  )
  returning id into v_voting_id;

  update public.parliament_commissions
     set voting_id = v_voting_id,
         updated_at = now()
   where id = p_commission_id;

  return jsonb_build_object(
    'success', true,
    'voting_id', v_voting_id,
    'message', 'Votação plenária aberta para a comissão temporária.'
  );
end;
$$;


ALTER FUNCTION "public"."open_temporary_commission_voting"("p_commission_id" "uuid") OWNER TO "postgres";


