CREATE OR REPLACE FUNCTION "public"."pay_boleto"("p_bill_code" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_account_id uuid;
    v_account_balance numeric;
    v_bill_info RECORD;
BEGIN
    -- 1. Validar o boleto
    SELECT * INTO v_bill_info FROM public.bills_of_exchange WHERE bill_code = p_bill_code;

    IF v_bill_info IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Boleto inexistente.');
    END IF;

    IF v_bill_info.status = 'paid' THEN
        RETURN json_build_object('success', false, 'message', 'Este boleto já foi pago.');
    END IF;

    -- 2. Obter conta bancária e saldo do utilizador autenticado
    SELECT id, balance INTO v_account_id, v_account_balance
    FROM public.accounts WHERE user_id = auth.uid() LIMIT 1;

    -- 3. Verificar se a conta existe
    IF v_account_id IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Conta bancária não encontrada.');
    END IF;

    -- 4. Validar o saldo
    IF v_account_balance < v_bill_info.amount THEN
        RETURN json_build_object('success', false, 'message', 'Saldo insuficiente para realizar o pagamento.');
    END IF;

    -- 5. Debitar da conta do pagador
    UPDATE public.accounts SET balance = balance - v_bill_info.amount WHERE id = v_account_id;

    -- 6. Creditar na conta do emissor (se houver)
    IF v_bill_info.issuer_id IS NOT NULL THEN
        UPDATE public.accounts SET balance = balance + v_bill_info.amount WHERE user_id = v_bill_info.issuer_id;
    END IF;

    -- 7. Atualizar o status do boleto
    UPDATE public.bills_of_exchange SET status = 'paid', updated_at = now() WHERE id = v_bill_info.id;

    -- 8. Registar a transação de pagamento
    INSERT INTO public.transactions (from_account_id, to_account_id, amount, description, type, metadata)
    VALUES (v_account_id, (SELECT id FROM public.accounts WHERE user_id = v_bill_info.issuer_id), v_bill_info.amount, 'Pagamento de Boleto: ' || v_bill_info.description, 'bill_payment', jsonb_build_object('bill_code', p_bill_code));

    -- 9. Retornar sucesso
    RETURN json_build_object('success', true, 'message', 'Boleto pago com sucesso!');
END;
$$;


ALTER FUNCTION "public"."pay_boleto"("p_bill_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pay_boleto"("p_bill_code" "text", "p_amount" numeric) RETURNS json
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_account_id uuid;
    v_account_balance numeric;
BEGIN
    -- 1. Obter conta bancária e saldo do utilizador autenticado
    SELECT id, balance INTO v_account_id, v_account_balance
    FROM public.accounts WHERE user_id = auth.uid() LIMIT 1;

    -- 2. Verificar se a conta existe
    IF v_account_id IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Conta bancária não encontrada.');
    END IF;

    -- 3. Validar o valor e o saldo
    IF p_amount <= 0 THEN
        RETURN json_build_object('success', false, 'message', 'O valor do pagamento deve ser positivo.');
    END IF;

    IF v_account_balance < p_amount THEN
        RETURN json_build_object('success', false, 'message', 'Saldo insuficiente para realizar o pagamento.');
    END IF;

    -- 4. Debitar da conta principal
    UPDATE public.accounts SET balance = balance - p_amount WHERE id = v_account_id;

    -- 5. Registar a transação de pagamento
    INSERT INTO public.transactions (from_account_id, amount, description, type, metadata)
    VALUES (v_account_id, p_amount, 'Pagamento de Boleto', 'bill_payment', jsonb_build_object('bill_code', p_bill_code));

    -- 6. Retornar sucesso
    RETURN json_build_object('success', true, 'message', 'Boleto pago com sucesso!');
END;
$$;


ALTER FUNCTION "public"."pay_boleto"("p_bill_code" "text", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pay_card_bill"("p_card_id" "uuid", "p_amount_to_pay" numeric) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_user_id uuid := auth.uid();
    v_account_id uuid;
    v_account_balance numeric;
    v_card record;
BEGIN
    -- 1. Obter detalhes do cartão
    SELECT * INTO v_card FROM public.cards WHERE id = p_card_id AND user_id = v_user_id;

    IF v_card IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Cartão não encontrado ou não pertence a você.');
    END IF;

    -- 2. Validação do valor a ser pago
    IF p_amount_to_pay <= 0 THEN
        RETURN json_build_object('success', false, 'message', 'O valor do pagamento deve ser positivo.');
    END IF;
    IF p_amount_to_pay > v_card.used_limit THEN
        RETURN json_build_object('success', false, 'message', 'O valor do pagamento não pode ser maior que o valor utilizado.');
    END IF;

    -- 3. Obter conta bancária e saldo do utilizador
    SELECT id, balance INTO v_account_id, v_account_balance
    FROM public.accounts WHERE user_id = v_user_id LIMIT 1;

    IF v_account_id IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Conta bancária não encontrada.');
    END IF;

    IF v_account_balance < p_amount_to_pay THEN
        RETURN json_build_object('success', false, 'message', 'Saldo insuficiente para realizar o pagamento.');
    END IF;

    -- 4. Executar as operações financeiras
    -- Debitar da conta principal
    UPDATE public.accounts SET balance = balance - p_amount_to_pay WHERE id = v_account_id;

    -- Deduzir do limite utilizado do cartão
    UPDATE public.cards SET used_limit = used_limit - p_amount_to_pay WHERE id = v_card.id;

    -- 5. Registar a transação de pagamento
    INSERT INTO public.transactions (from_account_id, to_account_id, amount, description, type, metadata)
    VALUES (v_account_id, NULL, p_amount_to_pay, 'Pagamento antecipado de cartão de crédito', 'card_payment', jsonb_build_object('card_id', v_card.id));

    RETURN json_build_object('success', true, 'message', 'Pagamento antecipado realizado com sucesso!');
END;
$$;


ALTER FUNCTION "public"."pay_card_bill"("p_card_id" "uuid", "p_amount_to_pay" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pay_card_invoice"("p_invoice_id" "uuid", "p_pay_full" boolean, "p_amount_to_pay" numeric) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    invoice_info RECORD;
    user_account RECORD;
    final_amount NUMERIC;
BEGIN
    SELECT * INTO invoice_info FROM public.card_invoices WHERE id = p_invoice_id AND user_id = current_user_id;

    IF invoice_info IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Fatura não encontrada ou não pertence a você.');
    END IF;

    IF invoice_info.status = 'paid' AND invoice_info.amount <= 0 THEN
        RETURN json_build_object('success', false, 'message', 'Esta fatura já foi paga.');
    END IF;

    IF p_pay_full THEN
        final_amount := invoice_info.amount;
    ELSE
        final_amount := p_amount_to_pay;
    END IF;

    IF final_amount <= 0 OR final_amount > invoice_info.amount THEN
        RETURN json_build_object('success', false, 'message', 'Valor de pagamento inválido.');
    END IF;

    SELECT * INTO user_account FROM public.accounts WHERE user_id = current_user_id;
    IF user_account IS NULL OR user_account.balance < final_amount THEN
        RETURN json_build_object('success', false, 'message', 'Saldo em conta insuficiente para pagar a fatura.');
    END IF;

    -- Debit from account
    UPDATE public.accounts SET balance = balance - final_amount WHERE id = user_account.id;

    -- Update invoice
    UPDATE public.card_invoices 
    SET amount = amount - final_amount, 
        status = CASE WHEN (amount - final_amount) <= 0 THEN 'paid' ELSE status END,
        updated_at = now()
    WHERE id = p_invoice_id;

    -- Update card used limit
    UPDATE public.cards SET used_limit = GREATEST(0, used_limit - final_amount) WHERE id = invoice_info.card_id;

    -- Log transaction
    INSERT INTO public.transactions (from_account_id, amount, description, type, metadata)
    VALUES (user_account.id, final_amount, 'Pagamento de Fatura de Cartão', 'invoice_payment', jsonb_build_object('invoice_id', p_invoice_id, 'card_id', invoice_info.card_id));

    RETURN json_build_object('success', true, 'message', 'Pagamento da fatura realizado com sucesso.');
END;
$$;


ALTER FUNCTION "public"."pay_card_invoice"("p_invoice_id" "uuid", "p_pay_full" boolean, "p_amount_to_pay" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."pay_fine"("p_fine_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    fine_info RECORD;
    user_account RECORD;
    current_user_id UUID := auth.uid();
    total_amount NUMERIC;
    interest_rate NUMERIC := 0.0033; -- 0.33% per day
    days_overdue INT;
    interest_amount NUMERIC := 0;
BEGIN
    SELECT * INTO fine_info FROM public.police_fines WHERE id = p_fine_id AND user_id = current_user_id;

    IF fine_info IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Multa não encontrada ou não pertence a você.');
    END IF;

    IF fine_info.status <> 'Pendente' THEN
        RETURN json_build_object('success', false, 'message', 'Esta multa não está pendente de pagamento.');
    END IF;

    -- Calculate interest if overdue
    IF fine_info.due_date < now() THEN
        days_overdue := EXTRACT(DAY FROM (now() - fine_info.due_date));
        interest_amount := fine_info.amount * interest_rate * days_overdue;
    END IF;
    
    total_amount := fine_info.amount + interest_amount;

    SELECT * INTO user_account FROM public.accounts WHERE user_id = current_user_id;
    IF user_account IS NULL OR user_account.balance < total_amount THEN
        RETURN json_build_object('success', false, 'message', 'Saldo insuficiente para pagar a multa (incluindo juros).');
    END IF;

    -- Debit from user
    UPDATE public.accounts SET balance = balance - total_amount WHERE id = user_account.id;
    -- Credit government treasury
    UPDATE public.government_finances SET treasury_balance = treasury_balance + total_amount WHERE id = 1;
    -- Update fine status
    UPDATE public.police_fines SET status = 'Paga', updated_at = now() WHERE id = p_fine_id;

    -- Log transaction
    INSERT INTO public.transactions (from_account_id, to_account_id, amount, description, type, metadata)
    VALUES (user_account.id, (SELECT id FROM accounts WHERE user_id = '00000000-0000-0000-0000-000000000001'), total_amount, 'Pagamento de multa: ' || fine_info.reason, 'fine_payment', 
    jsonb_build_object('base_amount', fine_info.amount, 'interest_amount', interest_amount));

    RETURN json_build_object('success', true, 'message', 'Multa paga com sucesso.');
END;
$$;


ALTER FUNCTION "public"."pay_fine"("p_fine_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."place_authoritative_trade"("_user_id" "uuid", "_account_type" "text", "_asset_id" "text", "_asset_symbol" "text", "_direction" "text", "_amount" numeric, "_entry_price" numeric, "_entry_quote_at" timestamp with time zone, "_payout_percent" numeric, "_expiry_time" timestamp with time zone, "_duration_seconds" integer, "_price_source" "text", "_price_engine_version" "text") RETURNS TABLE("trade_id" "uuid", "new_balance" numeric, "entry_price" numeric, "entry_quote_at" timestamp with time zone, "opened_at" timestamp with time zone, "expiry_time" timestamp with time zone)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  _role text := COALESCE(current_setting('request.jwt.claims', true)::jsonb->>'role', '');
  _trade_id uuid;
  _balance_before numeric;
  _balance_after numeric;
  _accepted_at timestamptz := clock_timestamp();
BEGIN
  IF _role <> 'service_role' THEN
    RAISE EXCEPTION 'Somente o servidor pode registrar uma operação autoritativa.';
  END IF;

  IF _user_id IS NULL OR _account_type NOT IN ('demo', 'real') THEN
    RAISE EXCEPTION 'Conta inválida.';
  END IF;
  IF COALESCE(trim(_asset_id), '') = '' OR COALESCE(trim(_asset_symbol), '') = '' THEN
    RAISE EXCEPTION 'Ativo inválido.';
  END IF;
  IF _direction NOT IN ('call', 'put') THEN
    RAISE EXCEPTION 'Direção inválida.';
  END IF;
  IF _amount IS NULL OR _amount < 1 OR _amount > 10000 THEN
    RAISE EXCEPTION 'Valor da operação inválido.';
  END IF;
  IF _entry_price IS NULL OR _entry_price <= 0
     OR _entry_price::text IN ('NaN', 'Infinity', '-Infinity') THEN
    RAISE EXCEPTION 'Preço de entrada inválido.';
  END IF;
  IF _entry_quote_at IS NULL
     OR _entry_quote_at < _accepted_at - interval '10 seconds'
     OR _entry_quote_at > _accepted_at + interval '2 seconds' THEN
    RAISE EXCEPTION 'Cotação de entrada expirada ou relógio do dispositivo dessincronizado.';
  END IF;
  IF _expiry_time IS NULL
     OR _expiry_time <= _accepted_at
     OR _expiry_time > _accepted_at + interval '24 hours 1 minute' THEN
    RAISE EXCEPTION 'Vencimento inválido.';
  END IF;
  IF _duration_seconds IS NULL OR _duration_seconds < 5 OR _duration_seconds > 86400 THEN
    RAISE EXCEPTION 'Duração inválida.';
  END IF;
  IF _payout_percent IS NULL OR _payout_percent < 0 OR _payout_percent > 100 THEN
    RAISE EXCEPTION 'Percentual de pagamento inválido.';
  END IF;
  IF COALESCE(trim(_price_source), '') = '' OR COALESCE(trim(_price_engine_version), '') = '' THEN
    RAISE EXCEPTION 'Metadados de preço inválidos.';
  END IF;

  PERFORM set_config('app.financial_update_allowed', 'true', true);

  IF _account_type = 'real' THEN
    SELECT real_balance
      INTO _balance_before
      FROM public.profiles
     WHERE id = _user_id
     FOR UPDATE;
  ELSE
    SELECT demo_balance
      INTO _balance_before
      FROM public.profiles
     WHERE id = _user_id
     FOR UPDATE;
  END IF;

  IF _balance_before IS NULL THEN
    RAISE EXCEPTION 'Perfil financeiro não encontrado.';
  END IF;
  IF _balance_before < _amount THEN
    RAISE EXCEPTION 'Saldo insuficiente.';
  END IF;

  IF _account_type = 'real' THEN
    UPDATE public.profiles
       SET real_balance = real_balance - _amount,
           updated_at = now()
     WHERE id = _user_id
     RETURNING real_balance INTO _balance_after;
  ELSE
    UPDATE public.profiles
       SET demo_balance = demo_balance - _amount,
           updated_at = now()
     WHERE id = _user_id
     RETURNING demo_balance INTO _balance_after;
  END IF;

  INSERT INTO public.trades (
    user_id,
    asset_id,
    asset_symbol,
    direction,
    amount,
    entry_price,
    entry_quote_at,
    price_source,
    price_engine_version,
    payout_percent,
    status,
    expiry_time,
    opened_at,
    duration_seconds,
    account_type
  ) VALUES (
    _user_id,
    _asset_id,
    _asset_symbol,
    _direction,
    _amount,
    _entry_price,
    _entry_quote_at,
    _price_source,
    _price_engine_version,
    _payout_percent,
    'active',
    _expiry_time,
    _accepted_at,
    _duration_seconds,
    _account_type
  )
  RETURNING id INTO _trade_id;

  INSERT INTO public.trade_settlement_audit (
    trade_id,
    user_id,
    account_type,
    event_type,
    status_before,
    status_after,
    amount,
    payout,
    entry_price,
    balance_before,
    balance_after,
    metadata
  ) VALUES (
    _trade_id,
    _user_id,
    _account_type,
    'placed',
    NULL,
    'active',
    _amount,
    0,
    _entry_price,
    _balance_before,
    _balance_after,
    jsonb_build_object(
      'asset_id', _asset_id,
      'asset_symbol', _asset_symbol,
      'direction', _direction,
      'payout_percent', _payout_percent,
      'entry_quote_at', _entry_quote_at,
      'accepted_at', _accepted_at,
      'price_source', _price_source,
      'price_engine_version', _price_engine_version
    )
  );

  RETURN QUERY
  SELECT
    _trade_id,
    _balance_after,
    _entry_price,
    _entry_quote_at,
    _accepted_at,
    _expiry_time;
END;
$$;


ALTER FUNCTION "public"."place_authoritative_trade"("_user_id" "uuid", "_account_type" "text", "_asset_id" "text", "_asset_symbol" "text", "_direction" "text", "_amount" numeric, "_entry_price" numeric, "_entry_quote_at" timestamp with time zone, "_payout_percent" numeric, "_expiry_time" timestamp with time zone, "_duration_seconds" integer, "_price_source" "text", "_price_engine_version" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."prevent_duplicate_party_leadership"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  leader_id uuid;
  conflict_party text;
begin
  if new.vice_president_id is not null
     and new.vice_president_id in (new.owner_id, new.president_id) then
    raise exception 'O vice-presidente deve ser diferente do dono e do presidente do partido.';
  end if;

  foreach leader_id in array array_remove(array[new.owner_id, new.president_id, new.vice_president_id], null)
  loop
    select concat(name, ' (', acronym, ')') into conflict_party
    from public.political_parties
    where id <> new.id
      and coalesce(is_active, true)
      and leader_id in (owner_id, president_id, vice_president_id)
    limit 1;

    if conflict_party is not null then
      raise exception 'Este usuário já ocupa liderança no partido %.', conflict_party;
    end if;
  end loop;

  return new;
end;
$$;


ALTER FUNCTION "public"."prevent_duplicate_party_leadership"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_automatic_stabilizers"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  unemployment numeric:=coalesce(economy_private.latest_indicator('unemployment_rate'),8.5);
  threshold numeric:=economy_private.calibration_numeric('automatic_stabilizer_unemployment_threshold',10);
  transfer_amount numeric;
  source_id text;
  expenditure_id uuid;
begin
  if auth.uid() is not null and not public.economic_has_role(array['Admin']) then
    raise exception 'Execução manual restrita ao Admin.' using errcode='42501';
  end if;
  if unemployment<=threshold then
    return jsonb_build_object('status','not_required','unemployment_rate',unemployment);
  end if;
  transfer_amount:=least(
    (unemployment-threshold)*economy_private.calibration_numeric('baseline_population',2000000)*25,
    economy_private.calibration_numeric('automatic_stabilizer_monthly_cap',100000000)
  );
  source_id:='unemployment:'||to_char(date_trunc('month',public.rp_now()),'YYYY-MM');
  insert into public.government_expenditures(
    expenditure_type,ministry,source_table,source_id,amount,productive_share,
    occurred_at_rp,metadata
  )
  values (
    'social_assistance','Assistência Social','automatic_stabilizers',source_id,
    transfer_amount,0,public.rp_now(),
    jsonb_build_object('unemployment_rate',unemployment,'threshold',threshold)
  )
  on conflict (source_table,source_id,expenditure_type) do nothing
  returning id into expenditure_id;
  if expenditure_id is null then
    return jsonb_build_object('status','already_processed','source_id',source_id);
  end if;
  return jsonb_build_object('status','processed','amount',transfer_amount,
    'expenditure_id',expenditure_id);
end;
$$;


ALTER FUNCTION "public"."process_automatic_stabilizers"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_card_transactions_for_invoice"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    card_record RECORD;
    invoice_record RECORD;
    total_amount NUMERIC;
BEGIN
    -- Iterate over all active cards
    FOR card_record IN SELECT * FROM public.cards WHERE is_active = true LOOP
        -- Check if an invoice for the current period already exists
        SELECT * INTO invoice_record
        FROM public.card_invoices
        WHERE card_id = card_record.id
          AND closing_date = date_trunc('month', now())::date + interval '24 days' - interval '1 day';

        -- If no invoice exists, create one
        IF invoice_record IS NULL THEN
            INSERT INTO public.card_invoices (card_id, user_id, closing_date, due_date, amount, status)
            VALUES (
                card_record.id,
                card_record.user_id,
                date_trunc('month', now())::date + interval '24 days' - interval '1 day', -- Example: closes on day 24
                date_trunc('month', now())::date + interval '1 month' + interval '9 days', -- Example: due on day 10 of next month
                0,
                'open'
            ) RETURNING * INTO invoice_record;
        END IF;

        -- Sum all transactions for this card that are not yet in an invoice
        SELECT COALESCE(SUM(t.amount), 0) INTO total_amount
        FROM public.transactions t
        WHERE t.metadata->>'card_id' = card_record.id::text
          AND NOT EXISTS (
              SELECT 1 FROM public.card_invoice_items cii WHERE cii.transaction_id = t.id
          );

        -- If there are new transactions, add them to the invoice
        IF total_amount > 0 THEN
            -- Add items to the invoice
            INSERT INTO public.card_invoice_items (invoice_id, transaction_id, description, amount)
            SELECT invoice_record.id, t.id, t.description, t.amount
            FROM public.transactions t
            WHERE t.metadata->>'card_id' = card_record.id::text
              AND NOT EXISTS (
                  SELECT 1 FROM public.card_invoice_items cii WHERE cii.transaction_id = t.id
              );

            -- Update the total amount of the invoice
            UPDATE public.card_invoices
            SET amount = amount + total_amount, updated_at = now()
            WHERE id = invoice_record.id;
        END IF;
    END LOOP;
END;
$$;


ALTER FUNCTION "public"."process_card_transactions_for_invoice"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_citizen_income"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    settings JSONB;
    income_amount NUMERIC;
    payment_day INT;
    today_day_of_week INT;
    citizen RECORD;
    total_paid NUMERIC := 0;
    users_paid INT := 0;
BEGIN
    SELECT value INTO settings FROM public.system_settings WHERE key = 'citizen_income' LIMIT 1;

    IF settings IS NULL OR NOT (settings->>'enabled')::boolean THEN
        RETURN json_build_object('success', true, 'message', 'Renda Cidadã está desativada.');
    END IF;

    income_amount := (settings->>'amount')::numeric;
    payment_day := (settings->>'day_of_week')::int;
    today_day_of_week := EXTRACT(DOW FROM now() AT TIME ZONE 'America/Sao_Paulo'); -- 0=Domingo, 6=Sábado

    IF today_day_of_week <> payment_day THEN
        RETURN json_build_object('success', true, 'message', 'Hoje não é o dia de pagamento da Renda Cidadã.');
    END IF;
    
    IF income_amount <= 0 THEN
       RETURN json_build_object('success', false, 'message', 'Valor da Renda Cidadã não é positivo.');
    END IF;

    -- Previne múltiplas execuções no mesmo dia
    IF EXISTS (SELECT 1 FROM public.transactions WHERE type = 'citizen_income' AND created_at >= date_trunc('day', now() AT TIME ZONE 'America/Sao_Paulo')) THEN
        RETURN json_build_object('success', true, 'message', 'Pagamento da Renda Cidadã para hoje já foi processado.');
    END IF;
    
    FOR citizen IN 
        SELECT id FROM public.accounts
    LOOP
        UPDATE public.accounts SET balance = balance + income_amount WHERE id = citizen.id;
        
        INSERT INTO public.transactions (to_account_id, amount, description, type)
        VALUES (citizen.id, income_amount, 'Renda Cidadã Semanal', 'citizen_income');
        
        total_paid := total_paid + income_amount;
        users_paid := users_paid + 1;
    END LOOP;
    
    RETURN json_build_object('success', true, 'message', 'Pagamento da Renda Cidadã concluído.', 'total_paid', total_paid, 'users_paid', users_paid);
END;
$$;


ALTER FUNCTION "public"."process_citizen_income"() OWNER TO "postgres";


