CREATE OR REPLACE FUNCTION "public"."process_weekly_salaries"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $_$
DECLARE
    v_batch_id UUID := gen_random_uuid();
    v_total_paid NUMERIC := 0;
    v_payments_count INT := 0;
    v_role_record RECORD;
    v_user_record RECORD;
    v_salary NUMERIC;
    v_title TEXT;
    v_gov_balance NUMERIC;
    v_payment_details JSONB := '[]'::JSONB;
BEGIN
    -- Get current government balance
    SELECT COALESCE(
        (SELECT value::NUMERIC FROM system_settings WHERE key = 'government_balance'),
        0
    ) INTO v_gov_balance;

    -- Define salary mapping
    FOR v_role_record IN (
        SELECT * FROM (VALUES
            ('Presidente', 'Presidente da República', 35000.00),
            ('Vice-Presidente', 'Vice-Presidente', 24500.00),
            ('Deputado', 'Deputado Federal', 10500.00),
            ('Senador', 'Senador', 17500.00),
            ('Presidente do Senado', 'Presidente do Senado', 24500.00),
            ('Presidente da Câmara', 'Presidente da Câmara', 21000.00),
            ('Ministro', 'Ministro de Estado', 17500.00)
        ) AS t(role, title, salary)
    ) LOOP
        -- Find all users with this role
        FOR v_user_record IN (
            SELECT p.id, p.full_name, p.role AS user_role, p.username
            FROM profiles p
            WHERE p.role = v_role_record.role
              AND p.id IS NOT NULL
        ) LOOP
            v_salary := v_role_record.salary;
            v_title := v_role_record.title;

            -- Check special titles (Presidente do Senado, Presidente da Câmara)
            -- These are extra roles determined by titles array or specific check
            -- For now, process based on role column

            -- Check if government has enough funds
            IF v_gov_balance >= v_salary THEN
                -- Insert salary payment record
                INSERT INTO salary_payments (user_id, role, title, amount, payment_batch_id)
                VALUES (v_user_record.id, v_role_record.role, v_title, v_salary, v_batch_id);

                -- Credit user bank balance
                UPDATE profiles
                SET bank_balance = COALESCE(bank_balance, 0) + v_salary
                WHERE id = v_user_record.id;

                -- Deduct from government balance
                v_gov_balance := v_gov_balance - v_salary;
                v_total_paid := v_total_paid + v_salary;
                v_payments_count := v_payments_count + 1;

                -- Create notification for the user
                INSERT INTO notifications (user_id, type, content, link)
                VALUES (
                    v_user_record.id,
                    'salary',
                    '💰 Salário recebido! Você recebeu R$ ' || TO_CHAR(v_salary, 'FM999G999D00') || ' referente ao cargo de ' || v_title || '.',
                    '/services/bank'
                );

                -- Add to payment details
                v_payment_details := v_payment_details || jsonb_build_object(
                    'user_id', v_user_record.id,
                    'name', COALESCE(v_user_record.full_name, v_user_record.username),
                    'role', v_title,
                    'amount', v_salary
                );
            END IF;
        END LOOP;
    END LOOP;

    -- Update government balance
    UPDATE system_settings
    SET value = v_gov_balance::TEXT
    WHERE key = 'government_balance';

    -- Publish to Diário Oficial if any payments were made
    IF v_payments_count > 0 THEN
        INSERT INTO news (
            title,
            content,
            category,
            author_id,
            image_url,
            is_published
        ) VALUES (
            '📋 Diário Oficial da União - Folha de Pagamento Semanal',
            E'O Governo Federal informa que a folha de pagamento semanal dos servidores públicos foi processada com sucesso.\n\n' ||
            E'**Resumo da Folha:**\n' ||
            E'- Total de servidores pagos: ' || v_payments_count || E'\n' ||
            E'- Valor total desembolsado: R$ ' || TO_CHAR(v_total_paid, 'FM999G999D00') || E'\n' ||
            E'- Fonte: Cofre da União\n' ||
            E'- Data de processamento: ' || TO_CHAR(NOW(), 'DD/MM/YYYY "às" HH24:MI') || E'\n\n' ||
            E'Os valores foram creditados diretamente nas contas bancárias dos respectivos servidores.',
            'oficial',
            (SELECT id FROM profiles WHERE role = 'Admin' LIMIT 1),
            NULL,
            true
        );
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'batch_id', v_batch_id,
        'total_paid', v_total_paid,
        'payments_count', v_payments_count,
        'payments', v_payment_details
    );
END;
$_$;


ALTER FUNCTION "public"."process_weekly_salaries"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."process_weekly_service_bills"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    service_rec RECORD;
    user_account RECORD;
    total_billed_amount NUMERIC := 0;
    billed_users_count INT := 0;
    today_is_monday BOOLEAN;
    current_hour INT;
BEGIN
    -- Check if it's Monday after 9 AM UTC (adjust UTC offset as needed, e.g., -3 for BRT)
    today_is_monday := EXTRACT(ISODOW FROM (now() AT TIME ZONE 'UTC')) = 1;
    current_hour := EXTRACT(HOUR FROM (now() AT TIME ZONE 'UTC'));

    IF NOT (today_is_monday AND current_hour >= 9) THEN
        RETURN json_build_object('success', true, 'message', 'Não é hora de cobrar as contas de serviço ainda.');
    END IF;

    FOR service_rec IN
        SELECT * FROM public.user_services
        WHERE is_active = true
          AND (last_billed_at IS NULL OR last_billed_at < (now() - interval '6 days'))
    LOOP
        SELECT * INTO user_account FROM public.accounts WHERE user_id = service_rec.user_id;

        IF user_account IS NOT NULL AND user_account.balance >= service_rec.price THEN
            -- Deduct from user's account
            UPDATE public.accounts SET balance = balance - service_rec.price WHERE id = user_account.id;

            -- Log the transaction
            INSERT INTO public.transactions (from_account_id, amount, description, type)
            VALUES (user_account.id, service_rec.price, 'Pagamento semanal: ' || service_rec.service_type, 'service_payment');

            -- Update the service billing date
            UPDATE public.user_services SET last_billed_at = now() WHERE id = service_rec.id;

            total_billed_amount := total_billed_amount + service_rec.price;
            billed_users_count := billed_users_count + 1;
        ELSE
            -- Deactivate service if user has no money
            UPDATE public.user_services SET is_active = false WHERE id = service_rec.id;
            
            -- Notify user about deactivation
            INSERT INTO public.notifications(user_id, type, content, link)
            VALUES (service_rec.user_id, 'service_deactivated', 'Seu serviço de ' || service_rec.service_type || ' foi desativado por falta de pagamento.', '/services/internet');
        END IF;
    END LOOP;

    RETURN json_build_object(
        'success', true, 
        'message', 'Processo de cobrança semanal concluído.',
        'total_billed', total_billed_amount,
        'users_billed', billed_users_count
    );
END;
$$;


ALTER FUNCTION "public"."process_weekly_service_bills"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."promote_vice_president_when_presidency_empty"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  vice_profile_id uuid;
begin
  if tg_op <> 'UPDATE'
     or coalesce(old.role, '') <> 'Presidente'
     or coalesce(new.role, '') = 'Presidente' then
    return new;
  end if;

  if exists (
    select 1
    from public.profiles profile
    where profile.id <> old.id
      and profile.role = 'Presidente'
  ) then
    return new;
  end if;

  select profile.id into vice_profile_id
  from public.profiles profile
  where profile.role = 'Vice-Presidente'
  order by profile.role_assigned_at asc nulls last, profile.full_name asc nulls last, profile.id::text asc
  limit 1;

  if vice_profile_id is null then
    insert into public.system_settings (key, value, description)
    values (
      'executive_governance',
      jsonb_build_object(
        'officeVacancy', jsonb_build_object(
          'vacant', true,
          'since', now(),
          'reason', 'Presidente deixou o cargo sem Vice-Presidente ativo',
          'triggered_by', coalesce(auth.uid(), old.id)
        ),
        'presidentialSuccession', null
      ),
      'Governança constitucional do Poder Executivo.'
    )
    on conflict (key) do update
    set
      value = coalesce(public.system_settings.value::jsonb, '{}'::jsonb)
        || jsonb_build_object(
          'officeVacancy', jsonb_build_object(
            'vacant', true,
            'since', now(),
            'reason', 'Presidente deixou o cargo sem Vice-Presidente ativo',
            'triggered_by', coalesce(auth.uid(), old.id)
          ),
          'presidentialSuccession', null
        ),
      updated_at = now();

    return new;
  end if;

  update public.profiles
  set
    role = 'Presidente',
    manual_role_override = true,
    role_assigned_at = now(),
    role_assigned_by = coalesce(auth.uid(), old.id)
  where id = vice_profile_id;

  insert into public.system_settings (key, value, description)
  values (
    'executive_governance',
    jsonb_build_object(
      'officeVacancy', jsonb_build_object(
        'vacant', false,
        'since', null,
        'reason', '',
        'triggered_by', null
      ),
      'presidentialSuccession', jsonb_build_object(
        'promoted_president_id', vice_profile_id,
        'previous_vice_id', vice_profile_id,
        'former_president_id', old.id,
        'term_election_id', null,
        'promoted_at', now(),
        'reason', 'Vacância presidencial automática',
        'triggered_by', coalesce(auth.uid(), old.id)
      )
    ),
    'Governança constitucional do Poder Executivo.'
  )
  on conflict (key) do update
  set
    value = coalesce(public.system_settings.value::jsonb, '{}'::jsonb)
      || jsonb_build_object(
        'officeVacancy', jsonb_build_object(
          'vacant', false,
          'since', null,
          'reason', '',
          'triggered_by', null
        ),
        'presidentialSuccession', jsonb_build_object(
          'promoted_president_id', vice_profile_id,
          'previous_vice_id', vice_profile_id,
          'former_president_id', old.id,
          'term_election_id', null,
          'promoted_at', now(),
          'reason', 'Vacância presidencial automática',
          'triggered_by', coalesce(auth.uid(), old.id)
        )
      ),
    updated_at = now();

  return new;
end;
$$;


ALTER FUNCTION "public"."promote_vice_president_when_presidency_empty"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."propose_government_project"("p_name" "text", "p_description" "text", "p_ministry" "text", "p_sector_id" "uuid", "p_project_type" "text", "p_approved_budget" numeric, "p_expected_completion_at_rp" timestamp with time zone, "p_productivity_impact" numeric DEFAULT 0, "p_employment_impact" numeric DEFAULT 0, "p_inflation_impact" numeric DEFAULT 0) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare project_id uuid;
begin
  if auth.uid() is null or not public.economic_has_role(array[
    'Admin','Presidente','Ministro','Ministro da Fazenda','Ministro da Economia'
  ]) then
    raise exception 'Cargo sem competência para propor projetos.' using errcode='42501';
  end if;
  if p_approved_budget<=0 or p_approved_budget>
      economy_private.calibration_numeric('max_government_project_budget',500000000) then
    raise exception 'Orçamento do projeto fora dos limites.';
  end if;
  insert into public.government_projects(
    name,description,ministry,sector_id,project_type,approved_budget,
    expected_completion_at,productivity_impact,employment_impact,inflation_impact,
    immediate_multiplier,future_multiplier,created_by
  )
  values (
    trim(p_name),trim(p_description),trim(p_ministry),p_sector_id,p_project_type,
    p_approved_budget,public.rp_date_to_real_date(p_expected_completion_at_rp),
    p_productivity_impact,p_employment_impact,p_inflation_impact,
    case p_project_type when 'infrastructure' then 1.35 when 'social_assistance' then 1.25 else 1 end,
    case p_project_type when 'education' then 1.65 when 'technology' then 1.75 when 'infrastructure' then 1.45 else 1 end,
    auth.uid()
  )
  returning id into project_id;
  perform economy_private.audit('propose_government_project','government_project',project_id::text,
    null,to_jsonb((select p from public.government_projects p where p.id=project_id)),
    'Proposta registrada pelo responsável.',auth.uid());
  return project_id;
end;
$$;


ALTER FUNCTION "public"."propose_government_project"("p_name" "text", "p_description" "text", "p_ministry" "text", "p_sector_id" "uuid", "p_project_type" "text", "p_approved_budget" numeric, "p_expected_completion_at_rp" timestamp with time zone, "p_productivity_impact" numeric, "p_employment_impact" numeric, "p_inflation_impact" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."protect_manual_admin_role"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if old.manual_role_override is true
     and old.role in ('Presidente', 'Vice-Presidente', 'Deputado', 'Senador', 'Ministro')
     and new.role in ('Usuario', 'Usuário', 'Cidadao', 'Cidadão')
     and coalesce(new.manual_role_override, old.manual_role_override) is true
     and public.election_supersedes_manual_role(old.role, old.role_assigned_at) is false then
    new.role := old.role;
    new.manual_role_override := true;
    new.role_assigned_at := old.role_assigned_at;
    new.role_assigned_by := old.role_assigned_by;
    return new;
  end if;

  if new.role is distinct from old.role
     and new.role is not null
     and new.role not in ('Usuario', 'Usuário', 'Cidadao', 'Cidadão')
     and coalesce(new.manual_role_override, false) is false
     and not exists (
       select 1
       from public.system_settings settings
       cross join lateral jsonb_array_elements(coalesce(settings.value::jsonb->'active_assignments', '[]'::jsonb)) assignment
       where settings.key = 'election_office_sync'
         and assignment->>'user_id' = new.id::text
         and assignment->>'office_role' = new.role
     ) then
    new.manual_role_override := true;
    new.role_assigned_at := now();
  end if;

  if new.role is not null
     and new.role not in ('Usuario', 'Usuário', 'Cidadao', 'Cidadão')
     and coalesce(new.manual_role_override, false) is true
     and new.role_assigned_at is null then
    new.role_assigned_at := now();
  end if;

  if new.role in ('Usuario', 'Usuário', 'Cidadao', 'Cidadão')
     and public.election_supersedes_manual_role(old.role, old.role_assigned_at) is true then
    new.manual_role_override := false;
    new.role_assigned_at := null;
    new.role_assigned_by := null;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."protect_manual_admin_role"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_bill_to_dou"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    author_name TEXT;
BEGIN
    IF NEW.status = 'Aprovado' AND OLD.status <> 'Aprovado' THEN
        SELECT full_name INTO author_name FROM public.profiles WHERE id = NEW.author_id;

        INSERT INTO public.dou_entries (title, summary, content, published_at, type, source_id)
        VALUES (
            NEW.title,
            'Proponente: ' || author_name,
            NEW.full_text,
            now(),
            NEW.type, -- 'PL' ou 'PEC'
            NEW.id
        );
    END IF;
    RETURN NEW;
END;
$$;


