CREATE OR REPLACE FUNCTION "public"."publish_parliament_leadership_gazette_event"("p_term_id" "uuid", "p_member_id" "uuid", "p_house_id" "uuid", "p_position" "text", "p_event" "text", "p_term_start_date" "date", "p_term_end_date" "date", "p_concluded_at" timestamp with time zone) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_house_name text;
  v_profile_name text;
  v_office_label text;
  v_source_id text;
  v_title text;
  v_summary text;
  v_content text;
begin
  if p_term_id is null or p_member_id is null or p_house_id is null or coalesce(trim(p_event), '') = '' then
    return;
  end if;

  select
    h.name,
    coalesce(p.full_name, p.username, 'Parlamentar')
  into
    v_house_name,
    v_profile_name
  from public.parliament_members pm
  join public.parliament_houses h
    on h.id = p_house_id
  left join public.profiles p
    on p.id = pm.user_id
  where pm.id = p_member_id;

  if v_house_name is null then
    return;
  end if;

  v_office_label := public.resolve_parliament_leadership_office_label(v_house_name, p_position);
  v_source_id := format('parliament-leadership-%s-%s-%s', p_event, p_term_id, p_member_id);

  if exists (
    select 1
    from public.dou_entries
    where source_id = v_source_id
  ) then
    return;
  end if;

  if p_event = 'start' then
    v_title := format('Posse em %s: %s', v_office_label, v_profile_name);
    v_summary := format('%s teve sua posse em %s oficializada no Diário Oficial.', v_profile_name, v_office_label);
    v_content := format(
      '%s passa a exercer o cargo de %s na %s. Início do mandato interno: %s.',
      v_profile_name,
      v_office_label,
      v_house_name,
      coalesce(to_char(p_term_start_date, 'DD/MM/YYYY'), 'data indefinida')
    );
  elsif p_event = 'end' then
    v_title := format('Encerramento de %s: %s', v_office_label, v_profile_name);
    v_summary := format('%s deixou o cargo de %s.', v_profile_name, v_office_label);
    v_content := format(
      '%s encerrou o exercício de %s na %s.%s',
      v_profile_name,
      v_office_label,
      v_house_name,
      case
        when p_term_end_date is not null then format(' Término registrado em %s.', to_char(p_term_end_date, 'DD/MM/YYYY'))
        when p_concluded_at is not null then format(' Encerramento registrado em %s.', to_char(p_concluded_at at time zone 'America/Sao_Paulo', 'DD/MM/YYYY HH24:MI'))
        else ''
      end
    );
  else
    return;
  end if;

  insert into public.dou_entries (
    title,
    summary,
    content,
    type,
    source_id,
    published_at
  )
  values (
    v_title,
    v_summary,
    v_content,
    'Nomeacao e Exoneracao',
    v_source_id,
    now()
  );
end;
$$;


ALTER FUNCTION "public"."publish_parliament_leadership_gazette_event"("p_term_id" "uuid", "p_member_id" "uuid", "p_house_id" "uuid", "p_position" "text", "p_event" "text", "p_term_start_date" "date", "p_term_end_date" "date", "p_concluded_at" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."publish_parliament_leadership_term_gazette"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_house_name text;
  v_profile_name text;
  v_position_label text;
  v_election_title text;
  v_start_source_id uuid := public.normalize_official_gazette_source_id(format('parliament-leadership-term-start-%s', new.id));
  v_end_source_id uuid := public.normalize_official_gazette_source_id(format('parliament-leadership-term-end-%s', new.id));
begin
  select
    h.name,
    p.full_name,
    public.resolve_parliament_leadership_position_label(h.name, new.position)
  into
    v_house_name,
    v_profile_name,
    v_position_label
  from public.parliament_houses h
  join public.parliament_members pm on pm.id = new.member_id
  join public.profiles p on p.id = pm.user_id
  where h.id = new.house_id;

  if v_profile_name is null then
    return new;
  end if;

  select election.title
  into v_election_title
  from public.parliament_leadership_elections election
  where election.id = new.elected_by_election_id;

  if new.status = 'active' then
    insert into public.dou_entries (title, summary, content, type, source_id, published_at)
    select
      format('Posse na Mesa Diretora: %s', v_profile_name),
      format('%s assumiu o posto de %s.', v_profile_name, v_position_label),
      format(
        '%s assumiu o posto de %s na %s%s Início do exercício: %s.%s',
        v_profile_name,
        v_position_label,
        coalesce(v_house_name, 'Casa Legislativa'),
        case
          when v_election_title is not null then format(', após a eleição interna "%s".', v_election_title)
          else '.'
        end,
        coalesce(to_char(new.term_start_date, 'DD/MM/YYYY'), 'data indefinida'),
        case
          when new.term_end_date is not null then format(' Término previsto: %s.', to_char(new.term_end_date, 'DD/MM/YYYY'))
          else ''
        end
      ),
      'Nomeacao e Exoneracao',
      v_start_source_id,
      coalesce(new.created_at, new.updated_at, now())
    where not exists (
      select 1
      from public.dou_entries existing_entry
      where existing_entry.source_id = v_start_source_id
    );
  end if;

  if new.status = 'concluded' or new.concluded_at is not null then
    insert into public.dou_entries (title, summary, content, type, source_id, published_at)
    select
      format('Encerramento na Mesa Diretora: %s', v_profile_name),
      format('%s deixou o posto de %s.', v_profile_name, v_position_label),
      format(
        '%s encerrou o exercício de %s na %s.%s',
        v_profile_name,
        v_position_label,
        coalesce(v_house_name, 'Casa Legislativa'),
        case
          when coalesce(new.concluded_at::text, '') <> '' then format(' Encerramento registrado em %s.', to_char(coalesce(new.concluded_at, now()), 'DD/MM/YYYY'))
          when new.term_end_date is not null then format(' Término registrado para %s.', to_char(new.term_end_date, 'DD/MM/YYYY'))
          else ''
        end
      ),
      'Nomeacao e Exoneracao',
      v_end_source_id,
      coalesce(new.concluded_at, new.updated_at, now())
    where not exists (
      select 1
      from public.dou_entries existing_entry
      where existing_entry.source_id = v_end_source_id
    );
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."publish_parliament_leadership_term_gazette"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."real_date_to_rp_date"("p_real_date" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select case
    when s.is_paused
      and s.paused_real_at is not null
      and p_real_date >= s.paused_real_at
      and s.paused_rp_at is not null
      then s.paused_rp_at
    else s.rp_epoch_game_at
      + make_interval(secs =>
          extract(epoch from (p_real_date - s.rp_epoch_real_at))
          * ((s.rp_days_per_year::numeric * 86400) / s.rp_year_real_seconds)
          * s.speed_multiplier
        )
  end
  from public.rp_time_settings s
  where s.id = true
$$;


ALTER FUNCTION "public"."real_date_to_rp_date"("p_real_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rebuild_economic_period"("p_period_id" "uuid", "p_justification" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare p public.economic_periods%rowtype;
begin
  if auth.uid() is null or not public.economic_has_role(array['Admin']) then
    raise exception 'Apenas administradores podem reconstruir períodos.' using errcode='42501';
  end if;
  if length(trim(coalesce(p_justification,'')))<20 then raise exception 'Justificativa insuficiente.'; end if;
  select * into p from public.economic_periods where id=p_period_id;
  if p.period_type='month' then return economy_private.close_month(p_period_id,true,auth.uid());
  elsif p.period_type='quarter' then return economy_private.close_quarter(p_period_id,true,auth.uid());
  elsif p.period_type='year' then return economy_private.close_year(p_period_id,true,auth.uid());
  end if;
  raise exception 'Período inválido.';
end;
$$;


ALTER FUNCTION "public"."rebuild_economic_period"("p_period_id" "uuid", "p_justification" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."record_economic_correction"("p_original_event_id" "uuid", "p_justification" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  original public.economic_events%rowtype;
  correction_id uuid;
begin
  if auth.uid() is null
     or not public.economic_has_role(array['Admin']) then
    raise exception 'Apenas a administração econômica pode corrigir eventos.'
      using errcode = '42501';
  end if;

  if length(btrim(coalesce(p_justification, ''))) < 12 then
    raise exception 'A correção exige justificativa detalhada.';
  end if;

  select * into original
  from public.economic_events
  where id = p_original_event_id;

  if not found then
    raise exception 'Evento econômico não encontrado.';
  end if;

  if exists (
    select 1
    from public.economic_events e
    where e.reverses_event_id = original.id
  ) then
    raise exception 'Este evento já possui correção.';
  end if;

  correction_id := economy_private.record_event(
    'correction_' || original.event_type,
    original.economic_classification,
    'economic_events',
    original.id::text || ':' || gen_random_uuid()::text,
    -original.nominal_amount,
    auth.uid(),
    original.business_id,
    original.government_entity_id,
    original.sector_id,
    original.quantity,
    original.unit_price,
    0,
    0,
    now(),
    public.rp_now(),
    original.is_simulated,
    original.macro_weight,
    jsonb_build_object(
      'correction_reason', p_justification,
      'original_event_id', original.id
    ),
    'correction:' || original.id::text,
    original.id
  );

  perform economy_private.audit(
    'economic_event_corrected',
    'economic_event',
    original.id::text,
    to_jsonb(original),
    jsonb_build_object('correction_event_id', correction_id),
    p_justification
  );

  return correction_id;
end;
$$;


ALTER FUNCTION "public"."record_economic_correction"("p_original_event_id" "uuid", "p_justification" "text") OWNER TO "postgres";


