    "title" "text" NOT NULL,
    "description" "text",
    "behavior_points" integer DEFAULT 0 NOT NULL,
    "sentence_credit_seconds" integer DEFAULT 0 NOT NULL,
    "registered_by" "uuid",
    "approved_by" "uuid",
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL
);


ALTER TABLE "public"."prison_events" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_prison_event"("p_prison_term_id" "uuid", "p_event_type" "text", "p_title" "text", "p_description" "text", "p_behavior_points" integer DEFAULT 0) RETURNS "public"."prison_events"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_event public.prison_events%rowtype;
begin
  if not public.justice_has_role(array[
    'Admin', 'Agente Penitenciário', 'Diretor Penitenciário'
  ]) then raise exception 'ROLE_NOT_AUTHORIZED'; end if;
  if length(trim(coalesce(p_description, ''))) < 15 then raise exception 'EVENT_DESCRIPTION_TOO_SHORT'; end if;
  if not exists (
    select 1 from public.prison_terms
    where id = p_prison_term_id
      and custody_status in ('awaiting_intake', 'provisional', 'serving')
  ) then raise exception 'ACTIVE_CUSTODY_NOT_FOUND'; end if;

  insert into public.prison_events(
    prison_term_id, event_type, title, description, behavior_points,
    sentence_credit_seconds, registered_by
  )
  values (
    p_prison_term_id, trim(p_event_type), trim(p_title), trim(p_description),
    greatest(-50, least(50, p_behavior_points)), 0, (select auth.uid())
  )
  returning * into v_event;

  update public.prison_terms
  set behavior_points = behavior_points + v_event.behavior_points
  where id = p_prison_term_id;

  perform public.justice_write_audit(
    'prison.event_registered', 'prison_term', p_prison_term_id,
    null, to_jsonb(v_event), p_description
  );
  return v_event;
end;
$$;


ALTER FUNCTION "public"."register_prison_event"("p_prison_term_id" "uuid", "p_event_type" "text", "p_title" "text", "p_description" "text", "p_behavior_points" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_candidacy"("p_candidate_id" "uuid", "p_feedback" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    candidate_info RECORD;
BEGIN
    IF get_user_role(auth.uid()) <> 'Admin' THEN
        RETURN json_build_object('success', false, 'message', 'Apenas administradores podem rejeitar candidaturas.');
    END IF;
    
    UPDATE public.candidates
    SET status = 'Rejected', admin_feedback = p_feedback
    WHERE id = p_candidate_id AND status = 'Pendente'
    RETURNING * INTO candidate_info;
    
    IF FOUND THEN
        INSERT INTO public.notifications(user_id, type, content, link)
        VALUES(candidate_info.user_id, 'candidacy_rejected', 'Sua candidatura para ' || (SELECT name FROM elections WHERE id = candidate_info.election_id) || ' foi REJEITADA. Motivo: ' || p_feedback, '/services/elections');
        RETURN json_build_object('success', true, 'message', 'Candidatura rejeitada com sucesso.');
    ELSE
        RETURN json_build_object('success', false, 'message', 'Candidatura não encontrada ou já processada.');
    END IF;
END;
$$;


ALTER FUNCTION "public"."reject_candidacy"("p_candidate_id" "uuid", "p_feedback" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reject_credit_card_application"("p_application_id" "uuid", "p_feedback" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if not public.is_national_bank_manager() then
    return jsonb_build_object('success', false, 'message', 'Apenas o Banco Nacional pode rejeitar cartões.');
  end if;

  update public.credit_card_applications
  set
    status = 'Rejeitado',
    feedback = p_feedback,
    admin_feedback = p_feedback,
    reviewed_by = auth.uid(),
    reviewed_at = now()
  where id = p_application_id
    and status in ('Pendente', 'pending');

  if not found then
    return jsonb_build_object('success', false, 'message', 'Solicitação pendente não encontrada.');
  end if;

  return jsonb_build_object('success', true, 'message', 'Solicitação de cartão rejeitada.');
end;
$$;


