CREATE OR REPLACE FUNCTION "public"."release_prisoner"("p_prison_term_id" "uuid", "p_release_reason" "text", "p_judicial_decision_id" "uuid" DEFAULT NULL::"uuid") RETURNS "public"."prison_terms"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_old public.prison_terms%rowtype;
  v_new public.prison_terms%rowtype;
begin
  if not public.justice_has_role(array[
    'Admin', 'Juiz', 'Agente Penitenciário', 'Diretor Penitenciário'
  ]) then raise exception 'ROLE_NOT_AUTHORIZED'; end if;
  if length(trim(coalesce(p_release_reason, ''))) < 15 then raise exception 'RELEASE_REASON_TOO_SHORT'; end if;

  select * into v_old from public.prison_terms where id = p_prison_term_id for update;
  if not found then raise exception 'PRISON_TERM_NOT_FOUND'; end if;
  if v_old.custody_status not in ('provisional', 'serving', 'awaiting_intake') then
    raise exception 'CUSTODY_NOT_ACTIVE';
  end if;
  if v_old.expected_release_at > now()
     and p_judicial_decision_id is null
     and not public.justice_has_role(array['Admin', 'Juiz']) then
    raise exception 'EARLY_RELEASE_REQUIRES_JUDICIAL_ORDER';
  end if;
  if p_judicial_decision_id is not null and not exists (
    select 1 from public.judicial_decisions
    where id = p_judicial_decision_id
      and result in ('release', 'acquittal', 'appeal_granted', 'bail')
  ) then raise exception 'INVALID_RELEASE_ORDER'; end if;

  update public.prison_terms
  set custody_status = 'released', actual_release_at = now(),
      release_reason = trim(p_release_reason)
  where id = p_prison_term_id
  returning * into v_new;

  if v_new.sentence_id is not null then
    update public.sentences set status = 'served', ends_at = now()
    where id = v_new.sentence_id;
  end if;
  if v_new.arrest_id is not null then
    update public.arrests set status = 'released', released_at = now(),
      release_reason = trim(p_release_reason)
    where id = v_new.arrest_id;
  end if;

  insert into public.prison_events(
    prison_term_id, event_type, title, description, registered_by, approved_by
  )
  values (
    p_prison_term_id, 'release', 'Soltura',
    trim(p_release_reason), (select auth.uid()), (select auth.uid())
  );

  perform public.justice_notify(
    v_new.inmate_id, 'justice_release_order',
    'Seu alvará de soltura foi cumprido.',
    '/services/justice?view=citizen',
    jsonb_build_object('prison_term_id', v_new.id)
  );
  perform public.justice_write_audit(
    'prison.released', 'prison_term', v_new.id,
    to_jsonb(v_old), to_jsonb(v_new), p_release_reason
  );
  return v_new;
end;
$$;


ALTER FUNCTION "public"."release_prisoner"("p_prison_term_id" "uuid", "p_release_reason" "text", "p_judicial_decision_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."remove_parliament_commission_member"("p_commission_id" "uuid", "p_member_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_house_id uuid;
  v_has_governance_access boolean;
begin
  if v_user_id is null then
    raise exception 'É necessário estar autenticado.';
  end if;

  select house_id
    into v_house_id
    from public.parliament_commission_houses
   where commission_id = p_commission_id
   limit 1;

  if v_house_id is null then
    raise exception 'Comissão não encontrada.';
  end if;

  select exists (
    select 1
      from public.parliament_commission_houses pch
     where pch.commission_id = p_commission_id
       and public.is_parliament_governance_manager(v_user_id, pch.house_id)
  )
    into v_has_governance_access;

  if not v_has_governance_access then
    raise exception 'Somente a mesa diretora pode alterar a composição da comissão.';
  end if;

  delete from public.parliament_commission_members
   where commission_id = p_commission_id
     and member_id = p_member_id;

  update public.parliament_commissions
     set reporter_member_id = null
   where id = p_commission_id
     and reporter_member_id = p_member_id;

  return jsonb_build_object(
    'success', true,
    'message', 'Membro removido da comissão.'
  );
end;
$$;


ALTER FUNCTION "public"."remove_parliament_commission_member"("p_commission_id" "uuid", "p_member_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_credit_card"("p_card_brand" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    card_count INT;
    brand_exists INT;
    user_profile RECORD;
    generated_card_number TEXT;
    generated_cvv TEXT;
    generated_expiry_date TEXT;
    card_prefix TEXT;
    expiry_years INT;
    v_closing_day INT;
    v_due_day INT;
BEGIN
    SELECT count(*) INTO card_count FROM public.cards WHERE user_id = current_user_id;
    IF card_count >= 2 THEN
        RETURN json_build_object('success', false, 'message', 'Você já atingiu o limite de 2 cartões.');
    END IF;

    SELECT count(*) INTO brand_exists FROM public.cards WHERE user_id = current_user_id AND brand = p_card_brand;
    IF brand_exists > 0 THEN
        RETURN json_build_object('success', false, 'message', 'Você já possui um cartão desta bandeira.');
    END IF;

    SELECT * INTO user_profile FROM public.profiles WHERE id = current_user_id;

    IF p_card_brand = 'mastercard' THEN
        card_prefix := (floor(random() * 5) + 51)::text;
        generated_card_number := card_prefix || lpad((floor(random() * power(10, 14)))::text, 14, '0');
    ELSE -- Default to Visa
        card_prefix := '4';
        generated_card_number := card_prefix || lpad((floor(random() * power(10, 15)))::text, 15, '0');
    END IF;

    generated_cvv := lpad((floor(random() * 999))::text, 3, '0');
    
    expiry_years := floor(random() * 3) + 3;
    generated_expiry_date := to_char(NOW() + (expiry_years || ' years')::interval, 'MM/YY');

    -- Define closing and due day with exactly 7 days difference
    v_closing_day := floor(random() * 21 + 1)::INT; -- Day between 1 and 21
    v_due_day := v_closing_day + 7;

    INSERT INTO public.cards(user_id, card_number, card_holder_name, expiry_date, cvv, type, is_active, card_limit, used_limit, brand, closing_day, due_day)
    VALUES (current_user_id, generated_card_number, user_profile.full_name, generated_expiry_date, generated_cvv, 'credit', true, 5000.00, 0, p_card_brand, v_closing_day, v_due_day);

    RETURN json_build_object('success', true, 'message', 'Cartão de crédito solicitado com sucesso!');
END;
$$;


ALTER FUNCTION "public"."request_credit_card"("p_card_brand" "text") OWNER TO "postgres";


CREATE TABLE IF NOT EXISTS "public"."judicial_requests" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "request_type" "text" NOT NULL,
    "requested_by" "uuid" NOT NULL,
    "case_id" "uuid",
    "investigation_id" "uuid",
    "target_profile_id" "uuid",
    "justification" "text" NOT NULL,
    "status" "public"."justice_request_status" DEFAULT 'pending'::"public"."justice_request_status" NOT NULL,
    "decided_by" "uuid",
    "decision_reason" "text",
    "decided_at" timestamp with time zone,
    "expires_at" timestamp with time zone,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "judicial_requests_check" CHECK ((("case_id" IS NOT NULL) OR ("investigation_id" IS NOT NULL))),
    CONSTRAINT "judicial_requests_request_type_check" CHECK (("request_type" = ANY (ARRAY['arrest_warrant'::"text", 'search_warrant'::"text", 'rp_confidentiality_break'::"text", 'preventive_detention'::"text", 'temporary_detention'::"text", 'provisional_release'::"text", 'bail'::"text", 'evidence_production'::"text", 'prison_transfer'::"text"])))
);


ALTER TABLE "public"."judicial_requests" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_judicial_warrant"("p_investigation_id" "uuid", "p_target_profile_id" "uuid", "p_warrant_type" "text", "p_justification" "text", "p_duration_rp_days" numeric DEFAULT 7) RETURNS "public"."judicial_requests"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_row public.judicial_requests%rowtype;
  v_real_seconds bigint;
begin
  if not public.justice_has_role(array['Admin', 'Policial', 'Police', 'Delegado', 'Promotor']) then
    raise exception 'ROLE_NOT_AUTHORIZED';
  end if;
  if p_warrant_type not in ('arrest_warrant', 'search_warrant') then
    raise exception 'INVALID_WARRANT_TYPE';
  end if;
  if length(trim(coalesce(p_justification, ''))) < 20 then
    raise exception 'JUSTIFICATION_TOO_SHORT';
  end if;
  if not exists (
    select 1 from public.criminal_investigations
    where id = p_investigation_id and status not in ('archived', 'closed')
  ) then raise exception 'INVESTIGATION_NOT_OPEN'; end if;

  v_real_seconds := public.rp_duration_to_real_seconds(p_duration_rp_days, 'day');

  insert into public.judicial_requests(
    request_type, requested_by, investigation_id, target_profile_id,
    justification, expires_at
  )
  values (
    p_warrant_type, (select auth.uid()), p_investigation_id, p_target_profile_id,
    trim(p_justification), now() + make_interval(secs => v_real_seconds)
  )
  returning * into v_row;

  perform public.justice_write_audit(
    'judicial_request.created', 'judicial_request', v_row.id,
    null, to_jsonb(v_row), p_justification
  );

  return v_row;
end;
$$;


ALTER FUNCTION "public"."request_judicial_warrant"("p_investigation_id" "uuid", "p_target_profile_id" "uuid", "p_warrant_type" "text", "p_justification" "text", "p_duration_rp_days" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_party_affiliation"("p_party_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
    DECLARE
        current_user_id UUID := auth.uid();
        party_info RECORD;
        current_affiliation RECORD;
        member_name TEXT;
    BEGIN
        SELECT * INTO party_info FROM public.political_parties WHERE id = p_party_id;
        IF party_info IS NULL THEN
            RETURN json_build_object('success', false, 'message', 'Partido não encontrado.');
        END IF;

        SELECT * INTO current_affiliation FROM public.party_members WHERE user_id = current_user_id;
        IF current_affiliation IS NOT NULL AND current_affiliation.party_id = p_party_id THEN
            RETURN json_build_object('success', false, 'message', 'Você já é membro deste partido.');
        END IF;

        IF party_info.affiliation_mode = 'automatic' THEN
            IF current_affiliation IS NOT NULL THEN
                DELETE FROM public.party_members WHERE user_id = current_user_id;
            END IF;

            INSERT INTO public.party_members (party_id, user_id, role)
            VALUES (p_party_id, current_user_id, 'Membro');
            
            -- Gravando o ID do partido (uuid) em vez do nome
            UPDATE public.profiles SET party_affiliation = p_party_id WHERE id = current_user_id;
            
            -- Notify other members
            SELECT full_name INTO member_name FROM public.profiles WHERE id = current_user_id;
            INSERT INTO public.notifications (user_id, type, content, link)
            SELECT pm.user_id, 'party_member_joined', member_name || ' entrou para o partido ' || party_info.name || '.', '/services/political-parties/' || p_party_id
            FROM public.party_members pm WHERE pm.party_id = p_party_id AND pm.user_id <> current_user_id;

            RETURN json_build_object('success', true, 'message', 'Filiação automática realizada com sucesso!');
        END IF;

        IF party_info.affiliation_mode = 'manual' THEN
            IF EXISTS (SELECT 1 FROM public.party_affiliation_requests WHERE user_id = current_user_id AND party_id = p_party_id AND status = 'pending') THEN
                RETURN json_build_object('success', false, 'message', 'Você já tem uma solicitação pendente para este partido.');
            END IF;

            INSERT INTO public.party_affiliation_requests (user_id, party_id, status)
            VALUES (current_user_id, p_party_id, 'pending');
            
            -- Notify leaders
            INSERT INTO public.notifications (user_id, sender_id, type, content, link)
            SELECT pm.user_id, current_user_id, 'affiliation_request', 'Novo pedido de filiação para ' || party_info.name, '/services/political-parties/' || p_party_id
            FROM public.party_members pm WHERE pm.party_id = p_party_id AND pm.role IN ('Dono', 'Presidente', 'Vice-Presidente');

            RETURN json_build_object('success', true, 'message', 'Sua solicitação de filiação foi enviada para aprovação.');
        END IF;
        
        RETURN json_build_object('success', false, 'message', 'Modo de filiação desconhecido.');
    END;
    $$;


ALTER FUNCTION "public"."request_party_affiliation"("p_party_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_plebiscite"("p_title" "text", "p_description" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
