    FROM public.profiles
    WHERE id = current_user_id;

    INSERT INTO public.plebiscites (title, description, status, author_id, author_name, author_avatar_url)
    VALUES (p_title, p_description, 'Pendente', current_user_id, v_author_name, v_author_avatar_url)
    RETURNING id INTO new_plebiscite_id;

    RETURN json_build_object('success', true, 'message', 'Sua solicitação de plebiscito foi enviada para análise.', 'plebiscite_id', new_plebiscite_id);
END;
