CREATE OR REPLACE FUNCTION "public"."request_prison_visit"("p_prison_term_id" "uuid") RETURNS "public"."prison_visits"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_term public.prison_terms%rowtype;
  v_visit public.prison_visits%rowtype;
begin
  if (select auth.uid()) is null then raise exception 'AUTHENTICATION_REQUIRED'; end if;
  select * into v_term from public.prison_terms
  where id = p_prison_term_id
    and custody_status in ('provisional', 'serving');
  if not found then raise exception 'ACTIVE_CUSTODY_NOT_FOUND'; end if;
  if v_term.inmate_id = (select auth.uid()) then raise exception 'INMATE_CANNOT_VISIT_SELF'; end if;
  if exists (
    select 1 from public.prison_visits
    where prison_term_id = p_prison_term_id
      and visitor_id = (select auth.uid())
      and status in ('pending', 'approved')
  ) then raise exception 'VISIT_REQUEST_ALREADY_EXISTS'; end if;

  insert into public.prison_visits(
    prison_term_id, inmate_id, visitor_id
  )
  values (p_prison_term_id, v_term.inmate_id, (select auth.uid()))
  returning * into v_visit;

  perform public.justice_notify(
    v_term.inmate_id, 'justice_prison_visit_requested',
    'Uma nova visita foi solicitada.',
    '/services/prison',
    jsonb_build_object('visit_id', v_visit.id)
  );
  return v_visit;
end;
$$;


ALTER FUNCTION "public"."request_prison_visit"("p_prison_term_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resell_product"("p_inventory_id" "uuid", "p_price" numeric) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    inventory_item RECORD;
    original_product RECORD;
    total_usage_interval INTERVAL;
    new_product_id UUID;
BEGIN
    SELECT * INTO inventory_item FROM public.user_inventory WHERE id = p_inventory_id AND user_id = current_user_id;

    IF inventory_item IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Item não encontrado no seu inventário.');
    END IF;

    SELECT * INTO original_product FROM public.products WHERE id = inventory_item.product_id;

    -- Calculate usage time
    SELECT sum(COALESCE(end_date, now()) - start_date)
    INTO total_usage_interval
    FROM public.product_ownership_history
    WHERE inventory_item_id = p_inventory_id;
    
    total_usage_interval := COALESCE(total_usage_interval, interval '0 seconds') + (now() - (SELECT start_date FROM product_ownership_history WHERE inventory_item_id = p_inventory_id AND end_date IS NULL));

    INSERT INTO public.products (seller_id, name, description, price, image_url, product_type, metadata)
    VALUES (
        current_user_id,
        original_product.name || ' (Usado)',
        original_product.description,
        p_price,
        original_product.image_url,
        'one-time',
        jsonb_build_object(
            'condition', 'used',
            'usage_time_seconds', EXTRACT(EPOCH FROM total_usage_interval),
            'original_product_id', original_product.id
        )
    ) RETURNING id INTO new_product_id;
    
    -- Mark old ownership as ended
    UPDATE public.product_ownership_history SET end_date = now() WHERE inventory_item_id = p_inventory_id AND end_date IS NULL;
    
    -- Remove item from inventory
    DELETE FROM public.user_inventory WHERE id = p_inventory_id;

    RETURN json_build_object('success', true, 'message', 'Produto listado para revenda com sucesso!', 'new_product_id', new_product_id);
END;
$$;


ALTER FUNCTION "public"."resell_product"("p_inventory_id" "uuid", "p_price" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resign_presidency"() RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    president_id UUID := auth.uid();
    minister_record RECORD;
BEGIN
    -- Check if the current user is indeed the President
    IF (SELECT role FROM public.profiles WHERE id = president_id) <> 'Presidente' THEN
        RETURN json_build_object('success', false, 'message', 'Apenas o Presidente pode renunciar ao cargo.');
    END IF;

    -- Demote all ministers appointed by this government to 'Cidadão'
    FOR minister_record IN 
        SELECT user_id FROM public.ministers
    LOOP
        UPDATE public.profiles SET role = 'Cidadão' WHERE id = minister_record.user_id;
    END LOOP;
    
    -- Delete all minister records
    DELETE FROM public.ministers;

    -- Demote the president to 'Cidadão'
    UPDATE public.profiles SET role = 'Cidadão' WHERE id = president_id;

    RETURN json_build_object('success', true, 'message', 'Você renunciou ao cargo de Presidente. Todos os ministros foram exonerados.');
EXCEPTION
    WHEN others THEN
        RETURN json_build_object('success', false, 'message', 'Ocorreu um erro inesperado durante a renúncia.');
END;
$$;


ALTER FUNCTION "public"."resign_presidency"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_parliament_leadership_office_label"("p_house_name" "text", "p_position" "text") RETURNS "text"
    LANGUAGE "sql" IMMUTABLE
    AS $$
  select case
    when p_position = 'president' and coalesce(p_house_name, '') ilike '%senado%'
      then 'Presidente do Senado'
    when p_position = 'president'
      then 'Presidente da Câmara dos Deputados'
    when p_position = 'vice_president' and coalesce(p_house_name, '') ilike '%senado%'
      then 'Vice-Presidente do Senado Federal'
    when p_position = 'vice_president'
      then 'Vice-Presidente da Câmara dos Deputados'
    else coalesce(nullif(trim(p_position), ''), 'Cargo parlamentar')
  end;
$$;


ALTER FUNCTION "public"."resolve_parliament_leadership_office_label"("p_house_name" "text", "p_position" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_parliament_leadership_position_label"("p_house_name" "text", "p_position" "text") RETURNS "text"
    LANGUAGE "sql" STABLE
    AS $$
  select case
    when p_position = 'president' then
      case
        when coalesce(p_house_name, '') ilike '%senado%' then 'Presidente do Senado'
        else 'Presidente da Câmara dos Deputados'
      end
    when p_position = 'vice_president' then
      case
        when coalesce(p_house_name, '') ilike '%senado%' then 'Vice-Presidente do Senado Federal'
        else 'Vice-Presidente da Câmara dos Deputados'
      end
    else coalesce(nullif(p_position, ''), 'Cargo da Mesa Diretora')
  end;
$$;


