CREATE OR REPLACE FUNCTION "public"."respond_to_affiliation_request"("p_request_id" "uuid", "p_is_approved" boolean) RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
    DECLARE
        request_info record;
        leader_id uuid := auth.uid();
        party_rec RECORD;
        member_name TEXT;
    BEGIN
        SELECT * INTO request_info FROM public.party_affiliation_requests WHERE id = p_request_id;
        SELECT * INTO party_rec FROM public.political_parties WHERE id = request_info.party_id;

        IF NOT (leader_id = party_rec.owner_id OR leader_id = party_rec.president_id OR leader_id = party_rec.vice_president_id) THEN
            RETURN json_build_object('success', false, 'message', 'Você não tem permissão para gerenciar este pedido.');
        END IF;

        IF p_is_approved THEN
            INSERT INTO public.party_members (party_id, user_id, role)
            VALUES (request_info.party_id, request_info.user_id, 'Membro');
            
            UPDATE public.party_affiliation_requests SET status = 'approved' WHERE id = p_request_id;

            -- Notify all other members
            SELECT full_name INTO member_name FROM public.profiles WHERE id = request_info.user_id;
            INSERT INTO public.notifications (user_id, type, content, link)
            SELECT pm.user_id, 'party_member_joined', member_name || ' entrou para o partido ' || party_rec.name || '.', '/services/political-parties/' || request_info.party_id
            FROM public.party_members pm WHERE pm.party_id = request_info.party_id AND pm.user_id <> request_info.user_id;

            RETURN json_build_object('success', true, 'message', 'Membro aprovado com sucesso.');
        ELSE
            UPDATE public.party_affiliation_requests SET status = 'rejected' WHERE id = p_request_id;
            RETURN json_build_object('success', true, 'message', 'Pedido de filiação rejeitado.');
        END IF;
    END;
    $$;


ALTER FUNCTION "public"."respond_to_affiliation_request"("p_request_id" "uuid", "p_is_approved" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rp_date_to_real_date"("p_rp_date" timestamp with time zone) RETURNS timestamp with time zone
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select s.rp_epoch_real_at
    + make_interval(secs =>
        extract(epoch from (p_rp_date - s.rp_epoch_game_at))
        / (
          ((s.rp_days_per_year::numeric * 86400) / s.rp_year_real_seconds)
          * s.speed_multiplier
        )
      )
  from public.rp_time_settings s
  where s.id = true
$$;


ALTER FUNCTION "public"."rp_date_to_real_date"("p_rp_date" timestamp with time zone) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rp_duration_to_real_seconds"("p_amount" numeric, "p_unit" "text") RETURNS bigint
    LANGUAGE "sql" STABLE
    SET "search_path" TO ''
    AS $$
  select greatest(
    1,
    round(
      (
        case lower(p_unit)
          when 'hour' then p_amount * 3600
          when 'day' then p_amount * 86400
          when 'week' then p_amount * 604800
          when 'month' then p_amount * ((s.rp_days_per_year::numeric / 12) * 86400)
          when 'year' then p_amount * (s.rp_days_per_year::numeric * 86400)
          else p_amount
        end
      ) / (
        ((s.rp_days_per_year::numeric * 86400) / s.rp_year_real_seconds)
        * s.speed_multiplier
      )
    )
  )::bigint
  from public.rp_time_settings s
  where s.id = true
$$;


ALTER FUNCTION "public"."rp_duration_to_real_seconds"("p_amount" numeric, "p_unit" "text") OWNER TO "postgres";


