CREATE OR REPLACE FUNCTION "public"."seal_case_evidence"("p_evidence_id" "uuid", "p_justification" "text") RETURNS "public"."case_evidence"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_old public.case_evidence%rowtype;
  v_new public.case_evidence%rowtype;
  v_hash text;
begin
  if not public.justice_has_role(array[
    'Admin', 'Policial', 'Police', 'Delegado', 'Promotor', 'Juiz', 'Perito'
  ]) then raise exception 'ROLE_NOT_AUTHORIZED'; end if;
  if nullif(trim(p_justification), '') is null then raise exception 'JUSTIFICATION_REQUIRED'; end if;

  select * into v_old from public.case_evidence where id = p_evidence_id for update;
  if not found then raise exception 'EVIDENCE_NOT_FOUND'; end if;
  if v_old.status = 'sealed' then raise exception 'EVIDENCE_ALREADY_SEALED'; end if;

  v_hash := encode(
    extensions.digest(
      coalesce(v_old.file_url, '') || '|' || coalesce(v_old.description, '')
      || '|' || v_old.id::text || '|' || v_old.version::text,
      'sha256'
    ),
    'hex'
  );

  update public.case_evidence
  set status = 'sealed', sealed_at = now(), evidence_hash = v_hash
  where id = p_evidence_id
  returning * into v_new;

  insert into public.evidence_custody_events(
    evidence_id, event_type, actor_id, justification
  )
  values (p_evidence_id, 'sealed', (select auth.uid()), trim(p_justification));

  perform public.justice_write_audit(
    'evidence.sealed', 'case_evidence', p_evidence_id,
    to_jsonb(v_old), to_jsonb(v_new), p_justification
  );

  return v_new;
end;
$$;


ALTER FUNCTION "public"."seal_case_evidence"("p_evidence_id" "uuid", "p_justification" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."search_x"("p_query_text" "text") RETURNS json
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    users_result json;
    posts_result json;
BEGIN
    SELECT json_agg(u) INTO users_result FROM (
        SELECT id, x_username, x_handle, avatar_url, x_bio
        FROM public.profiles
        WHERE x_handle IS NOT NULL AND (x_handle ILIKE '%' || p_query_text || '%' OR x_username ILIKE '%' || p_query_text || '%')
        LIMIT 10
    ) u;

    SELECT json_agg(p) INTO posts_result FROM (
        SELECT
            p.id, p.user_id, p.content, p.created_at, p.likes_count, p.comments_count, p.views_count, p.reposts_count, p.image_url,
            json_build_object(
              'id', author.id,
              'username', author.username,
              'full_name', author.full_name,
              'avatar_url', author.avatar_url,
              'x_username', author.x_username,
              'x_handle', author.x_handle
            ) as author,
            EXISTS(SELECT 1 FROM public.likes l WHERE l.post_id = p.id AND l.user_id = auth.uid()) as is_liked_by_user,
            EXISTS(SELECT 1 FROM public.reposts r WHERE r.post_id = p.id AND r.user_id = auth.uid()) as is_reposted_by_user
        FROM public.posts p
        JOIN public.profiles author ON p.user_id = author.id
        WHERE p.parent_post_id IS NULL AND p.content ILIKE '%' || p_query_text || '%'
        ORDER BY p.created_at DESC
        LIMIT 20
    ) p;

    RETURN json_build_object('users', COALESCE(users_result, '[]'::json), 'posts', COALESCE(posts_result, '[]'::json));
END;
$$;


ALTER FUNCTION "public"."search_x"("p_query_text" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_x_message"("p_recipient_id" "uuid", "p_content" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    v_conversation_id UUID;
    sender_x_handle TEXT;
    recipient_exists BOOLEAN;
BEGIN
    IF current_user_id = p_recipient_id THEN
        RETURN json_build_object('success', false, 'message', 'Você não pode enviar uma mensagem para si mesmo.');
    END IF;
    
    SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id = p_recipient_id AND x_handle IS NOT NULL) INTO recipient_exists;
    IF NOT recipient_exists THEN
        RETURN json_build_object('success', false, 'message', 'Participante não encontrado ou não possui perfil no X.');
    END IF;

    SELECT cp1.conversation_id INTO v_conversation_id
    FROM x_conversation_participants cp1
    JOIN x_conversation_participants cp2 ON cp1.conversation_id = cp2.conversation_id
    WHERE cp1.user_id = current_user_id AND cp2.user_id = p_recipient_id;

    IF v_conversation_id IS NULL THEN
        INSERT INTO public.x_conversations DEFAULT VALUES RETURNING id INTO v_conversation_id;
        INSERT INTO public.x_conversation_participants (conversation_id, user_id) VALUES (v_conversation_id, current_user_id);
        INSERT INTO public.x_conversation_participants (conversation_id, user_id) VALUES (v_conversation_id, p_recipient_id);
    END IF;

    INSERT INTO public.x_messages (conversation_id, sender_id, content)
    VALUES (v_conversation_id, current_user_id, p_content);
    
    SELECT x_handle INTO sender_x_handle FROM public.profiles WHERE id = current_user_id;
    INSERT INTO public.notifications (user_id, sender_id, type, content, link)
    VALUES (p_recipient_id, current_user_id, 'x_dm', 'enviou uma nova mensagem.', '/services/x/messages/' || v_conversation_id::text);

    RETURN json_build_object('success', true, 'message', 'Mensagem enviada.', 'conversation_id', v_conversation_id);
END;
$$;


ALTER FUNCTION "public"."send_x_message"("p_recipient_id" "uuid", "p_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_credit_card_limit"("p_card_id" "uuid", "p_card_limit" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  card_record public.cards%rowtype;
  next_limit numeric := greatest(0, coalesce(p_card_limit, 0));
begin
  if not public.is_national_bank_manager() then
    return jsonb_build_object('success', false, 'message', 'Apenas o Banco Nacional pode alterar limites.');
  end if;

  select * into card_record
  from public.cards
  where id = p_card_id
  for update;

  if not found then
    return jsonb_build_object('success', false, 'message', 'Cartão não encontrado.');
  end if;

  if next_limit < coalesce(card_record.used_limit, 0) then
    return jsonb_build_object('success', false, 'message', 'O limite não pode ser menor que o valor já utilizado.');
  end if;

  update public.cards
  set card_limit = next_limit
  where id = p_card_id;

  return jsonb_build_object('success', true, 'message', 'Limite do cartão atualizado.');
end;
$$;


ALTER FUNCTION "public"."set_credit_card_limit"("p_card_id" "uuid", "p_card_limit" numeric) OWNER TO "postgres";


