CREATE TABLE IF NOT EXISTS "public"."rp_time_settings" (
    "id" boolean DEFAULT true NOT NULL,
    "rp_year_real_seconds" bigint DEFAULT 604800 NOT NULL,
    "rp_days_per_year" integer DEFAULT 365 NOT NULL,
    "rp_epoch_real_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "rp_epoch_game_at" timestamp with time zone DEFAULT '2025-12-31 21:00:00-03'::timestamp with time zone NOT NULL,
    "speed_multiplier" numeric(10,4) DEFAULT 1 NOT NULL,
    "is_paused" boolean DEFAULT false NOT NULL,
    "paused_real_at" timestamp with time zone,
    "paused_rp_at" timestamp with time zone,
    "penal_time_multiplier" numeric(10,4) DEFAULT 1 NOT NULL,
    "updated_by" "uuid",
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "rp_time_settings_id_check" CHECK ("id"),
    CONSTRAINT "rp_time_settings_penal_time_multiplier_check" CHECK (("penal_time_multiplier" > (0)::numeric)),
    CONSTRAINT "rp_time_settings_rp_days_per_year_check" CHECK ((("rp_days_per_year" >= 1) AND ("rp_days_per_year" <= 1000))),
    CONSTRAINT "rp_time_settings_rp_year_real_seconds_check" CHECK (("rp_year_real_seconds" > 0)),
    CONSTRAINT "rp_time_settings_speed_multiplier_check" CHECK (("speed_multiplier" > (0)::numeric))
);


ALTER TABLE "public"."rp_time_settings" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."set_rp_clock_state"("p_action" "text", "p_speed_multiplier" numeric DEFAULT NULL::numeric, "p_justification" "text" DEFAULT NULL::"text") RETURNS "public"."rp_time_settings"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_old public.rp_time_settings%rowtype;
  v_new public.rp_time_settings%rowtype;
  v_rp_now timestamptz;
begin
  if not public.justice_has_role(array['Admin']) then raise exception 'ROLE_NOT_AUTHORIZED'; end if;
  if length(trim(coalesce(p_justification, ''))) < 15 then raise exception 'JUSTIFICATION_TOO_SHORT'; end if;

  select * into v_old from public.rp_time_settings where id = true for update;
  v_rp_now := public.rp_now();

  if p_action = 'pause' then
    if v_old.is_paused then raise exception 'RP_CLOCK_ALREADY_PAUSED'; end if;
    update public.rp_time_settings
    set is_paused = true, paused_real_at = now(), paused_rp_at = v_rp_now,
        updated_by = (select auth.uid())
    where id = true returning * into v_new;
  elsif p_action = 'resume' then
    if not v_old.is_paused then raise exception 'RP_CLOCK_NOT_PAUSED'; end if;
    update public.rp_time_settings
    set is_paused = false, rp_epoch_real_at = now(),
        rp_epoch_game_at = coalesce(paused_rp_at, v_rp_now),
        paused_real_at = null, paused_rp_at = null,
        updated_by = (select auth.uid())
    where id = true returning * into v_new;
  elsif p_action = 'speed' then
    if p_speed_multiplier is null or p_speed_multiplier <= 0 or p_speed_multiplier > 20 then
      raise exception 'INVALID_RP_CLOCK_SPEED';
    end if;
    update public.rp_time_settings
    set rp_epoch_real_at = now(), rp_epoch_game_at = v_rp_now,
        speed_multiplier = p_speed_multiplier,
        paused_rp_at = case when is_paused then v_rp_now else null end,
        updated_by = (select auth.uid())
    where id = true returning * into v_new;
  else
    raise exception 'INVALID_RP_CLOCK_ACTION';
  end if;

  perform public.justice_write_audit(
    'rp_clock.' || p_action, 'rp_time_settings', null,
    to_jsonb(v_old), to_jsonb(v_new), p_justification
  );
  return v_new;
end;
$$;


ALTER FUNCTION "public"."set_rp_clock_state"("p_action" "text", "p_speed_multiplier" numeric, "p_justification" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sign_parliament_commission"("p_commission_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_commission record;
  v_house record;
  v_member_id uuid;
  v_support_count integer;
  v_required_count integer;
  v_ready boolean := true;
begin
  if v_user_id is null then
    raise exception 'É necessário estar autenticado para assinar requerimento.';
  end if;

  select *
    into v_commission
    from public.parliament_commissions
   where id = p_commission_id;

  if not found then
    raise exception 'Comissão não encontrada.';
  end if;

  if v_commission.type not in ('cpi', 'cpmi') then
    raise exception 'Somente CPI e CPMI admitem apoio por requerimento.';
  end if;

  if v_commission.status not in ('collecting_support', 'active') then
    raise exception 'Esta comissão não está aberta para coleta de apoios.';
  end if;

  for v_house in
    select house_id
      from public.parliament_commission_houses
     where commission_id = p_commission_id
  loop
    v_member_id := public.get_active_parliament_member_id(v_user_id, v_house.house_id);
    if v_member_id is not null then
      insert into public.parliament_commission_supports (commission_id, member_id)
      values (p_commission_id, v_member_id)
      on conflict do nothing;
    end if;
  end loop;

  if not exists (
    select 1
      from public.parliament_commission_supports pcs
      join public.parliament_members pm
        on pm.id = pcs.member_id
      join public.parliament_commission_houses pch
        on pch.commission_id = pcs.commission_id
       and pch.house_id = pm.house_id
     where pcs.commission_id = p_commission_id
       and pm.user_id = v_user_id
  ) then
    raise exception 'Você não possui mandato ativo em nenhuma das Casas desta comissão.';
  end if;

  for v_house in
    select house_id
      from public.parliament_commission_houses
     where commission_id = p_commission_id
  loop
    select count(*)
      into v_support_count
      from public.parliament_commission_supports pcs
      join public.parliament_members pm
        on pm.id = pcs.member_id
     where pcs.commission_id = p_commission_id
       and pm.house_id = v_house.house_id
       and pm.term_end_date >= current_date;

    v_required_count := public.get_parliament_house_member_threshold(v_house.house_id);

    if v_support_count < v_required_count then
      v_ready := false;
    end if;
  end loop;

  if v_ready then
    update public.parliament_commissions
       set status = 'active',
           opened_at = coalesce(opened_at, now())
     where id = p_commission_id
       and status <> 'active';
  end if;

  return jsonb_build_object(
    'success', true,
    'commission_id', p_commission_id,
    'activated', v_ready,
    'message', case
      when v_ready then 'Quórum de requerimento alcançado. A comissão foi instalada.'
      else 'Apoio registrado com sucesso.'
    end
  );
end;
$$;


ALTER FUNCTION "public"."sign_parliament_commission"("p_commission_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."simulate_economic_policy"("p_policy_type" "text", "p_new_value" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null then
    raise exception 'Autenticação obrigatória.' using errcode='42501';
  end if;
  if p_policy_type not in (
    'selic','inflation_target','consumption_tax','corporate_tax','income_tax',
    'payroll_tax','minimum_wage','public_spending','subsidy',
    'reserve_requirement','exchange_intervention','debt_limit','emergency_rule'
  ) then
    raise exception 'Política econômica inválida.';
  end if;
  if p_new_value is null or p_new_value::text in ('NaN','Infinity','-Infinity')
     or abs(p_new_value)>1000000000000 then
    raise exception 'Valor de simulação inválido.';
  end if;
  return economy_private.forecast_policy(p_policy_type,p_new_value,auth.uid());
end;
$$;


ALTER FUNCTION "public"."simulate_economic_policy"("p_policy_type" "text", "p_new_value" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."start_prison_activity"("p_activity_id" "uuid") RETURNS "public"."prison_activity_runs"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_term public.prison_terms%rowtype;
  v_activity public.prison_activities%rowtype;
  v_run public.prison_activity_runs%rowtype;
begin
  if (select auth.uid()) is null then raise exception 'AUTHENTICATION_REQUIRED'; end if;

  select * into v_term from public.prison_terms
  where inmate_id = (select auth.uid())
    and custody_status in ('provisional', 'serving')
  order by admitted_at desc limit 1;
  if not found then raise exception 'ACTIVE_CUSTODY_NOT_FOUND'; end if;

  select * into v_activity from public.prison_activities
  where id = p_activity_id and is_active;
  if not found then raise exception 'ACTIVITY_NOT_AVAILABLE'; end if;
  if exists (
    select 1 from public.prison_activity_runs
    where inmate_id = (select auth.uid()) and status = 'in_progress'
  ) then raise exception 'ANOTHER_ACTIVITY_IS_RUNNING'; end if;
  if exists (
    select 1 from public.prison_activity_runs r
    where r.inmate_id = (select auth.uid())
      and r.activity_id = p_activity_id
      and r.started_at > now() - make_interval(secs => v_activity.cooldown_seconds)
  ) then raise exception 'ACTIVITY_COOLDOWN_ACTIVE'; end if;

  insert into public.prison_activity_runs(
    prison_term_id, activity_id, inmate_id, completes_at
  )
  values (
    v_term.id, v_activity.id, (select auth.uid()),
    now() + make_interval(secs => v_activity.duration_seconds)
  )
  returning * into v_run;

  return v_run;
end;
$$;


ALTER FUNCTION "public"."start_prison_activity"("p_activity_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_bill_suggestion"("p_title" "text", "p_suggestion" "text", "p_target_type" "text", "p_target_id" "uuid") RETURNS json
