ALTER FUNCTION "public"."submit_bill_suggestion"("p_title" "text", "p_suggestion" "text", "p_target_type" "text", "p_target_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_candidacy"("p_election_id" "uuid", "p_party_id" "uuid", "p_vice_candidate_id" "uuid", "p_political_name" "text", "p_bio" "text", "p_proposals" "text", "p_campaign_photo_url" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  requester_id uuid := auth.uid();
  election_record record;
  requires_vice boolean := false;
  active_conflict_count integer := 0;
begin
  if requester_id is null then
    return jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  end if;

  select
    e.id,
    e.name,
    e.status,
    e.voting_end_date,
    et.name as election_type_name,
    coalesce(et.requires_vice_candidate, false) as requires_vice_candidate
  into election_record
  from public.elections e
  left join public.election_types et on et.id = e.election_type_id
  where e.id = p_election_id;

  if election_record.id is null then
    return jsonb_build_object('success', false, 'message', 'Eleição não encontrada.');
  end if;

  if election_record.status <> 'Candidacy' then
    return jsonb_build_object('success', false, 'message', 'A janela de candidaturas desta eleição não está aberta.');
  end if;

  requires_vice :=
    election_record.requires_vice_candidate
    or lower(coalesce(election_record.election_type_name, '')) = 'presidente'
    or lower(coalesce(election_record.name, '')) like '%presidencial%';

  if requires_vice and p_vice_candidate_id is null then
    return jsonb_build_object('success', false, 'message', 'Candidaturas presidenciais exigem vice aceito.');
  end if;

  if p_vice_candidate_id = requester_id then
    return jsonb_build_object('success', false, 'message', 'O candidato não pode ser o próprio vice.');
  end if;

  select count(*) into active_conflict_count
  from public.candidates c
  join public.elections e on e.id = c.election_id
  where c.status in ('Pendente', 'Approved')
    and c.user_id = requester_id
    and (
      lower(coalesce(e.status, '')) in ('scheduled', 'candidacy', 'voting')
      or (e.voting_end_date is not null and e.voting_end_date > now())
    );

  if active_conflict_count > 0 then
    return jsonb_build_object('success', false, 'message', 'Você já possui uma candidatura ativa no momento.');
  end if;

  select count(*) into active_conflict_count
  from public.candidates c
  where c.election_id = p_election_id
    and c.status in ('Pendente', 'Approved')
    and (
      c.user_id = requester_id
      or c.vice_candidate_id = requester_id
      or (p_vice_candidate_id is not null and c.user_id = p_vice_candidate_id)
      or (p_vice_candidate_id is not null and c.vice_candidate_id = p_vice_candidate_id)
    );

  if active_conflict_count > 0 then
    return jsonb_build_object('success', false, 'message', 'Um dos participantes já está vinculado a uma candidatura nesta eleição.');
  end if;

  insert into public.candidates (
    election_id,
    user_id,
    party_id,
    vice_candidate_id,
    political_name,
    bio,
    proposals,
    campaign_photo_url,
    status
  )
  values (
    p_election_id,
    requester_id,
    p_party_id,
    p_vice_candidate_id,
    nullif(trim(coalesce(p_political_name, '')), ''),
    nullif(trim(coalesce(p_bio, '')), ''),
    nullif(trim(coalesce(p_proposals, '')), ''),
    nullif(trim(coalesce(p_campaign_photo_url, '')), ''),
    'Pendente'
  );

  return jsonb_build_object('success', true, 'message', 'Candidatura enviada para análise.');
end;
$$;


ALTER FUNCTION "public"."submit_candidacy"("p_election_id" "uuid", "p_party_id" "uuid", "p_vice_candidate_id" "uuid", "p_political_name" "text", "p_bio" "text", "p_proposals" "text", "p_campaign_photo_url" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_investigation_to_prosecutor"("p_investigation_id" "uuid", "p_conclusion" "text", "p_recommended_action" "text") RETURNS "public"."criminal_investigations"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_old public.criminal_investigations%rowtype;
  v_new public.criminal_investigations%rowtype;
begin
  if not public.justice_has_role(array['Admin', 'Delegado']) then
    raise exception 'ROLE_NOT_AUTHORIZED';
  end if;
  if length(trim(coalesce(p_conclusion, ''))) < 40 then raise exception 'CONCLUSION_TOO_SHORT'; end if;
  if not exists (
    select 1 from public.investigation_parties
    where investigation_id = p_investigation_id and party_type = 'suspect'
  ) then raise exception 'INVESTIGATION_REQUIRES_SUSPECT'; end if;
  if not exists (
    select 1 from public.case_evidence
    where investigation_id = p_investigation_id and status = 'sealed'
  ) then raise exception 'INVESTIGATION_REQUIRES_SEALED_EVIDENCE'; end if;

  select * into v_old from public.criminal_investigations
  where id = p_investigation_id for update;
  if not found then raise exception 'INVESTIGATION_NOT_FOUND'; end if;

  update public.criminal_investigations
  set status = 'sent_to_prosecutor', conclusion = trim(p_conclusion),
      recommended_action = trim(p_recommended_action)
  where id = p_investigation_id
  returning * into v_new;

  perform public.justice_write_audit(
    'investigation.sent_to_prosecutor', 'criminal_investigation', p_investigation_id,
    to_jsonb(v_old), to_jsonb(v_new), p_conclusion
  );

  return v_new;
end;
$$;


ALTER FUNCTION "public"."submit_investigation_to_prosecutor"("p_investigation_id" "uuid", "p_conclusion" "text", "p_recommended_action" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."submit_parliament_commission_report"("p_commission_id" "uuid", "p_report" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_commission record;
  v_house_id uuid;
  v_reporter_user_id uuid;
  v_has_governance_access boolean;
begin
  if v_user_id is null then
    raise exception 'É necessário estar autenticado.';
  end if;

  if p_report is null or btrim(p_report) = '' then
    raise exception 'O relatório final não pode ficar em branco.';
  end if;

  select pc.*, pch.house_id
    into v_commission
    from public.parliament_commissions pc
    join public.parliament_commission_houses pch
      on pch.commission_id = pc.id
   where pc.id = p_commission_id
   limit 1;

  if not found then
    raise exception 'Comissão não encontrada.';
  end if;

  v_house_id := v_commission.house_id;

  if v_commission.type in ('cpi', 'cpmi') and v_commission.reporter_member_id is null then
    raise exception 'Esta comissão de inquérito ainda não possui relator designado.';
  end if;

  select pm.user_id
    into v_reporter_user_id
    from public.parliament_members pm
   where pm.id = v_commission.reporter_member_id;

  select exists (
    select 1
      from public.parliament_commission_houses pch
     where pch.commission_id = p_commission_id
       and public.is_parliament_governance_manager(v_user_id, pch.house_id)
  )
    into v_has_governance_access;

  if v_user_id <> v_reporter_user_id and not v_has_governance_access then
    raise exception 'Somente o relator ou a mesa diretora podem protocolar o relatório final.';
  end if;

  update public.parliament_commissions
     set final_report = btrim(p_report),
         final_report_submitted_at = now()
   where id = p_commission_id;

  return jsonb_build_object(
    'success', true,
    'message', 'Relatório final protocolado com sucesso.'
  );
end;
$$;


ALTER FUNCTION "public"."submit_parliament_commission_report"("p_commission_id" "uuid", "p_report" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_legacy_prison_profile_state"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_active public.prison_terms%rowtype;
begin
  select * into v_active
  from public.prison_terms
  where inmate_id = new.inmate_id
    and custody_status in ('awaiting_intake', 'provisional', 'serving')
  order by admitted_at desc limit 1;

  update public.profiles
  set
    is_imprisoned = found,
    release_date = case when found then v_active.expected_release_at else null end,
    criminal_status = case
      when found and v_active.custody_status = 'provisional' then 'Preso Provisório'
      when found then 'Condenado'
      when exists (
        select 1 from public.criminal_records cr
        where cr.user_id = new.inmate_id
          and cr.record_status = 'conviction'
      ) then 'Cidadão com antecedentes'
      else 'Cidadão de Bem'
    end
  where id = new.inmate_id;
  return new;
end;
$$;


ALTER FUNCTION "public"."sync_legacy_prison_profile_state"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_parliament_leadership_term_to_gazette"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
begin
  if tg_op = 'INSERT' then
    perform public.publish_parliament_leadership_gazette_event(
      new.id,
      new.member_id,
      new.house_id,
      new.position,
      'start',
      new.term_start_date,
      new.term_end_date,
      new.concluded_at
    );

    return new;
  end if;

  if tg_op = 'UPDATE' then
    if old.member_id is distinct from new.member_id then
      perform public.publish_parliament_leadership_gazette_event(
        new.id,
        old.member_id,
        coalesce(old.house_id, new.house_id),
        coalesce(old.position, new.position),
        'end',
        old.term_start_date,
        old.term_end_date,
        old.concluded_at
      );

      perform public.publish_parliament_leadership_gazette_event(
        new.id,
        new.member_id,
        new.house_id,
        new.position,
        'start',
        new.term_start_date,
        new.term_end_date,
        new.concluded_at
      );

      return new;
    end if;

    if (
      coalesce(old.status, '') not in ('closed', 'concluded', 'inactive', 'expired')
      and coalesce(new.status, '') in ('closed', 'concluded', 'inactive', 'expired')
    )
    or (old.concluded_at is null and new.concluded_at is not null)
    or (old.term_end_date is null and new.term_end_date is not null and new.term_end_date <= current_date)
    then
      perform public.publish_parliament_leadership_gazette_event(
        new.id,
        new.member_id,
        new.house_id,
        new.position,
        'end',
        new.term_start_date,
        new.term_end_date,
        new.concluded_at
      );
    end if;
  end if;

  return new;
end;
$$;


ALTER FUNCTION "public"."sync_parliament_leadership_term_to_gazette"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_parliament_membership"("p_user_id" "uuid", "p_new_role" "text", "p_old_role" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_house_id UUID;
    v_camara_id UUID := 'a1b2c3d4-e5f6-7890-1234-567890abcdef';
    v_senado_id UUID := 'fedcba09-8765-4321-0987-654321fedcba';
BEGIN
    -- Define a casa legislativa com base no novo cargo
    IF p_new_role IN ('Deputado', 'Presidente da Câmara dos Deputados') THEN
        v_house_id := v_camara_id;
    ELSIF p_new_role IN ('Senador', 'Presidente do Senado') THEN
        v_house_id := v_senado_id;
    ELSE
        v_house_id := NULL;
    END IF;

    -- SE O USUÁRIO GANHOU UM CARGO PARLAMENTAR
    IF v_house_id IS NOT NULL THEN
        -- Insere ou atualiza o membro do parlamento
        INSERT INTO public.parliament_members (user_id, house_id, term_start_date, term_end_date)
        VALUES (p_user_id, v_house_id, now(), now() + interval '4 years')
        ON CONFLICT (user_id) DO UPDATE 
        SET house_id = EXCLUDED.house_id,
            term_start_date = EXCLUDED.term_start_date,
            term_end_date = EXCLUDED.term_end_date;
            
    -- SE O USUÁRIO PERDEU O CARGO PARLAMENTAR
    ELSIF v_house_id IS NULL AND p_old_role IN ('Deputado', 'Presidente da Câmara dos Deputados', 'Senador', 'Presidente do Senado') THEN
        DELETE FROM public.parliament_members WHERE user_id = p_user_id;
    END IF;
END;
$$;


ALTER FUNCTION "public"."sync_parliament_membership"("p_user_id" "uuid", "p_new_role" "text", "p_old_role" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."sync_political_point_awards"() RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_bill record;
  v_plebiscite record;
  v_election record;
  v_winner record;
  v_processed integer := 0;
begin
  for v_bill in
    select id, author_id, title
    from public.bills
    where status = 'Aprovado'
      and author_id is not null
  loop
    perform public.award_political_points(
      v_bill.author_id,
      'bill_approved',
      v_bill.id,
      v_bill.title,
      jsonb_build_object(
        'source_table', 'bills',
        'bill_id', v_bill.id,
        'title', v_bill.title
      )
    );
    v_processed := v_processed + 1;
  end loop;

  for v_plebiscite in
    select id, author_id, title, status
    from public.plebiscites
    where status in ('Ativo', 'Aprovado')
      and author_id is not null
  loop
    perform public.award_political_points(
      v_plebiscite.author_id,
      'plebiscite_approved',
      v_plebiscite.id,
      v_plebiscite.title,
      jsonb_build_object(
        'source_table', 'plebiscites',
        'plebiscite_id', v_plebiscite.id,
        'status', v_plebiscite.status,
        'title', v_plebiscite.title
      )
    );
    v_processed := v_processed + 1;
  end loop;

  for v_election in
    select id, name
    from public.elections
    where status = 'Finished'
  loop
    for v_winner in
      with ranked_results as (
        select
          c.user_id,
          c.id as candidate_id,
          count(v.id) as vote_count,
          dense_rank() over (order by count(v.id) desc) as result_rank
        from public.candidates c
        left join public.votes v
          on v.candidate_id = c.id
        where c.election_id = v_election.id
          and c.user_id is not null
        group by c.user_id, c.id
      )
      select user_id, candidate_id, vote_count
      from ranked_results
      where result_rank = 1
        and vote_count > 0
    loop
      perform public.award_political_points(
        v_winner.user_id,
        'election_win',
        v_election.id,
        v_election.name,
        jsonb_build_object(
          'source_table', 'elections',
          'election_id', v_election.id,
          'candidate_id', v_winner.candidate_id,
          'vote_count', v_winner.vote_count,
          'name', v_election.name
        )
      );
      v_processed := v_processed + 1;
    end loop;
  end loop;

  return jsonb_build_object(
    'success', true,
    'processed', v_processed,
    'message', 'Sincronizacao de Pontos Politicos concluida.'
  );
end;
$$;


ALTER FUNCTION "public"."sync_political_point_awards"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_follow"("p_following_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    follower_x_handle TEXT;
BEGIN
    IF current_user_id = p_following_id THEN
        RAISE EXCEPTION 'You cannot follow yourself.';
    END IF;

    IF EXISTS (SELECT 1 FROM public.followers WHERE follower_id = current_user_id AND following_id = p_following_id) THEN
        DELETE FROM public.followers WHERE follower_id = current_user_id AND following_id = p_following_id;
    ELSE
        INSERT INTO public.followers (follower_id, following_id) VALUES (current_user_id, p_following_id);
        SELECT x_handle INTO follower_x_handle FROM public.profiles WHERE id = current_user_id;
        INSERT INTO public.notifications (user_id, sender_id, type, content, link)
        VALUES (p_following_id, current_user_id, 'x_follow', '@' || follower_x_handle || ' começou a seguir você.', '/services/x/profile/' || follower_x_handle);
    END IF;
END;
$$;


ALTER FUNCTION "public"."toggle_follow"("p_following_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_like"("p_post_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  current_user_id UUID := auth.uid();
  post_author_id UUID;
  liker_x_handle TEXT;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM public.posts WHERE id = p_post_id) THEN
      RETURN;
    END IF;

    SELECT user_id INTO post_author_id FROM public.posts WHERE id = p_post_id;
    SELECT x_handle INTO liker_x_handle FROM public.profiles WHERE id = current_user_id;

    IF EXISTS (SELECT 1 FROM public.likes WHERE post_id = p_post_id AND user_id = current_user_id) THEN
        DELETE FROM public.likes WHERE post_id = p_post_id AND user_id = current_user_id;
    ELSE
        INSERT INTO public.likes (post_id, user_id) VALUES (p_post_id, current_user_id);
        IF current_user_id <> post_author_id THEN
            INSERT INTO public.notifications (user_id, sender_id, type, content, link)
            VALUES (post_author_id, current_user_id, 'x_like', '@' || liker_x_handle || ' curtiu seu post.', '/services/x');
        END IF;
    END IF;
END;
$$;


ALTER FUNCTION "public"."toggle_like"("p_post_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_party_affiliation_mode"("p_party_id" "uuid", "p_mode" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
BEGIN
    -- Only founder can change the mode
    IF NOT EXISTS (SELECT 1 FROM public.political_parties WHERE id = p_party_id AND founder_id = current_user_id) THEN
        RETURN json_build_object('success', false, 'message', 'Apenas o fundador pode alterar o modo de filiação.');
    END IF;

    IF p_mode NOT IN ('automatic', 'manual') THEN
        RETURN json_build_object('success', false, 'message', 'Modo de filiação inválido. Use "automatic" ou "manual".');
    END IF;

    UPDATE public.political_parties
    SET affiliation_mode = p_mode
    WHERE id = p_party_id;

    RETURN json_build_object('success', true, 'message', 'Modo de filiação atualizado para ' || p_mode || '.');
END;
$$;


ALTER FUNCTION "public"."toggle_party_affiliation_mode"("p_party_id" "uuid", "p_mode" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transfer_party_ownership"("p_party_id" "uuid", "p_new_founder_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
BEGIN
    -- Check if user is the founder
    IF NOT EXISTS (SELECT 1 FROM public.political_parties WHERE id = p_party_id AND founder_id = current_user_id) THEN
        RETURN json_build_object('success', false, 'message', 'Apenas o fundador pode transferir a posse.');
    END IF;

    -- Check if the new founder is a member
    IF NOT EXISTS (SELECT 1 FROM public.party_members WHERE party_id = p_party_id AND user_id = p_new_founder_id) THEN
        RETURN json_build_object('success', false, 'message', 'O novo líder deve ser um membro do partido.');
    END IF;

    -- Update founder in political_parties table
    UPDATE public.political_parties SET founder_id = p_new_founder_id WHERE id = p_party_id;
    -- Update roles in party_members table
    UPDATE public.party_members SET role = 'Fundador' WHERE user_id = p_new_founder_id AND party_id = p_party_id;
    UPDATE public.party_members SET role = 'Membro' WHERE user_id = current_user_id AND party_id = p_party_id;

    RETURN json_build_object('success', true, 'message', 'Posse do partido transferida com sucesso.');
END;
$$;


ALTER FUNCTION "public"."transfer_party_ownership"("p_party_id" "uuid", "p_new_founder_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."triage_police_occurrence"("p_occurrence_id" "uuid", "p_action" "text", "p_notes" "text") RETURNS "public"."police_occurrences"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  v_old public.police_occurrences%rowtype;
  v_new public.police_occurrences%rowtype;
  v_status text;
begin
  if not public.justice_has_role(array['Admin', 'Policial', 'Police', 'Delegado']) then
    raise exception 'ROLE_NOT_AUTHORIZED';
  end if;
  if nullif(trim(p_notes), '') is null then raise exception 'TRIAGE_JUSTIFICATION_REQUIRED'; end if;

  select * into v_old from public.police_occurrences
  where id = p_occurrence_id for update;
  if not found then raise exception 'OCCURRENCE_NOT_FOUND'; end if;

  v_status := case p_action
    when 'accept' then 'Em triagem'
    when 'more_info' then 'Aguardando informações'
    when 'duplicate' then 'Duplicada'
    when 'transfer' then 'Encaminhada'
    when 'archive' then 'Arquivada'
    when 'investigate' then 'Em investigação'
    else null
  end;
  if v_status is null then raise exception 'INVALID_TRIAGE_ACTION'; end if;

  update public.police_occurrences
  set status = v_status,
      triage_notes = trim(p_notes),
      assigned_officer_id = coalesce(assigned_officer_id, (select auth.uid()))
  where id = p_occurrence_id
  returning * into v_new;

  perform public.justice_write_audit(
    'occurrence.triaged', 'police_occurrence', p_occurrence_id,
    to_jsonb(v_old), to_jsonb(v_new), p_notes
  );

  if coalesce(v_new.reported_by, v_new.user_id) is not null then
    perform public.justice_notify(
      coalesce(v_new.reported_by, v_new.user_id),
      'justice_occurrence_updated',
      'A ocorrência ' || coalesce(v_new.protocol_number, v_new.id::text) || ' foi atualizada.',
      '/services/justice?view=citizen',
      jsonb_build_object('occurrence_id', v_new.id, 'status', v_new.status)
    );
  end if;

  return v_new;
end;
$$;


ALTER FUNCTION "public"."triage_police_occurrence"("p_occurrence_id" "uuid", "p_action" "text", "p_notes" "text") OWNER TO "postgres";


