CREATE TABLE IF NOT EXISTS "public"."citizen_economic_statuses" (
    "profile_id" "uuid" NOT NULL,
    "labor_status" "text" DEFAULT 'outside_labor_force'::"text" NOT NULL,
    "actively_seeking" boolean DEFAULT false NOT NULL,
    "available_for_work" boolean DEFAULT true NOT NULL,
    "last_economic_activity_at" timestamp with time zone,
    "activity_score" numeric(10,4) DEFAULT 0 NOT NULL,
    "macro_weight" numeric(8,4) DEFAULT 1 NOT NULL,
    "fraud_review_status" "text" DEFAULT 'clear'::"text" NOT NULL,
    "metadata" "jsonb" DEFAULT '{}'::"jsonb" NOT NULL,
    "updated_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "citizen_economic_statuses_fraud" CHECK (("fraud_review_status" = ANY (ARRAY['clear'::"text", 'under_review'::"text", 'restricted'::"text", 'blocked'::"text"]))),
    CONSTRAINT "citizen_economic_statuses_labor" CHECK (("labor_status" = ANY (ARRAY['private_employee'::"text", 'public_employee'::"text", 'entrepreneur'::"text", 'self_employed'::"text", 'unemployed'::"text", 'outside_labor_force'::"text", 'retired'::"text", 'imprisoned'::"text", 'temporarily_unable'::"text"]))),
    CONSTRAINT "citizen_economic_statuses_weight" CHECK ((("macro_weight" >= (0)::numeric) AND ("macro_weight" <= (1)::numeric)))
);


ALTER TABLE "public"."citizen_economic_statuses" OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_citizen_economic_status"("p_labor_status" "text", "p_actively_seeking" boolean, "p_available_for_work" boolean DEFAULT true) RETURNS "public"."citizen_economic_statuses"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare
  result public.citizen_economic_statuses%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Autenticação obrigatória.' using errcode = '42501';
  end if;

  if p_labor_status not in (
    'private_employee',
    'public_employee',
    'entrepreneur',
    'self_employed',
    'unemployed',
    'outside_labor_force',
    'retired',
    'imprisoned',
    'temporarily_unable'
  ) then
    raise exception 'Situação de trabalho inválida.';
  end if;

  if p_labor_status = 'private_employee'
     and not exists (
       select 1
       from public.business_employees be
       where be.profile_id = auth.uid()
         and be.fired_at is null
     ) then
    raise exception 'Não existe vínculo privado ativo para este perfil.';
  end if;

  if p_labor_status = 'entrepreneur'
     and not exists (
       select 1
       from public.businesses b
       where b.owner_id = auth.uid()
         and b.status = 'active'
     ) then
    raise exception 'Não existe empresa ativa para este perfil.';
  end if;

  insert into public.citizen_economic_statuses (
    profile_id,
    labor_status,
    actively_seeking,
    available_for_work,
    last_economic_activity_at,
    updated_at
  )
  values (
    auth.uid(),
    p_labor_status,
    case when p_labor_status = 'unemployed' then p_actively_seeking else false end,
    p_available_for_work,
    now(),
    now()
  )
  on conflict (profile_id) do update set
    labor_status = excluded.labor_status,
    actively_seeking = excluded.actively_seeking,
    available_for_work = excluded.available_for_work,
    last_economic_activity_at = excluded.last_economic_activity_at,
    updated_at = now()
  returning * into result;

  perform economy_private.audit(
    'citizen_economic_status_updated',
    'citizen_economic_status',
    auth.uid()::text,
    null,
    to_jsonb(result),
    'Atualização realizada pelo próprio cidadão.'
  );

  return result;
end;
$$;


ALTER FUNCTION "public"."update_citizen_economic_status"("p_labor_status" "text", "p_actively_seeking" boolean, "p_available_for_work" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_citizen_labor_status"("p_labor_status" "text", "p_actively_seeking" boolean, "p_available_for_work" boolean) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
begin
  if auth.uid() is null then raise exception 'Autenticação obrigatória.' using errcode='42501'; end if;
  if p_labor_status not in ('self_employed','unemployed','outside_labor_force','retired') then
    raise exception 'Status manual inválido. Emprego, prisão e empresa são derivados.';
  end if;
  if p_labor_status='unemployed' and not p_actively_seeking then
    raise exception 'Desempregado deve estar procurando trabalho.';
  end if;
  insert into public.citizen_economic_statuses(
    profile_id,labor_status,actively_seeking,available_for_work,
    last_economic_activity_at,updated_at
  )
  values (auth.uid(),p_labor_status,p_actively_seeking,p_available_for_work,now(),now())
  on conflict (profile_id) do update set
    labor_status=excluded.labor_status,
    actively_seeking=excluded.actively_seeking,
    available_for_work=excluded.available_for_work,
    last_economic_activity_at=excluded.last_economic_activity_at,
    updated_at=now();
  return to_jsonb((select s from public.citizen_economic_statuses s where s.profile_id=auth.uid()));
end;
$$;


ALTER FUNCTION "public"."update_citizen_labor_status"("p_labor_status" "text", "p_actively_seeking" boolean, "p_available_for_work" boolean) OWNER TO "postgres";


