CREATE OR REPLACE FUNCTION "public"."update_economic_calibration"("p_key" "text", "p_value" "jsonb", "p_justification" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO ''
    AS $$
declare old_row public.economic_calibrations%rowtype;
begin
  if auth.uid() is null or not public.economic_has_role(array['Admin']) then
    raise exception 'Apenas administradores podem calibrar o motor.' using errcode='42501';
  end if;
  if length(trim(coalesce(p_justification,'')))<20 then
    raise exception 'Justificativa insuficiente.';
  end if;
  select * into old_row from public.economic_calibrations where key=p_key for update;
  if not found then raise exception 'Calibração inexistente.'; end if;
  update public.economic_calibrations
  set value=p_value,updated_by=auth.uid(),updated_at=now(),
      engine_version=(string_to_array(engine_version,'.'))[1]||'.'||
        coalesce((string_to_array(engine_version,'.'))[2]::integer+1,1)||'.0'
  where key=p_key;
  perform economy_private.audit('update_economic_calibration','economic_calibration',p_key,
    to_jsonb(old_row),to_jsonb((select c from public.economic_calibrations c where c.key=p_key)),
    p_justification,auth.uid());
  return to_jsonb((select c from public.economic_calibrations c where c.key=p_key));
end;
$$;


ALTER FUNCTION "public"."update_economic_calibration"("p_key" "text", "p_value" "jsonb", "p_justification" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_election_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF (NOW() < NEW.candidacy_start_date) THEN
    NEW.status := 'Scheduled';
  ELSIF (NOW() >= NEW.candidacy_start_date AND NOW() < NEW.candidacy_end_date) THEN
    NEW.status := 'Candidacy';
  ELSIF (NOW() >= NEW.candidacy_end_date AND NOW() < NEW.voting_start_date) THEN
    NEW.status := 'Scheduled';
  ELSIF (NOW() >= NEW.voting_start_date AND NOW() < NEW.voting_end_date) THEN
    NEW.status := 'Voting';
  ELSE
    NEW.status := 'Finished';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_election_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_election_statuses"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_time_utc timestamp with time zone := now() AT TIME ZONE 'UTC';
BEGIN
    -- From 'Scheduled' (before candidacy) to 'Candidacy'
    UPDATE elections
    SET status = 'Candidacy'
    WHERE 
        status = 'Scheduled' AND
        current_time_utc >= candidacy_start_date AND
        current_time_utc < candidacy_end_date;

    -- From 'Candidacy' to 'Scheduled' (gap between candidacy and voting)
    UPDATE elections
    SET status = 'Scheduled'
    WHERE 
        status = 'Candidacy' AND
        current_time_utc >= candidacy_end_date AND
        current_time_utc < voting_start_date;
        
    -- From 'Candidacy' or 'Scheduled' (after candidacy) to 'Voting'
    UPDATE elections
    SET status = 'Voting'
    WHERE 
        status IN ('Candidacy', 'Scheduled') AND
        current_time_utc >= voting_start_date AND
        current_time_utc < voting_end_date;

    -- From 'Voting' to 'Finished'
    UPDATE elections
    SET status = 'Finished'
    WHERE 
        status = 'Voting' AND
        current_time_utc >= voting_end_date;
END;
$$;


