CREATE OR REPLACE FUNCTION "public"."update_party_active_status"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    member_count INT;
BEGIN
    IF (TG_OP = 'INSERT' OR TG_OP = 'DELETE') THEN
        SELECT count(*) INTO member_count FROM public.party_members WHERE party_id = COALESCE(NEW.party_id, OLD.party_id);

        UPDATE public.political_parties
        SET is_active = (member_count >= 5)
        WHERE id = COALESCE(NEW.party_id, OLD.party_id);
    END IF;
    RETURN NULL; -- result is ignored since this is an AFTER trigger
END;
$$;


ALTER FUNCTION "public"."update_party_active_status"() OWNER TO "postgres";


