CREATE OR REPLACE FUNCTION "public"."update_party_details"("p_party_id" "uuid", "p_ideology" "text", "p_statute" "text", "p_logo_url" "text", "p_president_id" "uuid", "p_vice_president_id" "uuid", "p_description" "text", "p_orientation" "public"."political_orientation") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    leader_id uuid := auth.uid();
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.political_parties pp
        WHERE pp.id = p_party_id AND (pp.founder_id = leader_id OR pp.president_id = leader_id)
    ) THEN
        RETURN json_build_object('success', false, 'message', 'Você não tem permissão para editar este partido.');
    END IF;

    UPDATE public.political_parties
    SET
        ideology = p_ideology,
        statute = p_statute,
        logo_url = p_logo_url,
        president_id = p_president_id,
        vice_president_id = p_vice_president_id,
        description = p_description,
        orientation = p_orientation
    WHERE id = p_party_id;

    UPDATE public.party_members SET role = 'Membro' WHERE party_id = p_party_id AND role IN ('Presidente', 'Vice-Presidente');
    IF p_president_id IS NOT NULL THEN
        UPDATE public.party_members SET role = 'Presidente' WHERE user_id = p_president_id AND party_id = p_party_id;
    END IF;
    IF p_vice_president_id IS NOT NULL THEN
       UPDATE public.party_members SET role = 'Vice-Presidente' WHERE user_id = p_vice_president_id AND party_id = p_party_id;
    END IF;

    RETURN json_build_object('success', true, 'message', 'Partido atualizado com sucesso.');
END;
