ALTER FUNCTION "public"."update_party_details"("p_party_id" "uuid", "p_ideology" "text", "p_statute" "text", "p_logo_url" "text", "p_president_id" "uuid", "p_vice_president_id" "uuid", "p_description" "text", "p_orientation" "public"."political_orientation") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_party_details"("p_party_id" "uuid", "p_name" "text", "p_acronym" "text", "p_ideology" "text", "p_statute" "text", "p_logo_url" "text", "p_president_id" "uuid", "p_vice_president_id" "uuid", "p_description" "text", "p_orientation" "public"."political_orientation") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    leader_id uuid := auth.uid();
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.political_parties pp
        WHERE pp.id = p_party_id AND (pp.founder_id = leader_id OR pp.president_id = leader_id)
    ) THEN
        RETURN json_build_object('success', false, 'message', 'Você não tem permissão para editar este partido.');
    END IF;

    UPDATE public.political_parties
    SET
        name = p_name,
        acronym = p_acronym,
        ideology = p_ideology,
        statute = p_statute,
        logo_url = p_logo_url,
        president_id = p_president_id,
        vice_president_id = p_vice_president_id,
        description = p_description,
        orientation = p_orientation
    WHERE id = p_party_id;

    -- Demote current president/vp
    UPDATE public.party_members SET role = 'Membro' WHERE party_id = p_party_id AND role IN ('Presidente', 'Vice-Presidente');
    
    -- Promote new president/vp if they exist
    IF p_president_id IS NOT NULL THEN
        UPDATE public.party_members SET role = 'Presidente' WHERE user_id = p_president_id AND party_id = p_party_id;
    END IF;
    IF p_vice_president_id IS NOT NULL THEN
       UPDATE public.party_members SET role = 'Vice-Presidente' WHERE user_id = p_vice_president_id AND party_id = p_party_id;
    END IF;

    RETURN json_build_object('success', true, 'message', 'Partido atualizado com sucesso.');
END;
$$;


ALTER FUNCTION "public"."update_party_details"("p_party_id" "uuid", "p_name" "text", "p_acronym" "text", "p_ideology" "text", "p_statute" "text", "p_logo_url" "text", "p_president_id" "uuid", "p_vice_president_id" "uuid", "p_description" "text", "p_orientation" "public"."political_orientation") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_party_details"("p_party_id" "uuid", "p_name" "text", "p_acronym" "text", "p_ideology" "text", "p_statute" "text", "p_logo_url" "text", "p_owner_id" "uuid", "p_president_id" "uuid", "p_vice_president_id" "uuid", "p_description" "text", "p_orientation" "public"."political_orientation") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    leader_id uuid := auth.uid();
    current_owner_id uuid;
    current_president_id uuid;
BEGIN
    SELECT owner_id, president_id INTO current_owner_id, current_president_id
    FROM public.political_parties WHERE id = p_party_id;
    
    IF NOT (leader_id = current_owner_id OR leader_id = current_president_id) THEN
        RETURN json_build_object('success', false, 'message', 'Você não tem permissão para editar este partido.');
    END IF;

    UPDATE public.political_parties
    SET
        name = p_name,
        acronym = p_acronym,
        ideology = p_ideology,
        statute = p_statute,
        logo_url = p_logo_url,
        owner_id = p_owner_id,
        president_id = p_president_id,
        vice_president_id = p_vice_president_id,
        description = p_description,
        orientation = p_orientation
    WHERE id = p_party_id;

    -- Reset previous leader roles to Member, except for the founder/owner
    UPDATE public.party_members
    SET role = 'Membro'
    WHERE party_id = p_party_id AND role IN ('Presidente', 'Vice-Presidente') AND user_id <> p_owner_id;

    -- Set new roles
    IF p_owner_id IS NOT NULL THEN
        UPDATE public.party_members SET role = 'Dono' WHERE user_id = p_owner_id AND party_id = p_party_id;
    END IF;

    IF p_president_id IS NOT NULL AND p_president_id <> p_owner_id THEN
        UPDATE public.party_members SET role = 'Presidente' WHERE user_id = p_president_id AND party_id = p_party_id;
    END IF;

    IF p_vice_president_id IS NOT NULL AND p_vice_president_id <> p_owner_id AND p_vice_president_id <> p_president_id THEN
       UPDATE public.party_members SET role = 'Vice-Presidente' WHERE user_id = p_vice_president_id AND party_id = p_party_id;
    END IF;

    RETURN json_build_object('success', true, 'message', 'Partido atualizado com sucesso.');
END;
$$;


ALTER FUNCTION "public"."update_party_details"("p_party_id" "uuid", "p_name" "text", "p_acronym" "text", "p_ideology" "text", "p_statute" "text", "p_logo_url" "text", "p_owner_id" "uuid", "p_president_id" "uuid", "p_vice_president_id" "uuid", "p_description" "text", "p_orientation" "public"."political_orientation") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_post"("p_post_id" "uuid", "p_new_content" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    post_author_id UUID;
BEGIN
    SELECT user_id INTO post_author_id FROM public.posts WHERE id = p_post_id;

    IF post_author_id IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Post não encontrado.');
    END IF;

    IF post_author_id <> current_user_id THEN
        RETURN json_build_object('success', false, 'message', 'Você não tem permissão para editar este post.');
    END IF;

    UPDATE public.posts
    SET 
        content = p_new_content,
        updated_at = now()
    WHERE id = p_post_id;

    RETURN json_build_object('success', true, 'message', 'Post atualizado com sucesso.');
END;
$$;


ALTER FUNCTION "public"."update_post"("p_post_id" "uuid", "p_new_content" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_post_counts"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF (TG_OP = 'INSERT') THEN
    IF (TG_TABLE_NAME = 'likes') THEN
      UPDATE posts SET likes_count = likes_count + 1 WHERE id = NEW.post_id;
    ELSIF (TG_TABLE_NAME = 'comments') THEN
      -- Only increment post's comment count for top-level comments
      IF NEW.parent_comment_id IS NULL THEN
        UPDATE posts SET comments_count = comments_count + 1 WHERE id = NEW.post_id;
      END IF;
    ELSIF (TG_TABLE_NAME = 'reposts') THEN
      UPDATE posts SET reposts_count = reposts_count + 1 WHERE id = NEW.post_id;
    END IF;
    RETURN NEW;
  ELSIF (TG_OP = 'DELETE') THEN
    IF (TG_TABLE_NAME = 'likes') THEN
      UPDATE posts SET likes_count = GREATEST(0, likes_count - 1) WHERE id = OLD.post_id;
    ELSIF (TG_TABLE_NAME = 'comments') THEN
      -- Only decrement post's comment count for top-level comments
      IF OLD.parent_comment_id IS NULL THEN
        UPDATE posts SET comments_count = GREATEST(0, comments_count - 1) WHERE id = OLD.post_id;
      END IF;
    END IF;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."update_post_counts"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_post_like_count"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF (TG_OP = 'INSERT') THEN
    UPDATE public.posts SET like_count = like_count + 1 WHERE id = NEW.post_id;
    RETURN NEW;
  ELSIF (TG_OP = 'DELETE') THEN
    UPDATE public.posts SET like_count = like_count - 1 WHERE id = OLD.post_id;
    RETURN OLD;
  END IF;
  RETURN NULL;
END;
$$;


