CREATE OR REPLACE FUNCTION "public"."update_trends_on_insert"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  tags TEXT[];
  tag TEXT;
BEGIN
  tags := extract_hashtags(NEW.content);
  IF tags IS NOT NULL THEN
    FOREACH tag IN ARRAY tags
    LOOP
      INSERT INTO public.trends (hashtag, post_count, last_used_at)
      VALUES (tag, 1, NOW())
      ON CONFLICT (hashtag)
      DO UPDATE SET
        post_count = trends.post_count + 1,
        last_used_at = NOW();
    END LOOP;
  END IF;
  RETURN NEW;
END;
$$;


