CREATE OR REPLACE FUNCTION "public"."update_x_handle"("p_new_handle" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    current_user_id UUID := auth.uid();
    clean_handle TEXT;
    handle_exists BOOLEAN;
BEGIN
    clean_handle := lower(trim(regexp_replace(p_new_handle, '[^a-zA-Z0-9_]', '', 'g')));

    IF clean_handle IS NULL OR clean_handle = '' THEN
        RETURN json_build_object('success', false, 'message', '@handle não pode estar vazio.');
    END IF;

    IF length(clean_handle) < 4 THEN
        RETURN json_build_object('success', false, 'message', '@handle deve ter pelo menos 4 caracteres.');
    END IF;

    SELECT EXISTS(SELECT 1 FROM public.profiles WHERE lower(x_handle) = clean_handle AND id <> current_user_id) INTO handle_exists;
    IF handle_exists THEN
        RETURN json_build_object('success', false, 'message', 'Este @handle já está em uso. Tente outro.');
    END IF;

    -- Store with original casing
    RETURN json_build_object('success', true, 'message', '@handle atualizado com sucesso!', 'new_handle', p_new_handle);
END;
$$;


ALTER FUNCTION "public"."update_x_handle"("p_new_handle" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."user_can_manage_national_bank"("p_user_id" "uuid") RETURNS boolean
    LANGUAGE "sql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
    select 1
    from public.profiles p
    where p.id = p_user_id
      and (
        p.role in ('Admin', 'Presidente do Banco Nacional')
        or exists (
          select 1
          from jsonb_array_elements_text(
            case
              when jsonb_typeof(to_jsonb(p.titles)) = 'array' then to_jsonb(p.titles)
              else '[]'::jsonb
            end
          ) as title(value)
          where title.value in ('Admin', 'Presidente do Banco Nacional')
        )
        or exists (
          select 1
          from public.system_settings s
          where s.key = 'executive_governance'
            and s.value -> 'specialAppointments' -> 'national_bank_president' ->> 'user_id' = p_user_id::text
        )
      )
  );
$$;


