CREATE OR REPLACE FUNCTION "public"."validate_and_get_bill"("p_bill_code" "text") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    bill_info RECORD;
BEGIN
    SELECT id, amount, status, description, due_date
    INTO bill_info
    FROM public.bills_of_exchange
    WHERE bill_code = p_bill_code;

    IF bill_info IS NULL THEN
        RETURN json_build_object('success', false, 'status', 'invalid', 'message', 'Boleto inexistente.');
    END IF;

    IF bill_info.status = 'paid' THEN
        RETURN json_build_object('success', false, 'status', 'paid', 'message', 'Este boleto já foi pago.');
    END IF;

    IF bill_info.status = 'pending' THEN
        RETURN json_build_object(
            'success', true,
            'status', 'valid',
            'message', 'Boleto válido e pendente.',
            'amount', bill_info.amount,
            'description', bill_info.description,
            'due_date', bill_info.due_date
        );
    END IF;

    RETURN json_build_object('success', false, 'status', 'unknown', 'message', 'Status do boleto desconhecido.');
END;
$$;


ALTER FUNCTION "public"."validate_and_get_bill"("p_bill_code" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."withdraw"("p_user_investment_id" "uuid", "p_amount" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  v_user_id uuid := auth.uid();
  v_account record;
  v_investment record;
  v_current_amount numeric;
  v_accrued numeric := 0;
  v_days numeric := 0;
begin
  if v_user_id is null then
    return jsonb_build_object('success', false, 'message', 'Usuário não autenticado.');
  end if;

  if p_amount is null or p_amount <= 0 then
    return jsonb_build_object('success', false, 'message', 'Informe um valor positivo para resgatar.');
  end if;

  select ui.*, io.name, io.annual_return_rate
  into v_investment
  from public.user_investments ui
  join public.investment_options io on io.id = ui.investment_option_id
  where ui.id = p_user_investment_id and ui.user_id = v_user_id
  for update;

  if not found then
    return jsonb_build_object('success', false, 'message', 'Investimento não encontrado.');
  end if;

  v_days := greatest(0, extract(epoch from (now() - coalesce(v_investment.updated_at, v_investment.created_at, now()))) / 86400);
  v_accrued := round(coalesce(v_investment.amount_invested, 0) * coalesce(v_investment.annual_return_rate, 0) * (v_days / 365), 2);
  v_current_amount := round(coalesce(v_investment.amount_invested, 0) + v_accrued, 2);

  if p_amount > v_current_amount then
    return jsonb_build_object('success', false, 'message', 'Valor de resgate maior que o saldo investido.');
  end if;

  select *
  into v_account
  from public.accounts
  where user_id = v_user_id
  for update;

  if not found then
    return jsonb_build_object('success', false, 'message', 'Conta bancária não encontrada.');
  end if;

  update public.accounts
  set balance = round(coalesce(balance, 0) + p_amount, 2), updated_at = now()
  where id = v_account.id;

  if v_current_amount - p_amount <= 0.01 then
    delete from public.user_investments where id = p_user_investment_id;
  else
    update public.user_investments
    set
      amount_invested = round(v_current_amount - p_amount, 2),
      updated_at = now()
    where id = p_user_investment_id;
  end if;

  insert into public.transactions (from_account_id, to_account_id, amount, type, description, created_at, metadata)
  values (
    null,
    v_account.id,
    round(p_amount, 2),
    'investment_withdrawal',
    'Resgate de investimento: ' || v_investment.name,
    now(),
    jsonb_build_object('user_investment_id', p_user_investment_id, 'accrued_before_withdrawal', v_accrued)
  );

  return jsonb_build_object('success', true, 'message', 'Resgate realizado com sucesso.');
end;
$$;


ALTER FUNCTION "public"."withdraw"("p_user_investment_id" "uuid", "p_amount" numeric) OWNER TO "postgres";


