CREATE OR REPLACE VIEW "public"."elections_with_status" AS
 SELECT "id",
    "name",
    "description",
    "election_type_id",
    "candidacy_start_date",
    "candidacy_end_date",
    "voting_start_date",
    "voting_end_date",
    "created_at",
        CASE
            WHEN ("now"() > "voting_end_date") THEN 'Finished'::"text"
            WHEN (("now"() >= "voting_start_date") AND ("now"() <= "voting_end_date")) THEN 'Voting'::"text"
            WHEN (("now"() >= "candidacy_start_date") AND ("now"() <= "candidacy_end_date")) THEN 'Candidacy'::"text"
            ELSE 'Scheduled'::"text"
        END AS "status"
   FROM "public"."elections";


