CREATE TABLE IF NOT EXISTS "public"."warrants" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "warrant_number" "text" NOT NULL,
    "warrant_type" "text" NOT NULL,
    "target_profile_id" "uuid" NOT NULL,
    "case_id" "uuid",
    "investigation_id" "uuid",
    "request_id" "uuid",
    "issued_by" "uuid" NOT NULL,
    "issued_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    "expires_at" timestamp with time zone NOT NULL,
    "status" "public"."justice_warrant_status" DEFAULT 'issued'::"public"."justice_warrant_status" NOT NULL,
    "executed_by" "uuid",
    "executed_at" timestamp with time zone,
    "revoked_by" "uuid",
    "revocation_reason" "text",
    "created_at" timestamp with time zone DEFAULT "now"() NOT NULL,
    CONSTRAINT "warrants_warrant_type_check" CHECK (("warrant_type" = ANY (ARRAY['arrest'::"text", 'search'::"text", 'seizure'::"text", 'transfer'::"text"])))
);


ALTER TABLE "public"."warrants" OWNER TO "postgres";


